# Plain-text reader/editor core, v3.10.0. Never executes the opened source file.
TEXT_EXTENSIONS = {'.txt', '.text', '.py', '.pyw', '.md', '.markdown', '.log',
                   '.ini', '.cfg', '.conf', '.json', '.jsonl', '.xml', '.yaml',
                   '.yml', '.toml', '.csv', '.tsv', '.html', '.htm', '.css',
                   '.js', '.ts', '.sql', '.bat', '.cmd', '.ps1', '.sh', '.lsp',
                   '.c', '.h', '.cpp', '.hpp', '.cs', '.java'}
TEXT_MAX_BYTES = 16 * 1024 * 1024
TEXT_MAX_CHARS = 8_000_000
TEXT_MAX_PAGES = 10_000
TEXT_FEATURE_VERSION = 1
TEXT_READ_DEFAULTS = {'font_size': 13, 'line_spacing': 1.65, 'tab_size': 4}
TEXT_ENCODING_CHOICES = ('auto', 'utf-8', 'utf-8-sig', 'cp949', 'euc-kr',
                         'utf-16-le', 'utf-16-be', 'utf-32-le', 'utf-32-be', 'cp1252', 'ascii', 'iso8859-1')


class PlainTextError(ValueError):
    pass


@dataclass
class PlainTextState:
    path: str
    raw: bytes
    decoded: str
    text: str
    codec: str
    bom: bytes
    sha256: str
    newline: str
    mixed: bool
    note: str = ''


def text_normalize(value):
    return value.replace('\r\n', '\n').replace('\r', '\n')


def read_plain_text(path, encoding='auto'):
    import codecs
    import tokenize
    path = Path(path).resolve()
    if path.stat().st_size > TEXT_MAX_BYTES:
        raise PlainTextError('텍스트 파일은 현재 16 MiB 이하를 지원합니다. 큰 로그는 나눠서 열어주세요.')
    raw = path.read_bytes()
    if len(raw) > TEXT_MAX_BYTES:
        raise PlainTextError('읽는 동안 파일 크기가 16 MiB를 넘었습니다.')
    if encoding not in TEXT_ENCODING_CHOICES:
        raise PlainTextError('지원하는 문자 인코딩을 선택하세요.')
    bom = b''; codec = ''; note = ''
    signatures = [(codecs.BOM_UTF32_LE, 'utf-32-le'), (codecs.BOM_UTF32_BE, 'utf-32-be'),
                  (codecs.BOM_UTF8, 'utf-8'), (codecs.BOM_UTF16_LE, 'utf-16-le'),
                  (codecs.BOM_UTF16_BE, 'utf-16-be')]
    for prefix, name in signatures:
        if raw.startswith(prefix):
            bom, codec = prefix, name
            break
    if encoding != 'auto':
        wanted = 'utf-8' if encoding == 'utf-8-sig' else encoding
        if bom and codec != wanted:
            raise PlainTextError('파일의 BOM과 선택한 인코딩이 다릅니다. 자동 또는 올바른 인코딩을 선택하세요.')
        codec = wanted
    if not codec and path.suffix.lower() in ('.py', '.pyw'):
        try:
            detected, _ = tokenize.detect_encoding(io.BytesIO(raw).readline)
            codec = codecs.lookup(detected).name
            if codec == 'utf-8-sig': codec = 'utf-8'
        except (SyntaxError, LookupError) as exc:
            raise PlainTextError('Python 파일의 인코딩 선언을 읽지 못했습니다. 본문 편집에서 인코딩을 지정하세요: '+str(exc)) from exc
    payload = raw[len(bom):]
    if not codec:
        try:
            decoded = payload.decode('utf-8', 'strict'); codec = 'utf-8'
        except UnicodeDecodeError:
            try:
                decoded = payload.decode('cp949', 'strict'); codec = 'cp949'
                note = 'CP949 후보로 읽었습니다. 글자가 다르면 본문 편집의 인코딩을 바꿔 다시 읽으세요.'
            except UnicodeDecodeError as exc:
                raise PlainTextError('UTF-8/CP949로 읽지 못했습니다. 본문 편집에서 원본 인코딩을 직접 선택하세요.') from exc
    else:
        try: decoded = payload.decode(codec, 'strict')
        except (UnicodeDecodeError, LookupError) as exc:
            raise PlainTextError('선택한 인코딩으로 읽을 수 없습니다: '+str(exc)) from exc
    if '\x00' in decoded:
        raise PlainTextError('NUL 문자가 있습니다. 바이너리 파일 또는 BOM 없는 UTF-16은 인코딩을 확인하세요.')
    if len(decoded) > TEXT_MAX_CHARS:
        raise PlainTextError('텍스트 800만 글자 한도를 초과했습니다.')
    if any(ord(c) < 32 and c not in '\r\n\t\f' for c in decoded[:131072]):
        raise PlainTextError('일반 텍스트로 표시하기 어려운 제어 문자가 있습니다.')
    endings = re.findall(r'\r\n|\r|\n', decoded)
    newline = max(dict.fromkeys(endings), key=endings.count) if endings else '\n'
    return PlainTextState(str(path), raw, decoded, text_normalize(decoded), codec, bom,
                          hashlib.sha256(raw).hexdigest(), newline, len(set(endings)) > 1, note)


def _text_pieces(value):
    """Split only CR/LF, not other Unicode characters (including NBSP)."""
    items = re.split(r'(\r\n|\r|\n)', value)
    return [items[i] + (items[i+1] if i+1 < len(items) else '')
            for i in range(0, len(items), 2)]


def text_preserve_endings(state, value):
    """Keep hard breaks of equal/one-to-one changed lines; new lines use dominant style."""
    from difflib import SequenceMatcher
    value = text_normalize(value)
    if value == state.text: return state.decoded
    if not state.mixed: return value.replace('\n', state.newline)
    old = _text_pieces(state.decoded)
    old_normal = [text_normalize(p) for p in old]
    new = _text_pieces(value)
    out = []
    for tag, a, b, x, y in SequenceMatcher(None, old_normal, new, autojunk=True).get_opcodes():
        if tag == 'equal': out.extend(old[a:b]); continue
        for index, part in enumerate(new[x:y]):
            ending = state.newline
            if tag == 'replace' and b-a == y-x:
                matched = re.search(r'(\r\n|\r|\n)$', old[a+index])
                if matched: ending = matched.group(1)
            out.append(part[:-1]+ending if part.endswith('\n') else part)
    return ''.join(out)


def text_encode(state, value, encoding=None, target=None):
    import codecs
    import tokenize
    if len(value) > TEXT_MAX_CHARS: raise PlainTextError('텍스트 800만 글자 한도를 초과했습니다.')
    codec = state.codec if encoding in (None, 'preserve') else encoding
    if codec not in TEXT_ENCODING_CHOICES and codec != state.codec:
        raise PlainTextError('지원하지 않는 저장 인코딩입니다.')
    bom = state.bom if encoding in (None, 'preserve') else (
        codecs.BOM_UTF8 if codec == 'utf-8-sig' else b'')
    if codec == 'utf-8-sig': codec = 'utf-8'
    decoded = text_preserve_endings(state, value)
    try: raw = bom + decoded.encode(codec, 'strict')
    except UnicodeEncodeError as exc:
        raise PlainTextError('현재 인코딩에 저장할 수 없는 글자가 있습니다. UTF-8 저장을 명시적으로 선택하세요.') from exc
    if len(raw) > TEXT_MAX_BYTES: raise PlainTextError('저장할 파일이 16 MiB를 넘습니다.')
    if Path(target or state.path).suffix.lower() in ('.py', '.pyw'):
        try:
            declared, _ = tokenize.detect_encoding(io.BytesIO(raw).readline)
            roundtrip = raw.decode(declared, 'strict')
        except (SyntaxError, UnicodeError, LookupError) as exc:
            raise PlainTextError('Python 인코딩 선언과 저장 인코딩을 맞춰주세요. 파일을 실행하지는 않습니다.') from exc
        if roundtrip != decoded:
            raise PlainTextError('Python 파일의 coding 선언과 저장 인코딩이 다릅니다.')
    return raw


def write_plain_text(state, value, target=None, encoding=None, expected_target_hash=None):
    """Optimistic conflict check, verified backup, same-directory atomic replacement."""
    import shutil
    path = Path(target or state.path).expanduser().absolute()
    if path.is_symlink(): raise PlainTextError('링크 파일은 덮어쓰지 않습니다. 다른 이름으로 저장하세요.')
    same = path.resolve() == Path(state.path).resolve()
    expected = state.sha256 if same else expected_target_hash
    raw = text_encode(state, value, encoding, target=path)
    if path.exists():
        if not path.is_file(): raise PlainTextError('저장 대상이 파일이 아닙니다.')
        current = path.read_bytes()
        if expected is None or hashlib.sha256(current).hexdigest() != expected:
            raise PlainTextError('열었던 뒤 원본이 변경됐거나 덮어쓰기 확인이 필요합니다. 다른 이름으로 저장하세요.')
        if current == raw: return {'path': str(path), 'backup': '', 'unchanged': True}
    elif same:
        raise PlainTextError('원본 파일이 사라졌습니다. 다른 이름으로 저장하세요.')
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix='.'+path.name+'.', suffix='.tmp', dir=str(path.parent))
    temporary = Path(temporary); backup = None; old_bytes = None
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(raw); stream.flush(); os.fsync(stream.fileno())
        if hashlib.sha256(temporary.read_bytes()).hexdigest() != hashlib.sha256(raw).hexdigest():
            raise PlainTextError('저장 사본의 무결성 검사에 실패했습니다.')
        if path.exists():
            old_bytes = path.read_bytes()
            if expected is None or hashlib.sha256(old_bytes).hexdigest() != expected:
                raise PlainTextError('저장 직전에 대상 파일이 변경됐습니다. 덮어쓰지 않았습니다.')
            backup = path.with_name(path.name+'.viewer-backup-'+time.strftime('%Y%m%d_%H%M%S')+'_'+uuid.uuid4().hex[:6]+'.bak')
            with backup.open('xb') as out: out.write(old_bytes)
            if backup.read_bytes() != old_bytes: raise PlainTextError('원본 백업 검사 실패.')
            shutil.copystat(path, temporary)
            if hashlib.sha256(path.read_bytes()).hexdigest() != expected:
                raise PlainTextError('백업 중 대상 파일이 변경됐습니다. 덮어쓰지 않았습니다.')
            os.replace(temporary, path)
        else:
            # Never overwrite a file created since the Save As confirmation.
            if os.name == 'nt':
                os.rename(temporary, path)  # Windows: fails instead of replacing an existing path.
            else:
                os.link(temporary, path)    # Atomic create-if-absent on the same filesystem.
                temporary.unlink()
        if path.read_bytes() != raw: raise PlainTextError('저장 후 재읽기 검사 실패. 백업 파일을 보존했습니다.')
        return {'path': str(path), 'backup': str(backup or ''), 'unchanged': False}
    finally:
        temporary.unlink(missing_ok=True)


def text_render_options(value=None):
    value = value or {}
    result = dict(TEXT_READ_DEFAULTS)
    for key, low, high in [('font_size', 9, 28), ('line_spacing', 1.2, 2.5), ('tab_size', 2, 8)]:
        v = float(value.get(key, result[key]))
        if not math.isfinite(v) or not low <= v <= high: raise PlainTextError('텍스트 표시 설정 범위를 확인하세요.')
        result[key] = int(v) if key in ('font_size','tab_size') else v
    return result


def text_visual_rows(value, font, options):
    """Rows carry source character offsets; soft wrapping never writes into the source."""
    width = 595.28 - 104
    size = options['font_size']; tab = options['tab_size']; cache = {}
    offset = 0
    for logical in value.split('\n'):
        if len(logical) > 1_000_000: raise PlainTextError('한 줄이 100만 글자를 넘습니다. 줄을 나눠서 열어주세요.')
        if not logical:
            yield '', offset
        else:
            rendered = []; offsets = []; column = 0
            for pos, ch in enumerate(logical):
                # Form feed is represented as a visible marker; raw text is unchanged.
                part = ' '*(tab-column % tab) if ch == '\t' else ('↡' if ch == '\f' else ch)
                for item in part:
                    rendered.append(item); offsets.append(offset+pos)
                column += len(part)
            start = 0; i = 0; used = 0.; last_break = -1
            while i < len(rendered):
                char = rendered[i]
                if char not in cache: cache[char] = font.text_length(char, fontsize=size)
                advance = cache[char]
                if used+advance > width and i > start:
                    end = last_break if last_break > start else i
                    yield ''.join(rendered[start:end]), offsets[start]
                    start = end; i = end; used = 0.; last_break = -1; continue
                used += advance; i += 1
                if char.isspace(): last_break = i
            if start < len(rendered): yield ''.join(rendered[start:]), offsets[start]
        offset += len(logical)+1




INPUT_EXTENSIONS |= TEXT_EXTENSIONS

def is_image_source(path):
    return str(path).startswith(IMAGE_SOURCE_PREFIX)


def image_source_path(path,member=None,index=None,info=None):
    if info is None:
        path=Path(path).resolve();stat=path.stat()
        value={'file':str(path),'stamp':[stat.st_size,stat.st_mtime_ns]}
    else:value=dict(info)
    if member is not None:value.update(member=member,index=index)
    return IMAGE_SOURCE_PREFIX+base64.urlsafe_b64encode(json.dumps(value,ensure_ascii=True).encode()).decode()


def image_source_info(path):
    if not is_image_source(path):raise ValueError('그림 원본 정보가 없습니다.')
    return json.loads(base64.urlsafe_b64decode(path[len(IMAGE_SOURCE_PREFIX):]))


def validate_image_source(path):
    value=image_source_info(path);source=Path(value['file']);stat=source.stat()
    if [stat.st_size,stat.st_mtime_ns]!=value['stamp']:
        raise ValueError('원본 파일이 변경되었습니다. 파일을 다시 열어주세요.')
    return value,source


def pillow_reader():
    try:
        from PIL import Image,ImageOps
        return Image,ImageOps
    except ImportError:
        raise ValueError('그림 읽기 모듈을 설치하세요.\npython -m pip install -U Pillow') from None


@contextmanager
def open_image_stream(path,archives=None):
    """Read a validated original or a ZIP member without extracting to disk."""
    import zipfile
    value,source=validate_image_source(path)
    archive=None;own_archive=False;stream=None
    try:
        if 'member' in value:
            cache_key=(str(source),*value['stamp'])
            archive=archives.get(cache_key) if archives is not None else None
            if archive is None:
                archive=zipfile.ZipFile(source)
                if archives is not None:
                    archives[cache_key]=archive
                    while len(archives)>2:archives.popitem(last=False)[1].close()
                else:own_archive=True
            elif archives is not None:archives.move_to_end(cache_key)
            member=archive.infolist()[value['index']]
            if member.filename!=value['member']:raise ValueError('압축파일의 그림 목록이 변경되었습니다.')
            if member.flag_bits&1:raise ValueError('암호가 설정된 그림은 먼저 압축을 풀어주세요.')
            if member.file_size>256*1024*1024:raise ValueError('그림 한 파일이 256MB를 초과합니다.')
            stream=archive.open(member)
        else:stream=source.open('rb')
        yield stream
    finally:
        if stream is not None:stream.close()
        if archive is not None and own_archive:archive.close()


@contextmanager
def open_image_source(path,number=0,archives=None):
    import warnings
    Image,_=pillow_reader()
    with open_image_stream(path,archives) as stream, warnings.catch_warnings():
        warnings.simplefilter('error',Image.DecompressionBombWarning)
        with Image.open(stream) as picture:
            picture.seek(int(number))
            yield picture,stream


def image_page_size(picture):
    dpi=picture.info.get('dpi',(96,96))
    try:dpi=float(dpi[0] if isinstance(dpi,(tuple,list)) else dpi)
    except (TypeError,ValueError,IndexError):dpi=96
    if not math.isfinite(dpi) or not 20<=dpi<=2400:dpi=96
    width,height=picture.size
    # TIFF decoder updates orientation while loading; get geometry afterwards for TIFF.
    if picture.getexif().get(274,1) in (5,6,7,8):width,height=height,width
    w,h=width*72/dpi,height*72/dpi
    scale=min(max(1,1/min(w,h)),14400/max(w,h))
    return w*scale,h*scale


def image_page_document(path,number=0):
    """Convert one requested frame only, for editing/export. Caller closes the PDF."""
    import viewer_pdf_engine
    _,ImageOps=pillow_reader()
    doc=viewer_pdf_engine.open()
    try:
        with open_image_source(path,number) as (picture,stream):
            orientation=picture.getexif().get(274,1)
            picture.load()
            width,height=image_page_size(picture)
            page=doc.new_page(width=width,height=height)
            if picture.format=='JPEG' and orientation==1:
                stream.seek(0);page.insert_image(page.rect,stream=stream.read())
            else:
                with ImageOps.exif_transpose(picture) as normalized:
                    mode='RGBA' if 'A' in normalized.getbands() or 'transparency' in normalized.info else 'RGB'
                    with normalized.convert(mode) as bitmap:
                        data=io.BytesIO();bitmap.save(data,format='PNG')
                    page.insert_image(page.rect,stream=data.getvalue())
        return doc
    except Exception:
        doc.close();raise


def render_image_source(path,number,bounds,archives=None):
    Image,ImageOps=pillow_reader()
    with open_image_source(path,number,archives) as (picture,_stream):
        # thumbnail uses JPEG decoder reduction before resizing; never decode into a PDF.
        rotated=picture.getexif().get(274,1) in (5,6,7,8)
        if picture.format=='TIFF':picture.load();rotated=picture.getexif().get(274,1) in (5,6,7,8)
        picture.thumbnail(tuple(reversed(bounds)) if rotated else bounds,Image.Resampling.LANCZOS,reducing_gap=2.0)
        with ImageOps.exif_transpose(picture) as normalized:
            with normalized.convert('RGBA') as rgba:
                with Image.new('RGB',rgba.size,'white') as canvas:
                    canvas.paste(rgba,mask=rgba.getchannel('A'))
                    data=io.BytesIO();canvas.save(data,format='PNG',compress_level=1)
                    return data.getvalue()


class DirectImageReader:
    """Native decoders, bounded ZIP-member/frame caches, no intermediate image/PDF."""
    MEMBER_LIMIT=32*1024*1024
    FRAME_LIMIT=48*1024*1024

    def __init__(self):
        from PySide6.QtCore import QCoreApplication
        self.app=QCoreApplication.instance() or QCoreApplication([])
        self.archives=OrderedDict();self.members=OrderedDict();self.frames=OrderedDict()
        self.member_bytes=0;self.frame_bytes=0

    def close(self):
        for archive in self.archives.values():archive.close()
        self.archives.clear();self.members.clear();self.frames.clear()
        self.member_bytes=self.frame_bytes=0

    def source(self,path,validated=None):
        value,source=validated if validated is not None else validate_image_source(path)
        if 'member' not in value:return str(source),None
        data=self.members.pop(path,None)
        if data is not None:self.members[path]=data;return None,data
        # Decompress this member once. Native decoders may seek many times;
        # a QBuffer avoids repeatedly inflating a ZipExtFile.
        with open_image_stream(path,self.archives) as stream:data=stream.read(256*1024*1024+1)
        if len(data)>256*1024*1024:raise ValueError('그림 한 파일이 256MB를 초과합니다.')
        if len(data)<=self.MEMBER_LIMIT:
            self.members[path]=data;self.member_bytes+=len(data)
            while self.member_bytes>self.MEMBER_LIMIT:self.member_bytes-=len(self.members.popitem(last=False)[1])
        return None,data

    def image_format(self,filename,data,number):
        # Header/frame validation retains the existing Pillow pixel-limit policy.
        import warnings
        Image,_=pillow_reader()
        with warnings.catch_warnings():
            warnings.simplefilter('error',Image.DecompressionBombWarning)
            with Image.open(io.BytesIO(data) if data is not None else filename) as picture:
                picture.seek(number)
                if picture.width<=0 or picture.height<=0:raise ValueError('그림 크기를 읽지 못했습니다.')
                # Pillow PNG.getexif() can force a full pixel decode. Keep header
                # inspection lazy; Qt's fallback scans late eXIf chunks without decoding.
                if picture.format=='PNG':
                    raw=picture.info.get('exif')
                    if raw:
                        exif=Image.Exif();exif.load(raw);orientation=exif.get(274,1)
                    else:orientation=None
                else:orientation=picture.getexif().get(274,1)
                # Pillow TIFF는 load 전 size에도 회전을 반영할 수 있어 원시 태그 크기를 쓴다.
                size=(int(picture.tag_v2.get(256,picture.width)),int(picture.tag_v2.get(257,picture.height))) if picture.format=='TIFF' else picture.size
                return picture.format,orientation,size

    def png_orientation(self,filename,data):
        import struct
        Image,_=pillow_reader()
        with io.BytesIO(data) if data is not None else open(filename,'rb') as stream:
            if stream.read(8)!=b'\x89PNG\r\n\x1a\n':return 1
            while True:
                header=stream.read(8)
                if len(header)!=8:return 1
                size,kind=struct.unpack('>I4s',header)
                if kind==b'IEND':return 1
                if kind==b'eXIf':
                    if size>16*1024*1024:raise ValueError('PNG EXIF 메타데이터가 너무 큽니다.')
                    exif=Image.Exif();exif.load(stream.read(size));return exif.get(274,1)
                stream.seek(size+4,1)



    def read_qt(self,filename,data,number,bounds,fmt,orientation=1):
        from PySide6.QtCore import QBuffer,QByteArray,QIODevice,QSize,Qt
        from PySide6.QtGui import QImageReader,QImage,QPainter,QColorSpace,QTransform
        reader=QImageReader();buffer=None
        try:
            if fmt=='PNG' and orientation is None:orientation=self.png_orientation(filename,data)
            if data is not None:
                buffer=QBuffer();buffer.setData(QByteArray(data));buffer.open(QIODevice.OpenModeFlag.ReadOnly)
                reader.setDevice(buffer)
            else:reader.setFileName(filename)
            reader.setAutoTransform(True);reader.setQuality(100)
            if number and not reader.jumpToImage(number):raise ValueError('Qt에서 해당 TIFF 쪽을 읽지 못했습니다.')
            size=reader.size()
            if not size.isValid():raise ValueError(reader.errorString())
            native_transform=reader.transformation().value
            manual=orientation if native_transform==0 else 1
            rotated=bool(native_transform & 4) or manual in (5,6,7,8)
            target=QSize(*(tuple(reversed(bounds)) if rotated else bounds))
            if size.width()>target.width() or size.height()>target.height():
                reader.setScaledSize(size.scaled(target,Qt.AspectRatioMode.KeepAspectRatio))
            picture=reader.read()
            if picture.isNull():raise ValueError(reader.errorString())
            # Qt's PNG/WebP plugins may not expose EXIF orientation. Apply it only
            # when the handler did not advertise a transform, avoiding double rotation.
            if manual in (2,3,4):picture=picture.mirrored(manual in (2,3),manual in (3,4))
            elif manual==5:picture=picture.transformed(QTransform(0,1,1,0,0,0))
            elif manual==6:picture=picture.transformed(QTransform().rotate(90))
            elif manual==7:picture=picture.transformed(QTransform(0,-1,-1,0,0,0))
            elif manual==8:picture=picture.transformed(QTransform().rotate(270))
            if picture.width()>bounds[0] or picture.height()>bounds[1]:
                picture=picture.scaled(QSize(*bounds),Qt.AspectRatioMode.KeepAspectRatio,Qt.TransformationMode.SmoothTransformation)
            if picture.colorSpace().isValid():picture=picture.convertedToColorSpace(QColorSpace(QColorSpace.NamedColorSpace.SRgb))
            if picture.hasAlphaChannel():
                canvas=QImage(picture.size(),QImage.Format.Format_RGB888);canvas.fill(Qt.GlobalColor.white)
                painter=QPainter(canvas);painter.drawImage(0,0,picture);painter.end();picture=canvas
            else:picture=picture.convertToFormat(QImage.Format.Format_RGB888)
            return bytes(picture.constBits()),picture.width(),picture.height(),picture.bytesPerLine()
        finally:
            # Detach the native reader BEFORE releasing its Python-owned QBuffer.
            reader.setDevice(None)
            if buffer is not None:buffer.close()

    def read_pillow(self,filename,data,number,bounds,fmt,orientation=1):
        Image,ImageOps=pillow_reader()
        with Image.open(io.BytesIO(data) if data is not None else filename) as picture:
            picture.seek(number)
            if picture.format=='TIFF':picture.load()
            rotated=picture.getexif().get(274,1) in (5,6,7,8)
            picture.thumbnail(tuple(reversed(bounds)) if rotated else bounds,Image.Resampling.LANCZOS,reducing_gap=2.0)
            with ImageOps.exif_transpose(picture) as normalized:
                # Opaque RGB JPEG needs neither an alpha channel nor background compositing.
                # Keep orientation, thumbnail decoding and all other format paths unchanged.
                if picture.format=='JPEG' and normalized.mode=='RGB':
                    return normalized.tobytes(),normalized.width,normalized.height,normalized.width*3
                with normalized.convert('RGBA') as rgba, Image.new('RGB',normalized.size,'white') as canvas:
                    canvas.paste(rgba,mask=rgba.getchannel('A'))
                    return canvas.tobytes(),canvas.width,canvas.height,canvas.width*3

    def smaller_frame(self,path,number,bounds,mode):
        """Reuse an oriented, colour-managed preview for a smaller thumbnail."""
        from PySide6.QtCore import QSize,Qt
        from PySide6.QtGui import QImage
        candidates=[(key,frame) for key,frame in self.frames.items()
                    if key[:2]==(path,number) and key[3]==mode and
                    key[2][0]>=bounds[0] and key[2][1]>=bounds[1]]
        if not candidates:return None
        key,frame=min(candidates,key=lambda item:item[1][1]*item[1][2])
        raw,width,height,stride,engine,note=frame
        picture=QImage(raw,width,height,stride,QImage.Format.Format_RGB888)
        if width>bounds[0] or height>bounds[1]:
            picture=picture.scaled(QSize(*bounds),Qt.AspectRatioMode.KeepAspectRatio,
                                   Qt.TransformationMode.SmoothTransformation)
        self.frames.move_to_end(key)
        return (bytes(picture.constBits()),picture.width(),picture.height(),
                picture.bytesPerLine(),engine,note)

    def read(self,path,number,bounds,mode='auto',reuse_preview=False):
        if number<0:raise ValueError('그림 쪽 번호가 올바르지 않습니다.')
        bounds=tuple(max(1,min(IMAGE_PREVIEW_MAX_SIDE,int(v))) for v in bounds)
        validated=validate_image_source(path)  # Revalidate even a decoded-cache hit.
        key=(path,number,bounds,mode);frame=self.frames.pop(key,None)
        if frame is not None:self.frames[key]=frame;return frame
        if reuse_preview:
            frame=self.smaller_frame(path,number,bounds,mode)
            if frame is not None:return frame
        filename,data=self.source(path,validated)
        fmt,orientation,original_size=self.image_format(filename,data,number)
        if fmt=='PNG' and orientation is None:orientation=self.png_orientation(filename,data)
        width,height=reversed(original_size) if orientation in (5,6,7,8) else original_size
        scale=min(1.0,bounds[0]/width,bounds[1]/height,
                  math.sqrt(IMAGE_PREVIEW_MAX_PIXELS/(width*height)))
        target=(max(1,min(bounds[0],math.floor(width*scale))),
                max(1,min(bounds[1],math.floor(height*scale))))
        first=mode if mode in ('qt','pillow') else ('pillow' if fmt=='TIFF' else 'qt')
        engines=[first]+([e for e in ('qt','pillow') if e!=first] if first!='pillow' else [])
        errors=[]
        for engine in engines:
            try:
                raw,width,height,stride=getattr(self,'read_'+engine)(filename,data,number,target,fmt,orientation)
                if (not 0<width<=bounds[0] or not 0<height<=bounds[1] or
                        width*height>IMAGE_PREVIEW_MAX_PIXELS or len(raw)!=stride*height):
                    raise ValueError('그림 디코더의 출력 크기가 올바르지 않습니다.')
                frame=(raw,width,height,stride,engine,' / '.join(errors))
                if len(raw)<=self.FRAME_LIMIT:
                    self.frames[key]=frame;self.frame_bytes+=len(raw)
                    while self.frame_bytes>self.FRAME_LIMIT:self.frame_bytes-=len(self.frames.popitem(last=False)[1][0])
                return frame
            except Exception as exc:errors.append(f'{engine}: {exc}')
        raise ValueError('그림을 읽지 못했습니다.\n'+'\n'.join(errors))


def image_worker():
    reader=DirectImageReader()
    for line in sys.stdin.buffer:
        request={};raw=b''
        try:
            request=json.loads(line)
            if request['op']=='release':
                reader.close();result={}
            elif request['op']=='animation':
                filename,data=reader.source(request['path'],validate_image_source(request['path']))
                if data is None:
                    if Path(filename).stat().st_size>64*1024*1024:raise ValueError('64MB 초과 GIF는 첫 프레임만 표시합니다.')
                    data=Path(filename).read_bytes()
                fmt,_orientation,size=reader.image_format(filename,data,0)
                if fmt!='GIF' or len(data)>64*1024*1024 or size[0]*size[1]>IMAGE_PREVIEW_MAX_PIXELS or max(size)>IMAGE_PREVIEW_MAX_SIDE:
                    raise ValueError('GIF 재생 한도를 넘으면 첫 프레임만 표시합니다.')
                raw=data;result={'animation':True,'width':size[0],'height':size[1]}
            else:
                side=request.get('max_side',1800) if request['op']=='preview' else request.get('payload',{}).get('thumb_side',370)
                side=max(64,min(IMAGE_PREVIEW_MAX_SIDE,side))
                bounds=(side,side) if request['op']=='preview' else (round(side*280/370),side)
                raw,width,height,stride,engine,note=reader.read(request['path'],request['page'],bounds,
                    request.get('payload',{}).get('engine','auto'),reuse_preview=request['op']!='preview')
                result=dict(width=width,height=height,stride=stride,engine=engine,note=note)
            response={'id':request['id'],'ok':True,**result}
        except Exception as exc:raw=b'';response={'id':request.get('id'),'ok':False,'error':str(exc)}
        response['nbytes']=len(raw)
        sys.stdout.buffer.write((json.dumps(response,ensure_ascii=True)+'\n').encode('ascii'))
        sys.stdout.buffer.write(raw);sys.stdout.buffer.flush()
    reader.close()




def natural_path_key(value):
    # Tag tokens so names beginning with a digit and a letter remain comparable.
    return tuple(tuple((1,int(t)) if t.isdecimal() else (0,t.casefold())
                       for t in re.split(r'(\d+)',part))
                 for part in str(value).replace('\\','/').split('/'))


def supported_input(path):
    return Path(path).suffix.lower() in INPUT_EXTENSIONS | VECTOR_EXTENSIONS | DOCUMENT_EXTENSIONS or Path(path).is_dir()








def vector_worker():
    try:
        job=json.loads(sys.stdin.buffer.readline())
        result=probe_vector_file(job['path'],bool(job.get('verify',False)))
    except Exception as exc:result={'error':f'{type(exc).__name__}: {exc}'}
    sys.stdout.buffer.write((json.dumps(result,ensure_ascii=True)+'\n').encode('ascii'))
    sys.stdout.buffer.flush()
    return 0






def document_engine_roots():
    roots=[Path(getattr(sys,'_MEIPASS',Path(__file__).resolve().parent)),Path(sys.executable).resolve().parent,Path(__file__).resolve().parent]
    return list(dict.fromkeys(roots))




def clean_engine_environment():
    env=os.environ.copy()
    for key in ('QT_PLUGIN_PATH','QT_QPA_PLATFORM_PLUGIN_PATH','PYTHONHOME','PYTHONPATH'):
        env.pop(key,None)
    if getattr(sys,'frozen',False):
        for key in ('LD_LIBRARY_PATH','DYLD_LIBRARY_PATH'):
            if key+'_ORIG' in env:env[key]=env[key+'_ORIG']
            else:env.pop(key,None)
        bundle=os.path.normcase(os.path.abspath(sys._MEIPASS))
        env['PATH']=os.pathsep.join(part for part in env.get('PATH','').split(os.pathsep)
            if part and not (os.path.normcase(os.path.abspath(part))==bundle or
                os.path.normcase(os.path.abspath(part)).startswith(bundle+os.sep)))
    return env


def run_document_engine(args,work):
    import subprocess
    log=Path(work)/'engine.log'
    with log.open('wb') as output:
        # Child inherits the dedicated Windows Job / POSIX process group from this worker.
        kernel=None;previous=None
        if sys.platform=='win32' and getattr(sys,'frozen',False):
            import ctypes
            kernel=ctypes.windll.kernel32;previous=ctypes.create_unicode_buffer(32768)
            kernel.GetDllDirectoryW(len(previous),previous)
            kernel.SetDllDirectoryW(None)
        try:
            proc=subprocess.Popen([str(a) for a in args],cwd=str(work),stdout=output,stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,env=clean_engine_environment(),
                creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        finally:
            if kernel is not None:kernel.SetDllDirectoryW(previous.value or None)
        try:code=proc.wait(timeout=DOCUMENT_TIMEOUT_SECONDS)
        except BaseException:
            proc.kill();proc.wait();raise
    if code:
        with log.open('rb') as stream:
            stream.seek(max(0,log.stat().st_size-2000));detail=stream.read().decode('utf-8','replace')
        raise ValueError(f'변환 엔진 종료 코드 {code}\n{detail}')


def psd_to_pdf(source,target,emit=lambda _stage:None):
    from psd_tools import PSDImage
    import viewer_pdf_engine
    emit('PSD 합성 이미지 확인')
    import struct
    with open(source,'rb') as stream:header=stream.read(26)
    if len(header)!=26 or header[:4]!=b'8BPS':raise ValueError('PSD 헤더가 올바르지 않습니다.')
    height,width=struct.unpack('>II',header[14:22])
    if not width or not height or width*height>80_000_000:raise ValueError('8천만 픽셀 이내의 PSD를 선택하세요.')
    psd=PSDImage.open(source)
    if not psd.has_preview():
        raise ValueError('PSD에 저장된 합성 이미지가 없습니다. Photoshop에서 호환성 최대화로 저장하거나 PDF 사본을 저장해 주세요.')
    if psd.width*psd.height>80_000_000:raise ValueError('8천만 픽셀을 넘는 PSD입니다. Photoshop에서 PDF로 저장해 주세요.')
    picture=psd.topil()
    if picture is None:raise ValueError('PSD 합성 이미지를 읽지 못했습니다.')
    if picture.mode not in ('RGB','RGBA','L','LA','P'):
        original=picture;picture=original.convert('RGB');original.close()
    emit('PSD → PDF 저장')
    try:
        png=io.BytesIO();picture.save(png,format='PNG')
        # PSD is a raster source; retain all pixels and use 96 dpi for its PDF page size.
        with viewer_pdf_engine.open() as doc:
            page=doc.new_page(width=picture.width*.75,height=picture.height*.75)
            page.insert_image(page.rect,stream=png.getvalue());doc.save(target,deflate=True)
    finally:picture.close()




def office_to_pdf(source,target,work,engine,emit=lambda _stage:None):
    import shutil
    executable=find_document_engine('office',engine)
    if not executable:raise ValueError('LibreOffice를 찾지 못했습니다. LibreOffice를 설치한 뒤 다시 열어주세요.')
    profile=Path(work)/'lo_profile';profile.mkdir(parents=True,exist_ok=True)
    user=profile/'user';user.mkdir(exist_ok=True)
    # Separate profile; disable macros and external-link updates for this conversion only.
    (user/'registrymodifications.xcu').write_text('''<?xml version="1.0" encoding="UTF-8"?>
<oor:items xmlns:oor="http://openoffice.org/2001/registry">
<item oor:path="/org.openoffice.Office.Common/Security/Scripting"><prop oor:name="MacroSecurityLevel" oor:op="fuse"><value>3</value></prop></item>
<item oor:path="/org.openoffice.Office.Calc/Content/Update"><prop oor:name="Link" oor:op="fuse"><value>0</value></prop></item>
<item oor:path="/org.openoffice.Office.Writer/Content/Update"><prop oor:name="Link" oor:op="fuse"><value>0</value></prop></item>
</oor:items>''',encoding='utf-8')
    emit(document_theme(source)[0]+' → PDF 저장')
    suffix=Path(source).suffix.lower()
    filter_name='calc_pdf_Export' if suffix.startswith('.xls') else 'impress_pdf_Export' if suffix.startswith('.ppt') else 'writer_pdf_Export'
    run_document_engine([executable,'-env:UserInstallation='+profile.resolve().as_uri(),'--headless','--nologo','--nodefault',
        '--norestore','--convert-to','pdf:'+filter_name,'--outdir',str(Path(work).resolve()),str(Path(source).resolve())],work)
    result=Path(work)/(Path(source).stem+'.pdf')
    if not result.is_file():raise ValueError('Office 변환 결과가 없습니다. 암호·손상 여부를 확인하거나 원본 프로그램에서 PDF로 저장해 주세요.')
    if result.resolve()!=Path(target).resolve():shutil.move(str(result),str(target))


class NativeHangulPDF:
    """Offline, approximate HWP5/HWPX reading using hwpx + Qt QTextDocument.

    Text remains text in the PDF. Unknown objects are reported, never advertised
    as an exact Hancom print engine. XML and resources never resolve URLs.
    """
    HP='{http://www.hancom.co.kr/hwpml/2011/paragraph}'
    HH='{http://www.hancom.co.kr/hwpml/2011/head}'
    HC='{http://www.hancom.co.kr/hwpml/2011/core}'


    @staticmethod
    def local(node):return str(node.tag).rsplit('}',1)[-1]

    @staticmethod
    def number(value,default=0):
        try:
            result=float(value)
            return result if math.isfinite(result) else default
        except (TypeError,ValueError):return default

    def unit(self,value,default=0):return self.number(value,default*100)/100

    @staticmethod
    def color(value,default='#000000'):
        return value if re.fullmatch(r'#[0-9a-fA-F]{6}',str(value or '')) else default

    def note(self,message):
        if message not in self.notes:self.notes.append(message)

    def border_css(self,ref):
        node=self.borders.get(ref);styles=[]
        if node is None:return ''
        for side in ('left','right','top','bottom'):
            edge=node.find(self.HH+side+'Border')
            if edge is not None and edge.get('type','NONE')!='NONE':
                width=self.number(str(edge.get('width','.1')).split()[0],.1)*72/25.4
                styles.append(f'border-{side}:{max(.1,min(width,10))}pt solid {self.color(edge.get("color"))}')
        fill=node.find('.//'+self.HC+'winBrush')
        if fill is not None and fill.get('faceColor','none').lower()!='none':
            styles.append('background-color:'+self.color(fill.get('faceColor'),'#ffffff'))
        return ';'.join(styles)

    def paragraph_css(self,element):
        node=self.para.get(element.get('paraPrIDRef'));styles=[]
        if node is None:return ''
        align=node.find(self.HH+'align')
        if align is not None:
            value={'CENTER':'center','RIGHT':'right','BOTH':'justify','DISTRIBUTE':'justify'}.get(align.get('horizontal'),'left')
            styles.append('text-align:'+value)
        spacing=node.find('.//'+self.HH+'lineSpacing')
        if spacing is not None:
            value=self.number(spacing.get('value'),160)
            line=str(max(.8,min(value/100,4))) if spacing.get('type','PERCENT')=='PERCENT' else f'{max(5,value/100)}pt'
            styles.append('line-height:'+line)
        margin=node.find('.//'+self.HH+'margin')
        if margin is not None:
            for child in margin:
                key={'left':'margin-left','right':'margin-right','prev':'margin-top','next':'margin-bottom','intent':'text-indent'}.get(self.local(child))
                if key:styles.append(f'{key}:{max(-100,min(500,self.unit(child.get("value"))))}pt')
        return ';'.join(styles)

    def run_css(self,run):
        node=self.char.get(run.get('charPrIDRef'))
        if node is None:return ''
        values=[f'font-size:{max(3,min(150,self.unit(node.get("height"),10)))}pt','color:'+self.color(node.get('textColor'))]
        if node.find(self.HH+'bold') is not None:values.append('font-weight:bold')
        if node.find(self.HH+'italic') is not None:values.append('font-style:italic')
        u=node.find(self.HH+'underline')
        if u is not None and u.get('type','NONE')!='NONE':values.append('text-decoration:underline')
        return ';'.join(values)

    def text_node(self,node):
        text=html.escape(node.text or '')
        for child in node:
            name=self.local(child)
            if name in ('lineBreak','br'):text+='<br/>'
            elif name=='tab':text+='&#160;&#160;&#160;&#160;'
            elif name=='autoNum':text+='__VIEWER_PAGE__'
            else:text+=self.text_node(child)
            text+=html.escape(child.tail or '')
        return text


    def table(self,node):
        size=node.find(self.HP+'sz')
        width=min(self.body_width,self.unit(size.get('width'),self.body_width)) if size is not None else self.body_width
        output=[f'<table style="width:{max(10,width)}pt;{self.border_css(node.get("borderFillIDRef"))}">']
        defaults=node.find(self.HP+'inMargin')
        for row in node.findall(self.HP+'tr'):
            output.append('<tr>')
            for cell in row.findall(self.HP+'tc'):
                span=cell.find(self.HP+'cellSpan');col=max(1,min(256,int(self.number(span.get('colSpan'),1)))) if span is not None else 1
                rows=max(1,min(256,int(self.number(span.get('rowSpan'),1)))) if span is not None else 1
                styles=[self.border_css(cell.get('borderFillIDRef'))]
                margin=cell.find(self.HP+'cellMargin')
                if margin is None:margin=defaults
                if margin is not None:
                    for side in ('left','right','top','bottom'):styles.append(f'padding-{side}:{max(0,self.unit(margin.get(side)))}pt')
                else:styles.append('padding:2pt')
                dimensions=cell.find(self.HP+'cellSz')
                if dimensions is not None:
                    padding=sum(max(0,self.unit(margin.get(side))) for side in ('left','right')) if margin is not None else 4
                    styles.append(f'width:{max(1,self.unit(dimensions.get("width"))-padding-1)}pt')
                sub=cell.find(self.HP+'subList')
                if sub is not None:
                    styles.append('vertical-align:'+{'CENTER':'middle','BOTTOM':'bottom'}.get(sub.get('vertAlign'),'top'))
                content=''.join(self.paragraph(p,allow_float=False) for p in sub if self.local(p)=='p') if sub is not None else ''
                output.append(f'<td colspan="{col}" rowspan="{rows}" style="{";".join(styles)}">{content or "&#160;"}</td>')
            output.append('</tr>')
        return ''.join(output)+'</table>'

    def object_html(self,node,allow_float=True):
        name=self.local(node)
        if name=='tbl':content=self.table(node)
        elif name=='pic':content=self.picture(node)
        elif name=='equation':
            self.note('수식은 수식 스크립트 문자로 표시했습니다.')
            content='<span>'+html.escape(''.join(node.itertext()))+'</span>'
        elif name in ('rect','ellipse','line','polygon','curve','container','arc','connectLine','ole','textart'):
            texts=[self.paragraph(p,allow_float=False) for p in node.findall('.//'+self.HP+'drawText/'+self.HP+'subList/'+self.HP+'p')]
            self.note('도형·글상자는 내용과 단순 테두리로 표시합니다. 3D·OLE·그룹 도형은 원본과 다를 수 있습니다.')
            line=node.find(self.HP+'lineShape');box_style='padding:0;'
            if line is not None and line.get('style','NONE')!='NONE':
                box_style+=f'border:{max(.1,self.unit(line.get("width"),.5))}pt solid {self.color(line.get("color"))};'
            fill=node.find('.//'+self.HC+'winBrush')
            if fill is not None and fill.get('faceColor','none').lower()!='none':box_style+='background-color:'+self.color(fill.get('faceColor'),'#ffffff')+';'
            content='<div style="'+box_style+'">'+(''.join(texts) or '['+{'ole':'OLE 개체','line':'선','ellipse':'타원'}.get(name,'도형')+']')+'</div>'
        else:return ''
        pos=node.find(self.HP+'pos');size=node.find(self.HP+'sz')
        if allow_float and pos is not None and pos.get('treatAsChar')=='0':
            if pos.get('vertRelTo') in ('PAPER','PAGE') and pos.get('horzRelTo') in ('PAPER','PAGE') and size is not None:
                width=max(1,self.unit(size.get('width')));height=max(1,self.unit(size.get('height')))
                paperx=0 if pos.get('horzRelTo')=='PAPER' else self.margin['left']
                papery=0 if pos.get('vertRelTo')=='PAPER' else self.margin['top']
                availw=self.width if pos.get('horzRelTo')=='PAPER' else self.body_width
                availh=self.height if pos.get('vertRelTo')=='PAPER' else self.body_height
                x=paperx+self.unit(pos.get('horzOffset'));y=papery+self.unit(pos.get('vertOffset'))
                if pos.get('horzAlign')=='CENTER':x+=(availw-width)/2
                elif pos.get('horzAlign')=='RIGHT':x+=availw-width
                if pos.get('vertAlign')=='CENTER':y+=(availh-height)/2
                elif pos.get('vertAlign')=='BOTTOM':y+=availh-height
                self.floats.append((content,(x,y,x+width,y+height),node.get('textWrap')=='BEHIND_TEXT'))
                return ''
            self.note('문단을 기준으로 떠 있는 개체는 문단 사이에 배치했습니다.')
        return content

    def paragraph(self,node,allow_float=True):
        css=self.paragraph_css(node);parts=[];inline=[];has_content=False
        def flush():
            if inline:parts.append(f'<p style="{css}">'+''.join(inline)+'</p>');inline.clear()
        for run in node:
            if self.local(run)!='run':continue
            style=self.run_css(run)
            for child in run:
                name=self.local(child)
                if name=='t':
                    value=self.text_node(child)
                    if value:inline.append(f'<span style="{style}">{value}</span>');has_content=True
                elif name=='ctrl':
                    for control in child:
                        key=self.local(control)
                        if key=='autoNum':inline.append('__VIEWER_PAGE__');has_content=True
                        elif key in ('footNote','endNote'):
                            self.note('각주·미주는 해당 문단 뒤에 표시했습니다.');flush()
                            parts.extend(self.paragraph(p,False) for p in control.findall('.//'+self.HP+'subList/'+self.HP+'p'))
                        elif key=='colPr' and self.number(control.get('colCount'),1)>1:self.note('다단 본문은 한 단으로 이어서 표시했습니다.')
                elif name not in ('secPr','linesegarray'):
                    content=self.object_html(child,allow_float)
                    if content:flush();parts.append(content);has_content=True
        flush()
        return ''.join(parts) if parts else ('<p>&#160;</p>' if not len(node.findall('.//'+self.HP+'pos')) and not has_content else '')

    def geometry(self,section):
        page=section.find('.//'+self.HP+'pagePr')
        self.width=self.unit(page.get('width'),595.28) if page is not None else 595.28
        self.height=self.unit(page.get('height'),841.89) if page is not None else 841.89
        if page is not None and page.get('landscape','WIDELY')!='WIDELY':self.width,self.height=self.height,self.width
        m=page.find(self.HP+'margin') if page is not None else None
        self.margin={k:max(0,self.unit(m.get(k),v)) if m is not None else v for k,v in
                     {'left':56.7,'right':56.7,'top':56.7,'bottom':56.7,'header':28.3,'footer':28.3}.items()}
        self.body_width=self.width-self.margin['left']-self.margin['right']
        self.body_height=self.height-self.margin['top']-self.margin['bottom']
        if not (40<=self.width<=4000 and 40<=self.height<=4000 and self.body_width>20 and self.body_height>20):
            raise ValueError('지원 범위를 벗어난 한글 용지/여백입니다.')



def hwp_to_pdf(source,target,job_name='',emit=lambda _stage:None):
    reader=NativeHangulPDF(source,emit)
    notes=reader.write(target)
    if reader.hwp_report:notes.append('HWP5 변환 보고: '+reader.hwp_report)
    return notes





def document_worker():
    if sys.platform!='win32':
        try:os.setsid()
        except OSError:pass
    def send(value):
        sys.stdout.buffer.write((json.dumps(value,ensure_ascii=True)+'\n').encode('ascii'));sys.stdout.buffer.flush()
    try:
        job=json.loads(sys.stdin.buffer.readline())
        result=convert_document_job(job,lambda stage:send({'progress':stage}))
        send({'result':result})
    except Exception as exc:send({'result':{'error':f'{type(exc).__name__}: {exc}'}})
    return 0





def input_origin(path):
    p=Path(path)
    return str(p/(p.name+'.pdf')) if p.is_dir() else str(p)


def neighboring_inputs(path,include_containers=False,book_library=None):
    """이름·파일 속성만 읽는다. 책 폴더 탐색은 해당 폴더에서 찾은 ZIP/CBZ로 제한한다."""
    current=Path(path).resolve();entries=[];found=False
    current_key=os.path.normcase(str(current))
    # A directly opened photo stays in its own folder's photo sequence, even
    # when an earlier archive/folder browsing context enabled containers.
    photo_navigation=current.suffix.lower() in IMAGE_EXTENSIONS and not current.is_dir()
    if photo_navigation:include_containers=False;book_library=None
    folder_navigation=include_containers and current.is_dir()
    if book_library:
        root=Path(book_library['root']).resolve()
        for value in book_library.get('paths',[]):
            candidate=Path(value)
            if candidate.suffix.lower() not in ARCHIVE_EXTENSIONS or root not in candidate.parents:continue
            if candidate.is_symlink() or not candidate.is_file():continue
            entries.append(str(candidate))
            if os.path.normcase(str(candidate))==current_key:found=True
        entries=sorted(set(entries),key=lambda p:(natural_path_key(Path(p).relative_to(root)),p))
    else:
        allowed=INPUT_EXTENSIONS if include_containers else IMAGE_EXTENSIONS|TEXT_EXTENSIONS|{'.pdf'}
        file_types=IMAGE_EXTENSIONS if photo_navigation else (ARCHIVE_EXTENSIONS if folder_navigation else allowed)
        with os.scandir(current.parent) as items:
            for item in items:
                try:
                    if os.path.normcase(item.path)==current_key:
                        entries.append(str(current));found=True;continue
                    if ((Path(item.name).suffix.lower() in file_types and item.is_file(follow_symlinks=False)) or
                            (include_containers and item.is_dir(follow_symlinks=False))):
                        entries.append(str(Path(item.path)))
                except OSError:continue
        entries.sort(key=lambda p:(natural_path_key(Path(p).name),p))
    if not found:raise ValueError('현재 항목을 같은 폴더에서 찾지 못했습니다. 파일을 다시 열어주세요.')
    index=next((i for i,p in enumerate(entries) if os.path.normcase(p)==os.path.normcase(str(current))),None)
    if index is None:raise ValueError('현재 항목을 같은 폴더에서 찾지 못했습니다. 파일을 다시 열어주세요.')
    return {'previous':entries[index-1] if index>0 else '',
            'next':entries[index+1] if index+1<len(entries) else ''}


def next_sibling_input(path,direction,include_containers=False,book_library=None):
    return neighboring_inputs(path,include_containers,book_library)['previous' if direction<0 else 'next']


def import_input_pages(path, directory, emit, progress=None):
    """Stream immutable page PDFs and their thumbnails from a separate process."""
    import zipfile
    import shutil
    import warnings
    import viewer_pdf_engine
    root=Path(path);directory=Path(directory);directory.mkdir(parents=True,exist_ok=True)
    errors=[];page_count=0;completed=0;total=0;members_by_path={};last_scan=0
    progress=progress or (lambda data:None)

    def report(name='',frame=0,frames=0):
        fraction=frame/frames if frames else 0
        progress({'phase':'convert','done':completed,'total':total,'fraction':fraction,
                  'name':str(name),'frame':frame,'frames':frames,'pages':page_count,'errors':len(errors)})

    def publish(data):
        nonlocal page_count
        page_count+=data['count'];emit(data)

    def scan(found,force=False):
        nonlocal last_scan
        now=time.monotonic()
        if force or now-last_scan>=.1:
            progress({'phase':'scan','found':found,'name':str(root)});last_scan=now

    def image_pages(source, label):
        try:
            from PIL import Image, ImageOps
        except ImportError:
            raise ValueError('그림 읽기 모듈이 필요합니다. 실행에 사용하는 Python의 CMD에서\n'
                             'python -m pip install -U Pillow') from None
        with warnings.catch_warnings():
            warnings.simplefilter('error',Image.DecompressionBombWarning)
            with Image.open(source) as picture:
                frames=getattr(picture,'n_frames',1) if picture.format=='TIFF' else 1
                for index in range(frames):
                    target=None;published=False
                    try:
                        report(label,index,frames)
                        picture.seek(index)
                        dpi=picture.info.get('dpi',(96,96))
                        try: dpi=float(dpi[0] if isinstance(dpi,(tuple,list)) else dpi)
                        except (TypeError,ValueError,IndexError): dpi=96
                        if not math.isfinite(dpi) or not 20<=dpi<=2400:dpi=96
                        orientation=picture.getexif().get(274,1)
                        # Load before exif_transpose: TIFF's decoder may already apply orientation.
                        picture.load()
                        normalized=ImageOps.exif_transpose(picture)
                        try:
                            width,height=normalized.size
                            page_w,page_h=width*72/dpi,height*72/dpi
                            scale=min(max(1,1/min(page_w,page_h)),14400/max(page_w,page_h))
                            page_w,page_h=page_w*scale,page_h*scale
                            target=directory/(uuid.uuid4().hex+'.pdf')
                            with viewer_pdf_engine.open() as doc:
                                page=doc.new_page(width=page_w,height=page_h)
                                if picture.format=='JPEG' and orientation==1:
                                    # Keep the original JPEG stream; no second lossy compression.
                                    page.insert_image(page.rect,filename=str(source))
                                else:
                                    mode='RGBA' if 'A' in normalized.getbands() or 'transparency' in normalized.info else 'RGB'
                                    with normalized.convert(mode) as bitmap:
                                        stream=io.BytesIO();bitmap.save(stream,format='PNG')
                                    page.insert_image(page.rect,stream=stream.getvalue())
                                doc.save(str(target),deflate=True)
                                zoom=min(280/page_w,370/page_h)
                                pix=page.get_pixmap(matrix=viewer_pdf_engine.Matrix(zoom,zoom),alpha=False)
                                thumb=base64.b64encode(pix.tobytes('png')).decode('ascii')
                            publish({'path':str(target),'count':1,'source_path':str(label),
                                     'source_number':index,'thumbnail':thumb})
                            published=True
                        finally:normalized.close()
                    except Exception as exc:
                        errors.append(f'{label} · {index+1}쪽: {exc}')
                    finally:
                        if target is not None and not published:target.unlink(missing_ok=True)
                        report(label,index+1,frames)

    def read_file(source, label=None):
        nonlocal completed
        label=label or str(source)
        suffix=source.suffix.lower()
        archive_input=suffix in ARCHIVE_EXTENSIONS
        start_count=completed
        report(label)
        try:
            if suffix=='.pdf':
                with viewer_pdf_engine.open(source) as doc:
                    if not doc.is_pdf or doc.needs_pass:raise ValueError('암호가 없는 PDF를 선택하세요.')
                    if doc.page_count:publish({'path':str(source),'count':doc.page_count})
            elif suffix in IMAGE_EXTENSIONS:image_pages(source,label)
            elif suffix in ARCHIVE_EXTENSIONS:
                with zipfile.ZipFile(source) as archive:
                    members=members_by_path[source]
                    for member in members:
                        staged=directory/(uuid.uuid4().hex+Path(member.filename).suffix.lower())
                        member_label=str(source)+'/'+member.filename.replace('\\','/')
                        report(member_label)
                        try:
                            if member.flag_bits&1:raise ValueError('암호가 설정된 그림은 먼저 압축을 풀어주세요.')
                            if member.file_size>256*1024*1024:raise ValueError('그림 한 파일이 256MB를 초과합니다.')
                            # Generated path only: never extract archive member paths into the filesystem.
                            with archive.open(member) as incoming,staged.open('xb') as output:
                                shutil.copyfileobj(incoming,output,1024*1024)
                            image_pages(staged,member_label)
                        except Exception as exc:errors.append(f'{member_label}: {exc}')
                        finally:
                            staged.unlink(missing_ok=True);completed+=1;report(member_label)
        except Exception as exc:errors.append(f'{label}: {exc}')
        finally:
            if archive_input:completed=start_count+len(members_by_path.get(source,()))
            else:completed+=1
            report(label)

    scan(0,True)
    entries=[]
    if root.is_dir():
        def walk_error(exc):errors.append(str(exc))
        for base,dirs,files in os.walk(root,followlinks=False,onerror=walk_error):
            dirs[:]=[d for d in dirs if not d.startswith('.') and d!='__MACOSX'
                     and not Path(base,d).is_symlink()]
            entries.extend(Path(base,f) for f in files if not f.startswith('.')
                           and Path(f).suffix.lower() in INPUT_EXTENSIONS)
            scan(len(entries))
        entries.sort(key=lambda p:(natural_path_key(p.relative_to(root)),str(p)))
    elif root.is_file():entries=[root]
    else:errors.append(f'파일 또는 폴더를 찾을 수 없습니다: {root}')
    ready=[]
    for source in entries:
        if source.suffix.lower() in ARCHIVE_EXTENSIONS:
            try:
                with zipfile.ZipFile(source) as archive:
                    members=sorted((i for i in archive.infolist() if not i.is_dir()
                        and Path(i.filename).suffix.lower() in IMAGE_EXTENSIONS
                        and not any(p.startswith('.') or p=='__MACOSX' for p in i.filename.replace('\\','/').split('/'))),
                        key=lambda i:(natural_path_key(i.filename),i.filename))
                if not members:raise ValueError('압축파일에 지원하는 그림이 없습니다.')
                members_by_path[source]=members;total+=len(members);ready.append(source)
            except Exception as exc:errors.append(f'{source}: {exc}')
        else:total+=1;ready.append(source)
        scan(total)
    report(root)
    for source in ready:read_file(source)
    if not page_count and not errors:errors.append('읽을 수 있는 PDF 또는 그림이 없습니다.')
    return {'count':page_count,'errors':errors,'done':completed,'total':total}


def discover_input_pages(path,emit,progress=None,images_only=False,directory=None,text_options=None,text_encoding='auto'):
    """Catalog originals only. Decode pixels later in the visible-page image worker."""
    import zipfile
    root=Path(path);progress=progress or (lambda _data:None);folder_input=root.is_dir()
    extensions=IMAGE_EXTENSIONS|ARCHIVE_EXTENSIONS if images_only else INPUT_EXTENSIONS
    errors=[];records=[];pending=[];page_count=0;last_report=0;last_publish=0
    def report(data,force=False):
        nonlocal last_report
        now=time.monotonic()
        if force or now-last_report>=.08:progress(data);last_report=now
    report({'phase':'scan','found':0,'name':str(root)},True)
    entries=[]
    if folder_input:
        for base,dirs,files in os.walk(root,followlinks=False,onerror=lambda exc:errors.append(str(exc))):
            dirs[:]=[d for d in dirs if not d.startswith('.') and d!='__MACOSX' and not Path(base,d).is_symlink()]
            entries.extend(Path(base,f) for f in files if not f.startswith('.') and Path(f).suffix.lower() in extensions)
            report({'phase':'scan','found':len(entries),'name':str(root)})
        entries.sort(key=lambda p:(natural_path_key(p.relative_to(root)),str(p)))
    elif root.is_file() and root.suffix.lower() in extensions:entries=[root]
    else:errors.append(f'파일 또는 폴더를 찾을 수 없습니다: {root}')
    book_library=None;book_path=''
    if folder_input and not images_only:
        books=[source for source in entries if source.suffix.lower() in ARCHIVE_EXTENSIONS and not source.is_symlink()]
        if books:
            book_library={'root':str(root.resolve()),'paths':[str(source.resolve()) for source in books]}
            book_path=book_library['paths'][0]
            emit({'items':[],'book_library':book_library,'book_path':book_path})
            # 각 압축파일은 한 권이다. 첫 책 외에는 ZIP 헤더나 그림을 읽지 않는다.
            entries=[Path(book_path)];folder_input=False
    for source in entries:
        try:
            if source.suffix.lower() in ARCHIVE_EXTENSIONS:
                with zipfile.ZipFile(source) as archive:
                    members=sorted(((i,m) for i,m in enumerate(archive.infolist()) if not m.is_dir()
                        and Path(m.filename).suffix.lower() in IMAGE_EXTENSIONS
                        and not any(p.startswith('.') or p=='__MACOSX' for p in m.filename.replace('\\','/').split('/'))),
                        key=lambda pair:(natural_path_key(pair[1].filename),pair[1].filename,pair[0]))
                    if not members:errors.append(f'{source}: 압축파일에 지원하는 그림이 없습니다.')
                    for index,member in members:
                        records.append((source,member,index))
            else:records.append((source,None,None))
        except Exception as exc:errors.append(f'{source}: {exc}')
        report({'phase':'scan','found':len(records),'name':str(root)})
    total=len(records);archives=OrderedDict();source_info={}
    try:
        report({'phase':'catalog','total':total,'done':0,'name':str(root)},True)
        for done,(source,member,index) in enumerate(records,1):
            label=str(source)+('/'+member.filename.replace('\\','/') if member else '')
            try:
                suffix=Path(member.filename if member else source).suffix.lower()
                if member and (member.flag_bits&1 or member.file_size>256*1024*1024):
                    raise ValueError('암호가 있거나 256MB를 초과하는 그림은 읽을 수 없습니다.')
                if suffix in TEXT_EXTENSIONS and not images_only:
                    work=Path(directory) if directory else Path(tempfile.mkdtemp(prefix='TheViewerText_'))
                    item=render_plain_text(source,work,text_options,text_encoding,progress)
                    if folder_input:
                        item['document_pages']=item['count'];item['count']=1
                elif suffix=='.pdf':
                    import viewer_pdf_engine
                    with viewer_pdf_engine.open(source) as doc:
                        if not doc.is_pdf or doc.needs_pass:raise ValueError('암호가 없는 PDF를 선택하세요.')
                        if not len(doc):raise ValueError('페이지가 없는 PDF입니다.')
                        item={'path':str(source),'count':1 if folder_input else len(doc)}
                        if folder_input:item['document_pages']=len(doc)
                else:
                    if source not in source_info:
                        resolved=source.resolve();stat=resolved.stat()
                        source_info[source]={'file':str(resolved),'stamp':[stat.st_size,stat.st_mtime_ns]}
                    locator=image_source_path(source,member.filename if member else None,index,source_info[source])
                    count=1
                    if suffix in ('.tif','.tiff'):
                        with open_image_source(locator,0,archives) as (picture,_):count=getattr(picture,'n_frames',1)
                    item={'path':locator,'count':count,'source_path':label,'image':True}
                page_count+=item['count'];pending.append(item)
                now=time.monotonic()
                if page_count==item['count'] or len(pending)>=64 or now-last_publish>=.05:
                    emit({'items':pending,'book_path':book_path});pending=[];last_publish=now
            except Exception as exc:errors.append(f'{label}: {exc}')
            report({'phase':'catalog','total':total,'done':done,'name':label,'pages':page_count,'errors':len(errors)},done==total)
        if pending:emit({'items':pending,'book_path':book_path})
    finally:
        for archive in archives.values():archive.close()
    if not page_count and not errors:errors.append('읽을 수 있는 PDF 또는 그림이 없습니다.')
    return {'count':page_count,'errors':errors,'done':total,'total':total}


def input_worker():
    def send(data):
        sys.stdout.buffer.write((json.dumps(data,ensure_ascii=True)+'\n').encode('ascii'));sys.stdout.buffer.flush()
    for line in sys.stdin.buffer:
        job={}
        try:
            job=json.loads(line)
            emit=lambda data:send({'id':job['id'],'item':data})
            progress=lambda data:send({'id':job['id'],'progress':data})
            if job.get('mode')=='convert':result=import_input_pages(job['path'],job['directory'],emit,progress)
            else:result=discover_input_pages(job['path'],emit,progress,directory=job.get('directory'),text_options=job.get('text_options'),text_encoding=job.get('text_encoding','auto'))
            send({'id':job['id'],'done':result})
        except Exception as exc:send({'id':job.get('id'),'done':{'count':0,'errors':[str(exc)]}})




def editable_copy(path, number, normalize_rotation=True):
    """페이지별 불변 작업 사본. 화면 좌표와 PDF 편집 좌표를 일치시킨다."""
    import viewer_pdf_engine
    if is_image_source(path):return image_page_document(path,number)
    result = viewer_pdf_engine.open()
    try:
        with viewer_pdf_engine.open(path) as source:
            result.insert_pdf(source, from_page=number, to_page=number)
        if normalize_rotation:result[0].remove_rotation()
        return result
    except Exception:
        result.close()
        raise


def image_pdf_reader(doc):
    try:
        from pypdf import PdfReader
    except ImportError:
        raise ValueError('그림 편집 모듈이 필요합니다. CMD에서 py -m pip install -U pypdf 를 실행하세요.') from None
    return PdfReader(io.BytesIO(doc.tobytes()))


def pdf_image_occurrences(doc, reader=None):
    """XObject/인라인 그림의 개별 그리기 명령을 찾는다. 공유 xref와 배치 ID를 구분."""
    import viewer_pdf_engine
    from pypdf.generic import ContentStream, DictionaryObject
    reader = reader or image_pdf_reader(doc)
    page = doc[0]
    result = []

    def walk(stream, resources, matrix, path, clip, complex_clip=False, ancestors=(),object_id=None):
        if len(path) > 24:
            raise ValueError('그림의 중첩 구조가 너무 깊어 편집할 수 없습니다.')
        stack = [];marks=[]
        path_rect = None; other_path = False
        axis_aligned = lambda m: (abs(m.b)<1e-5 and abs(m.c)<1e-5) or (abs(m.a)<1e-5 and abs(m.d)<1e-5)
        for index, (args, op) in enumerate(ContentStream(stream, reader).operations):
            if op in (b'BDC',b'BMC'):
                marks.append(object_id)
                if op==b'BDC' and args[0]=='/TheViewerObject':object_id=str(args[1]['/ID'])
            elif op==b'EMC' and marks:object_id=marks.pop()
            elif op == b'q':
                stack.append((viewer_pdf_engine.Matrix(matrix), viewer_pdf_engine.Rect(clip), complex_clip))
            elif op == b'Q' and stack:
                matrix, clip, complex_clip = stack.pop()
            elif op == b'cm':
                matrix = viewer_pdf_engine.Matrix(*map(float, args)) * matrix
            elif op == b're':
                x,y,w,h = map(float,args)
                area = viewer_pdf_engine.Rect(x,y,x+w,y+h).normalize() * matrix * page.transformation_matrix
                if path_rect is not None: other_path = True
                if not axis_aligned(matrix * page.transformation_matrix): other_path = True
                path_rect = area
            elif op in (b'm', b'l', b'c', b'v', b'y'):
                other_path = True
            elif op in (b'W', b'W*'):
                if path_rect is not None and not other_path:
                    clip = clip & path_rect
                else:
                    complex_clip = True
            elif op in (b'n', b'S', b's', b'f', b'F', b'f*', b'B', b'B*', b'b', b'b*'):
                path_rect = None; other_path = False
            elif op == b'Tr' and int(args[0])>=4:
                complex_clip = True
            elif op in (b'Do', b'INLINE IMAGE'):
                obj = None
                if op == b'Do':
                    obj = resources.get('/XObject', {}).get_object().get(args[0]) if '/XObject' in resources else None
                    if obj is None: continue
                    obj = obj.get_object()
                    if obj.get('/Subtype') == '/Form':
                        identity = (getattr(obj.indirect_reference, 'idnum', None) if hasattr(obj,'indirect_reference') else id(obj))
                        if identity in ancestors: continue
                        fm = viewer_pdf_engine.Matrix(*map(float, obj.get('/Matrix', [1,0,0,1,0,0]))) * matrix
                        fc = clip
                        if '/BBox' in obj:
                            fc = clip & (viewer_pdf_engine.Rect(list(map(float,obj['/BBox']))) * fm * page.transformation_matrix)
                        walk(obj, obj.get('/Resources', resources).get_object(), fm, path+[index], fc,
                             complex_clip or not axis_aligned(fm * page.transformation_matrix), ancestors+(identity,),object_id)
                        continue
                    if obj.get('/Subtype') != '/Image': continue
                    width, height = int(obj.get('/Width',0)), int(obj.get('/Height',0))
                else:
                    settings = args['settings']
                    width = int(settings.get('/W', settings.get('/Width',0)))
                    height = int(settings.get('/H', settings.get('/Height',0)))
                transform = viewer_pdf_engine.Matrix(1,0,0,-1,0,1) * matrix * page.transformation_matrix
                box = viewer_pdf_engine.Rect(0,0,1,1) * transform
                if box.is_empty or (box & clip).is_empty: continue
                result.append({'id':path+[index], 'rect':list(box), 'width':width, 'height':height,
                               'transform':list(transform), 'clip':list(clip), 'complex_clip':complex_clip,
                               'parent_object_id':object_id})

    root = reader.pages[0]
    content = root.get_contents()
    if content is not None:
        walk(content, root.get('/Resources', DictionaryObject()).get_object(),
             viewer_pdf_engine.Matrix(1,0,0,1,0,0), [], page.rect)
    return result


def change_pdf_image(doc, operation):
    """선택한 Do 명령과 그 Form 경로만 복제. 다른 배치·레이어·투명도·원본 해상도를 보존."""
    import viewer_pdf_engine
    from pypdf import PdfWriter
    from pypdf.generic import ContentStream, DecodedStreamObject, DictionaryObject, NameObject, FloatObject
    reader = image_pdf_reader(doc)
    images = pdf_image_occurrences(doc, reader)
    chosen = next((im for im in images if im['id'] == operation['image_id']), None)
    if chosen is None or max(abs(a-b) for a,b in zip(chosen['rect'],operation['rect'])) > 0.1:
        raise ValueError('그림이 변경되었습니다. 다시 선택하세요.')
    kind = operation['kind']
    source = viewer_pdf_engine.Rect(chosen['rect'])
    target = viewer_pdf_engine.Rect(operation.get('target', chosen['rect']))
    delta = viewer_pdf_engine.Matrix(1,0,0,1,0,0)
    if kind == 'image_transform':
        if target.width < 2 or target.height < 2 or not doc[0].rect.contains(target):
            raise ValueError('그림은 페이지 안에 놓아주세요. 최소 크기는 2pt입니다.')
        if chosen['complex_clip'] or not (viewer_pdf_engine.Rect(chosen['clip']) + (-0.1,-0.1,0.1,0.1)).contains(target):
            raise ValueError('이 그림에는 잘라내기 경계가 있습니다. 경계 안으로 이동하거나 새 그림 넣기를 사용하세요.')
        sx, sy = target.width/source.width, target.height/source.height
        delta = viewer_pdf_engine.Matrix(sx,0,0,sy,target.x0-source.x0*sx,target.y0-source.y0*sy)
    writer = PdfWriter(); writer.clone_document_from_reader(reader)
    root = writer.pages[0]
    replacement = None
    if kind == 'image_replace':
        with viewer_pdf_engine.open() as image_doc:
            image_page = image_doc.new_page()
            image_page.insert_image(viewer_pdf_engine.Rect(0,0,100,100), filename=operation['filename'], keep_proportion=False)
            image_reader = image_pdf_reader(image_doc)
            objects = image_reader.pages[0]['/Resources']['/XObject']
            replacement = next(iter(objects.values())).clone(writer)

    def modify(container, stream, resources, depth, matrix, text_mode=0):
        content = ContentStream(stream, writer)
        operations = list(content.operations)
        chosen_index = chosen['id'][depth]
        inherited_text_mode=text_mode
        stack = []
        for args,op in operations[:chosen_index]:
            if op == b'q': stack.append((viewer_pdf_engine.Matrix(matrix),text_mode))
            elif op == b'Q' and stack: matrix,text_mode = stack.pop()
            elif op == b'cm': matrix = viewer_pdf_engine.Matrix(*map(float,args)) * matrix
            elif op == b'Tr':text_mode=int(args[0])
        # 리소스 사전도 복제하여 같은 Form의 다른 배치에 영향을 주지 않는다.
        local_resources = DictionaryObject(dict(resources.get_object()))
        objects = DictionaryObject(dict(local_resources.get('/XObject', DictionaryObject()).get_object()))
        local_resources[NameObject('/XObject')] = objects
        container[NameObject('/Resources')] = local_resources
        args,op = operations[chosen_index]
        name = NameObject('/PM'+uuid.uuid4().hex)
        if depth+1 < len(chosen['id']):
            original = objects[args[0]].get_object()
            form = DecodedStreamObject()
            for key,value in original.items():
                if key not in ('/Length','/Filter','/DecodeParms'): form[key] = value
            form.set_data(original.get_data())
            objects[name] = writer._add_object(form)
            operations[chosen_index] = ([name],b'Do')
            fm = viewer_pdf_engine.Matrix(*map(float,form.get('/Matrix',[1,0,0,1,0,0]))) * matrix
            modify(form, form, form.get('/Resources',local_resources), depth+1, fm,text_mode)
        elif kind == 'image_delete':
            operations[chosen_index:chosen_index+1] = []
        elif kind == 'image_replace':
            objects[name] = replacement
            operations[chosen_index] = ([name],b'Do')
        elif kind == 'image_transform':
            world = matrix * doc[0].transformation_matrix
            if abs(world.a*world.d-world.b*world.c) < 1e-9:
                raise ValueError('변환할 수 없는 그림 좌표입니다.')
            local_delta = world * delta * ~world
            operations[chosen_index:chosen_index+1] = [([],b'q'),
                ([FloatObject(float(v)) for v in local_delta],b'cm'), (args,op), ([],b'Q')]
        if kind == 'image_isolate':
            # Keep the selected occurrence and its graphics/clipping state,
            # including nested Forms. Other page artwork must not be copied.
            isolated=[];text_mode=inherited_text_mode;text_stack=[]
            for index,(values,operator) in enumerate(operations):
                if operator==b'q':text_stack.append(text_mode)
                elif operator==b'Q' and text_stack:text_mode=text_stack.pop()
                if operator in (b'Do',b'INLINE IMAGE') and index!=chosen_index:continue
                if operator==b'sh':continue
                if operator in (b'S',b's',b'f',b'F',b'f*',b'B',b'B*',b'b',b'b*'):
                    values,operator=[],b'n'
                if operator==b'Tr':
                    text_mode=int(values[0]);values=[FloatObject(7 if text_mode>=4 else 3)]
                isolated.append((values,operator))
                if operator==b'BT':isolated.append(([FloatObject(7 if text_mode>=4 else 3)],b'Tr'))
            operations=isolated
        content.operations = operations
        if depth == 0:
            container[NameObject('/Contents')] = writer._add_object(content)
        else:
            container.set_data(content.get_data())

    modify(root, root.get_contents(), root['/Resources'], 0, viewer_pdf_engine.Matrix(1,0,0,1,0,0))
    buffer = io.BytesIO(); writer.write(buffer)
    # 새 객체를 다시 열어 검증하고, 작업 사본을 압축한다.
    with viewer_pdf_engine.open(stream=buffer.getvalue(), filetype='pdf') as result:
        return result.tobytes(garbage=4,deflate=True)


def copy_pdf_image_png(path,number,selected):
    """Transparent raster of one occurrence, with displayed transform/mask/clip.

    Render at least 216 dpi where possible, bounded to 4096 px on each side.
    Never rasterize neighbouring text or pictures into the clipboard image.
    """
    import viewer_pdf_engine
    with editable_copy(path,number) as doc:
        if selected.get('object_id'):
            selected=next((im for im in pdf_image_occurrences(doc) if im.get('parent_object_id')==selected['object_id']),None)
            if selected is None:raise ValueError('복사할 사진 개체가 없습니다.')
        area=viewer_pdf_engine.Rect(selected['rect']) & doc[0].rect
        if area.is_empty:raise ValueError('복사할 그림 영역이 없습니다.')
        data=change_pdf_image(doc,{'kind':'image_isolate','rect':selected['rect'],'image_id':selected['id']})
        scale=min(max(3,selected.get('width',0)/area.width,selected.get('height',0)/area.height),
                  4096/max(area.width,area.height))
        with viewer_pdf_engine.open(stream=data,filetype='pdf') as isolated:
            pix=isolated[0].get_pixmap(matrix=viewer_pdf_engine.Matrix(scale,scale),clip=area,alpha=True,annots=False)
            return pix.tobytes('png'),[area.width,area.height]


def copy_pdf_text_pdf(path,number,selected):
    """Isolate one text object, retaining its original font codes and coordinates."""
    import viewer_pdf_edit as edit,viewer_pdf_engine as engine
    from pypdf import PdfReader,PdfWriter
    from pypdf.generic import ArrayObject,FloatObject,NameObject
    with editable_copy(path,number) as doc,engine.PDFIUM_LOCK:
        page=doc[0];data=doc.tobytes();original=page._pdfpage.get_contents().operations
        if selected.get('object_id'):
            current=next((o for o in edit.editor_objects(page) if o['object_id']==selected['object_id']),None)
            if current is None or current['kind']!='text' or current['rect']!=selected['rect']:
                raise ValueError('복사할 글상자가 변경되었습니다. 다시 선택하세요.')
            block=next((ops for identity,ops in edit._editor_blocks(page) if identity==selected['object_id']),None)
            if not block:raise ValueError('글상자의 원본 레이어를 찾지 못했습니다.')
            updated=block[1:-1]
        else:
            before,unmarked=edit._tagged_text_snapshot(data,0,original,page.transformation_matrix)
            area=engine.Rect(selected['rect'])
            chosen=edit._selected_glyphs(before,unmarked,selected.get('source_glyphs'),lambda r:(area+(-.12,-.12,.12,.12)).contains(r))
            runs=edit._text_stream_runs(page._pdfpage,original,before);updated=[]
            for index,(args,operator) in enumerate(original):
                if operator not in edit._TEXT_SHOW:
                    if operator in (b'Do',b'sh',b'BMC',b'BDC',b'EMC'):continue
                    if operator in (b'S',b's',b'f',b'F',b'f*',b'B',b'B*',b'b',b'b*'):
                        updated.append(([],b'n'))
                    else:updated.append((args,operator))
                    continue
                run=runs[index];state=run['state'];indexes=set(chosen.get(index,()))
                chars=before.get(index,{}).get('chars',[])
                if indexes:
                    if len(run['units'])!=len(chars):raise ValueError('원본 글꼴 코드를 분리하지 못했습니다.')
                    if all(i in indexes or not char['text'].strip() for i,char in enumerate(chars)):
                        indexes.update(range(len(chars)))
                    else:
                        for i in range(min(indexes),max(indexes)+1):
                            if not chars[i]['text'].strip():indexes.add(i)
                updated.extend(run['prefix']);cursor=run['matrix'];chunks=[];previous=False
                for token in run['tokens']:
                    keep=token['unit'] in indexes if token['unit'] is not None else previous
                    if not chunks or keep!=chunks[-1]['keep']:
                        chunks.append({'keep':keep,'matrix':cursor,'tokens':[],'units':[]})
                    chunks[-1]['tokens'].append(token['value'])
                    if token['unit'] is not None:chunks[-1]['units'].append(token['unit'])
                    cursor=engine.Matrix(1,0,0,1,token['advance'],0)*cursor;previous=keep
                for chunk in chunks:
                    if not chunk['keep'] or not chunk['units']:continue
                    matrix=chunk['matrix']
                    anchor=chars[chunk['units'][0]]['origin']*~page.transformation_matrix*~state['ctm']
                    matrix=engine.Matrix(matrix.a,matrix.b,matrix.c,matrix.d,anchor.x-matrix.c*state['rise'],anchor.y-matrix.d*state['rise'])
                    updated.append(([FloatObject(v) for v in matrix],b'Tm'))
                    updated.append(([ArrayObject(chunk['tokens'])],b'TJ'))
                line,end=run['line'],run['end'];delta=engine.Point(end.e,end.f)*~line
                if abs(delta.y)>.0001:raise ValueError('원본 글줄 기준을 복원하지 못했습니다.')
                updated.append(([FloatObject(v) for v in line],b'Tm'))
                if state['size'] and state['scale']:
                    updated.append(([ArrayObject([FloatObject(-delta.x*1000/(state['size']*state['scale']))])],b'TJ'))
        writer=PdfWriter(clone_from=PdfReader(io.BytesIO(data)));target=writer.pages[0];content=target.get_contents()
        content.operations=updated;target.replace_contents(content)
        for key in ('/Annots','/TheViewerObjects'):
            target.pop(NameObject(key),None)
        resources=target['/Resources'].get_object();xobjects=resources.get('/XObject')
        if xobjects is not None:
            keep={str(args[0]) for args,op in updated if op==b'Do'}
            xobjects=xobjects.get_object()
            for name in list(xobjects):
                if str(name) not in keep:del xobjects[name]
        writer.compress_identical_objects(remove_duplicates=True,remove_unreferenced=True)
        buffer=io.BytesIO();writer.write(buffer);result=buffer.getvalue()
        if len(result)>64*1024*1024:raise ValueError('복사할 글상자의 원본 글꼴 데이터가 너무 큽니다.')
        if not selected.get('object_id'):
            with engine.open(stream=result,filetype='pdf') as check:
                isolated=check[0]._pdfpage.get_contents().operations
                after,_=edit._tagged_text_snapshot(result,0,isolated,check[0].transformation_matrix)
                actual=[char for group in after.values() for char in group['chars'] if char['text'].strip()]
                expected=[g for g in selected['source_glyphs'] if g['text'].strip()]
                if len(actual)!=len(expected):raise ValueError('복사할 글자의 원본을 확인하지 못했습니다.')
                for glyph in expected:
                    hits=[c for c in actual if c['text']==glyph['text'] and max(abs(a-b) for a,b in zip(c['box'],glyph['rect']))<.0025
                          and engine.Point(*glyph['origin']).distance_to(c['origin'])<.0025]
                    if len(hits)!=1:raise ValueError('복사 후 글자 위치 또는 원본 글꼴이 달라졌습니다.')
        return result


def native_text_for_editing(page, objects):
    """Read base text from the inspection copy by marked layer ownership."""
    import viewer_pdf_edit,viewer_pdf_engine
    flags=viewer_pdf_engine.TEXTFLAGS_DICT & ~viewer_pdf_engine.TEXT_PRESERVE_IMAGES
    identities={obj['object_id'] for obj in objects if obj['kind']=='text'}
    if not identities:return page.get_text('rawdict',flags=flags)
    with viewer_pdf_engine.PDFIUM_LOCK:
        blocks=viewer_pdf_edit._editor_blocks(page)
        original=[operation for identity,block in blocks for operation in block]
        native=[operation for identity,block in blocks if identity not in identities for operation in block]
        viewer_pdf_edit._set_operations(page,native)
        try:return page.get_text('rawdict',flags=flags)
        finally:viewer_pdf_edit._set_operations(page,original)


def vector_bounds(strokes):
    points=[point for stroke in strokes for segment in stroke['segments'] for point in segment]
    return [min(p[0] for p in points),min(p[1] for p in points),max(p[0] for p in points),max(p[1] for p in points)]


def transform_vector_strokes(strokes, source, target):
    result=json.loads(json.dumps(strokes))
    sx=(target[2]-target[0])/(source[2]-source[0]) if source[2]-source[0]>.001 else 1
    sy=(target[3]-target[1])/(source[3]-source[1]) if source[3]-source[1]>.001 else 1
    for stroke in result:
        for segment in stroke['segments']:
            for point in segment:point[:]=[target[0]+(point[0]-source[0])*sx,target[1]+(point[1]-source[1])*sy]
    return result


def validate_vector_strokes(strokes,width,height):
    if not isinstance(strokes,list) or not 1<=len(strokes)<=20000:raise ValueError('선 정보가 올바르지 않습니다.')
    total=0
    for stroke in strokes:
        segments=stroke.get('segments',[]);total+=len(segments)
        if not segments or total>20000:raise ValueError('선 개수가 너무 많습니다.')
        for segment in segments:
            if len(segment)!=2:raise ValueError('선 좌표가 올바르지 않습니다.')
            for point in segment:
                if len(point)!=2 or any(not isinstance(v,(int,float)) or not math.isfinite(v) for v in point):raise ValueError('선 좌표가 올바르지 않습니다.')
                if not -.001<=point[0]<=width+.001 or not -.001<=point[1]<=height+.001:raise ValueError('선은 페이지 안에 놓아주세요.')
        if not isinstance(stroke.get('width'),(int,float)) or not .1<=stroke['width']<=100:raise ValueError('선 굵기는 0.1~100 pt로 선택하세요.')
        color=stroke.get('color',[])
        if len(color)!=3 or any(not isinstance(v,(int,float)) or not 0<=v<=1 for v in color):raise ValueError('선 색상이 올바르지 않습니다.')
        if not 0<=stroke.get('opacity',1)<=1 or stroke.get('cap',0) not in (0,1,2) or stroke.get('join',0) not in (0,1,2):raise ValueError('선 서식이 올바르지 않습니다.')
        dash=stroke.get('dash',[[],0])
        if len(dash)!=2 or not isinstance(dash[0],list) or len(dash[0])>100 or any(not isinstance(v,(int,float)) or not math.isfinite(v) or v<0 for v in dash[0]+[dash[1]]):raise ValueError('선 종류가 올바르지 않습니다.')
    if not any(math.dist(*segment)>=.1 for stroke in strokes for segment in stroke['segments']):raise ValueError('선 길이를 조금 늘려주세요.')
    return json.loads(json.dumps(strokes))


def inspect_vector_objects(page,objects):
    import viewer_pdf_edit
    paths=viewer_pdf_edit.vector_paths(page);parents=list(range(len(paths)))
    def strokes(path):return path.get('strokes',[path['stroke']])
    def root(i):
        while parents[i]!=i:parents[i]=parents[parents[i]];i=parents[i]
        return i
    def axis(segment):
        a,b=segment
        if abs(a[1]-b[1])<.05:return 'h'
        if abs(a[0]-b[0])<.05:return 'v'
        return ''
    def touch(a,b):
        aa,bb=axis(a),axis(b)
        if not aa or not bb:return False
        if aa==bb:
            along=0 if aa=='h' else 1;cross=1-along
            return abs(a[0][cross]-b[0][cross])<=1 and max(min(p[along] for p in a),min(p[along] for p in b))<=min(max(p[along] for p in a),max(p[along] for p in b))+1
        h,v=(a,b) if aa=='h' else (b,a)
        return min(p[0] for p in h)-1<=v[0][0]<=max(p[0] for p in h)+1 and min(p[1] for p in v)-1<=h[0][1]<=max(p[1] for p in v)+1
    # Bound the grouping cost for large illustrations. Individual paint paths
    # remain selectable even when the page contains thousands of segments.
    if sum(len(s['segments']) for p in paths for s in strokes(p))<=2500:
        for i,a in enumerate(paths):
            for j in range(i):
                b=paths[j];ar,br=a['rect'],b['rect']
                if ar[0]>br[2]+1 or br[0]>ar[2]+1 or ar[1]>br[3]+1 or br[1]>ar[3]+1:continue
                if any(touch(x,y) for sa in strokes(a) for x in sa['segments'] for sb in strokes(b) for y in sb['segments']):parents[root(i)]=root(j)
    groups={}
    for i,path in enumerate(paths):groups.setdefault(root(i),[]).append(path)
    result=[]
    for group in groups.values():
        group_strokes=[s for p in group for s in strokes(p)];segments=[s for stroke in group_strokes for s in stroke['segments']]
        horizontal={round(sum(p[1] for p in s)/2,1) for s in segments if axis(s)=='h'}
        vertical={round(sum(p[0] for p in s)/2,1) for s in segments if axis(s)=='v'}
        shape=('line' if len(segments)==1 else 'table' if len(horizontal)>=2 and len(vertical)>=2 and len(horizontal)+len(vertical)>4 else 'frame')
        result.append({'kind':'vector','shape':shape,'rect':vector_bounds(group_strokes),'strokes':group_strokes,
                       'native_paths':[{'id':p['id'],'signature':p['signature']} for p in group]})
    result.extend(o for o in objects if o['kind']=='vector')
    return result


def vector_parts(vectors):
    result=[]
    for parent in vectors:
        if parent.get('shape')=='line' and sum(len(s['segments']) for s in parent['strokes'])==1:
            result.append(parent);continue
        for i,stroke in enumerate(parent['strokes']):
            for j,segment in enumerate(stroke['segments']):
                part={**stroke,'segments':[segment]}
                result.append({'kind':'vector','shape':'line','rect':vector_bounds([part]),'strokes':[part],
                               'parent_vector':parent,'segment_ref':[i,j],'z':parent.get('z',0)})
    return result


def vector_parent_identity(parent):
    return parent.get('object_id') or uuid.uuid5(uuid.NAMESPACE_URL,json.dumps(parent.get('native_paths',[]),sort_keys=True)).hex


def edit_vector_parts(page,operation):
    import viewer_pdf_edit
    parent=operation['parent_vector'];parts=operation['parts'];remaining=json.loads(json.dumps(parent['strokes']))
    removed=set()
    for part in parts:
        i,j=part['segment_ref']
        if (i,j) in removed or not 0<=i<len(remaining) or not 0<=j<len(remaining[i]['segments']):raise ValueError('선 선택 정보가 변경되었습니다.')
        removed.add((i,j))
        if part.get('strokes') is not None:validate_vector_strokes(part['strokes'],page.rect.width,page.rect.height)
    if parent.get('object_id'):
        current=next((v for v in viewer_pdf_edit.editor_objects(page) if v['object_id']==parent['object_id']),None)
        if current is None or current['strokes']!=parent['strokes']:raise ValueError('표 테두리 정보가 변경되었습니다.')
        viewer_pdf_edit.edit_editor_object(page,{'kind':'object_delete','object_id':parent['object_id'],'rect':parent['rect']})
    else:viewer_pdf_edit.remove_vector_paths(page,parent['native_paths'])
    for i,stroke in enumerate(remaining):stroke['segments']=[s for j,s in enumerate(stroke['segments']) if (i,j) not in removed]
    remaining=[s for s in remaining if s['segments']]
    records=[]
    if remaining:records.append({'kind':'vector','shape':'frame','strokes':remaining,'rect':vector_bounds(remaining),'object_id':vector_parent_identity(parent)})
    for part in parts:
        if part.get('strokes') is not None:
            records.append({'kind':'vector','shape':'line','strokes':part['strokes'],'rect':vector_bounds(part['strokes']),
                            'object_id':part.get('object_id') or uuid.uuid4().hex})
    for record in records:viewer_pdf_edit.append_editor_object(page,record,lambda layer,r=record:viewer_pdf_edit.draw_vector_object(layer,r))


def rebase_batch_operation(path,number,operation,original=None):
    """Resolve native occurrence addresses again after each staged edit."""
    operation=json.loads(json.dumps(operation));kind=operation['kind']
    if kind.startswith('image_') and kind not in ('image_add',):
        with editable_copy(path,number) as doc:
            hits=[v for v in pdf_image_occurrences(doc) if max(abs(a-b) for a,b in zip(v['rect'],operation['rect']))<.01]
            if len(hits)!=1:raise ValueError('선택한 그림을 다시 확인하지 못했습니다. 원본은 변경되지 않았습니다.')
            operation['image_id']=hits[0]['id']
    if kind in ('vector_edit','vector_delete','vector_parts'):
        import viewer_pdf_edit
        with editable_copy(path,number) as doc:
            page=doc[0];paths=viewer_pdf_edit.vector_paths(page)
            parent=operation['parent_vector'] if kind=='vector_parts' else operation
            if kind!='vector_parts' or not parent.get('object_id'):
                evidence=[];source_paths=None
                for old in parent.get('native_paths',[]):
                    hits=[p for p in paths if p['signature']==old['signature']]
                    if hits:
                        same=[p for p in hits if p['id']==old['id']];hits=same or hits
                    elif original is not None:
                        if source_paths is None:
                            with editable_copy(*original) as source:source_paths=viewer_pdf_edit.vector_paths(source[0])
                        proven=[p for p in source_paths if p['id']==old['id'] and p['signature']==old['signature']]
                        if len(proven)==1:hits=[p for p in paths if viewer_pdf_edit.same_vector_path(proven[0],p)]
                    if len(hits)!=1:raise ValueError('선 선택이 겹치거나 변경되었습니다. 원본은 변경되지 않았습니다.')
                    evidence.append({'id':hits[0]['id'],'signature':hits[0]['signature']})
                parent['native_paths']=evidence
    return operation


def apply_edit_batch(path,number,operation,output):
    operations=operation.get('operations',[])
    if not operations or len(operations)>5000 or any(o.get('kind')=='batch' for o in operations):raise ValueError('일괄 편집 정보가 올바르지 않습니다.')
    with tempfile.TemporaryDirectory(prefix='TheViewerBatch_') as work:
        current=path;page_number=number
        for i,op in enumerate(operations):
            op=rebase_batch_operation(current,page_number,op,original=(path,number))
            destination=str(Path(work)/(str(i)+'.pdf'))
            apply_page_edit(current,page_number,op,destination);current=destination;page_number=0
        target=Path(output);target.parent.mkdir(parents=True,exist_ok=True)
        try:
            with target.open('xb') as stream:stream.write(Path(current).read_bytes())
        except FileExistsError:raise
        except Exception:
            target.unlink(missing_ok=True);raise
    return str(output)



def inspect_edit_page(path, number, tables=False, images=False):
    import viewer_pdf_engine
    viewer_pdf_engine.TOOLS.set_small_glyph_heights(True)
    with editable_copy(path, number) as doc:
        page = doc[0]
        import viewer_pdf_edit
        objects=viewer_pdf_edit.editor_objects(page)
        spans = []
        for block in native_text_for_editing(page,objects)['blocks']:
            for line in block.get('lines', []):
                dx, dy = line.get('dir', (1, 0))
                angle = math.degrees(math.atan2(-dy, dx)) % 360
                rotation = int(round(angle / 90) * 90) % 360
                if abs((angle - rotation + 180) % 360 - 180) > 1:
                    continue  # 임의 각도 글자는 영역 도구로 보정한다.
                for span in line.get('spans', []):
                    text=''.join(char['c'] for char in span['chars'])
                    if text.strip():
                        glyphs=[{'text':char['c'],'rect':list(char['bbox']),'origin':list(char['origin'])}
                                for char in span['chars'] if char['c'].strip()]
                        spans.append({'rect': list(span['bbox']), 'text': text,'source_glyphs':glyphs,
                                      'size': span['size'], 'color': '#%06x' % span['color'],
                                      'bold': bool(span['flags'] & 16), 'font':span['font'], 'rotate': rotation,
                                      'origin':list(span.get('origin',span['bbox'][:2])), 'family':span.get('family',span['font'])})
        cells = []
        if tables:
            seen = set()
            for table in page.find_tables().tables:
                for box in table.cells:
                    if box is None or tuple(box) in seen:
                        continue
                    seen.add(tuple(box))
                    r = viewer_pdf_engine.Rect(box)
                    inner = r + (1, 1, -1, -1)
                    contained = [s for s in spans if inner.contains(viewer_pdf_engine.Rect(s['rect']))]
                    sample = contained[0] if contained else {}
                    text_rect = [min(s['rect'][0] for s in contained), min(s['rect'][1] for s in contained),
                                 r.x1-2, r.y1-2] if contained else list(r + (2, 2, -2, -2))
                    cells.append({'rect': list(r), 'text': page.get_textbox(inner).strip(),
                                  'size': sample.get('size', 11), 'color': sample.get('color', '#111111'),
                                  'bold': sample.get('bold', False), 'rotate': sample.get('rotate', 0),
                                  'text_rect': text_rect})
        owned_text = [o for o in objects if o['kind']=='text']
        # Our added sentence keeps its own identity even when font fallback
        # produces several PDF runs or the sentence wraps across lines.
        spans += owned_text
        pictures = pdf_image_occurrences(doc, image_pdf_reader(doc)) if images else []
        pictures = [p for p in pictures if not p.get('parent_object_id')]
        pictures += [o for o in objects if o['kind'] in ('image','cover')]
        blocks=viewer_pdf_edit._editor_blocks(page) if objects else []
        base_z=next((i for i,(identity,_) in enumerate(blocks) if identity is None),0)
        vectors=inspect_vector_objects(page,objects) if images else []
        return {'width': page.rect.width, 'height': page.rect.height, 'spans': spans, 'cells': cells,
                'tables': tables, 'images':pictures, 'vectors':vectors,
                'images_ready':images, 'objects':objects,'base_z':base_z,
                'vector_parts':vector_parts(vectors)}


LEGACY_BITMAP_FONTS = frozenset(('small fonts','system','terminal','fixedsys','modern','roman','script','ms sans serif','ms serif','oem fixed'))


@lru_cache(maxsize=1)
def safe_font_families():
    from PySide6.QtGui import QFontDatabase
    return tuple(f for f in QFontDatabase.families() if f.casefold() not in LEGACY_BITMAP_FONTS
            and not QFontDatabase.isPrivateFamily(f) and QFontDatabase.isSmoothlyScalable(f))


def font_family_key(name):
    name=re.sub(r'^/?[A-Z]{6}\+','',str(name or '')).strip().lstrip('/')
    key=re.sub(r'[^\w]','',name).casefold()
    return {'맑은고딕':'malgungothic','맑은고딕semilight':'malgungothicsemilight',
            '굴림':'gulim','굴림체':'gulimche','돋움':'dotum','돋움체':'dotumche',
            '바탕':'batang','바탕체':'batangche'}.get(key,key)


def installed_font_family(requested,families=None):
    families=safe_font_families() if families is None else families
    lookup={font_family_key(f):f for f in reversed(families)}
    name=re.sub(r'^/?[A-Z]{6}\+','',str(requested or '')).strip().lstrip('/')
    for _ in range(4):
        match=lookup.get(font_family_key(name))
        if match:return match
        shortened=re.sub(r'[-, _]?(?:BoldItalic|BoldOblique|SemiBold|DemiBold|Regular|Bold|Italic|Oblique|PSMT|MT)$','',name,flags=re.I)
        if shortened==name:break
        name=shortened
    return ''


def prioritized_font_families(document_fonts=(),families=None):
    installed=tuple(safe_font_families() if families is None else families)
    result=[];seen=set()
    for name in (*document_fonts,'맑은 고딕','Malgun Gothic','굴림','돋움','바탕'):
        family=installed_font_family(name,installed)
        key=font_family_key(family)
        if family and key not in seen:result.append(family);seen.add(key)
    for family in installed:
        key=font_family_key(family)
        if key not in seen:result.append(family);seen.add(key)
    return tuple(result)


def safe_font_family(requested=''):
    from PySide6.QtGui import QFontDatabase
    families=safe_font_families();match=installed_font_family(requested,families)
    if match:return match
    for preferred in ('Malgun Gothic','맑은 고딕','Noto Sans CJK KR','Noto Sans KR','Arial','DejaVu Sans'):
        if preferred in families:return preferred
    return families[0] if families else QFontDatabase.systemFont(QFontDatabase.GeneralFont).family()


def editor_text_content(operation):
    size=max(4,min(144,float(operation.get('size',11))))
    family=operation.get('font','sans-serif')
    if not isinstance(family,str) or len(family)>150 or any(c in family for c in '\n\r;{}<>'):
        raise ValueError('올바른 글꼴을 선택하세요.')
    _viewer_conversion_app()
    family=safe_font_family(family)
    quoted='"'+family.replace('\\','\\\\').replace('"','\\"')+'"'
    color=operation.get('color','#111111')
    if not re.fullmatch(r'#[0-9a-fA-F]{6}',color):raise ValueError('올바른 글자 색상을 선택하세요.')
    align=operation.get('align','left')
    if align not in ('left','center','right'):align='left'
    css=('body {margin:0; padding:0;} p {margin:0; padding:0; line-height:1.05; white-space:pre-wrap; '
         f'font-family:{quoted}; font-size:{size}pt; color:{color}; text-align:{align}; '
         f'font-weight:{"bold" if operation.get("bold") else "normal"};'+'}')
    return '<p>'+html.escape(operation.get('text','')).replace('\n','<br>')+'</p>',css


def editor_text_layout(operation,width=None):
    from PySide6.QtGui import QImage,QTextDocument
    content,css=editor_text_content(operation)
    device=QImage(1,1,QImage.Format.Format_RGB32)
    device.setDotsPerMeterX(round(720/.0254));device.setDotsPerMeterY(round(720/.0254))
    document=QTextDocument();document.documentLayout().setPaintDevice(device)
    document.setDocumentMargin(0);document.setDefaultStyleSheet(css);document.setHtml(content)
    document.setTextWidth(-1 if width is None else max(1,width)*10)
    measured=document.size();layout=document.firstBlock().layout()
    line=layout.lineAt(0) if layout is not None and layout.lineCount() else None
    return {'width':document.idealWidth()/10,'height':measured.height()/10,
            'baseline':(line.y()+line.ascent())/10 if line is not None and line.isValid() else float(operation.get('size',11)),
            'line_height':line.height()/10 if line is not None and line.isValid() else max(1,measured.height()/10)}


def insert_editor_text(page, rect, operation):
    """실제 PDF 텍스트 기록. 직접 편집에서는 지정 크기를 유지하고 넘침을 알린다."""
    if not operation.get('text',''):return
    if operation.get('native_pdf'):
        import viewer_pdf_engine
        with viewer_pdf_engine.open(stream=base64.b64decode(operation['native_pdf'],validate=True),filetype='pdf') as source:
            if len(source)!=1 or source.needs_pass:raise ValueError('복사한 글상자의 원본을 읽지 못했습니다.')
            page.show_pdf_page(source[0].rect,source,0,keep_proportion=False)
        return
    if operation.get('page_number_owner')==PAGE_NUMBER_OWNER and '\n' not in operation.get('text',''):
        return insert_page_number_text(page,rect,operation)
    content,css=editor_text_content(operation)
    spare,scale=page.insert_htmlbox(rect,content,css=css,
        scale_low=1 if operation.get('strict_size') else .5,rotate=operation.get('rotate',0))
    if spare<0:
        raise ValueError('내용이 페이지 안에 들어가지 않습니다. 글자 크기를 줄이거나 영역을 넓혀주세요. 입력 내용은 유지됩니다.')


def add_editor_object(page, operation, draw):
    import viewer_pdf_edit
    record={k:v for k,v in operation.items() if k not in ('filename','image_id','old_text','source_glyphs','native_pdf')}
    record['kind']={'image_add':'image','replace':'text','format':'text','cell':'text'}.get(record['kind'],record['kind'])
    record['object_id']=record.get('object_id') or uuid.uuid4().hex
    viewer_pdf_edit.append_editor_object(page,record,draw)


def promote_image_layer(doc, operation):
    """Keep an existing image's mask/clip, then make that occurrence a layer."""
    import viewer_pdf_edit,viewer_pdf_engine
    from pypdf import PdfReader,PdfWriter
    from pypdf.generic import ContentStream,DecodedStreamObject,NameObject
    occurrence=next(im for im in pdf_image_occurrences(doc) if im['id']==operation['image_id'])
    if occurrence['complex_clip']:
        raise ValueError('복잡한 클리핑을 가진 원본 그림은 Z 순서를 변경하지 않습니다. 원본은 변경되지 않았습니다.')
    isolated=change_pdf_image(doc,{**operation,'kind':'image_isolate'})
    clean=PdfWriter(clone_from=PdfReader(io.BytesIO(isolated)));content=clean.pages[0].get_contents()
    shows=(b'Tj',b'TJ',b"'",b'"')
    content.operations=[(a,op) for a,op in content.operations if op not in shows]
    clean.pages[0].replace_contents(content)
    visited=set()
    def clean_forms(resources):
        objects=resources.get('/XObject',{})
        if hasattr(objects,'get_object'):objects=objects.get_object()
        for name,ref in list(objects.items()):
            obj=ref.get_object()
            if obj.get('/Subtype')!='/Form':continue
            identity=id(obj)
            if identity in visited:continue
            visited.add(identity)
            stream=ContentStream(obj,clean)
            stream.operations=[(a,op) for a,op in stream.operations if op not in shows]
            replacement=DecodedStreamObject()
            for key,value in obj.items():
                if key not in ('/Length','/Filter','/DecodeParms'):replacement[key]=value
            replacement.set_data(stream.get_data());objects[name]=clean._add_object(replacement)
            if '/Resources' in replacement:clean_forms(replacement['/Resources'])
    clean_forms(clean.pages[0]['/Resources'])
    buffer=io.BytesIO();clean.write(buffer);isolated=buffer.getvalue()
    removed=change_pdf_image(doc,{**operation,'kind':'image_delete'})
    doc._writer=PdfWriter(clone_from=PdfReader(io.BytesIO(removed)));doc._changed()
    identity=uuid.uuid4().hex
    with viewer_pdf_engine.open(stream=isolated,filetype='pdf') as source:
        add_editor_object(doc[0],{'kind':'image_add','rect':operation['rect'],'object_id':identity},
            lambda layer:layer.show_pdf_page(layer.rect,source,0,keep_proportion=False))
    viewer_pdf_edit.edit_editor_object(doc[0],{**operation,'kind':'object_z','object_id':identity})




def check_text_delete(page, rect, expected_text):
    """선택한 글자 경계가 다른 글자에 걸치면 실제 삭제 전에 중단한다."""
    import viewer_pdf_engine
    import viewer_pdf_edit
    matched=False
    for block in page.get_text('dict',flags=viewer_pdf_engine.TEXTFLAGS_DICT & ~viewer_pdf_engine.TEXT_PRESERVE_IMAGES)['blocks']:
        for line in block.get('lines',[]):
            for span in line['spans']:
                if not span['text'].strip():continue
                box=viewer_pdf_engine.Rect(span['bbox'])
                if (box & rect).get_area()<=0:continue
                if span['text']==expected_text and max(abs(box[i]-rect[i]) for i in range(4))<0.1 and not matched:
                    matched=True
                else:
                    raise ValueError('다른 글자와 겹친 영역입니다. 흰색 덮기로 필요한 범위를 지정하세요.')
    if not matched:raise ValueError('삭제할 글자가 변경되었습니다. 다시 선택하세요.')


def apply_page_edit(path, number, operation, output):
    """수정은 새 PDF에만 기록한다. 오류 시 원본과 이전 작업 사본은 그대로 유지."""
    if operation['kind']=='batch':return apply_edit_batch(path,number,operation,output)
    import viewer_pdf_engine
    import viewer_pdf_edit
    viewer_pdf_engine.TOOLS.set_small_glyph_heights(True)
    with editable_copy(path, number) as doc:
        page = doc[0]
        kind = operation['kind']
        image_data = None
        rect = viewer_pdf_engine.Rect(operation['rect']) & page.rect
        minimum = 0.1 if kind == 'text_delete' else (0.5 if kind in ('cover','object_cover_color') else 2)
        if kind not in ('line','vector','vector_edit','vector_delete','object_vector') and not operation.get('vector') and (rect.is_empty or rect.width < minimum or rect.height < minimum):
            raise ValueError('조금 더 넓은 영역을 선택하세요.')
        if kind=='vector_parts':edit_vector_parts(page,operation)
        if kind in ('vector','vector_edit','object_vector'):
            strokes=validate_vector_strokes(operation['strokes'],page.rect.width,page.rect.height)
            operation={**operation,'strokes':strokes,'target':vector_bounds(strokes)}
        if kind in ('vector_edit','vector_delete'):
            viewer_pdf_edit.remove_vector_paths(page,operation['native_paths'])
        if kind in ('vector','vector_edit'):
            record={'kind':'vector','shape':operation.get('shape','line'),'rect':operation['target'],'strokes':operation['strokes'],
                    'object_id':operation.get('object_id') or uuid.uuid4().hex}
            viewer_pdf_edit.append_editor_object(page,record,lambda layer:viewer_pdf_edit.draw_vector_object(layer,record))
        if kind.startswith('object_'):
            draw=(lambda layer:insert_editor_text(layer,viewer_pdf_engine.Rect(operation.get('target',operation['rect'])),operation)) if kind=='object_format' else None
            if kind=='object_cover_color':
                color=operation.get('color','#ffffff')
                if not re.fullmatch(r'#[0-9a-fA-F]{6}',color):raise ValueError('올바른 덮기 색상을 선택하세요.')
                fill=tuple(int(color[i:i+2],16)/255 for i in (1,3,5))
                draw=lambda layer:layer.draw_rect(rect,color=None,fill=fill,fill_opacity=1,overlay=True)
            if kind=='object_vector':draw=lambda layer:viewer_pdf_edit.draw_vector_object(layer,operation)
            if kind=='object_image_replace':draw=lambda layer:layer.insert_image(rect,filename=operation['filename'],keep_proportion=operation.get('keep_ratio',True))
            viewer_pdf_edit.edit_editor_object(page,operation,draw)
        elif kind=='image_z':
            promote_image_layer(doc,operation)
        if kind in ('replace', 'format', 'cell', 'move','move_group','text_delete'):
            # 기존의 미적용 redaction 주석까지 적용하지 않도록 보호한다.
            if any(a.type[0] == viewer_pdf_engine.PDF_ANNOT_REDACT for a in (page.annots() or [])):
                raise ValueError('미적용 삭제 주석이 있는 페이지입니다. 글자 넣기 / 흰색 덮기를 사용하세요.')
            if kind not in ('move','move_group'):
                if kind in ('text_delete','format'):
                    viewer_pdf_edit._edit_text_stream(page,[rect],expected_text=operation.get('old_text',operation['text']),
                                                      source_glyphs=operation.get('source_glyphs'))
                else:
                    erase = rect + (1, 1, -1, -1) if kind == 'cell' else rect
                    page.add_redact_annot(erase, fill=False, cross_out=False)
                    page.apply_redactions(images=0, graphics=0, text=0)
        if kind == 'cover' or operation.get('white'):
            color=operation.get('color','#ffffff') if kind=='cover' else '#ffffff'
            if not re.fullmatch(r'#[0-9a-fA-F]{6}',color):raise ValueError('올바른 덮기 색상을 선택하세요.')
            fill=tuple(int(color[i:i+2],16)/255 for i in (1,3,5))
            add_editor_object(page,{'kind':'cover','rect':list(rect),'color':color,'object_id':operation.get('object_id')},
                lambda layer:layer.draw_rect(rect,color=None,fill=fill,fill_opacity=1,overlay=True))
        if kind in ('image_transform', 'image_replace', 'image_delete'):
            image_data = change_pdf_image(doc, operation)
        elif kind == 'image_add':
            add_editor_object(page,operation,lambda layer:layer.insert_image(rect,filename=operation['filename'],keep_proportion=operation.get('keep_ratio',True)))
        elif kind == 'move':
            move_pdf_text(page, path, number, rect, operation['dx'], operation['dy'], operation['text'],operation.get('source_glyphs'))
        elif kind == 'move_group':
            viewer_pdf_edit.move_text_objects(page,rect,operation['dx'],operation['dy'],None,operation['source_glyphs'])
        elif kind == 'text_delete':
            pass
        elif kind in ('replace', 'format', 'cell', 'text'):
            target = rect + (2, 2, -2, -2) if kind == 'cell' else viewer_pdf_engine.Rect(operation.get('target',rect))
            if kind == 'cell' and operation.get('text_rect'):
                target = viewer_pdf_engine.Rect(operation['text_rect']) & target
            add_editor_object(page,{**operation,'rect':list(target)},lambda layer:insert_editor_text(layer,target,operation))
        elif kind == 'line':
            a, b = viewer_pdf_engine.Point(operation['start']), viewer_pdf_engine.Point(operation['end'])
            if not (page.rect.contains(a) and page.rect.contains(b)):
                raise ValueError('선은 페이지 안에 그려주세요.')
            color = tuple(int(operation.get('color', '#111111')[i:i+2], 16)/255 for i in (1, 3, 5))
            page.draw_line(a, b, color=color, width=operation.get('width', 1), overlay=True)
        elif kind == 'table':
            values = operation['values']
            rows, cols = len(values), len(values[0])
            if not 1 <= rows <= 30 or not 1 <= cols <= 15 or any(len(r) != cols for r in values):
                raise ValueError('표 크기가 올바르지 않습니다.')
            cw, ch = rect.width / cols, rect.height / rows
            if cw < 12 or ch < 12:
                raise ValueError('표 영역이 너무 작습니다. 영역을 넓히거나 행·열 수를 줄이세요.')
            for r in range(rows):
                for c in range(cols):
                    cell = viewer_pdf_engine.Rect(rect.x0+c*cw+3, rect.y0+r*ch+3,
                                     rect.x0+(c+1)*cw-3, rect.y0+(r+1)*ch-3)
                    insert_editor_text(page, cell, {**operation, 'text': values[r][c]})
            shape = page.new_shape()
            for r in range(rows+1):
                shape.draw_line((rect.x0, rect.y0+r*ch), (rect.x1, rect.y0+r*ch))
            for c in range(cols+1):
                shape.draw_line((rect.x0+c*cw, rect.y0), (rect.x0+c*cw, rect.y1))
            shape.finish(color=(0.12, 0.12, 0.12), width=0.7)
            shape.commit()
        elif kind not in ('cover','image_z','vector','vector_edit','vector_delete','vector_parts') and not kind.startswith('object_'):
            raise ValueError('지원하지 않는 편집 도구입니다.')
        output = Path(output)
        output.parent.mkdir(parents=True, exist_ok=True)
        data = image_data if image_data is not None else doc.tobytes(garbage=4, deflate=True)
        try:
            with output.open('xb') as stream:
                stream.write(data)
        except FileExistsError:
            raise
        except Exception:
            output.unlink(missing_ok=True)
            raise
    return str(output)


PAGE_NUMBER_OWNER = 'TheViewer/page-number/v1'
PAGE_NUMBER_DEFAULTS = {'x':50.0,'y':95.0,'font':'','size':11.0,'bold':False,
                        'color':'#111111','prefix':'','suffix':'','start':1,'digits':1}


def page_number_options(values=None):
    values={**PAGE_NUMBER_DEFAULTS,**(values or {})}
    result={}
    for name,minimum,maximum in [('x',0,100),('y',0,100),('size',4,144)]:
        value=float(values[name])
        if not math.isfinite(value) or not minimum<=value<=maximum:
            raise ValueError('쪽번호 위치는 0~100, 크기는 4~144 pt로 지정하세요.')
        result[name]=round(value,2)
    for name,minimum,maximum in [('start',0,999999),('digits',1,6)]:
        value=int(values[name])
        if value!=float(values[name]) or not minimum<=value<=maximum:
            raise ValueError('쪽번호 시작 번호와 자릿수를 확인하세요.')
        result[name]=value
    for name in ('prefix','suffix'):
        value=values[name]
        if not isinstance(value,str) or len(value)>40 or any(c in value for c in '\r\n\t'):
            raise ValueError('번호 양쪽 장식은 한 줄에 40자까지 입력하세요.')
        result[name]=value
    color=values['color']
    if not isinstance(color,str) or not re.fullmatch(r'#[0-9a-fA-F]{6}',color):
        raise ValueError('쪽번호 색상을 확인하세요.')
    result.update(font=safe_font_family(str(values['font'])),bold=bool(values['bold']),color=color)
    return result


def page_number_layout(operation):
    # Separate numeric runs in Qt PDF output. Some CJK fonts otherwise omit
    # the digits' ToUnicode entries when they follow a Latin prefix.
    parts=[];x=0.;baseline=0.
    for text in re.findall(r'[0-9]+|[^0-9]+',operation.get('text','')):
        measured=editor_text_layout({**operation,'text':text})
        parts.append({'text':text,'x':x,**measured});x+=measured['width']
        baseline=max(baseline,measured['baseline'])
    height=0.
    for part in parts:
        part['y']=baseline-part['baseline'];height=max(height,part['y']+part['height'])
    return {'parts':parts,'width':x,'height':height}


def insert_page_number_text(page,rect,operation):
    import viewer_pdf_engine
    turn=int(operation.get('rotate',0))%360
    width,height=(rect.height,rect.width) if turn in (90,270) else (rect.width,rect.height)
    layout=page_number_layout(operation)
    if layout['width']>width+.01 or layout['height']>height+.01:
        raise ValueError('쪽번호가 글상자 안에 들어가지 않습니다. 영역을 넓히거나 크기를 줄여주세요.')
    with viewer_pdf_engine.open() as document:
        layer=document.new_page(width=width,height=height)
        for part in layout['parts']:
            content,css=editor_text_content({**operation,'text':part['text']})
            area=viewer_pdf_engine.Rect(part['x'],part['y'],part['x']+part['width']+1.,part['y']+part['height']+.5)
            spare,_scale=layer.insert_htmlbox(area,content,css=css,scale_low=1)
            if spare<0:raise ValueError('쪽번호를 지정한 크기로 출력하지 못했습니다.')
        page.show_pdf_page(rect,document,0,rotate=turn,keep_proportion=False)


def page_number_record(options,index,width,height):
    options=page_number_options(options)
    text=options['prefix']+str(options['start']+int(index)).zfill(options['digits'])+options['suffix']
    record={'kind':'text','text':text,'font':options['font'],'size':options['size'],
            'bold':options['bold'],'color':options['color'],'align':'left','rotate':0,
            'strict_size':True,'text_frame':True,'object_id':uuid.uuid4().hex,
            'page_number_owner':PAGE_NUMBER_OWNER,'page_number_value':options['start']+int(index)}
    measured=page_number_layout(record)
    w,h=measured['width']+1.5,measured['height']+1.0
    if width<=0 or height<=0 or w>width or h>height:
        raise ValueError('쪽번호가 페이지보다 큽니다. 글자 크기나 양쪽 장식을 줄여주세요.')
    x=max(0.,min(width-w,width*options['x']/100-w/2))
    y=max(0.,min(height-h,height*options['y']/100-h/2))
    record['rect']=[x,y,x+w,y+h]
    return record


def remove_viewer_page_numbers(page):
    import viewer_pdf_edit
    records=viewer_pdf_edit.editor_objects(page)
    ids={r['object_id'] for r in records if r.get('page_number_owner')==PAGE_NUMBER_OWNER}
    if not ids:return 0
    blocks=viewer_pdf_edit._editor_blocks(page)
    viewer_pdf_edit._set_operations(page,[op for identity,ops in blocks if identity not in ids for op in ops])
    viewer_pdf_edit._set_editor_records(page,[r for r in records if r['object_id'] not in ids])
    return len(ids)


def apply_page_batch(payload):
    """Create every replacement first; a failed batch never updates any page."""
    import viewer_pdf_engine
    import viewer_pdf_edit
    from pypdf import PdfReader
    kind=payload['kind'];entries=payload['entries'];created=[];replacements=[];count=0;sources=OrderedDict()
    if kind not in ('rotate','page_numbers','delete_page_numbers') or not entries:
        raise ValueError('변경할 페이지를 선택하세요.')
    if len({entry['uid'] for entry in entries})!=len(entries):raise ValueError('페이지 선택이 중복되었습니다.')
    if kind=='page_numbers':
        _viewer_conversion_app();options=page_number_options(payload.get('options'))
    turn=int(payload.get('turn',0))
    if kind=='rotate' and turn not in (-90,90):raise ValueError('회전 방향을 확인하세요.')
    try:
        for index,entry in enumerate(entries):
            card=int(entry.get('document_pages',0))
            if card and kind!='delete_page_numbers':raise ValueError('PDF 카드의 전체 문서를 연 뒤 페이지를 선택하세요.')
            if card:document=viewer_pdf_engine.open(entry['path'])
            elif is_image_source(entry['path']):document=image_page_document(entry['path'],entry['number'])
            else:
                # Reuse one lazy reader instead of serializing the entire source
                # for every selected page in a large numbering/rotation batch.
                if entry['path'] not in sources:
                    reader=PdfReader(entry['path'])
                    if reader.is_encrypted and not reader.decrypt(''):raise ValueError('암호가 없는 PDF 파일을 선택하세요.')
                    sources[entry['path']]=reader
                sources.move_to_end(entry['path'])
                while len(sources)>4:sources.popitem(last=False)
                reader=sources[entry['path']]
                number=int(entry['number'])
                if not 0<=number<len(reader.pages):raise ValueError('변경할 PDF 페이지를 찾지 못했습니다.')
                document=viewer_pdf_engine.open();document._writer.add_page(reader.pages[number])
            with document as doc:
                if doc.needs_pass:raise ValueError('암호가 없는 PDF 파일을 선택하세요.')
                changed=0
                for page in doc:
                    if kind=='rotate':
                        page.set_rotation((page.rotation+turn)%360);changed+=1
                    elif kind=='page_numbers':
                        remove_viewer_page_numbers(page)
                        record=page_number_record(options,index,page.rect.width,page.rect.height)
                        rotation=page.rotation
                        if rotation:
                            record['rect']=list(viewer_pdf_engine.Rect(record['rect'])*page.derotation_matrix)
                            record['rotate']=rotation;page.set_rotation(0)
                        try:
                            viewer_pdf_edit.append_editor_object(page,record,
                                lambda layer,r=record:insert_editor_text(layer,viewer_pdf_engine.Rect(r['rect']),r))
                        finally:
                            if rotation:page.set_rotation(rotation)
                        changed+=1
                    else:changed+=remove_viewer_page_numbers(page)
                if not changed:continue
                output=Path(entry['output']);output.parent.mkdir(parents=True,exist_ok=True)
                data=doc.tobytes(garbage=4,deflate=True)
                with output.open('xb') as stream:
                    created.append(output);stream.write(data)
                replacements.append({'uid':entry['uid'],'path':str(output),'number':0})
                count+=changed
        return {'replacements':replacements,'count':count}
    except Exception:
        for path in created:path.unlink(missing_ok=True)
        raise


def pdf_worker():
    """Qt와 분리된 단일 PDF 프로세스. PDFium를 여러 스레드에서 호출하지 않는다."""
    import viewer_pdf_engine
    viewer_pdf_engine.TOOLS.mupdf_display_errors(False)
    viewer_pdf_engine.TOOLS.mupdf_display_warnings(False)
    documents = OrderedDict()
    for line in sys.stdin.buffer:
        request = {}
        raw_frame=b''
        try:
            request = json.loads(line)
            if request['op']=='page_batch':
                result=apply_page_batch(request['payload'])
                sys.stdout.buffer.write((json.dumps({'id':request['id'],'ok':True,'batch':result},ensure_ascii=True)+'\n').encode('ascii'))
                sys.stdout.buffer.flush();continue
            if request['op']=='release':
                for cached in documents.values():cached.close()
                documents.clear()
                sys.stdout.buffer.write((json.dumps({'id':request['id'],'ok':True})+'\n').encode('ascii'))
                sys.stdout.buffer.flush()
                continue
            path = request['path']
            if request['op'] in ('sibling','neighbors'):
                payload=request.get('payload',{})
                neighbors=neighboring_inputs(path,payload.get('include_containers',False),payload.get('book_library'))
                result=({'path':neighbors['previous' if payload['direction']<0 else 'next']}
                        if request['op']=='sibling' else {'neighbors':neighbors})
                sys.stdout.buffer.write((json.dumps({'id':request['id'],'ok':True,**result},ensure_ascii=True)+'\n').encode('ascii'))
                sys.stdout.buffer.flush();continue
            if is_image_source(path):
                payload=request.get('payload',{})
                if request['op']=='editinfo':
                    result={'info':inspect_edit_page(path,request['page'],payload.get('tables',False),payload.get('images',False))}
                elif request['op']=='edit':
                    result={'path':apply_page_edit(path,request['page'],payload['operation'],payload['output'])}
                else:raise ValueError('그림 미리보기는 그림 엔진에서 처리해야 합니다.')
                sys.stdout.buffer.write((json.dumps({'id':request['id'],'ok':True,**result},ensure_ascii=True)+'\n').encode('ascii'))
                sys.stdout.buffer.flush();continue
            if path not in documents:
                doc = viewer_pdf_engine.open(path)
                if not doc.is_pdf or doc.needs_pass:
                    doc.close()
                    raise ValueError('암호가 없는 PDF 파일을 선택하세요.')
                documents[path] = doc
            documents.move_to_end(path)
            while len(documents) > 4:
                documents.popitem(last=False)[1].close()
            doc = documents[path]
            if request['op'] == 'editinfo':
                payload = request.get('payload', {})
                result = {'info': inspect_edit_page(path, request['page'], payload.get('tables', False), payload.get('images', False))}
            elif request['op'] == 'edit':
                payload = request['payload']
                result = {'path': apply_page_edit(path, request['page'], payload['operation'], payload['output'])}
            elif request['op'] == 'inspect':
                result = {'count': len(doc)}
            else:
                page = doc[request['page']]
                rect = page.rect
                if request['op'] == 'preview':
                    limit = max(1000, min(5000, request.get('max_side', 1800)))
                    scale = limit / max(1, rect.width, rect.height)
                else:
                    limit = request.get('payload', {}).get('thumb_side', 370)
                    scale = min(limit*280/370 / max(1, rect.width), limit / max(1, rect.height))
                pix = page.get_pixmap(matrix=viewer_pdf_engine.Matrix(scale, scale), colorspace=viewer_pdf_engine.csRGB, alpha=False)
                if request.get('payload',{}).get('raw_frame'):
                    raw_frame=pix.samples
                    result={'width':pix.width,'height':pix.height,'stride':pix.width*3,
                            'nbytes':len(raw_frame)}
                else:
                    result = {'png': base64.b64encode(pix.tobytes('png')).decode('ascii')}
            response = {'id': request['id'], 'ok': True, **result}
        except Exception as exc:
            raw_frame=b''
            response = {'id': request.get('id'), 'ok': False, 'error': str(exc)}
        sys.stdout.buffer.write((json.dumps(response, ensure_ascii=True) + '\n').encode('ascii'))
        if raw_frame:sys.stdout.buffer.write(raw_frame)
        sys.stdout.buffer.flush()
    for doc in documents.values():
        doc.close()



def hangul_python_executable():
    if getattr(sys,'frozen',False):return ''
    executable=Path(sys.executable)
    if executable.name.lower()=='pythonw.exe' and executable.with_name('python.exe').is_file():
        executable=executable.with_name('python.exe')
    return str(executable)


def hangul_install_command():
    executable=hangul_python_executable()
    return f'"{executable}" -m pip install "python-hwpx==6.6.0"' if executable else ''


