MIME = 'application/x-krs-pdf-pages-v2'
CLIPBOARD_MIME = 'application/x-krs-pdf-clipboard-v1'
TEXT_OBJECT_CLIPBOARD_MIME = 'application/x-the-viewer-text-object-v1'
OBJECT_BUNDLE_CLIPBOARD_MIME = 'application/x-the-viewer-object-bundle-v1'
VECTOR_OBJECT_CLIPBOARD_MIME = 'application/x-the-viewer-vector-object-v1'
IMAGE_CLIPBOARD_MIME = 'application/x-krs-pdf-image-size-v1'
TEMP_ROOT = Path(tempfile.gettempdir()) / 'KRS_PDF_Page_Drag'
PT_PER_MM = 72 / 25.4


def prune_working_files(session_root, references=(), protected=(), scopes=None):
    """Only our working areas; never remove originals, delivery copies or other sessions."""
    session_root=Path(session_root).absolute()
    allowed=[session_root/name for name in ('imports','edits','blank','paste')]
    keep={os.path.normcase(os.path.abspath(p)) for p in references}
    protected=[Path(p).absolute() for p in protected]
    failures=[]
    for scope in (allowed if scopes is None else [Path(p).absolute() for p in scopes]):
        if not any(scope==base or base in scope.parents for base in allowed):continue
        if any(p.is_symlink() for p in [scope,*scope.parents] if p==session_root or session_root in p.parents):continue
        if not scope.is_dir():continue
        for root,dirs,files in os.walk(scope,topdown=False,followlinks=False):
            root=Path(root)
            for name in files:
                path=root/name
                if os.path.normcase(os.path.abspath(path)) in keep:continue
                if any(path==p or p in path.parents for p in protected):continue
                try:path.unlink(missing_ok=True)
                except OSError:failures.append(str(path))
            for name in dirs:
                path=root/name
                if path.is_symlink():continue
                try:path.rmdir()
                except OSError:pass
        try:scope.rmdir()
        except OSError:pass
    try:session_root.rmdir()
    except OSError:pass
    return failures


def worker_launch(flag='--pdf-worker'):
    executable = Path(sys.executable)
    if getattr(sys, 'frozen', False):
        return str(executable), [flag]
    if executable.name.lower() == 'pythonw.exe' and executable.with_name('python.exe').is_file():
        executable = executable.with_name('python.exe')
    if flag == '--pdf-worker':
        # Reuse this already compiled function instead of reparsing the whole
        # single-file application in every Python PDF process. The temporary
        # marshal file belongs to this interpreter/session only; never import
        # user-provided cache files. Frozen EXEs already contain compiled code.
        try:
            import atexit
            import marshal
            cache = getattr(_viewer_fast_pdf_worker, '_launch_cache', None)
            if cache is None or not Path(cache).is_file():
                fd, cache = tempfile.mkstemp(prefix='TheViewer_PdfRead_', suffix='.code')
                try:
                    with os.fdopen(fd, 'wb') as stream:
                        marshal.dump(_viewer_fast_pdf_worker.__code__, stream)
                except BaseException:
                    Path(cache).unlink(missing_ok=True)
                    raise
                _viewer_fast_pdf_worker._launch_cache = cache
                atexit.register(lambda p=cache: Path(p).unlink(missing_ok=True))
            bootstrap = (
                "import sys,marshal,types;"
                "f=open(sys.argv[1],'rb');c=marshal.load(f);f.close();"
                "g={'sys':sys,'__file__':sys.argv[2],'__builtins__':__builtins__};"
                "types.FunctionType(c,g)()"
            )
            return str(executable), ['-u', '-c', bootstrap, cache, str(Path(__file__).resolve()), flag]
        except Exception:
            # Read-only installations/temporary-folder failures can still run
            # the normal single-file entry point with the same fast backend.
            pass
    return str(executable), ['-u', str(Path(__file__).resolve()), flag]


def windows_registration_values(command, icon_path):
    """Register supported file handlers; Windows system UI owns the user's defaults."""
    classes = r'Software\Classes'
    capabilities = r'Software\KRS\TheViewer\Capabilities'
    values = [
        (capabilities, 'ApplicationName', APP_NAME),
        (capabilities, 'ApplicationIcon', '"'+icon_path+'",0'),
        (capabilities, 'ApplicationDescription', 'PDF · JPG · 그림 보기 및 페이지 편집'),
        (r'Software\RegisteredApplications', 'The Viewer', capabilities),
    ]
    for progid, description, extensions in (
        ('TheViewer.PDF', APP_NAME+' PDF', ('.pdf',)),
        ('TheViewer.Image', APP_NAME+' JPG', ('.jpg','.jpeg')),
    ):
        base=classes+'\\'+progid
        values.extend([
            (base, '', description), (base, 'FriendlyTypeName', description),
            (base, 'AppUserModelID', APP_USER_MODEL_ID),
            (base+r'\DefaultIcon', '', '"'+icon_path+'",0'),
            (base+r'\shell\open\command', '', command),
        ])
        for extension in extensions:
            values.extend([
                (classes+'\\'+extension+r'\OpenWithProgids', progid, ''),
                (capabilities+r'\FileAssociations', extension, progid),
            ])
    return values


def windows_default_apps_uri(build=None):
    if build is None:
        build=sys.getwindowsversion().build if sys.platform=='win32' else 0
    return ('ms-settings:defaultapps?registeredAppUser=The%20Viewer'
            if build>=22000 else 'ms-settings:defaultapps')


@dataclass
class PageRef:
    path: str
    number: int
    uid: str = field(default_factory=lambda: uuid.uuid4().hex)
    source_path: str = ''
    source_number: int = -1
    input_path: str = ''  # 연 파일/폴더/ZIP. 편집·복사 후에도 파일 탐색 기준을 보존한다.
    document_pages: int = 0  # Folder PDF/text first-page card.
    text_info: dict = field(default_factory=dict)
    comparison_group: str = ''  # One right-pane drop is one independent navigation group.

    @property
    def is_text_document(self):
        return bool(self.source_path and Path(self.source_path).suffix.lower() in TEXT_EXTENSIONS)

    @property
    def document_kind(self):
        return Path(self.source_path).suffix[1:].upper() if self.is_text_document else 'PDF'

    @property
    def is_document_card(self):
        return self.document_pages > 0

    @property
    def state_key(self):
        return (self.path, self.number, self.document_pages)

    @property
    def label_path(self):
        return self.source_path or self.path

    @property
    def label_number(self):
        return self.source_number if self.source_number >= 0 else self.number


def total_page_count(pages):
    return sum(p.document_pages or 1 for p in pages)


def expanded_page_refs(pages):
    """출력할 때만 PDF 카드를 전체 쪽으로 펼친다. 화면/원본은 변경하지 않는다."""
    expanded=[];counts={}
    for page in pages:
        if not page.is_document_card:
            expanded.append(page);continue
        if page.path not in counts:
            import viewer_pdf_engine
            with viewer_pdf_engine.open(page.path) as doc:
                if not doc.is_pdf or doc.needs_pass:raise ValueError('암호가 없는 PDF를 선택하세요.')
                counts[page.path]=len(doc)
        if counts[page.path]!=page.document_pages:
            raise ValueError(f'원본 PDF의 쪽수가 바뀌었습니다. 폴더를 다시 열어주세요: {Path(page.label_path).name}')
        expanded.extend(PageRef(page.path,i,source_path=page.source_path,
                        source_number=i,input_path=page.input_path,text_info=page.text_info) for i in range(page.document_pages))
    return expanded


def page_is_picture(page):
    return is_image_source(page.path) or Path(page.label_path).suffix.lower() in IMAGE_EXTENSIONS


def page_border_brush(page, rect, selected=False, angle=0):
    if page.is_text_document:return QBrush(QColor('#a78bfa' if selected else '#7c62bd'))
    picture=page_is_picture(page)
    if selected:
        gradient=QConicalGradient(rect.center(),angle)
        colors=('#238bff','#20b2df','#b5fff0','#27d99c','#238bff') if picture else (
                '#e91435','#ff294a','#ffc0c9','#ff425d','#e91435')
        for stop,color in zip((0,.32,.47,.58,1),colors):gradient.setColorAt(stop,QColor(color))
        return QBrush(gradient)
    if picture:
        gradient=QLinearGradient(rect.topLeft(),rect.bottomRight())
        gradient.setColorAt(0,QColor('#298eff'));gradient.setColorAt(1,QColor('#24c79c'))
        return QBrush(gradient)
    return QBrush(QColor('#dc3952'))


def clean_name(value):
    value = value.strip()
    if value.lower().endswith('.pdf'):
        value = value[:-4]
    if not value or any(c in value for c in '<>:"/\\|?*') or any(ord(c) < 32 for c in value):
        raise ValueError('파일 이름에서 \\ / : * ? " < > | 문자를 빼주세요.')
    value = value.rstrip(' .')
    if not value or value.split('.')[0].upper() in {
        'CON', 'PRN', 'AUX', 'NUL', *('COM'+str(i) for i in range(1,10)),
        *('LPT'+str(i) for i in range(1,10)),
    }:
        raise ValueError('Windows에서 사용할 수 없는 파일 이름입니다.')
    if len(value) > 140:
        raise ValueError('파일 이름은 140자 이내로 입력하세요.')
    return value


class ExportCancelled(Exception):
    pass


def export_pages(pages, directory, stem, separate=False):
    """화면 순서대로 복사. 이름 충돌을 먼저 점검하며 실패 시 이번 출력만 정리한다."""
    import viewer_pdf_engine
    pages = expanded_page_refs(pages)
    if not pages:
        return []
    stem = clean_name(stem)
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    groups = [[p] for p in pages] if separate else [pages]
    targets = [directory / (f'{stem}_{i+1:03d}.pdf' if separate else f'{stem}.pdf')
               for i in range(len(groups))]
    for target in targets:
        if target.exists():
            raise FileExistsError(f'이미 있는 파일입니다: {target.name}')
    opened, created = {}, []
    try:
        for group, target in zip(groups, targets):
            app=QApplication.instance()
            if any(is_image_source(p.path) for p in group) and app is not None and QThread.currentThread()==app.thread():
                dialog=ImageExportDialog(app.activeWindow(),target,group);dialog.exec()
                result,error,cancelled=dialog.result_path,dialog.error,dialog.cancelled;dialog.deleteLater()
                if cancelled:raise ExportCancelled()
                if not result:
                    if target.exists():raise FileExistsError(f'이미 있는 파일입니다: {target.name}')
                    raise RuntimeError(error or '그림 PDF 변환을 완료하지 못했습니다.')
                created.append(target);continue
            with viewer_pdf_engine.open() as out:
                for page in group:
                    if is_image_source(page.path):
                        with image_page_document(page.path,page.number) as doc:out.insert_pdf(doc)
                        continue
                    if page.path not in opened:
                        doc = viewer_pdf_engine.open(page.path)
                        if doc.needs_pass:
                            doc.close()
                            raise ValueError('암호가 설정된 PDF입니다.')
                        opened[page.path] = doc
                    out.insert_pdf(opened[page.path], from_page=page.number, to_page=page.number)
                # exclusive create: 기존 파일을 덮어쓰지 않는다.
                data = out.tobytes(garbage=3, deflate=True)
                with target.open('xb') as stream:
                    created.append(target)
                    stream.write(data)
        return targets
    except Exception:
        for target in created:
            target.unlink(missing_ok=True)
        raise
    finally:
        for doc in opened.values():
            doc.close()


def export_numbered_copy(pages, original_path, directory=None):
    """원본 이름 계열의 다음 번호. 동시 실행 중 충돌도 exclusive create로 재시도."""
    if not pages:
        raise ValueError('저장할 페이지가 없습니다.')
    original = Path(original_path)
    folder = Path(directory) if directory is not None else original.parent
    stem = re.sub(r'(?:-정\([0-9]+\))+$', '', original.stem) or original.stem
    pattern = re.compile(re.escape(stem)+r'-정\(([0-9]+)\)\.pdf$', re.IGNORECASE)
    number = 1
    if folder.is_dir():
        for child in folder.iterdir():
            match = pattern.fullmatch(child.name)
            if match:
                number = max(number,int(match[1])+1)
    while True:
        try:
            return export_pages(pages,folder,f'{stem}-정({number})',False)[0]
        except FileExistsError:
            if not folder.is_dir():raise
            number += 1


def reveal_saved_file(path):
    """Open Explorer with the completed file selected; never interpret a shell command."""
    target=Path(path).resolve()
    if not target.is_file():return False
    try:
        if sys.platform=='win32':
            import subprocess
            subprocess.Popen(['explorer.exe','/select,',str(target)])
            return True
        return bool(QDesktopServices.openUrl(QUrl.fromLocalFile(str(target.parent))))
    except Exception:return False


def commit_output_file(part, target, overwrite=True):
    if overwrite:os.replace(part,target)
    elif sys.platform=='win32':os.rename(part,target)  # Windows rename refuses an existing destination.
    else:
        os.link(part,target);Path(part).unlink()  # Same-directory, atomic no-clobber publication.


def choose_pdf_save_path(parent,title,suggestion,protected=()):
    filename,_=QFileDialog.getSaveFileName(parent,title,str(suggestion),'PDF (*.pdf)')
    if not filename:return None
    if not filename.lower().endswith('.pdf'):
        filename+='.pdf'
        if Path(filename).exists() and QMessageBox.question(parent,'파일 덮어쓰기',
            '이미 있는 PDF를 덮어쓸까요?\n'+filename,QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes:return None
    target=Path(filename)
    normalized=os.path.normcase(os.path.realpath(target))
    if normalized in {os.path.normcase(os.path.realpath(p)) for p in protected if p and not is_image_source(p)}:
        QMessageBox.warning(parent,'PDF 저장','현재 읽고 있는 원본과 다른 파일 이름을 지정하세요.');return None
    return target


def next_print_save_path(directory,stem):
    directory=Path(directory);stem=clean_name(stem);number=0
    while True:
        target=directory/(stem+(f'({number})' if number else '')+'.pdf')
        if not target.exists():return target
        number+=1


def export_pdf_to_path(pages,target):
    """Write a complete new document before replacing a user-confirmed destination."""
    target=Path(target)
    if not target.parent.is_dir():raise FileNotFoundError('저장 폴더가 없습니다: '+str(target.parent))
    with tempfile.TemporaryDirectory(prefix='TheViewerSave_',dir=str(target.parent)) as work:
        temporary=export_pages(pages,work,target.name,False)[0]
        commit_output_file(temporary,target,overwrite=True)
    return target


def deepl_client(api_key):
    try:
        import deepl
    except ImportError:
        raise RuntimeError('번역 모듈을 설치하세요.\nCMD: py -m pip install -U deepl') from None
    client_type=getattr(deepl,'DeepLClient',deepl.Translator)
    return client_type(api_key)


def protect_deepl_key(key):
    """Windows 현재 사용자 계정의 DPAPI로 보호. 평문 설정 파일을 만들지 않는다."""
    if sys.platform!='win32':
        raise RuntimeError('이 PC에 키 저장은 Windows에서 지원합니다. 현재 실행 중에는 키를 사용할 수 있습니다.')
    try:
        import win32crypt
    except ImportError:
        raise RuntimeError('키 저장 모듈을 설치하세요.\nCMD: py -m pip install -U pywin32') from None
    encrypted=win32crypt.CryptProtectData(key.encode('utf-8'),'PDF Magnet DeepL',None,None,None,1)
    return base64.b64encode(encrypted).decode('ascii')


def load_deepl_key(settings):
    encrypted=settings.value('deepl/key_dpapi','',type=str)
    if not encrypted or sys.platform!='win32':return ''
    try:
        import win32crypt
        return win32crypt.CryptUnprotectData(base64.b64decode(encrypted),None,None,None,1)[1].decode('utf-8')
    except Exception:
        return ''


def translation_stem(original):
    base=Path(original).stem
    base=re.sub(r'-\(번역\)(?:\([0-9]+\))?$','',base) or base
    return clean_name(base+'-(번역)')


def next_translation_path(directory, stem):
    folder=Path(directory);stem=clean_name(stem);number=0
    while True:
        candidate=folder/(stem+(f'({number})' if number else '')+'.pdf')
        if not candidate.exists():return candidate
        number+=1


def publish_translation(download, directory, stem):
    """완료된 다운로드를 새 파일로 복사. 경합 시 번호를 올리고 기존 파일은 보존."""
    import shutil
    folder=Path(directory);folder.mkdir(parents=True,exist_ok=True)
    while True:
        target=next_translation_path(folder,stem)
        try:
            stream=target.open('xb')
        except FileExistsError:
            continue
        try:
            with stream, Path(download).open('rb') as source:
                shutil.copyfileobj(source,stream,1024*1024)
            return target
        except Exception:
            try:target.unlink(missing_ok=True)
            except OSError:pass
            raise


class DeepLWorker(QThread):
    """네트워크 전용 작업. PDF 처리는 이 스레드에서 실행하지 않는다."""
    stage=Signal(str)
    result=Signal(object)
    failed=Signal(object)

    def __init__(self, api_key, job=None, parent=None):
        super().__init__(parent)
        self.api_key=api_key
        self.job=dict(job) if job is not None else None

    def run(self):
        try:
            client=deepl_client(self.api_key)
            if self.job is None:
                usage=client.get_usage()
                chars=usage.character
                self.result.emit({'kind':'usage','valid':chars.valid,
                                  'count':chars.count if chars.valid else None,
                                  'limit':chars.limit if chars.valid else None})
                return
            job=self.job
            handle=job.get('handle')
            if handle is None:
                self.stage.emit('DeepL로 PDF 전송 중…')
                with Path(job['input']).open('rb') as source:
                    handle=client.translate_document_upload(source,target_lang='KO',output_format='pdf')
                job['handle']=handle
            self.stage.emit('DeepL 번역 상태 확인 중…')
            deadline=time.monotonic()+1800
            previous=''
            while True:
                status=client.translate_document_get_status(handle)
                if not status.ok:
                    job['terminal_error']=True
                    raise RuntimeError(status.error_message or 'DeepL에서 문서 번역에 실패했습니다.')
                if status.done:
                    job['billed_characters']=status.billed_characters
                    break
                state=getattr(status.status,'value',str(status.status))
                if state=='downloaded':
                    job['terminal_error']=True
                    raise RuntimeError('DeepL에서 이미 내려받은 문서로 표시됩니다. 저장 폴더와 번역 기록을 확인하세요.')
                label='DeepL 대기 중…' if state=='queued' else '한국어로 번역 중…'
                if label!=previous:self.stage.emit(label);previous=label
                if time.monotonic()>deadline:
                    raise TimeoutError('번역 상태 확인 시간이 지났습니다. 이어받기로 같은 작업을 다시 확인할 수 있습니다.')
                self.msleep(1500)
            self.stage.emit('번역 PDF 내려받는 중…')
            destination=Path(job['download'])
            # 사용자에게 보이는 PDF는 다운로드와 PDF 검사가 모두 끝난 뒤 만든다.
            with destination.open('wb') as stream:
                client.translate_document_download(handle,stream,chunk_size=64*1024)
            job['downloaded']=True
            self.result.emit({'kind':'translation','job':dict(job)})
        except Exception as exc:
            message=f'{type(exc).__name__}: {exc}'
            secrets=[self.api_key]
            if self.job is not None:
                handle=self.job.get('handle')
                if handle is not None:secrets.append(getattr(handle,'document_key',''))
                if not self.job.get('downloaded'):
                    try:Path(self.job['download']).unlink(missing_ok=True)
                    except OSError:pass
            for secret in secrets:
                if secret:message=message.replace(secret,'[숨김]')
            self.failed.emit({'message':message,'job':dict(self.job) if self.job is not None else None})
        finally:
            self.api_key=''


class TranslationStatusDialog(QDialog):
    def __init__(self, owner):
        super().__init__(owner)
        self.owner=owner;self.setWindowTitle('PDF 번역');self.resize(510,340)
        self.setWindowIcon(corner_icon('translate'))
        layout=QVBoxLayout(self)
        self.status=QLabel();self.status.setWordWrap(True);layout.addWidget(self.status)
        self.progress=QProgressBar();self.progress.setTextVisible(False);layout.addWidget(self.progress)
        self.log=QPlainTextEdit();self.log.setReadOnly(True);layout.addWidget(self.log)
        row=QHBoxLayout();layout.addLayout(row)
        self.retry=QPushButton('이어받기');self.retry.clicked.connect(owner.resume_translation);row.addWidget(self.retry)
        self.open_button=QPushButton('검토뷰 열기');self.open_button.clicked.connect(owner.open_translation);row.addWidget(self.open_button)
        self.copy=QPushButton('내용 복사');self.copy.clicked.connect(lambda:QApplication.clipboard().setText(self.log.toPlainText()));row.addWidget(self.copy)
        close=QPushButton('닫기');close.clicked.connect(self.hide);row.addWidget(close)
        owner.translationChanged.connect(self.refresh);self.refresh()

    def refresh(self):
        owner=self.owner;job=owner.translation_job or {}
        self.status.setText(owner.translation_status)
        self.progress.setRange(0,0 if owner.translation_busy else 100)
        if not owner.translation_busy:self.progress.setValue(100 if job.get('published') else 0)
        text='\n'.join(owner.translation_log)
        if text!=self.log.toPlainText():
            self.log.setPlainText(text);bar=self.log.verticalScrollBar();bar.setValue(bar.maximum())
        self.retry.setText('저장 다시 시도' if job.get('downloaded') else '이어받기')
        self.retry.setVisible(bool(job and not job.get('published') and not job.get('terminal_error') and (job.get('handle') or job.get('downloaded'))))
        self.retry.setEnabled(not owner.translation_busy)
        self.open_button.setVisible(bool(job.get('published')))


class TranslationSettings(QWidget):
    def __init__(self, owner, dialog):
        super().__init__();self.owner=owner;self.dialog=dialog
        layout=QVBoxLayout(self);layout.setSpacing(10)
        title=QLabel('DeepL · 한국어 PDF 번역');title.setStyleSheet('font-size:17px;font-weight:600;');layout.addWidget(title)
        self.show_toolbar_button=QCheckBox('상단에 번역 버튼 표시')
        self.show_toolbar_button.setObjectName('show_translate_toolbar_button')
        self.show_toolbar_button.setChecked(owner.settings.value('toolbar/show_translate',False,type=bool))
        self.show_toolbar_button.toggled.connect(lambda checked:owner.set_toolbar_button_visible('translate',checked))
        layout.addWidget(self.show_toolbar_button)
        self.key=QLineEdit(owner.deepl_api_key);self.key.setEchoMode(QLineEdit.EchoMode.Password)
        self.key.setPlaceholderText('DeepL API 키');self.key.setObjectName('deepl_api_key')
        row=QHBoxLayout();row.addWidget(self.key)
        peek=QPushButton('보기');peek.setCheckable(True)
        peek.toggled.connect(lambda checked:self.key.setEchoMode(QLineEdit.EchoMode.Normal if checked else QLineEdit.EchoMode.Password))
        row.addWidget(peek);layout.addLayout(row)
        self.remember=QCheckBox('이 PC에 키 저장 (Windows 계정 암호화)')
        self.remember.setChecked(sys.platform=='win32' and owner.settings.value('deepl/remember_key',True,type=bool))
        self.remember.setEnabled(sys.platform=='win32');layout.addWidget(self.remember)
        row=QHBoxLayout()
        apply=QPushButton('키 적용');apply.clicked.connect(self.apply_key);row.addWidget(apply)
        remove=QPushButton('키 삭제');remove.clicked.connect(self.remove_key);row.addWidget(remove)
        self.check=QPushButton('연결 / 사용량 확인');self.check.clicked.connect(self.check_key);row.addWidget(self.check)
        layout.addLayout(row)
        self.key_status=QLabel();self.key_status.setWordWrap(True);layout.addWidget(self.key_status)
        form=QFormLayout();form.addRow('원문 언어',QLabel('자동 감지'));form.addRow('번역 언어',QLabel('한국어'))
        row=QHBoxLayout();self.folder=QLineEdit(owner.translation_directory)
        self.folder.setPlaceholderText('비워두면 원본 PDF 폴더');self.folder.textChanged.connect(self.save_folder)
        choose=QPushButton('폴더');choose.clicked.connect(self.choose_folder)
        row.addWidget(self.folder);row.addWidget(choose);form.addRow('저장 위치',row)
        form.addRow('파일명',QLabel('원본이름-(번역).pdf · 중복 시 (1), (2)…'))
        form.addRow('문서 번역 사용량',QLabel('PDF 한 파일당 최소 50,000자 산정'));layout.addLayout(form)
        self.usage=QLabel();self.usage.setWordWrap(True);layout.addWidget(self.usage)
        self.status=QLabel();self.status.setWordWrap(True);layout.addWidget(self.status)
        self.start=QPushButton('현재 PDF 번역');self.start.setIcon(corner_icon('translate'));self.start.clicked.connect(self.start_now)
        layout.addWidget(self.start)
        details=QPushButton('번역 진행 / 결과')
        details.clicked.connect(lambda:(dialog.accept(),QTimer.singleShot(0,owner.show_translation_status)));layout.addWidget(details)
        layout.addStretch()
        owner.translationChanged.connect(self.refresh);self.refresh()

    def apply_key(self):
        key=self.key.text().strip()
        if not key:self.key_status.setText('API 키를 입력하세요.');return False
        self.owner.deepl_api_key=key
        self.owner.settings.setValue('deepl/remember_key',self.remember.isChecked())
        try:
            if self.remember.isChecked():
                encrypted=protect_deepl_key(key)
                self.owner.settings.setValue('deepl/key_dpapi',encrypted)
                self.owner.settings.sync()
                if self.owner.settings.status()!=QSettings.Status.NoError:raise OSError('API 키 설정 저장에 실패했습니다.')
                self.key_status.setText('키를 적용하고 이 PC에 저장했습니다.')
            else:
                self.owner.settings.remove('deepl/key_dpapi');self.owner.settings.sync()
                self.key_status.setText('현재 실행에 키를 적용했습니다.')
        except Exception as exc:
            self.key_status.setText(f'키는 현재 실행에 적용되었습니다. 저장은 실패했습니다.\n{exc}')
        return True

    def remove_key(self):
        self.key.clear();self.owner.deepl_api_key=''
        self.remember.setChecked(False);self.owner.settings.setValue('deepl/remember_key',False)
        self.owner.settings.remove('deepl/key_dpapi');self.owner.settings.sync()
        self.key_status.setText('저장된 키를 삭제했습니다.')

    def save_folder(self, text):
        self.owner.translation_directory=text.strip()
        self.owner.settings.setValue('deepl/directory',text.strip())

    def choose_folder(self):
        folder=QFileDialog.getExistingDirectory(self,'번역 PDF 저장 폴더',self.folder.text())
        if folder:self.folder.setText(folder)

    def check_key(self):
        if self.apply_key():self.owner.check_deepl_usage()

    def start_now(self):
        if self.apply_key():
            self.dialog.accept();QTimer.singleShot(0,self.owner.translate_current)

    def refresh(self):
        owner=self.owner
        self.usage.setText(owner.deepl_usage_text)
        self.status.setText(owner.translation_status)
        self.start.setEnabled(bool(owner.pages) and not owner.translation_busy)
        self.check.setEnabled(owner.usage_thread is None)


class PageState(list):
    def __init__(self, pages, original_path):
        super().__init__(pages)
        self.original_path = original_path


class ConversionProcessBase(QObject):
    """Own the converter process so cancel/timeout stops child conversion processes."""
    completed=Signal(int,object)
    progress=Signal(int,object)
    cancelled=Signal(int)

    def __init__(self,parent=None):
        super().__init__(parent)
        self.proc=QProcess(self);self.active=None;self.cancelling=None;self.closing=False
        self.phase='';self.buffer=b'';self.errors=b'';self.job=None;self.terminal_error=''
        self.timeout=QTimer(self);self.timeout.setSingleShot(True);self.timeout.timeout.connect(self.timed_out)
        self.tick=QTimer(self);self.tick.setInterval(500);self.tick.timeout.connect(self.report_progress)
        self.proc.started.connect(self.send_job)
        self.proc.readyReadStandardOutput.connect(self.read_output)
        self.proc.readyReadStandardError.connect(self.read_error)
        self.proc.finished.connect(self.process_finished);self.proc.errorOccurred.connect(self.failed)

    def start(self,token,path,directory,engine='',timeout_seconds=120):
        self.completed.emit(token,{'error':'이 빌드에서는 DWG·AI·EPS·PS를 지원하지 않습니다. PDF로 저장해 열어주세요.'})

    def report_progress(self):
        if self.active is None:return
        stages={'probe':'PDF 데이터 확인','convert':'임시 PDF 변환','verify':'변환 PDF 확인'}
        self.progress.emit(self.active,{'phase':'vector','stage':stages.get(self.phase,''),
            'seconds':int(time.monotonic()-self.started_at),'name':self.source})

    def launch(self,executable,args,phase,job=None):
        self.phase=phase;self.job=job;self.buffer=b'';self.errors=b''
        env=QProcessEnvironment.systemEnvironment()
        if phase=='convert':
            for key in ('GS_OPTIONS','GS_DEVICE'):env.remove(key)
            # PyInstaller's private shared libraries must not replace an installed engine's libraries.
            if getattr(sys,'frozen',False):
                for key in ('LD_LIBRARY_PATH','DYLD_LIBRARY_PATH'):
                    if env.contains(key+'_ORIG'):env.insert(key,env.value(key+'_ORIG'))
                    else:env.remove(key)
        self.proc.setProcessEnvironment(env);self.proc.setWorkingDirectory(str(self.directory))
        self.report_progress();self.proc.start(executable,args)


    def send_job(self):
        if self.job is not None:
            self.proc.write((json.dumps(self.job,ensure_ascii=True)+'\n').encode('ascii'))
        self.proc.closeWriteChannel()

    def read_output(self):self.buffer=(self.buffer+bytes(self.proc.readAllStandardOutput()))[-65536:]
    def read_error(self):self.errors=(self.errors+bytes(self.proc.readAllStandardError()))[-65536:]

    def process_finished(self,exit_code,*_args):
        self.finish({'error':'이 형식의 변환은 제외된 기능입니다.'})

    def failed(self,error):
        if error!=QProcess.ProcessError.FailedToStart:return  # crashes also emit finished
        if self.cancelling is not None:self.finish_cancel()
        elif self.active is not None:self.finish({'error':'읽기 프로그램을 실행하지 못했습니다.\n'+self.proc.errorString()})

    def timed_out(self):
        self.terminal_error='변환 제한 시간을 초과했습니다.'
        self.proc.kill()

    def finish(self,result):
        if self.active is None or self.closing:return
        token=self.active;self.active=None;self.timeout.stop();self.tick.stop()
        self.completed.emit(token,result)

    def cancel(self,token):
        self.active=None;self.cancelling=token;self.timeout.stop();self.tick.stop()
        if self.proc.state()==QProcess.ProcessState.NotRunning:QTimer.singleShot(0,self.finish_cancel)
        else:self.proc.kill()

    def finish_cancel(self):
        if self.cancelling is None:return
        token=self.cancelling;self.cancelling=None;self.buffer=b'';self.errors=b''
        self.cancelled.emit(token)

    def stop(self):
        self.closing=True;self.active=None;self.cancelling=None;self.timeout.stop();self.tick.stop()
        if self.proc.state()!=QProcess.ProcessState.NotRunning:
            self.proc.kill();self.proc.waitForFinished(1500)


class DocumentBackend(ConversionProcessBase):
    def __init__(self,parent=None):
        super().__init__(parent);self.job_object=None;self.result_data=None;self.worker_pid=0

    def start(self,token,path,directory,office='',cad='',timeout_seconds=DOCUMENT_TIMEOUT_SECONDS):
        if self.active is not None or self.cancelling is not None:raise RuntimeError('현재 문서 변환을 먼저 마쳐 주세요.')
        self.active=token;self.source=str(Path(path).resolve());self.directory=Path(directory)
        self.started_at=time.monotonic();self.terminal_error='';self.stage='PDF 변환 준비';self.result_data=None
        self.worker_pid=0;self.job_name='TheViewerConvert_'+uuid.uuid4().hex
        try:self.directory.mkdir(parents=True,exist_ok=True)
        except OSError as exc:QTimer.singleShot(0,lambda message=str(exc):self.finish({'error':message}));return
        self.timeout.start(max(1,int(timeout_seconds*1000)));self.tick.start()
        executable,args=worker_launch('--document-worker')
        self.launch(executable,args,'document',{'path':self.source,'directory':str(self.directory),
            'office':office,'cad':cad,'job_name':self.job_name})

    def send_job(self):
        self.worker_pid=int(self.proc.processId())
        if sys.platform=='win32':
            try:
                import win32job,win32api
                self.job_object=win32job.CreateJobObject(None,self.job_name)
                info=win32job.QueryInformationJobObject(self.job_object,win32job.JobObjectExtendedLimitInformation)
                info['BasicLimitInformation']['LimitFlags']|=win32job.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
                win32job.SetInformationJobObject(self.job_object,win32job.JobObjectExtendedLimitInformation,info)
                process=win32api.OpenProcess(0x0100|0x0001|0x0400,False,self.worker_pid)
                try:win32job.AssignProcessToJobObject(self.job_object,process)
                finally:process.Close()
            except Exception as exc:
                self.terminal_error='문서 변환 프로세스 격리에 실패했습니다.\n'+str(exc);self.kill_tree();return
        super().send_job()

    def report_progress(self):
        if self.active is not None:
            label=document_theme(self.source)[0]
            self.progress.emit(self.active,{'phase':'vector','stage':self.stage,
                'message':label+' 파일을 PDF로 읽는 중입니다.','seconds':int(time.monotonic()-self.started_at),'name':self.source})

    def read_output(self):
        self.buffer+=bytes(self.proc.readAllStandardOutput())
        while b'\n' in self.buffer:
            line,self.buffer=self.buffer.split(b'\n',1)
            try:data=json.loads(line)
            except (ValueError,UnicodeError):continue
            if 'progress' in data:self.stage=str(data['progress']);self.report_progress()
            if 'result' in data:self.result_data=data['result']
        self.buffer=self.buffer[-65536:]

    def kill_tree(self):
        if self.job_object is not None:
            import win32job
            try:win32job.TerminateJobObject(self.job_object,1)
            except Exception:pass
        elif sys.platform!='win32' and self.worker_pid:
            import signal
            try:os.killpg(self.worker_pid,signal.SIGKILL)
            except ProcessLookupError:pass
            except OSError:pass
        if self.proc.state()!=QProcess.ProcessState.NotRunning:self.proc.kill()

    def release_group(self):
        if self.job_object is not None:
            self.job_object.Close();self.job_object=None
        elif sys.platform!='win32' and self.worker_pid:
            import signal
            try:os.killpg(self.worker_pid,signal.SIGKILL)
            except OSError:pass
        self.worker_pid=0

    def process_finished(self,exit_code,*_args):
        self.read_output();self.read_error();self.release_group()
        if self.cancelling is not None:self.finish_cancel();return
        if self.active is None or self.closing:return
        result=self.result_data
        if self.terminal_error:result={'error':self.terminal_error}
        elif exit_code or not result:result={'error':'문서 변환 프로세스가 완료되지 않았습니다.\n'+self.errors.decode('utf-8','replace')[-1800:]}
        self.finish(result)

    def timed_out(self):
        if self.active is None:return
        self.terminal_error='문서 변환 제한 시간을 초과했습니다. 원본 프로그램에서 PDF로 저장해 열어 주세요.'
        self.kill_tree()

    def cancel(self,token):
        self.active=None;self.cancelling=token;self.timeout.stop();self.tick.stop()
        self.kill_tree()
        if self.proc.state()==QProcess.ProcessState.NotRunning:self.release_group();QTimer.singleShot(0,self.finish_cancel)

    def stop(self):
        self.kill_tree();super().stop();self.release_group()


def compact_plus_path(rect,stem_width=None,stem_height=None):
    """Short, thick arms; one closed filled shape with no overlapping center seams."""
    cx,cy=rect.center().x(),rect.center().y()
    sx=(rect.width()*26/60 if stem_width is None else stem_width)/2
    sy=(rect.height()*26/60 if stem_height is None else stem_height)/2
    points=[(cx-sx,rect.top()),(cx+sx,rect.top()),(cx+sx,cy-sy),
            (rect.right(),cy-sy),(rect.right(),cy+sy),(cx+sx,cy+sy),
            (cx+sx,rect.bottom()),(cx-sx,rect.bottom()),(cx-sx,cy+sy),
            (rect.left(),cy+sy),(rect.left(),cy-sy),(cx-sx,cy-sy)]
    path=QPainterPath();path.setFillRule(Qt.FillRule.WindingFill)
    path.moveTo(QPointF(*points[0]))
    for point in points[1:]:path.lineTo(QPointF(*point))
    path.closeSubpath();return path


class ConversionOverlay(QWidget):
    """Document-conversion overlay.

    Numeric worker progress is used when supplied. Otherwise the fill advances only
    when the converter reports a new stage; elapsed time alone never invents progress.
    The frame interior has no separate static panel color: only the progress fill rises
    from the bottom. On success the center [+] expands until it fills the frame.
    """
    cancelled=Signal()

    def __init__(self,owner):
        super().__init__(owner.content);self.owner=owner;self.state='hidden';self.stage='';self.source=''
        self.started_at=0.;self.finished_at=0.;self.success=True
        self.progress=0.;self.target_progress=0.;self.stage_serial=0;self.last_stage=''
        self.timer=QTimer(self);self.timer.setInterval(25);self.timer.timeout.connect(self.tick)
        self.cancel=QPushButton('취소',self);self.cancel.setFixedSize(48,23);self.cancel.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.cancel.setStyleSheet('QPushButton{background:rgba(110,120,140,35);color:#aab4c5;border:1px solid #566277;border-radius:5px;font-size:11px;}')
        self.cancel.clicked.connect(self.cancelled);self.setAcceptDrops(True);self.hide()

    def begin(self,path):
        self.source=str(path);self.label,self.color=document_theme(path)
        batch=self.owner.pending_import[2] if self.owner.pending_import else None
        self.target_editor=batch.get('preview_target') if batch else None
        self.target_host=self.owner.thumbnail_host.body if self.target_editor is not None else self.owner.preview_host
        self.state='running';self.started_at=time.monotonic();self.stage='PDF 변환 준비'
        self.finished_at=0.;self.success=True;self.progress=.04;self.target_progress=.07
        self.stage_serial=0;self.last_stage=self.stage
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents,False)
        self.cancel.show();self.timer.start();self.place()

    @staticmethod
    def _bounded_fraction(value):
        try:value=float(value)
        except (TypeError,ValueError):return None
        if not math.isfinite(value):return None
        if value>1:value/=100
        return max(0.,min(1.,value))

    def set_stage(self,data):
        if self.state!='running':return
        stage=str(data.get('stage',self.stage) or self.stage)
        self.stage=stage
        # Prefer real worker progress whenever a future/current backend supplies it.
        fraction=self._bounded_fraction(data.get('fraction'))
        if fraction is None:fraction=self._bounded_fraction(data.get('progress'))
        if fraction is None:
            done,total=data.get('done'),data.get('total')
            try:
                if total and float(total)>0:fraction=max(0.,min(1.,float(done)/float(total)))
            except (TypeError,ValueError):fraction=None
        if fraction is not None:
            self.target_progress=max(self.target_progress,min(.97,fraction))
        elif stage!=self.last_stage:
            self.stage_serial+=1;self.last_stage=stage
            lowered=stage.casefold()
            mapped=None
            for key,value in (
                ('준비',.08),('확인',.18),('분석',.20),('사본',.27),
                ('dwg → dxf',.42),('pdf 저장',.68),('→ pdf',.68),
                ('구성',.72),('변환 pdf 확인',.92),('pdf 확인',.92),
            ):
                if key in lowered:
                    mapped=value;break
            # Repeated page/stage messages still move forward, but never by elapsed time.
            fallback=min(.91,.12+self.stage_serial*.105)
            self.target_progress=max(self.target_progress,mapped if mapped is not None else fallback)
        self.update()

    def finish(self,success=True,cancelled=False):
        if self.state=='hidden':return
        self.state='settling';self.finished_at=time.monotonic();self.success=success
        self.stage='취소' if cancelled else '완료' if success else 'PDF로 저장해 열어주세요'
        if success:self.progress=self.target_progress=1.
        self.cancel.hide();self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents,True);self.update()

    def dismiss(self):self.timer.stop();self.state='hidden';self.hide()

    def place(self):
        if self.state=='hidden':return
        if self.target_editor is not None and (not self.owner.dual_mode or self.target_editor is not self.owner.dual_preview):
            self.hide();return
        target=self.target_host
        origin=target.mapTo(self.parentWidget(),QPoint(0,0))
        self.setGeometry(origin.x(),origin.y(),target.width(),target.height())
        self.cancel.move(max(0,self.width()//2-24),min(self.height()-28,self.height()//2+137))
        self.show();self.raise_();self.update()

    def dragEnterEvent(self,event):
        if self.owner.accepts_open_drop(event):event.setDropAction(Qt.DropAction.CopyAction);event.accept()
        else:event.ignore()

    def dragMoveEvent(self,event):self.dragEnterEvent(event)

    def dropEvent(self,event):
        batch=self.owner.pending_import[2] if self.owner.pending_import else None
        right=batch.get('preview_target') if batch else None
        if right is not None and right is self.owner.dual_preview:self.owner.drop_comparison_files(right,event)
        else:self.owner.dropEvent(event)

    def tick(self):
        if self.state=='running':
            # Smooth only toward a stage/worker-derived target.
            self.progress+=max(0.,self.target_progress-self.progress)*.14
            if self.target_progress-self.progress<.002:self.progress=self.target_progress
        elif self.state=='settling' and time.monotonic()-self.finished_at>1.0:
            self.dismiss();return
        self.place()

    def paintEvent(self,event):
        if self.state=='hidden':return
        painter=QPainter(self);painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        elapsed=time.monotonic()-self.started_at
        done=min(1.,max(0.,(time.monotonic()-self.finished_at)/.68)) if self.state=='settling' else 0.
        fade=1.-max(0.,(done-.82)/.18)*.38
        bg=QColor('#181b24' if self.owner.dark else '#edf0f5');bg.setAlpha(round(245*fade));painter.fillRect(self.rect(),bg)
        painter.translate(self.width()/2,self.height()/2-22)
        scale=min(1.,self.width()/370,self.height()/380);painter.scale(scale,scale)

        color=QColor(self.color)
        frame_left,frame_top,frame_right,frame_bottom=-103.,-86.,103.,86.
        inner=QRectF(frame_left+8,frame_top+8,(frame_right-frame_left)-16,(frame_bottom-frame_top)-16)

        # [ ] frame only. There is deliberately no differently colored static panel inside it.
        painter.setBrush(Qt.BrushStyle.NoBrush);painter.setPen(QPen(color,5,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap,Qt.PenJoinStyle.RoundJoin))
        for side in (-1,1):
            x=frame_right if side>0 else frame_left
            inward=-side*20
            painter.drawLine(QPointF(x+inward,frame_top),QPointF(x,frame_top))
            painter.drawLine(QPointF(x,frame_top),QPointF(x,frame_bottom))
            painter.drawLine(QPointF(x,frame_bottom),QPointF(x+inward,frame_bottom))

        # Stage/worker progress rises strictly from bottom to top.
        visible_progress=1. if self.state=='settling' and self.success else max(0.,min(.97,self.progress))
        fill_h=inner.height()*visible_progress
        if fill_h>0:
            progress_color=QColor(color);progress_color.setAlpha(48 if self.state=='running' else 70)
            painter.setPen(Qt.PenStyle.NoPen);painter.setBrush(progress_color)
            painter.drawRoundedRect(QRectF(inner.left(),inner.bottom()-fill_h,inner.width(),fill_h),3,3)

        # A compact 60px cross grows continuously into the completed rectangle.
        if self.state=='settling' and self.success:
            ease=1-(1-done)**3
            width=60+(inner.width()-60)*ease;height=60+(inner.height()-60)*ease
            bounds=QRectF(-width/2,-height/2,width,height)
            plus=compact_plus_path(bounds,26+(inner.width()-26)*ease,26+(inner.height()-26)*ease)
            fill=QColor(color);fill.setAlpha(round(190+35*done))
            painter.setPen(Qt.PenStyle.NoPen);painter.setBrush(fill);painter.drawPath(plus)
            if done>.94:
                outline=QColor(color.lighter(145));outline.setAlpha(180)
                painter.setBrush(Qt.BrushStyle.NoBrush);painter.setPen(QPen(outline,2));painter.drawRoundedRect(inner,3,3)
        else:
            pulse=1.+.025*math.sin(elapsed*7.5)
            painter.save();painter.scale(pulse,pulse)
            plus=compact_plus_path(QRectF(-30,-30,60,60))
            glow=QColor(color);glow.setAlpha(30)
            painter.setBrush(Qt.BrushStyle.NoBrush);painter.setPen(QPen(glow,8));painter.drawPath(plus)
            fill=QColor(color);fill.setAlpha(210)
            painter.setBrush(fill);painter.setPen(QPen(color.lighter(125),1.5,Qt.PenStyle.SolidLine,
                Qt.PenCapStyle.RoundCap,Qt.PenJoinStyle.RoundJoin));painter.drawPath(plus)
            painter.restore()

        painter.setPen(QColor('#aeb8ca' if self.owner.dark else '#566177'))
        font=QFont();font.setPixelSize(12);painter.setFont(font)
        name=self.fontMetrics().elidedText(Path(self.source).name,Qt.TextElideMode.ElideMiddle,280)
        painter.drawText(QRectF(-155,102,310,22),Qt.AlignmentFlag.AlignCenter,name)
        font.setPixelSize(11);painter.setFont(font)
        stage=self.stage+(f' · {int(elapsed)}초' if self.state=='running' else '')
        painter.drawText(QRectF(-170,124,340,36),Qt.AlignmentFlag.AlignHCenter|Qt.TextFlag.TextWordWrap,stage)
        painter.end()







class InputBackend(QObject):
    itemReady=Signal(int,object)
    progress=Signal(int,object)
    completed=Signal(int,object)
    cancelled=Signal(int)

    def __init__(self,parent=None):
        super().__init__(parent)
        self.proc=QProcess(self);self.buffer=b'';self.active=None;self.closing=False;self.cancelling=None
        self.drain_timer=QTimer(self);self.drain_timer.setSingleShot(True)
        self.drain_timer.timeout.connect(self.drain_output)
        self.proc.readyReadStandardOutput.connect(self.read_output)
        self.proc.readyReadStandardError.connect(lambda:self.proc.readAllStandardError())
        self.proc.started.connect(self.send_job)
        self.proc.errorOccurred.connect(self.failed)
        self.proc.finished.connect(self.process_finished)

    def start(self,token,path,directory,text_options=None,text_encoding='auto'):
        if self.cancelling is not None:raise RuntimeError('읽기 프로세스 종료를 기다리는 중입니다.')
        self.active={'id':token,'path':path,'directory':str(directory),'text_options':text_options,'text_encoding':text_encoding}
        if self.proc.state()==QProcess.ProcessState.Running:self.send_job()
        else:
            self.buffer=b''
            executable,args=worker_launch('--input-worker');self.proc.start(executable,args)

    def send_job(self):
        if self.active:self.proc.write((json.dumps(self.active,ensure_ascii=True)+'\n').encode('ascii'))

    def read_output(self):
        self.buffer+=bytes(self.proc.readAllStandardOutput())
        if self.active and not self.drain_timer.isActive():self.drain_timer.start(0)
        elif not self.active:self.buffer=b''

    def drain_output(self):
        # Yield to mouse/keyboard events even when the worker has filled the pipe.
        started=time.monotonic();handled=0
        while self.active and b'\n' in self.buffer and handled<16 and time.monotonic()-started<.012:
            line,self.buffer=self.buffer.split(b'\n',1)
            handled+=1
            try:data=json.loads(line)
            except (ValueError,UnicodeError):continue
            if not self.active or data.get('id')!=self.active['id']:continue
            token=self.active['id']
            if 'item' in data:self.itemReady.emit(token,data['item'])
            elif 'progress' in data:self.progress.emit(token,data['progress'])
            elif 'done' in data:
                self.active=None;self.completed.emit(token,data['done'])
        if self.active and b'\n' in self.buffer:self.drain_timer.start(0)

    def cancel(self,token):
        self.active=None;self.cancelling=token;self.buffer=b'';self.drain_timer.stop()
        if self.proc.state()==QProcess.ProcessState.NotRunning:QTimer.singleShot(0,self.finish_cancel)
        else:self.proc.kill()

    def finish_cancel(self):
        if self.cancelling is None:return
        token=self.cancelling;self.cancelling=None;self.buffer=b''
        self.proc.readAllStandardOutput();self.cancelled.emit(token)

    def process_finished(self,*_args):
        if self.cancelling is not None:self.finish_cancel()
        else:self.failed()

    def failed(self,*_args):
        if self.cancelling is not None:
            if self.proc.state()==QProcess.ProcessState.NotRunning:self.finish_cancel()
            return
        if self.proc.state()!=QProcess.ProcessState.NotRunning:return
        if self.closing or not self.active:return
        token=self.active['id'];self.active=None
        self.completed.emit(token,{'errors':['그림/폴더 읽기 프로세스가 중단되었습니다. 파일과 Pillow 설치를 확인하세요.']})

    def stop(self):
        self.closing=True;self.active=None;self.cancelling=None;self.drain_timer.stop();self.buffer=b''
        if self.proc.state()!=QProcess.ProcessState.NotRunning:
            self.proc.kill();self.proc.waitForFinished(1500)


class PdfBackend(QObject):
    searchResult = Signal(int,object,str)
    metadata = Signal(int, str, int, str)
    thumbnail = Signal(str, int, object, str)
    preview = Signal(int, object, str)
    editInfo = Signal(int, object, str)
    edited = Signal(int, str, str)
    pageBatchDone = Signal(int, object, str)
    siblingReady = Signal(int, str, str)
    neighborsReady = Signal(int, object, str)
    released = Signal()
    warmed = Signal(str)

    def __init__(self, parent=None,worker_flag='--pdf-worker',lazy=False):
        super().__init__(parent)
        self.proc = QProcess(self)
        self.proc.readyReadStandardOutput.connect(self.read_output)
        self.proc.readyReadStandardError.connect(lambda: self.proc.readAllStandardError())
        self.proc.finished.connect(self.finished)
        self.proc.errorOccurred.connect(self.failed)
        self.buffer = bytearray()
        self.frame_header = None
        self.serial = 0
        self.active = None
        self.jobs = []
        self.render_paused = False
        self.closing = False
        self.worker_flag=worker_flag;self.lazy=lazy
        self.proc.started.connect(self.pump)
        if not lazy:
            executable, arguments = worker_launch(worker_flag)
            self.proc.start(executable, arguments)

    def request(self, op, path, page=None, token=0, priority=False, max_side=1800, payload=None):
        payload=dict(payload or {})
        if op in ('preview','render'):payload['raw_frame']=True
        self.serial += 1
        job = {'id': self.serial, 'op': op, 'path': path, 'page': page,
               'token': token, 'max_side': max_side, 'payload': payload or {}}
        if priority:
            self.jobs.insert(0, job)
        else:
            self.jobs.append(job)
        self.pump()

    def set_thumbnail_order(self, keys):
        rank = {key: i for i, key in enumerate(keys)}
        self.jobs.sort(key=lambda j: (0 if j['op']=='release' else 1 if j['op']=='inspect'
            else 2 if j['op']!='render' else 3,rank.get((j['path'],j['page']),100000)))

    def pump(self):
        if self.closing:return
        eligible=next((i for i,j in enumerate(self.jobs) if not self.render_paused or j['op']!='render'),None)
        if eligible is None:return
        if self.lazy and self.proc.state()==QProcess.ProcessState.NotRunning:
            executable,arguments=worker_launch(self.worker_flag);self.proc.start(executable,arguments)
        if self.active is None and self.proc.state() == QProcess.ProcessState.Running:
            self.active = self.jobs.pop(eligible)
            self.proc.write((json.dumps(self.active, ensure_ascii=True)+'\n').encode('ascii'))

    def read_output(self):
        self.buffer.extend(bytes(self.proc.readAllStandardOutput()))
        while True:
            if self.frame_header is None:
                end=self.buffer.find(b'\n')
                if end<0:return
                line=bytes(self.buffer[:end]);del self.buffer[:end+1]
                try:
                    result=json.loads(line)
                    if not isinstance(result,dict):raise ValueError('header')
                    count=result.get('nbytes',0)
                    if type(count) is not int or not 0<=count<=75_000_000:raise ValueError('frame size')
                    if count:
                        width,height,stride=result['width'],result['height'],result['stride']
                        if not all(type(v) is int for v in (width,height,stride)):raise ValueError('dimensions')
                        if not (0<width<=5000 and 0<height<=5000 and stride==width*3 and count==stride*height):
                            raise ValueError('stride')
                    self.frame_header=result
                except (ValueError,UnicodeError,KeyError,TypeError):
                    self.failed(None);self.proc.kill();return
            result=self.frame_header;count=result.get('nbytes',0)
            if len(self.buffer)<count:return
            job = self.active
            # Consume obsolete frames without copying or creating a GUI pixmap.
            # The worker protocol still drains every byte before the next job.
            valid=bool(job and result.get('id')==job['id'])
            raw=bytes(self.buffer[:count]) if valid and not job.get('discarded') else b''
            del self.buffer[:count];self.frame_header=None
            if not valid:
                continue
            self.active = None
            if job.get('discarded'):
                self.pump();continue
            error = '' if result.get('ok') else result.get('error', 'PDF 처리 실패')
            if job['op']=='warmup':
                self.warmed.emit(error)
            elif job['op']=='release':
                self.released.emit()
            elif job['op'] == 'inspect':
                self.metadata.emit(job['token'], job['path'], result.get('count', 0), error)
            elif job['op'] == 'sibling':
                self.siblingReady.emit(job['token'],result.get('path',''),error)
            elif job['op'] == 'neighbors':
                self.neighborsReady.emit(job['token'],result.get('neighbors',{}),error)
            elif job['op'] == 'search':
                self.searchResult.emit(job['token'],result.get('search',{}),error)
            elif job['op'] == 'editinfo':
                self.editInfo.emit(job['token'], result.get('info', {}), error)
            elif job['op'] == 'edit':
                self.edited.emit(job['token'], result.get('path', ''), error)
            elif job['op'] == 'page_batch':
                self.pageBatchDone.emit(job['token'], result.get('batch', {}), error)
            else:
                pix = QPixmap()
                if not error:
                    if count:
                        picture=QImage(raw,result['width'],result['height'],result['stride'],QImage.Format.Format_RGB888)
                        pix=QPixmap.fromImage(picture.copy())
                    else:pix.loadFromData(base64.b64decode(result['png']))
                    if pix.isNull():error='PDF 화면을 만들지 못했습니다.'
                if job['op'] == 'preview':
                    self.preview.emit(job['token'], pix, error)
                else:
                    self.thumbnail.emit(job['path'], job['page'], pix, error)
            self.pump()

    def failed(self, _error):
        if self.closing:
            return
        self.buffer=bytearray();self.frame_header=None
        # 처리 대기 항목에 오류를 전달해 조용히 빈 썸네일로 남지 않도록 한다.
        jobs = ([self.active] if self.active else []) + self.jobs
        self.active, self.jobs = None, []
        for job in jobs:
            if job.get('discarded'):continue
            if job['op']=='warmup':
                self.warmed.emit('편집 사전 준비 프로세스가 종료되었습니다.')
            elif job['op']=='release':
                self.released.emit()
            elif job['op'] == 'inspect':
                self.metadata.emit(job['token'], job['path'], 0, 'PDF 처리 프로세스를 시작하지 못했습니다.')
            elif job['op'] == 'sibling':
                self.siblingReady.emit(job['token'],'','같은 폴더의 항목을 확인하지 못했습니다.')
            elif job['op'] == 'neighbors':
                self.neighborsReady.emit(job['token'],{},'같은 폴더의 항목 이름을 확인하지 못했습니다.')
            elif job['op'] == 'preview':
                self.preview.emit(job['token'], QPixmap(), 'PDF 처리 프로세스가 종료되었습니다.')
            elif job['op'] == 'search':
                self.searchResult.emit(job['token'],{},'PDF 검색 프로세스가 종료되었습니다.')
            elif job['op'] == 'editinfo':
                self.editInfo.emit(job['token'], {}, 'PDF 편집 정보를 읽지 못했습니다.')
            elif job['op'] == 'edit':
                self.edited.emit(job['token'], '', 'PDF 편집 프로세스가 종료되었습니다.')
            elif job['op'] == 'page_batch':
                self.pageBatchDone.emit(job['token'], {}, 'PDF 일괄 편집 프로세스가 종료되었습니다.')
            else:
                self.thumbnail.emit(job['path'], job['page'], QPixmap(), 'PDF 처리 프로세스가 종료되었습니다.')

    def finished(self, code, status):
        if not self.closing and (code != 0 or self.active or self.jobs):
            self.failed(status)

    def stop(self):
        self.closing = True
        self.jobs.clear()
        if self.proc.state()==QProcess.ProcessState.NotRunning:return
        self.proc.closeWriteChannel()
        if not self.proc.waitForFinished(400):
            self.proc.kill()
            self.proc.waitForFinished(500)


class ImageBackend(PdfBackend):
    animation=Signal(int,object,object,str)
    def __init__(self,parent=None):
        self.resetting=False;self.frame_header=None;self.last_engine='';self.last_note=''
        owner=getattr(parent,'owner',parent)
        self.engine_mode=getattr(owner,'image_engine','auto')
        super().__init__(parent,worker_flag='--image-worker',lazy=True)
        self.buffer=bytearray()
        self.cancel_timer=QTimer(self);self.cancel_timer.setSingleShot(True);self.cancel_timer.setInterval(250)
        self.cancel_timer.timeout.connect(self.restart_stale_request)

    def request(self,op,path,page=None,token=0,priority=False,max_side=1800,payload=None):
        payload=dict(payload or {});payload['engine']=self.engine_mode
        super().request(op,path,page,token,priority,max_side,payload)

    def read_output(self):
        if self.resetting:self.proc.readAllStandardOutput();return
        self.buffer.extend(bytes(self.proc.readAllStandardOutput()))
        while True:
            if self.frame_header is None:
                end=self.buffer.find(b'\n')
                if end<0:
                    if len(self.buffer)>16384:self.protocol_error()
                    return
                line=bytes(self.buffer[:end]);del self.buffer[:end+1]
                try:
                    header=json.loads(line);count=header['nbytes']
                    if type(count) is not int or not 0<=count<=IMAGE_FRAME_MAX_BYTES:raise ValueError('frame size')
                    if count and header.get('animation'):
                        if count>64*1024*1024:raise ValueError('animation size')
                        if not all(type(header.get(k)) is int and 0<header[k]<=IMAGE_PREVIEW_MAX_SIDE for k in ('width','height')):
                            raise ValueError('animation dimensions')
                        if header['width']*header['height']>IMAGE_PREVIEW_MAX_PIXELS:raise ValueError('animation pixels')
                    elif count:
                        width,height,stride=header['width'],header['height'],header['stride']
                        if not all(type(v) is int for v in (width,height,stride)):raise ValueError('dimensions')
                        if not (0<width<=IMAGE_PREVIEW_MAX_SIDE and 0<height<=IMAGE_PREVIEW_MAX_SIDE and
                                width*height<=IMAGE_PREVIEW_MAX_PIXELS and width*3<=stride<=width*3+3 and count==stride*height):
                            raise ValueError('stride')
                    self.frame_header=header
                except (ValueError,KeyError,TypeError):self.protocol_error();return
            result=self.frame_header;count=result['nbytes']
            if len(self.buffer)<count:return
            raw=bytes(self.buffer[:count]);del self.buffer[:count];self.frame_header=None
            job=self.active
            if job is None or result.get('id')!=job['id']:continue
            self.cancel_timer.stop()
            self.active=None;pix=QPixmap()
            if job.get('discarded'):
                self.pump();continue
            error='' if result.get('ok') else result.get('error','그림을 읽지 못했습니다.')
            if job['op']=='release':self.released.emit()
            elif job['op']=='animation':
                if not error and not raw.startswith((b'GIF87a',b'GIF89a')):error='GIF 데이터를 읽지 못했습니다.'
                self.animation.emit(job['token'],raw,(result.get('width',0),result.get('height',0)),error)
            else:
                if not error:
                    if count:
                        picture=QImage(raw,result['width'],result['height'],result['stride'],QImage.Format.Format_RGB888)
                        pix=QPixmap.fromImage(picture.copy())
                    if pix.isNull():error='그림 화면을 만들지 못했습니다.'
                    else:self.last_engine=result.get('engine','');self.last_note=result.get('note','')
                if job['op']=='preview':self.preview.emit(job['token'],pix,error)
                else:self.thumbnail.emit(job['path'],job['page'],pix,error)
            self.pump()

    def protocol_error(self):
        self.failed(None);self.reset()

    def pump(self):
        if not self.resetting:
            # 새 파일의 우선 요청도 이전 ZIP/원본 핸들 해제보다 앞서지 않는다.
            release=next((i for i,j in enumerate(self.jobs) if j['op']=='release'),None)
            if release is not None:self.jobs.insert(0,self.jobs.pop(release))
            super().pump()

    def cancel_pending(self,release=False):
        """결과만 무효화하고 정상 처리기는 유지. 오래 걸리는 이전 읽기만 강제 중단."""
        self.jobs=[] if release else [j for j in self.jobs if j['op']=='release']
        if self.active is not None:
            self.active['discarded']=True
            if not self.cancel_timer.isActive():self.cancel_timer.start()
        if release and self.proc.state()!=QProcess.ProcessState.NotRunning:
            self.request('release','',priority=True)

    def restart_stale_request(self):
        if self.closing or self.resetting or not self.active or not self.active.get('discarded'):return
        pending=list(self.jobs)
        self.reset();self.jobs=pending;self.pump()

    def reset(self):
        self.cancel_timer.stop()
        self.active=None;self.jobs.clear();self.buffer=bytearray();self.frame_header=None
        self.resetting=self.proc.state()!=QProcess.ProcessState.NotRunning
        if self.resetting:self.proc.kill()

    def failed(self,error):
        self.cancel_timer.stop()
        self.buffer=bytearray();self.frame_header=None
        if self.resetting or self.closing:return
        jobs=([self.active] if self.active else [])+self.jobs;self.active=None;self.jobs=[]
        for job in jobs:
            if job.get('discarded'):continue
            message='그림 읽기 프로세스가 종료되었습니다. 정 → 기본에서 다른 그림 읽기 엔진을 선택해 보세요.'
            if job['op']=='release':self.released.emit()
            elif job['op']=='animation':self.animation.emit(job['token'],b'',(0,0),message)
            elif job['op']=='preview':self.preview.emit(job['token'],QPixmap(),message)
            else:self.thumbnail.emit(job['path'],job['page'],QPixmap(),message)

    def finished(self,code,status):
        if self.resetting:
            self.resetting=False;self.buffer=bytearray();self.frame_header=None;self.proc.readAllStandardOutput();self.pump()
        else:super().finished(code,status)

    def stop(self):
        self.cancel_timer.stop();super().stop()


def pdf_reading_side(view):
    """Render for physical screen pixels; zoom still requests up to 5000 px."""
    viewport=view.viewport()
    pixels=max(viewport.width(),viewport.height())*view.devicePixelRatioF()
    return min(5000,max(1024,math.ceil(pixels/128)*128))


class ReadingRenderScheduler(QObject):
    """Show the current page first, then warm only the next reading position.

    Reuse warm image workers, preparing both next images together in dual view.
    A requested page can adopt an in-flight image instead of decoding it again.
    Cached pixmaps retain original colours; each view applies its reading palette.
    """
    # Allocated on demand, bounded across both panes. A normal report should
    # remain warm when the reader returns from its last page to its first.
    CACHE_BYTES=256*1024*1024
    CACHE_PAGES=32

    def __init__(self,owner):
        super().__init__(owner)
        self.owner=owner;self.sessions={};self.cache=OrderedDict()
        self.image_readers=[]
        self.prefetch={};self.serial=0;self.failed_keys=set();self.opening=False;self.closing=False
        self.timer=QTimer(self);self.timer.setSingleShot(True);self.timer.setInterval(35)
        self.timer.timeout.connect(self.sync)
        for engine in self.engines():engine.preview.connect(self.got_prefetch)

    def engines(self):return (self.owner.backend,self.owner.image_backend,*self.image_readers)

    def attach_image_reader(self,engine):
        if engine in self.engines():return
        self.image_readers.append(engine);engine.preview.connect(self.got_prefetch)

    def discard_active(self,engine):
        if engine.active is None or engine.active['op']=='release':return
        engine.active['discarded']=True
        timer=getattr(engine,'cancel_timer',None)
        if timer is not None and not timer.isActive():timer.start()

    def cancel_image_preview(self,editor):
        # Another view may be waiting for a prefetch on this view's reader.
        engine=editor.image_backend
        protected={token for token,job in self.prefetch.items() if job['engine'] is engine}
        engine.jobs=[j for j in engine.jobs if j['op']=='release' or j['token'] in protected]
        if engine.active is not None and engine.active['token'] not in protected:self.discard_active(engine)

    def claim_preview(self,editor,side,token):
        key=self.page_key(editor.page)
        for job in self.prefetch.values():
            if job['key']==key and job['side']>=side:
                job.setdefault('waiters',{})[editor]=token;return True
        return False

    def claim_image(self,editor,side,token):
        return self.claim_preview(editor,side,token)

    def page_key(self,page):
        picture=is_image_source(page.path)
        try:
            filename=image_source_info(page.path)['file'] if picture else page.path
            stamp=Path(filename).stat()
        except (OSError,ValueError,KeyError):return None
        return (page.path,page.number,stamp.st_size,stamp.st_mtime_ns,
                self.owner.image_engine if picture else 'pdf')

    def lookup(self,page,side=0):
        key=self.page_key(page);entry=self.cache.get(key)
        if entry is None or entry['side']<side:return None
        self.cache.move_to_end(key);return entry['pix']

    def remember(self,key,pix,side):
        if key is None or pix.isNull():return
        cost=pix.width()*pix.height()*4
        if cost>self.CACHE_BYTES:return
        old=self.cache.get(key)
        if old is None or side>=old['side']:
            self.cache[key]={'pix':QPixmap(pix),'side':side,'bytes':cost}
        self.cache.move_to_end(key)
        while len(self.cache)>self.CACHE_PAGES or sum(e['bytes'] for e in self.cache.values())>self.CACHE_BYTES:
            self.cache.popitem(last=False)
        if hasattr(self.owner,'cache_preview_thumbnail'):
            self.owner.cache_preview_thumbnail(key,pix,side)

    def pause_thumbnails(self,paused):
        for engine in self.engines():
            engine.render_paused=paused
            if not paused and not self.closing:engine.pump()

    def cancel_prefetch(self,keep_keys=()):
        keep=set(keep_keys)
        self.prefetch={token:job for token,job in self.prefetch.items() if job['key'] in keep}
        protected=set(self.prefetch)
        for engine in self.engines():
            engine.jobs=[j for j in engine.jobs if not j.get('payload',{}).get('reading_prefetch') or j['token'] in protected]
            if (engine.active and engine.active.get('payload',{}).get('reading_prefetch') and
                    engine.active['token'] not in protected):self.discard_active(engine)

    def expect_open(self):
        if self.closing:return
        self.opening=True;self.pause_thumbnails(True)

    def begin(self,editor,side,token):
        if self.closing:return
        self.timer.stop();self.pause_thumbnails(True)
        # A page the user has left must not delay the current page with a large
        # RGB-to-pixmap conversion. Useful prefetches keep their own cache path.
        engine=editor.image_backend if is_image_source(editor.page.path) else editor.backend
        job=engine.active
        if (job and job['op']=='preview' and not job.get('payload',{}).get('reading_prefetch') and
                (job['path'],job['page'])!=(editor.page.path,editor.page.number)):
            self.discard_active(engine)
        for job in self.prefetch.values():job.get('waiters',{}).pop(editor,None)
        editors=self.active_editors()
        keep={self.page_key(editor.page)}|{self.page_key(e.page) for e in editors}
        keep.update(key for _page,key,_side in self.next_targets(editors))
        self.cancel_prefetch(keep)
        self.opening=False;self.failed_keys.clear()
        self.sessions[editor]={'key':self.page_key(editor.page),'side':side,'token':token,'pending':True}

    def complete(self,editor,token,pix,error):
        if self.closing:return
        session=self.sessions.get(editor)
        if session is None or token!=session['token']:return
        session['pending']=False
        if not error and self.page_key(editor.page)==session['key']:
            self.remember(session['key'],pix,session['side'])
        if is_image_source(editor.page.path):self.sync()
        else:self.schedule()

    def schedule(self):
        if not self.closing:self.timer.start()

    def detach(self,editor):
        self.sessions.pop(editor,None)
        engine=getattr(editor,'image_backend',None)
        if engine in self.image_readers:
            retry=[]
            for token,job in list(self.prefetch.items()):
                job.get('waiters',{}).pop(editor,None)
                if job['engine'] is not engine:continue
                for waiter,current in job.get('waiters',{}).items():
                    session=self.sessions.get(waiter)
                    if session and session['pending'] and session['token']==current and session['key']==job['key']:
                        retry.append(waiter)
                self.prefetch.pop(token)
            self.cancel_image_preview(editor)
            self.image_readers.remove(engine);engine.preview.disconnect(self.got_prefetch)
            for waiter in retry:
                waiter.requested_side=0;QTimer.singleShot(0,waiter.request_image)
        self.schedule()

    def active_editors(self):
        owner=self.owner
        editors=[getattr(owner,'preview_dialog',None)]
        if getattr(owner,'dual_mode',False):editors.append(getattr(owner,'dual_preview',None))
        return [e for e in editors if e is not None and not e.closed and not e.book_blank]

    def next_targets(self,editors):
        visible={self.page_key(e.page) for e in editors};targets=[];seen=set()
        step=2 if self.owner.book_mode and self.owner.book_step==2 else 1
        for editor in editors:
            pages=editor.navigation_pages()
            index=next((i for i,p in enumerate(pages) if p.uid==editor.page.uid),None)
            if index is None:continue
            # PDF report review commonly alternates between adjacent pages.
            # Image/book mode keeps its existing forward-reading policy.
            offsets=(step,) if is_image_source(editor.page.path) else (step,-step)
            for offset in offsets:
                position=index+offset
                if not 0<=position<len(pages):continue
                page=pages[position];key=self.page_key(page)
                if key is None or key in visible or key in seen:continue
                seen.add(key)
                if is_image_source(page.path):
                    viewport=editor.view.viewport()
                    side=min(2048,max(256,math.ceil(max(viewport.width(),viewport.height())*
                                                   editor.view.devicePixelRatioF()/64)*64))
                else:side=pdf_reading_side(editor.view)
                targets.append((page,key,side))
        return targets

    def sync(self):
        if self.closing:return
        editors=self.active_editors()
        self.sessions={e:s for e,s in self.sessions.items() if e in editors}
        if self.opening or any(self.sessions.get(e,{}).get('pending',not e.preview_ready) for e in editors):
            self.pause_thumbnails(True);return
        targets=self.next_targets(editors)
        # Keep recently read pages for backward navigation. remember() bounds
        # both page count and bytes; source stamps still guard every lookup.
        needed=[(p,k,s) for p,k,s in targets if self.lookup(p,s) is None and k not in self.failed_keys]
        if not needed:
            self.cancel_prefetch();self.pause_thumbnails(False);return
        self.pause_thumbnails(True)
        busy={job['engine'] for job in self.prefetch.values()}
        queued={job['key'] for job in self.prefetch.values()}
        limit=2 if self.owner.dual_mode else 1
        for page,key,side in needed:
            if key in queued or len(self.prefetch)>=limit:continue
            if is_image_source(page.path):
                readers=[e for e in (*self.image_readers,self.owner.image_backend) if e not in busy and
                         (e.active is None or e.active.get('discarded'))]
                if not readers:self.schedule();continue
                # Avoid starting a second interpreter for a page an idle reader can decode.
                readers.sort(key=lambda e:bool(getattr(e,'proc',None) is not None and
                    e.proc.state()!=QProcess.ProcessState.Running))
                engine=readers[0]
            else:
                engine=self.owner.backend
                if engine in busy:continue
            self.serial+=1;token=-self.serial
            self.prefetch[token]={'key':key,'page':page,'side':side,'engine':engine,'waiters':{}}
            busy.add(engine);queued.add(key)
            engine.request('preview',page.path,page.number,token=token,priority=True,max_side=side,
                           payload={'reading_prefetch':True})

    def got_prefetch(self,token,pix,error):
        if self.closing:return
        job=self.prefetch.pop(token,None)
        if job is None:return
        if self.page_key(job['page'])==job['key']:
            if error or pix.isNull():self.failed_keys.add(job['key'])
            else:self.remember(job['key'],pix,job['side'])
        else:pix=QPixmap();error='원본 그림이 변경되었습니다. 파일을 다시 열어주세요.'
        for editor,current in list(job.get('waiters',{}).items()):
            session=self.sessions.get(editor)
            if (not editor.closed and session and session['pending'] and session['token']==current and
                    session['key']==job['key']):editor.got_image(current,pix,error)
        self.schedule()

    def reset(self):
        self.timer.stop();self.cancel_prefetch();self.sessions.clear();self.cache.clear()
        self.failed_keys.clear();self.opening=False;self.pause_thumbnails(False)

    def stop(self):
        self.closing=True;self.timer.stop();self.cancel_prefetch();self.sessions.clear();self.cache.clear()


def same_file_contents(source,copy):
    """A size match alone is not proof that Explorer finished copying a file."""
    source,copy=Path(source),Path(copy)
    try:
        if (copy.is_symlink() or not copy.is_file() or source.resolve()==copy.resolve() or
                source.stat().st_size!=copy.stat().st_size):return False
        with source.open('rb') as left,copy.open('rb') as right:
            while True:
                a,b=left.read(1024*1024),right.read(1024*1024)
                if a!=b:return False
                if not a:return True
    except OSError:return False


def save_drag_copies(sources,folder,name):
    """Recover a shell copy into a user-selected folder without overwriting."""
    folder=Path(folder);name=clean_name(name)
    if not folder.is_dir():raise FileNotFoundError('저장 폴더가 없습니다: '+str(folder))
    targets=[folder/(f'{name}_{i+1:03d}.pdf' if len(sources)>1 else f'{name}.pdf')
             for i in range(len(sources))]
    if any(p.exists() for p in targets):raise FileExistsError('같은 이름의 파일이 이미 있습니다.')
    created=[]
    try:
        for source,target in zip(sources,targets):
            fd,temporary=tempfile.mkstemp(prefix='.TheViewer_',suffix='.tmp',dir=str(folder))
            try:
                with os.fdopen(fd,'wb') as out,Path(source).open('rb') as inp:
                    shutil.copyfileobj(inp,out,1024*1024)
                if not same_file_contents(source,temporary):raise OSError('PDF 사본 검증에 실패했습니다.')
                commit_output_file(temporary,target,overwrite=False)
                created.append(target)
            finally:Path(temporary).unlink(missing_ok=True)
        return targets
    except Exception:
        for target in created:target.unlink(missing_ok=True)
        raise


class ExplorerTarget:
    """Identify the actual shell drop, separately from candidate folder discovery."""
    def __init__(self):
        self.available=False;self.folders=[];self.is_explorer=False
        self.user32=None;self.shell=None;self.root=None
        if sys.platform=='win32':
            try:
                import ctypes
                from ctypes import wintypes
                self.user32=ctypes.WinDLL('user32',use_last_error=True)
                self.user32.WindowFromPoint.argtypes=[wintypes.POINT]
                self.user32.WindowFromPoint.restype=wintypes.HWND
                self.user32.GetAncestor.argtypes=[wintypes.HWND,wintypes.UINT]
                self.user32.GetAncestor.restype=wintypes.HWND
                self.user32.GetClassNameW.argtypes=[wintypes.HWND,wintypes.LPWSTR,ctypes.c_int]
                self.user32.GetClassNameW.restype=ctypes.c_int
                self.available=True
            except Exception:self.user32=None
            try:
                import win32com.client
                self.shell=win32com.client.Dispatch('Shell.Application')
            except Exception:pass

    def sample(self):
        # Never retain an Explorer hover as evidence after dropping on a Viewer.
        self.is_explorer=False;self.folders=[];self.root=None
        if not self.available:return
        try:
            import ctypes
            from ctypes import wintypes
            p=QCursor.pos();hwnd=self.user32.WindowFromPoint(wintypes.POINT(p.x(),p.y()))
            root=self.user32.GetAncestor(hwnd,2);name=ctypes.create_unicode_buffer(256)
            self.user32.GetClassNameW(root,name,len(name));cls=name.value
            self.root=root
            self.is_explorer=cls in ('CabinetWClass','ExploreWClass','Progman','WorkerW')
            if not self.is_explorer:return
            candidates=[]
            if cls in ('Progman','WorkerW'):
                try:
                    import win32com.shell.shell as shell
                    import win32com.shell.shellcon as sc
                    candidates.append(shell.SHGetFolderPath(0,sc.CSIDL_DESKTOPDIRECTORY,0,0))
                except Exception:pass
            if self.shell is not None:
                for win in self.shell.Windows():
                    try:
                        if int(win.HWND)!=root:continue
                        candidates.append(win.Document.Folder.Self.Path)
                        for item in win.Document.SelectedItems():
                            if item.IsFolder:candidates.append(item.Path)
                    except Exception:continue
            self.folders=list(dict.fromkeys(str(p) for p in candidates if p))
        except Exception:pass

    def find_copies(self,sources):
        if not self.is_explorer or not sources:return None
        def match(folder):
            copies=[Path(folder)/p.name for p in sources]
            return copies if all(same_file_contents(s,c) for s,c in zip(sources,copies)) else None
        for folder in reversed(self.folders):
            found=match(folder)
            if found:return found
            # A folder-icon drop can target one child of the shell window.
            try:
                with os.scandir(folder) as entries:
                    for index,entry in enumerate(entries):
                        if index>=200:break
                        if entry.is_dir(follow_symlinks=False):
                            found=match(entry.path)
                            if found:return found
            except OSError:pass
        return None


