SHORTCUT_DEFINITIONS=[
    ('previous_page','이전 쪽',['Left','Backspace','PgUp','WheelUp']),
    ('next_page','다음 쪽',['Right','Space','PgDown','WheelDown']),
    ('zoom_in','크게 보기 확대',['Up']),('zoom_out','크게 보기 축소',['Down']),
    ('previous_file','이전 파일 / 폴더',[',','[']),
    ('next_file','다음 파일 / 폴더',['.',']']),
    ('clear','전체 비우기',['Ctrl+N']),('save','전체 PDF 저장',['Ctrl+S']),('print','인쇄',['Ctrl+P']),
    ('open','파일 추가',['Ctrl+Shift+O']),('options','옵션',['Ctrl+O']),
    ('translate','번역',['Ctrl+T']),('hangul','한글 변환',['Ctrl+H']),
    ('undo','되돌리기',['Ctrl+Z']),('redo','다시 실행',['Ctrl+Y','Ctrl+Shift+Z']),
    ('copy','페이지 / 선택 개체 복사',['Ctrl+C']),('cut','선택 개체 잘라내기',['Ctrl+X']),
    ('paste','붙여넣기',['Ctrl+V']),('select_all','전체 페이지 선택',['Ctrl+A']),
    ('delete','선택 페이지 / 개체 삭제',['Del']),
]


WHEEL_MODIFIERS=(('Ctrl',Qt.KeyboardModifier.ControlModifier),('Alt',Qt.KeyboardModifier.AltModifier),
                 ('Shift',Qt.KeyboardModifier.ShiftModifier),('Meta',Qt.KeyboardModifier.MetaModifier))


def is_wheel_shortcut(key):return isinstance(key,str) and key.split('+')[-1] in ('WheelUp','WheelDown')


def wheel_shortcut(modifiers,up):
    return ''.join(name+'+' for name,flag in WHEEL_MODIFIERS if modifiers & flag)+('WheelUp' if up else 'WheelDown')


def shortcut_label(key):
    if is_wheel_shortcut(key):return key.replace('WheelUp','휠 ↑').replace('WheelDown','휠 ↓')
    return QKeySequence(key).toString(QKeySequence.SequenceFormat.NativeText)


class ShortcutBindings(QObject):
    """창별 단축키. 문자 입력, 다른 대화창, 편집 개체 이동을 침범하지 않는다."""
    GLOBAL={'clear','save','print','open','options','translate','hangul'}
    def __init__(self,owner,settings):
        super().__init__(owner);self.owner=owner;self.settings=settings
        self.bindings=self.defaults()
        try:
            current=settings.value('shortcuts_v2','',type=str)
            saved=json.loads(current or settings.value('shortcuts_v1','{}',type=str))
            if isinstance(saved,dict):
                values={**self.bindings,**saved}
                if current:
                    used={self.normalize(key) for name,keys in saved.items() if name in self.bindings for key in keys if key}
                    for name,defaults in self.bindings.items():
                        if name not in saved:values[name]=[key for key in defaults if self.normalize(key) not in used]
                if not current:
                    # 기존 키 3개는 보존하고 새 휠 기본값만 추가한다. 기존 사용자 키가
                    # ↑/↓를 사용 중이면 그 키를 새 확대/축소 기본값으로 빼앗지 않는다.
                    used={self.normalize(key) for name,keys in saved.items() if name in self.bindings for key in keys if key}
                    for name,defaults in self.bindings.items():
                        if name not in saved:values[name]=[key for key in defaults if self.normalize(key) not in used]
                        elif values[name] and not any(is_wheel_shortcut(key) for key in values[name]):
                            values[name]=list(values[name])+[key for key in defaults if is_wheel_shortcut(key) and key not in used]
                self.bindings=self.validate(values)
        except (TypeError,ValueError):self.bindings=self.defaults()
        self.reindex()

    @staticmethod
    def defaults():return {name:list(keys) for name,_label,keys in SHORTCUT_DEFINITIONS}

    @staticmethod
    def normalize(key):
        if is_wheel_shortcut(key):
            parts=key.split('+');modifiers=parts[:-1]
            if len(set(modifiers))!=len(modifiers) or any(part not in dict(WHEEL_MODIFIERS) for part in modifiers):
                raise ValueError('휠 조합에는 Ctrl·Alt·Shift·Meta만 사용할 수 있습니다.')
            return ''.join(name+'+' for name,_flag in WHEEL_MODIFIERS if name in modifiers)+parts[-1]
        return QKeySequence(key,QKeySequence.SequenceFormat.PortableText).toString(QKeySequence.SequenceFormat.PortableText)

    @classmethod
    def validate(cls,values):
        result={};seen={};labels={name:label for name,label,_ in SHORTCUT_DEFINITIONS}
        for name,_label,_keys in SHORTCUT_DEFINITIONS:
            keys=values.get(name,[])
            if not isinstance(keys,list) or len(keys)>4:raise ValueError('동작마다 키 3개와 휠 1개까지 지정하세요.')
            result[name]=[]
            for key in keys:
                if not isinstance(key,str):raise ValueError('올바른 단축키를 입력하세요.')
                if not key:continue
                if not is_wheel_shortcut(key):
                    seq=QKeySequence(key,QKeySequence.SequenceFormat.PortableText)
                    if seq.count()!=1 or seq[0].key() in (Qt.Key.Key_unknown,Qt.Key.Key_Control,Qt.Key.Key_Shift,Qt.Key.Key_Alt,Qt.Key.Key_Meta):
                        raise ValueError('Ctrl+S처럼 한 번에 누르는 키 조합만 지정하세요.')
                    if seq[0].key() in (Qt.Key.Key_Escape,Qt.Key.Key_Tab,Qt.Key.Key_Backtab,Qt.Key.Key_Return,Qt.Key.Key_Enter):
                        raise ValueError('Esc·Enter·Tab은 취소·확정·입력칸 이동을 위해 고정됩니다.')
                normalized=cls.normalize(key)
                if normalized in seen and seen[normalized]!=name:
                    raise ValueError(f'{shortcut_label(normalized)}: {labels[seen[normalized]]} / {labels[name]}에 중복 지정되었습니다.')
                seen[normalized]=name
                if normalized not in result[name]:result[name].append(normalized)
            wheel_count=sum(is_wheel_shortcut(key) for key in result[name])
            if wheel_count>1 or len(result[name])-wheel_count>3:
                raise ValueError('동작마다 키 3개와 휠 1개까지 지정하세요.')
        return result

    def reindex(self):
        self.lookup={key:name for name,keys in self.bindings.items() for key in keys}
        self.wheel_state=None;self.wheel_remainder=0.0;self.wheel_time=0.0

    def describe(self,name):
        return ' / '.join(shortcut_label(k) for k in self.bindings[name]) or '미지정'

    def apply(self,values):
        self.bindings=self.validate(values);self.reindex()
        self.settings.setValue('shortcuts_v2',json.dumps(self.bindings,ensure_ascii=False));self.settings.sync()
        self.owner.actions.set_ctrl(self.owner.actions.ctrl_down,force=True)
        editor=self.owner.preview_dialog
        if editor is not None and not editor.closed:editor.actions.set_ctrl(editor.actions.ctrl_down,force=True)
        self.owner.update_action_states()

    def matches(self,name,event):
        return self.lookup.get(QKeySequence(event.keyCombination()).toString(QKeySequence.SequenceFormat.PortableText))==name

    def context(self,widget):
        owner=self.owner;editor=owner.preview_dialog
        secondary=getattr(owner,'dual_preview',None)
        if secondary is not None and not secondary.closed and widget is not None and (widget is secondary or secondary.isAncestorOf(widget)):
            editor=secondary
        in_preview=editor is not None and not editor.closed and widget is not None and (widget is editor or editor.isAncestorOf(widget))
        text_input=False;current=widget
        while current is not None and current not in (owner,editor):
            if isinstance(current,(QLineEdit,QPlainTextEdit,QTextEdit,QSpinBox,QDoubleSpinBox,QComboBox,QKeySequenceEdit)):
                text_input=True;break
            current=current.parentWidget()
        return editor,in_preview,text_input

    def key_action(self,event,widget):
        owner=self.owner
        if getattr(owner,'closing',True):return ''
        editor,in_preview,text_input=self.context(widget)
        modal=QApplication.activeModalWidget()
        if modal is not None and modal is not editor:return ''
        if QApplication.activePopupWidget() is not None:return ''
        if (owner.book_focus and event.key()==Qt.Key.Key_Escape and
                event.modifiers()==Qt.KeyboardModifier.NoModifier and
                widget is not None and (widget is owner or owner.isAncestorOf(widget))):
            return 'exit_book_focus'
        if (in_preview and not text_input and editor.mode=='edit' and
                (editor.selected_text or editor.selected_image or editor.selected_vector or editor.bulk_items or editor.bulk_restore or editor.restore_selection or editor.restore_image or editor.restore_vector) and
                event.key() in (Qt.Key.Key_Left,Qt.Key.Key_Right,Qt.Key.Key_Up,Qt.Key.Key_Down)):
            return 'move_object'
        action=self.lookup.get(QKeySequence(event.keyCombination()).toString(QKeySequence.SequenceFormat.PortableText),'')
        if text_input and (action not in self.GLOBAL or not event.modifiers() & (
                Qt.KeyboardModifier.ControlModifier|Qt.KeyboardModifier.AltModifier|Qt.KeyboardModifier.MetaModifier)):
            return ''
        return action

    def handle(self,event,widget):
        action=self.key_action(event,widget)
        if not action:return False
        event.accept()
        if event.isAutoRepeat() and action not in ('previous_page','next_page','zoom_in','zoom_out','move_object'):return True
        self.execute(action,widget,event=event)
        return True

    def handle_wheel(self,event,widget):
        if self.owner.closing:return False
        editor,in_preview,text_input=self.context(widget)
        modal=QApplication.activeModalWidget()
        if (not in_preview or text_input or QApplication.activePopupWidget() is not None or
                (modal is not None and modal is not editor)):return False
        angle=event.angleDelta().y();pixel=event.pixelDelta().y()
        delta=angle or pixel;unit=120 if angle else 40
        if not delta:
            if event.phase()==Qt.ScrollPhase.ScrollEnd:self.wheel_state=None;self.wheel_remainder=0.0
            return False
        key=wheel_shortcut(event.modifiers(),delta>0);action=self.lookup.get(key)
        if not action:self.wheel_state=None;self.wheel_remainder=0.0;return False
        event.accept();now=time.monotonic();state=(widget,key,unit)
        if self.wheel_state!=state or now-self.wheel_time>.4 or event.phase()==Qt.ScrollPhase.ScrollBegin:
            self.wheel_remainder=0.0
        self.wheel_state=state;self.wheel_time=now;self.wheel_remainder+=abs(delta)
        steps=int(self.wheel_remainder/unit);self.wheel_remainder-=steps*unit
        if steps:self.execute(action,widget,steps=min(steps,100),zoom_position=event.position().toPoint())
        return True

    def execute(self,action,widget,steps=1,event=None,zoom_position=None):
        owner=self.owner;editor,in_preview,_=self.context(widget)
        if action=='exit_book_focus':owner.set_book_focus(False);return
        if getattr(owner,'page_batch_job',None) is not None and action not in ('zoom_in','zoom_out'):return
        if (getattr(owner,'page_number_session',None) is not None and in_preview and
                action in ('previous_file','next_file','previous_page','next_page','move_object','copy','cut','paste','delete')):return
        if getattr(owner,'page_number_session',None) is not None and action in ('select_all','paste','delete'):return
        if editor is not None and editor.dual_secondary and action in ('copy','cut','paste','delete'):
            QToolTip.showText(QCursor.pos(),'오른쪽 보기는 읽기 전용입니다.',editor.view);return
        if action=='move_object':editor.handle_move_key(event)
        elif action in ('previous_file','next_file'):owner.navigate_sibling(-1 if action=='previous_file' else 1)
        elif action in ('previous_page','next_page'):
            if not owner.pages:return
            if editor is None or editor.closed:owner.open_combined_view();editor=owner.preview_dialog
            if editor is not None and not editor.closed:
                index=editor.nav_display_index if editor.nav_target_uid is not None or owner.book_target_index is not None else editor.navigation_index()
                editor.request_navigation(index+(-steps if action=='previous_page' else steps))
        elif action in ('zoom_in','zoom_out'):
            if not owner.pages:return
            if editor is None or editor.closed:owner.open_combined_view();editor=owner.preview_dialog
            if editor is not None and not editor.closed:
                editor.view.zoom_steps(steps if action=='zoom_in' else -steps,zoom_position)
        elif action in self.GLOBAL:
            method={'clear':'clear','save':'save_revision','print':'print_document','open':'open_files','options':'show_settings',
                    'translate':'translate_current','hangul':'choose_hangul'}[action]
            getattr(owner,method)()
        elif action=='undo':editor.undo_edit() if in_preview else owner.undo()
        elif action=='redo':editor.redo_edit() if in_preview else owner.redo()
        elif action=='copy':editor.copy_selected_object() if in_preview else owner.copy_pages()
        elif action=='cut':
            if in_preview:editor.copy_selected_object(cut=True)
        elif action=='paste':editor.paste_clipboard() if in_preview else owner.paste_pages()
        elif action=='select_all':
            owner.canvas.selected={p.uid for p in owner.pages};owner.canvas.selectionChanged.emit();owner.canvas.viewport().update()
        elif action=='delete':
            if in_preview:
                if editor.mode=='edit' and (editor.selected_text or editor.selected_image or editor.selected_vector or editor.bulk_items):editor.delete_selected()
            else:owner.remove_selected()

    def eventFilter(self,watched,event):
        if event.type() not in (QEvent.Type.ShortcutOverride,QEvent.Type.KeyPress) or not isinstance(watched,QWidget):return False
        if (watched is getattr(self.owner,'book_gap_handle',None) and
                event.key() in (Qt.Key.Key_Left,Qt.Key.Key_Right,Qt.Key.Key_Escape) and
                not event.modifiers()&Qt.KeyboardModifier.ControlModifier):return False
        editor=self.owner.preview_dialog
        if watched.window() is not self.owner and (editor is None or watched.window() is not editor):return False
        if event.type()==QEvent.Type.ShortcutOverride:
            if self.key_action(event,watched):event.accept();return True
            return False
        return self.handle(event,watched)


class ShortcutSettings(QWidget):
    def __init__(self,owner):
        super().__init__();self.owner=owner;self.controls={};self.wheel_controls={}
        layout=QVBoxLayout(self)
        self.table=QTableWidget(len(SHORTCUT_DEFINITIONS),5);self.table.setObjectName('shortcut_table')
        self.table.setHorizontalHeaderLabels(['동작','키 1','키 2','키 3','휠']);self.table.verticalHeader().hide()
        self.table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
        self.table.horizontalHeader().setSectionResizeMode(0,QHeaderView.ResizeMode.ResizeToContents)
        for column in (1,2,3):self.table.horizontalHeader().setSectionResizeMode(column,QHeaderView.ResizeMode.Stretch)
        self.table.horizontalHeader().setSectionResizeMode(4,QHeaderView.ResizeMode.ResizeToContents)
        for row,(name,label,_defaults) in enumerate(SHORTCUT_DEFINITIONS):
            self.table.setItem(row,0,QTableWidgetItem(label));self.table.setRowHeight(row,34);self.controls[name]=[]
            for column in range(3):
                field=QKeySequenceEdit();field.setObjectName(f'shortcut_{name}_{column}')
                if hasattr(field,'setMaximumSequenceLength'):field.setMaximumSequenceLength(1)
                if hasattr(field,'setClearButtonEnabled'):field.setClearButtonEnabled(True)
                self.controls[name].append(field);self.table.setCellWidget(row,column+1,field)
            wheel=QComboBox();wheel.setObjectName(f'shortcut_{name}_wheel');wheel.addItem('미지정','')
            for modifiers in (Qt.KeyboardModifier.NoModifier,Qt.KeyboardModifier.ControlModifier,
                              Qt.KeyboardModifier.ShiftModifier,Qt.KeyboardModifier.AltModifier,
                              Qt.KeyboardModifier.ControlModifier|Qt.KeyboardModifier.ShiftModifier):
                for up in (True,False):
                    key=wheel_shortcut(modifiers,up);wheel.addItem(shortcut_label(key),key)
            self.wheel_controls[name]=wheel;self.table.setCellWidget(row,4,wheel)
        layout.addWidget(self.table)
        self.status=QLabel();self.status.setWordWrap(True);layout.addWidget(self.status)
        buttons=QHBoxLayout();reset=QPushButton('기본값 복원');reset.setObjectName('shortcut_reset')
        apply=QPushButton('적용');apply.setObjectName('shortcut_apply')
        buttons.addWidget(reset);buttons.addStretch();buttons.addWidget(apply);layout.addLayout(buttons)
        self.fill(owner.keys.bindings);reset.clicked.connect(self.restore_defaults);apply.clicked.connect(self.apply)

    def fill(self,values):
        for name,fields in self.controls.items():
            keys=[key for key in values[name] if not is_wheel_shortcut(key)]
            for i,field in enumerate(fields):field.setKeySequence(QKeySequence(keys[i] if i<len(keys) else ''))
            value=next((key for key in values[name] if is_wheel_shortcut(key)),'');wheel=self.wheel_controls[name]
            if wheel.findData(value)<0:wheel.addItem(shortcut_label(value),value)
            wheel.setCurrentIndex(wheel.findData(value))

    def apply(self):
        values={name:[field.keySequence().toString(QKeySequence.SequenceFormat.PortableText) for field in fields]+[self.wheel_controls[name].currentData()]
                for name,fields in self.controls.items()}
        try:self.owner.keys.apply(values)
        except ValueError as exc:
            self.status.setStyleSheet('color:#d74c66;');self.status.setText(str(exc));return False
        self.status.setStyleSheet('color:#399c77;');self.status.setText('적용했습니다. 다음 실행에도 유지됩니다.');return True

    def restore_defaults(self):self.fill(self.owner.keys.defaults());self.apply()


def normalize_github_repository(value):
    value=str(value).strip().rstrip('/')
    if not value:return ''
    value=re.sub(r'^https://github\.com/','',value,flags=re.IGNORECASE)
    if value.endswith('.git'):value=value[:-4]
    if not re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})/[A-Za-z0-9_.-]+',value):
        raise ValueError('https://github.com/계정/저장소 형식으로 입력하세요.')
    if value.split('/')[1] in ('.','..'):raise ValueError('저장소 이름을 확인하세요.')
    return 'https://github.com/'+value


"""Release checks and verified downloads; no network or process launch on import."""
import hashlib as tv_update_hashlib
import json as tv_update_json
import os as tv_update_os
import re as tv_update_re
import tempfile as tv_update_tempfile
import time as tv_update_time
from pathlib import Path as TVUpdatePath
from urllib import request as tv_update_http, error as tv_update_errors
from urllib.parse import urlsplit as tv_update_urlsplit, quote as tv_update_quote

TV_UPDATE_APP_ID = 'KRS.TheViewer'
TV_UPDATE_MUTEX = 'Local\\KRS.TheViewer.Installer'
TV_UPDATE_MAX_SETUP = 4 * 1024 ** 3


def tv_update_version(value):
    match = tv_update_re.fullmatch(r'v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)', str(value))
    if not match:
        raise ValueError('버전은 3.12.3 또는 v3.12.3 형식이어야 합니다.')
    return tuple(map(int, match.groups()))


def tv_update_repo(value):
    value = str(value).strip().rstrip('/')
    value = tv_update_re.sub(r'^https://github\.com/', '', value, flags=tv_update_re.I)
    if value.endswith('.git'):
        value = value[:-4]
    if not tv_update_re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]+', value) or value.split('/')[1] in ('.', '..'):
        raise ValueError('GitHub 계정/저장소 주소를 확인하세요.')
    return value


def tv_update_setup_name(version):
    tv_update_version(version)
    return 'The_Viewer_Setup_' + str(version).removeprefix('v') + '_x64.exe'


def tv_update_default_repo(default, installed_root=None):
    if installed_root:
        try:
            marker = tv_update_json.loads((TVUpdatePath(installed_root) / 'INSTALL_INFO.json').read_text(encoding='utf-8-sig'))
            if marker.get('app_id') == TV_UPDATE_APP_ID:
                return 'https://github.com/' + tv_update_repo(marker['repo'])
        except (OSError, ValueError, KeyError, TypeError):
            pass
    return default


def tv_update_allowed_url(url, api=False):
    part = tv_update_urlsplit(url)
    if part.scheme != 'https' or part.username or part.password or part.port not in (None, 443):
        raise ValueError('HTTPS GitHub 주소만 사용할 수 있습니다.')
    host = (part.hostname or '').lower()
    allowed = host == 'api.github.com' if api else host == 'github.com' or host.endswith('.githubusercontent.com')
    if not allowed:
        raise ValueError('GitHub 밖의 다운로드 주소를 사용하지 않습니다.')
    return url


class TVUpdateRedirect(tv_update_http.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        tv_update_allowed_url(newurl, api=tv_update_urlsplit(req.full_url).hostname == 'api.github.com')
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def tv_update_open(url, timeout=15, opener=None, api=False):
    tv_update_allowed_url(url, api=api)
    headers = {'User-Agent': 'TheViewer-Update', 'Accept': 'application/vnd.github+json' if api else 'application/octet-stream'}
    if api:
        headers['X-GitHub-Api-Version'] = '2026-03-10'
    request = tv_update_http.Request(url, headers=headers)
    client = opener or tv_update_http.build_opener(TVUpdateRedirect()).open
    return client(request, timeout=timeout)


def tv_update_select_release(payload, repo, current):
    repo = tv_update_repo(repo)
    if not isinstance(payload, dict):
        raise ValueError('새 버전 응답이 올바르지 않습니다.')
    if payload.get('draft') or payload.get('prerelease'):
        return {'state': 'current', 'current': current, 'repo': repo}
    tag = str(payload.get('tag_name', ''))
    target = tv_update_version(tag)
    if target <= tv_update_version(current):
        return {'state': 'current', 'current': current, 'repo': repo, 'latest': tag.removeprefix('v')}
    version = tag.removeprefix('v')
    release_url = 'https://github.com/' + repo + '/releases/tag/' + tv_update_quote(tag, safe='')
    name = tv_update_setup_name(version)
    matches = [a for a in payload.get('assets', []) if isinstance(a, dict) and a.get('name') == name and a.get('state') == 'uploaded']
    result = {'state': 'available', 'current': current, 'version': version, 'tag': tag, 'repo': repo,
              'release_url': release_url, 'notes': str(payload.get('body') or '')[:20000], 'installer': None}
    if len(matches) == 1:
        asset = matches[0]
        digest = str(asset.get('digest') or '')
        expected_url = 'https://github.com/' + repo + '/releases/download/' + tv_update_quote(tag, safe='') + '/' + name
        size = asset.get('size')
        if (tv_update_re.fullmatch(r'sha256:[0-9a-fA-F]{64}', digest)
                and type(size) is int and 0 < size <= TV_UPDATE_MAX_SETUP
                and asset.get('browser_download_url') == expected_url):
            result['installer'] = {'name': name, 'url': expected_url, 'bytes': size, 'sha256': digest[7:].lower(),
                                   'version': version, 'repo': repo, 'tag': tag}
    return result


def tv_update_check(repo, current, opener=None):
    repo = tv_update_repo(repo)
    url = 'https://api.github.com/repos/' + repo + '/releases/latest'
    try:
        with tv_update_open(url, timeout=10, opener=opener, api=True) as response:
            tv_update_allowed_url(response.geturl(), api=True)
            raw = response.read(1024 * 1024 + 1)
        if len(raw) > 1024 * 1024:
            raise ValueError('새 버전 응답이 너무 큽니다.')
        return tv_update_select_release(tv_update_json.loads(raw.decode('utf-8')), repo, current)
    except tv_update_errors.HTTPError as exc:
        if exc.code == 404:
            raise ValueError('공개 릴리스가 없거나 저장소를 읽을 수 없습니다. 저장소 주소와 공개 여부를 확인하세요.') from exc
        if exc.code in (403, 429):
            raise ValueError('GitHub 요청 한도 또는 접근 제한입니다. 잠시 뒤 다시 확인하세요.') from exc
        raise ValueError('GitHub 새 버전 확인에 실패했습니다: HTTP ' + str(exc.code)) from exc
    except (tv_update_errors.URLError, TimeoutError, OSError) as exc:
        raise ValueError('업데이트 서버에 연결하지 못했습니다. 인터넷 연결을 확인한 뒤 다시 시도하세요.') from exc


def tv_update_file_hash(path, check=lambda: None):
    digest = tv_update_hashlib.sha256()
    with TVUpdatePath(path).open('rb') as stream:
        while True:
            check()
            block = stream.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def tv_update_download(installer, cache, check=lambda: None, progress=lambda done, total: None, opener=None):
    item = dict(installer)
    repo = tv_update_repo(item['repo'])
    version = str(item['version'])
    tag = str(item['tag'])
    if tv_update_version(tag) != tv_update_version(version) or item['name'] != tv_update_setup_name(version):
        raise ValueError('설치 파일의 버전이 올바르지 않습니다.')
    expected_url = 'https://github.com/' + repo + '/releases/download/' + tv_update_quote(tag, safe='') + '/' + item['name']
    if item['url'] != expected_url or not tv_update_re.fullmatch(r'[0-9a-f]{64}', item['sha256']):
        raise ValueError('설치 파일 주소 또는 검사 값이 올바르지 않습니다.')
    total = item['bytes']
    if type(total) is not int or not 0 < total <= TV_UPDATE_MAX_SETUP:
        raise ValueError('설치 파일 크기가 올바르지 않습니다.')
    folder = TVUpdatePath(cache) / version
    folder.mkdir(parents=True, exist_ok=True)
    target = folder / item['name']
    check()
    if target.is_file() and target.stat().st_size == total and tv_update_file_hash(target, check) == item['sha256']:
        progress(total, total)
        return dict(item, path=str(target))
    fd, temporary = tv_update_tempfile.mkstemp(prefix='download_', suffix='.partial', dir=str(folder))
    temp = TVUpdatePath(temporary)
    tv_update_os.close(fd)
    try:
        digest = tv_update_hashlib.sha256()
        done = 0
        last = 0.0
        with tv_update_open(expected_url, timeout=15, opener=opener) as response, temp.open('wb') as stream:
            tv_update_allowed_url(response.geturl())
            while True:
                check()
                block = response.read(1024 * 1024)
                if not block:
                    break
                done += len(block)
                if done > total:
                    raise ValueError('다운로드 파일의 크기가 릴리스 기록과 다릅니다.')
                stream.write(block)
                digest.update(block)
                if tv_update_time.monotonic() - last > .1 or done == total:
                    progress(done, total)
                    last = tv_update_time.monotonic()
        check()
        if done != total or digest.hexdigest() != item['sha256']:
            raise ValueError('설치 파일의 SHA-256 또는 크기가 일치하지 않습니다. 파일을 실행하지 않았습니다.')
        with temp.open('rb') as stream:
            if stream.read(2) != b'MZ':
                raise ValueError('Windows 설치 실행파일이 아닙니다.')
        tv_update_os.replace(temp, target)
        progress(total, total)
        return dict(item, path=str(target))
    finally:
        temp.unlink(missing_ok=True)


def tv_update_launch(record, installed_root=None, platform=None, popen=None):
    import sys
    import subprocess
    if (platform or sys.platform) != 'win32':
        raise ValueError('Windows에서 설치 파일을 실행할 수 있습니다.')
    path = TVUpdatePath(record['path']).resolve()
    if path.name != tv_update_setup_name(record['version']) or not path.is_file() or path.stat().st_size != record['bytes'] or tv_update_file_hash(path) != record['sha256']:
        raise ValueError('설치 파일이 다운로드 후 변경되었습니다. 다시 다운로드하세요.')
    command = [str(path), '/NORESTART']
    if installed_root:
        root = TVUpdatePath(installed_root).resolve()
        try:
            marker = tv_update_json.loads((root / 'INSTALL_INFO.json').read_text(encoding='utf-8-sig'))
        except (OSError, ValueError):
            marker = {}
        if marker.get('app_id') == TV_UPDATE_APP_ID:
            command.append('/DIR=' + str(root))
    return (popen or subprocess.Popen)(command, cwd=str(path.parent), close_fds=True)


def tv_update_mutex_open():
    import sys
    if sys.platform != 'win32':
        return None
    import ctypes
    api = ctypes.windll.kernel32.CreateMutexW
    api.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_wchar_p]
    api.restype = ctypes.c_void_p
    handle = api(None, False, TV_UPDATE_MUTEX)
    if not handle:
        raise OSError('설치 상태 확인용 Windows 개체를 만들지 못했습니다.')
    return handle


def tv_update_mutex_close(handle):
    if handle:
        import ctypes
        api = ctypes.windll.kernel32.CloseHandle
        api.argtypes = [ctypes.c_void_p]
        api.restype = ctypes.c_int
        api(handle)


class TVUpdateWorker(QThread):
    completed = Signal(object)
    failed = Signal(str)
    progress = Signal(int)

    def __init__(self, owner, repo, installer=None):
        super().__init__(owner)
        self.repo = repo
        self.installer = installer

    def check_cancel(self):
        if self.isInterruptionRequested():
            raise ValueError('업데이트 작업을 취소했습니다.')

    def run(self):
        try:
            self.check_cancel()
            if self.installer:
                cache = Path(os.environ.get('LOCALAPPDATA', str(Path.home()))) / 'KRS' / 'TheViewerUpdates'
                result = tv_update_download(self.installer, cache, self.check_cancel,
                    lambda done, total: self.progress.emit(min(1000, round(done * 1000 / total))))
            else:
                result = tv_update_check(self.repo, APP_VERSION)
            self.check_cancel()
            self.completed.emit(result)
        except Exception as exc:
            self.failed.emit(str(exc))


class TVUpdateDialog(QDialog):
    def __init__(self, owner, info):
        super().__init__(owner)
        self.owner = owner
        self.info = dict(info)
        self.record = None
        self.install_requested = False
        self.setWindowTitle('The Viewer 업데이트')
        self.resize(580, 450)
        self.setObjectName('viewer_update_dialog')
        layout = QVBoxLayout(self)
        heading = QLabel('새 버전 ' + info['version'] + ' · 현재 ' + APP_VERSION)
        heading.setStyleSheet('font-size:16px;font-weight:bold;')
        layout.addWidget(heading)
        text = QPlainTextEdit()
        text.setReadOnly(True)
        text.setPlainText(info.get('notes') or '새 버전 수정 내역은 릴리스 페이지에서 확인할 수 있습니다.')
        layout.addWidget(text)
        self.status = QLabel('설치 후 기존 설정은 유지됩니다. 설치 전에 현재 작업을 저장할 수 있습니다.')
        self.status.setWordWrap(True)
        layout.addWidget(self.status)
        self.bar = QProgressBar()
        self.bar.setRange(0, 1000)
        self.bar.setValue(0)
        self.bar.hide()
        layout.addWidget(self.bar)
        row = QHBoxLayout()
        layout.addLayout(row)
        release = QPushButton('수정 내역 보기')
        release.clicked.connect(lambda: QDesktopServices.openUrl(QUrl(info['release_url'])))
        row.addWidget(release)
        row.addStretch()
        self.install = QPushButton('업데이트 설치')
        self.install.setObjectName('viewer_update_install')
        self.install.clicked.connect(self.start_install)
        self.cancel = QPushButton('다운로드 취소')
        self.cancel.clicked.connect(owner.cancel_update_download)
        self.cancel.hide()
        row.addWidget(self.cancel)
        row.addWidget(self.install)
        close = QPushButton('나중에')
        close.clicked.connect(self.close)
        row.addWidget(close)
        if sys.platform != 'win32':
            self.install.setEnabled(False)
            self.status.setText('이 설치 파일은 Windows용입니다. 수정 내역에서 새 버전을 확인하세요.')
        elif not info.get('installer'):
            self.install.setEnabled(False)
            self.status.setText('자동으로 설치할 파일이 준비되지 않았습니다. 수정 내역에서 배포 파일을 확인하세요.')

    def start_install(self):
        if self.record:
            self.owner.install_downloaded_update(self.record)
        else:
            self.install_requested = True
            if not self.owner.download_update(self):
                self.install_requested = False

    def closeEvent(self,event):
        self.install_requested = False
        worker = self.owner.update_thread
        if worker is not None and worker.installer is not None:
            self.owner.cancel_update_download()
        super().closeEvent(event)

    def downloading(self):
        self.install.setEnabled(False)
        self.cancel.setEnabled(True)
        self.cancel.show()
        self.bar.show()
        self.status.setText('새 버전을 다운로드하고 확인합니다. 현재 문서는 계속 볼 수 있습니다.')

    def ready(self, record):
        self.record = record
        self.bar.setValue(1000)
        self.cancel.hide()
        self.install.setText('저장 확인 후 설치')
        self.install.setEnabled(True)
        self.status.setText('다운로드를 확인했습니다. 설치 버튼을 누르면 저장 확인 후 뷰어가 종료됩니다.')

    def failed(self, message):
        self.install_requested = False
        self.cancel.hide()
        self.bar.hide()
        self.install.setText('다시 다운로드')
        self.install.setEnabled(sys.platform == 'win32' and bool(self.info.get('installer')))
        self.status.setText(message)


def tv_window_check_updates(self, manual=True):
    if self.update_thread is not None:
        if manual and self.update_thread.installer is None:
            self.update_thread.manual_requested = True
        if self.update_dialog is not None:
            self.update_dialog.show()
            self.update_dialog.raise_()
        return False
    repo = self.github_repository_url()
    if not repo:
        if manual:
            QMessageBox.information(self, '업데이트 확인', '정 → 소식에서 GitHub 저장소 주소를 먼저 저장하세요.')
        return False
    self.settings.setValue('updates/last_attempt', int(time.time()))
    self.settings.sync()
    worker = TVUpdateWorker(self, repo)
    worker.manual_requested = bool(manual)
    self.update_thread = worker
    outcome = {}
    worker.completed.connect(lambda info: outcome.update(info=info))
    worker.failed.connect(lambda message: outcome.update(error=message))
    def finished():
        self.update_thread = None
        worker.deleteLater()
        if self._update_close_requested or self.closing:
            return
        if 'error' in outcome:
            if worker.manual_requested:
                QMessageBox.information(self, '업데이트 확인', outcome['error'])
            return
        info = outcome.get('info', {})
        if info.get('state') != 'available':
            if worker.manual_requested:
                QMessageBox.information(self, '업데이트 확인', '설치할 새 버전이 없습니다.\n현재 버전: ' + APP_VERSION + ('\n배포 버전: ' + info['latest'] if info.get('latest') else ''))
            return
        if not worker.manual_requested and self.settings.value('updates/deferred_version', '', type=str) == info['version']:
            return
        if self.update_dialog is not None:
            self.update_dialog.close()
            self.update_dialog.deleteLater()
        dialog = TVUpdateDialog(self, info)
        self.update_dialog = dialog
        dialog.finished.connect(lambda _result: self.settings.setValue('updates/deferred_version', info['version']))
        dialog.show()
        dialog.raise_()
    worker.finished.connect(finished)
    worker.start()
    return True


def tv_window_startup_update(self):
    if not self.settings.value('updates/auto', True, type=bool) or self.closing:
        return
    try:
        attempted = int(self.settings.value('updates/last_attempt', 0))
    except (TypeError, ValueError):
        attempted = 0
    age = time.time() - attempted
    if age < 0 or age >= 24 * 60 * 60:
        self.check_for_updates(manual=False)


def tv_window_download_update(self, dialog):
    if self.update_thread is not None or not dialog.info.get('installer'):
        return False
    worker = TVUpdateWorker(self, dialog.info['repo'], dialog.info['installer'])
    self.update_thread = worker
    outcome = {}
    worker.completed.connect(lambda record: outcome.update(record=record))
    worker.failed.connect(lambda message: outcome.update(error=message))
    worker.progress.connect(dialog.bar.setValue)
    def finished():
        self.update_thread = None
        worker.deleteLater()
        if self._update_close_requested or self.closing:
            return
        install_requested = dialog.install_requested
        if 'record' in outcome:
            dialog.ready(outcome['record'])
        else:
            dialog.failed(outcome.get('error', '다운로드가 끝나지 않았습니다. 다시 시도하세요.'))
        if install_requested:
            dialog.show()
            dialog.raise_()
            if 'record' in outcome:
                def install_when_ready():
                    if dialog.install_requested and dialog.isVisible() and not self.closing:
                        dialog.install_requested = False
                        self.install_downloaded_update(outcome['record'])
                QTimer.singleShot(0,install_when_ready)
        elif dialog.isVisible():
            dialog.raise_()
    worker.finished.connect(finished)
    dialog.downloading()
    worker.start()
    return True


def tv_window_cancel_update(self):
    if self.update_dialog is not None:
        self.update_dialog.install_requested = False
    if self.update_thread is not None:
        self.update_thread.requestInterruption()
        if self.update_dialog is not None:
            self.update_dialog.cancel.setEnabled(False)
            self.update_dialog.status.setText('다운로드를 취소하는 중입니다…')


def tv_window_install_update(self, record):
    if self.update_thread is not None or sys.platform != 'win32':
        return False
    choice = QMessageBox.question(self, '새 버전 설치',
        '현재 작업의 저장을 확인한 뒤 뷰어를 종료하고 새 버전을 설치할까요?\n설치 완료 화면에서 뷰어를 다시 실행할 수 있습니다.',
        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.Yes)
    if choice != QMessageBox.StandardButton.Yes:
        return False
    self.pending_update_install = dict(record)
    if not self.close():
        self.pending_update_install = None
        return False
    return True


