class CornerActions(QWidget):
    """읽기·편집 도구 모음. 변환 버튼은 설정에서 선택한 경우에만 표시한다."""
    def __init__(self, parent, host, save, translate, hangul, options, clear, right_inset=0, print_document=None):
        super().__init__(parent)
        self.host=host;self.ctrl_down=False;self.right_inset=right_inset
        layout=QHBoxLayout(self);layout.setContentsMargins(0,0,0,0);layout.setSpacing(3)
        self.clear_button=QToolButton(self);self.save_button=QToolButton(self);self.translate_button=QToolButton(self)
        self.hangul_button=QToolButton(self);self.options_button=QToolButton(self);self.print_button=QToolButton(self)
        self.edit_button=QToolButton(self);self.edit_button.setObjectName('pdf_edit_button')
        self.edit_button.setCheckable(True);self.edit_button.setAccessibleName('PDF 글/그림 편집')
        for button,kind,tip,callback in [(self.clear_button,'clear','전체 비우기 · 새 작업 · Ctrl+N',clear),
                                        (self.save_button,'save','전체 PDF 저장 · Ctrl+S',save),
                                        (self.print_button,'print','인쇄 · Ctrl+P',print_document),
                                        (self.edit_button,'edit','PDF 글/그림 편집',self.toggle_edit),
                                        (self.translate_button,'translate','현재 전체 PDF 번역 · Ctrl+T',translate),
                                        (self.hangul_button,'hangul','한글 변환 · Ctrl+H',hangul),
                                        (self.options_button,'options','옵션 · Ctrl+O',options)]:
            button.setIcon(edit_icon() if kind=='edit' else corner_icon(kind));button.setIconSize(QSize(22,22));button.setFixedSize(28,28)
            button.setFocusPolicy(Qt.FocusPolicy.NoFocus);button.setToolTip(tip)
            button.setStyleSheet('QToolButton{background:rgba(29,34,45,220);color:#e4e8f2;border:1px solid #465064;border-radius:6px;padding:1px;font-size:11px;} QToolButton:hover{background:#4b303e;border-color:#ff667a;} QToolButton:pressed{background:#78283d;} QToolButton:checked{background:#8c304b;border-color:#ff819c;} QToolButton:disabled{border-color:#303746;}')
            button.clicked.connect(callback);layout.addWidget(button)
        owner=getattr(host,'owner',host)
        self.save_button.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.save_button.customContextMenuRequested.connect(lambda pos:owner.show_save_menu(self.save_button.mapToGlobal(pos)))
        self.shortcuts=[]
        QApplication.instance().installEventFilter(self)
        self.sync_visibility();self.sync_edit_state()
        self.set_ctrl(False,force=True)

    def sync_visibility(self):
        owner=getattr(self.host,'owner',self.host)
        for kind in ('translate','hangul'):
            getattr(self,kind+'_button').setVisible(owner.settings.value('toolbar/show_'+kind,False,type=bool))
        self.place()

    def sync_edit_state(self):
        owner=getattr(self.host,'owner',self.host)
        editor=self.host if hasattr(self.host,'page') else getattr(owner,'preview_dialog',None)
        page=getattr(editor,'page',None)
        if page is None and hasattr(owner,'toolbar_edit_page'):page=owner.toolbar_edit_page()
        enabled=(page is not None and not page.is_text_document and not page.is_document_card
                 and not getattr(editor,'closed',False) and not getattr(editor,'dual_secondary',False)
                 and not getattr(editor,'busy',False) and not getattr(owner,'clear_pending',False)
                 and not getattr(owner,'pending_import',None) and not getattr(owner,'imports',[])
                 and not getattr(owner,'import_cancelling',False) and not getattr(owner,'page_batch_job',None))
        active=bool(editor is not None and not getattr(editor,'closed',False) and getattr(editor,'mode','pan')=='edit')
        blocked=self.edit_button.blockSignals(True)
        self.edit_button.setChecked(active);self.edit_button.blockSignals(blocked)
        self.edit_button.setEnabled(bool(enabled))
        self.edit_button.setToolTip('PDF 글/그림 편집 중 · 다시 누르면 읽기 모드' if active else 'PDF 글/그림 편집 · 문서의 글자·그림·표선 수정')

    def toggle_edit(self):
        try:self.host.toggle_document_edit()
        finally:self.sync_edit_state()

    def place(self):
        buttons=[self.layout().itemAt(i).widget() for i in range(self.layout().count()) if not self.layout().itemAt(i).widget().isHidden()]
        self.setFixedSize(sum(b.width() for b in buttons)+max(0,len(buttons)-1)*self.layout().spacing(),28)
        self.move(max(4,self.parentWidget().width()-self.right_inset-self.width()-6),6);self.raise_()

    def set_ctrl(self, down, force=False):
        if down == self.ctrl_down and not force:return
        self.ctrl_down=down
        owner=getattr(self.host,'owner',self.host)
        for button,name,label in [(self.clear_button,'clear','비우기'),(self.save_button,'save','저장'),(self.print_button,'print','인쇄'),(self.translate_button,'translate','번역'),
                                 (self.hangul_button,'hangul','한글'),(self.options_button,'options','옵션')]:
            keys=owner.keys.bindings[name];key=(keys[0].removeprefix('Ctrl+') if keys else '—')
            text=f'{label}({key})';button.setToolTip(f'{label} · {owner.keys.describe(name)}')
            button.setText(text if down else '')
            button.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon if down else Qt.ToolButtonStyle.ToolButtonIconOnly)
            button.setFixedWidth(max(84,button.fontMetrics().horizontalAdvance(text)+32) if down else 28)
        self.edit_button.setText('편집' if down else '')
        self.edit_button.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon if down else Qt.ToolButtonStyle.ToolButtonIconOnly)
        self.edit_button.setFixedWidth(84 if down else 28)
        self.place()

    def eventFilter(self, watched, event):
        kind=event.type()
        if watched is self.host:
            if kind in (QEvent.Type.WindowDeactivate,QEvent.Type.Hide): self.set_ctrl(False)
            elif kind == QEvent.Type.WindowActivate:
                self.set_ctrl(bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ControlModifier))
        if kind in (QEvent.Type.KeyPress,QEvent.Type.KeyRelease,QEvent.Type.ShortcutOverride) and isinstance(watched,QWidget) and watched.window() is self.host:
            if event.key() == Qt.Key.Key_Control:
                if not event.isAutoRepeat():self.set_ctrl(kind != QEvent.Type.KeyRelease)
            else:
                self.set_ctrl(bool(event.modifiers() & Qt.KeyboardModifier.ControlModifier))
        return False


def fit_document_window(widget, single_file, screen=None):
    """한 파일은 A4 세로 비율로, 여러 파일은 넓게. 작업표시줄 영역을 피한다."""
    screen=screen or widget.screen() or QApplication.primaryScreen()
    area=screen.availableGeometry()
    max_w=max(120,area.width()-24);max_h=max(160,area.height()-54)
    if single_file:
        height=min(1050,max_h,int(area.height()*0.9))
        width=round(height*210/297)
        if width>max_w:width=max_w;height=round(width*297/210)
    else:
        width=min(1280,max_w);height=min(850,max_h)
    center=widget.frameGeometry().center() if widget.isVisible() else area.center()
    x=max(area.left()+8,min(center.x()-width//2,area.right()-width-8))
    y=max(area.top()+8,min(center.y()-height//2,area.bottom()-height-32))
    widget.setGeometry(x,y,width,height)


def edit_icon():
    """접힌 문서와 연필을 작은 도구 모음에서도 구분되게 그린다."""
    pm = QPixmap(64, 64); pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm); p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(QPen(QColor('#e4e8f2'), 3.5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
    path = QPainterPath(QPointF(12,8));path.lineTo(35,8);path.lineTo(47,20)
    path.lineTo(47,53);path.lineTo(12,53);path.closeSubpath();p.drawPath(path)
    p.drawPolyline([QPointF(35,8),QPointF(35,20),QPointF(47,20)])
    p.drawLine(QPointF(19,28),QPointF(28,28));p.drawLine(QPointF(19,36),QPointF(24,36))
    p.setBrush(QColor('#f3c674'));p.setPen(QPen(QColor('#fff0cc'),2.5,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap,Qt.PenJoinStyle.RoundJoin))
    pencil = QPainterPath(QPointF(25,41)); pencil.lineTo(28,29); pencil.lineTo(49,8)
    pencil.quadTo(51,6,53,8); pencil.lineTo(58,13); pencil.quadTo(60,15,58,17)
    pencil.lineTo(37,38); pencil.closeSubpath(); p.drawPath(pencil)
    p.drawLine(QPointF(46,11),QPointF(55,20)); p.drawLine(QPointF(29,30),QPointF(36,37))
    p.end(); return QIcon(pm)


def segment_in_rect(a,b,rect,padding=0):
    r=[rect[0]-padding,rect[1]-padding,rect[2]+padding,rect[3]+padding];low,high=0.,1.
    dx,dy=b[0]-a[0],b[1]-a[1]
    for p,q in ((-dx,a[0]-r[0]),(dx,r[2]-a[0]),(-dy,a[1]-r[1]),(dy,r[3]-a[1])):
        if abs(p)<1e-12:
            if q<0:return False
        else:
            value=q/p
            if p<0:low=max(low,value)
            else:high=min(high,value)
            if low>high:return False
    return True


def bulk_text_rows(items):
    """Keep font runs sharing a baseline together, including Korean fragments."""
    units=[]
    for item in sorted(items,key=lambda i:(i['rect'][1],i['rect'][0])):
        row_text=('text' in item and item.get('rotate',0)==0 and
                  len(item['text'].splitlines())<=1 and
                  item['rect'][3]-item['rect'][1]<=max(2,float(item.get('size',11))*1.8))
        match=None
        if row_text:
            for unit in units:
                if not unit['row_text']:continue
                reference=unit['items'][0];a=item['rect'];b=reference['rect']
                ha,hb=a[3]-a[1],b[3]-b[1]
                origin=item.get('origin') or item.get('native_origin');ref_origin=reference.get('origin') or reference.get('native_origin')
                if origin and ref_origin:
                    same=abs(origin[1]-ref_origin[1])<=max(1,min(item.get('size',11),reference.get('size',11))*.15)
                else:
                    same=(abs((a[1]+a[3]-b[1]-b[3])/2)<=min(ha,hb)*.3 and
                          min(a[3],b[3])-max(a[1],b[1])>=min(ha,hb)*.5)
                if same:match=unit;break
        if match is None:units.append({'items':[item],'rect':list(item['rect']),'row_text':row_text})
        else:
            match['items'].append(item);a=match['rect'];b=item['rect']
            match['rect']=[min(a[0],b[0]),min(a[1],b[1]),max(a[2],b[2]),max(a[3],b[3])]
    for unit in units:unit['items'].sort(key=lambda i:i['rect'][0])
    return sorted(units,key=lambda u:(u['rect'][1],u['rect'][0]))


def bulk_new_overlap(changes):
    def overlaps(a,b):
        return min(a[2],b[2])-max(a[0],b[0])>.1 and min(a[3],b[3])-max(a[1],b[1])>.1
    active=[]
    for item,target in sorted(changes,key=lambda pair:pair[1][0]):
        active=[pair for pair in active if pair[1][2]>target[0]+.1]
        for previous,other in active:
            if overlaps(target,other) and not overlaps(item['rect'],previous['rect']):return True
        active.append((item,target))
    return False


def bulk_alignment_targets(items,action,page_size):
    """Distribute within reading rows, expanding only into available page space."""
    if action not in ('start_x','start_y','center_x','center_y','gap_x','gap_y'):
        raise ValueError('정렬 방향을 다시 선택하세요.')
    axis=0 if action.endswith('_x') else 1
    rows=bulk_text_rows(items)
    units=rows if action in ('start_x','center_x','gap_y') else [
        {'items':[i],'rect':list(i['rect']),'row_text':False} for i in items]
    if len(units)<2:return []
    targets={id(i):list(i['rect']) for i in items}

    def distribute(group):
        if len(group)<2:return
        ordered=sorted(group,key=lambda u:(u['rect'][axis],u['rect'][1-axis]))
        start=ordered[0]['rect'][axis];end=max(u['rect'][axis+2] for u in ordered)
        total=sum(u['rect'][axis+2]-u['rect'][axis] for u in ordered)
        gap=(end-start-total)/(len(ordered)-1)
        if gap<0:
            limit=page_size[axis]
            if total>limit+.0001:
                raise ValueError('글자·개체 크기를 유지한 채 배치할 공간이 부족합니다. 선택 영역을 나누거나 글상자를 합쳐주세요.')
            old_gaps=[b['rect'][axis]-a['rect'][axis+2] for a,b in zip(ordered,ordered[1:])]
            preferred=max(2.,min((g for g in old_gaps if g>0),default=2.))
            gap=min(preferred,max(0,(limit-total)/(len(ordered)-1)))
            start=max(0,min(start,limit-total-gap*(len(ordered)-1)))
        for unit in ordered:
            delta=start-unit['rect'][axis]
            for item in unit['items']:
                r=list(item['rect']);r[axis]+=delta;r[axis+2]+=delta;targets[id(item)]=r
            start+=unit['rect'][axis+2]-unit['rect'][axis]+gap

    if action=='gap_x':
        # Each reading row has its own horizontal space. Widths of distinct
        # paragraphs must never be added as if they occupied one long row.
        bands=[]
        for unit in rows:
            match=None;a=unit['rect']
            for band in bands:
                b=band['rect'];overlap=min(a[3],b[3])-max(a[1],b[1])
                if overlap>=max(.1,min(a[3]-a[1],b[3]-b[1])*.5):match=band;break
            if match is None:bands.append({'items':list(unit['items']),'rect':list(a)})
            else:
                match['items'].extend(unit['items']);b=match['rect']
                match['rect']=[min(a[0],b[0]),min(a[1],b[1]),max(a[2],b[2]),max(a[3],b[3])]
        for band in bands:distribute([{'items':[i],'rect':i['rect']} for i in band['items']])
    elif action=='gap_y':distribute(units)
    else:
        left=min(u['rect'][axis] for u in units);right=max(u['rect'][axis+2] for u in units)
        position=left if action.startswith('start') else (left+right)/2
        for unit in units:
            r=unit['rect'];delta=position-(r[axis] if action.startswith('start') else (r[axis]+r[axis+2])/2)
            for item in unit['items']:
                target=list(item['rect']);target[axis]+=delta;target[axis+2]+=delta;targets[id(item)]=target
        # If aligning creates a collision, move the later row just far enough
        # on the other axis, retaining its words, dimensions and reading order.
        other=1-axis;placed=[]
        for unit in sorted(units,key=lambda u:(u['rect'][other],u['rect'][axis])):
            moved=[(i,targets[id(i)]) for i in unit['items']]
            for previous in placed:
                if bulk_new_overlap(moved+previous):
                    delta=max(p[other+2] for j,p in previous)+2-min(t[other] for i,t in moved)
                    if delta>0:
                        for item,target in moved:target[other]+=delta;target[other+2]+=delta
            placed.append(moved)
        smallest=min(targets[id(i)][other] for i in items);largest=max(targets[id(i)][other+2] for i in items)
        shift=min(0,page_size[other]-largest)
        if smallest+shift<-.0001:raise ValueError('정렬 후 겹치지 않게 놓을 공간이 부족합니다. 선택 영역을 나누거나 글상자를 합쳐주세요.')
        if shift:
            for target in targets.values():target[other]+=shift;target[other+2]+=shift
    changes=[(i,targets[id(i)]) for i in items]
    if bulk_new_overlap(changes):raise ValueError('이 범위에서는 개체가 겹칩니다. 선택 영역 손잡이로 간격을 넓히거나 글상자를 합쳐주세요.')
    return changes


def bulk_stretch_targets(items,bounds,page_size):
    """Stretch spacing, keeping artwork sizes and text baselines unchanged."""
    source=[min(i['rect'][0] for i in items),min(i['rect'][1] for i in items),
            max(i['rect'][2] for i in items),max(i['rect'][3] for i in items)]
    rows=bulk_text_rows(items)

    def position(old,size,axis,target):
        room=source[axis+2]-source[axis]-size
        fraction=(old-source[axis])/room if room>.0001 else .5
        return target[axis]+fraction*(target[axis+2]-target[axis]-size)

    def calculate(target):
        result=[]
        for unit in rows:
            row=unit['rect'];dy=position(row[1],row[3]-row[1],1,target)-row[1]
            for item in unit['items']:
                r=item['rect'];x=position(r[0],r[2]-r[0],0,target)
                result.append((item,[x,r[1]+dy,x+r[2]-r[0],r[3]+dy]))
        return result

    def valid(changes):
        return (all(r[0]>=-.0001 and r[1]>=-.0001 and r[2]<=page_size[0]+.0001 and r[3]<=page_size[1]+.0001
                    for i,r in changes) and not bulk_new_overlap(changes))
    desired=[max(0,bounds[0]),max(0,bounds[1]),min(page_size[0],bounds[2]),min(page_size[1],bounds[3])]
    changes=calculate(desired)
    if valid(changes):return changes
    low,high=0.,1.;best=calculate(source)
    for _ in range(18):
        ratio=(low+high)/2;candidate=calculate([a+(b-a)*ratio for a,b in zip(source,desired)])
        if valid(candidate):low=ratio;best=candidate
        else:high=ratio
    return best


def merged_text_operation(items,page_size):
    """Build one editable text box, retaining reading order and line breaks."""
    import unicodedata
    texts=[i for i in items if 'text' in i and i['text'].strip()]
    if len(texts)<2:raise ValueError('합칠 글상자를 두 개 이상 선택하세요.')
    if any(i.get('rotate',0) for i in texts):raise ValueError('글상자 합치기는 가로로 쓰인 글자를 선택하세요.')
    rows=bulk_text_rows(texts);lines=[];previous=None
    for row in rows:
        glyphs=sorted([(g,i) for i in row['items'] for g in i.get('source_glyphs',[])],key=lambda pair:pair[0]['origin'][0])
        advances={}
        for (a,item),(b,other) in zip(glyphs,glyphs[1:]):
            if unicodedata.east_asian_width(a['text'][-1:]) not in ('W','F'):continue
            ratio=(b['origin'][0]-a['origin'][0])/max(1,item.get('size',11))
            if .3<ratio<2:advances.setdefault(item.get('font',''),[]).append(ratio)
        advances={font:sorted(values)[(len(values)-1)//4] for font,values in advances.items()}
        parts=[];last=None
        for item in row['items']:
            value=item['text'].strip()
            if not value:continue
            if last is not None:
                gap=item['rect'][0]-last['rect'][2]
                explicit=last['text'][-1:].isspace() or item['text'][:1].isspace()
                a=last.get('source_glyphs',[]);b=item.get('source_glyphs',[])
                if a and b and unicodedata.east_asian_width(a[-1]['text'][-1:]) in ('W','F'):
                    # Narrow Korean ink boxes have normal intra-word gaps.
                    # Use the original baseline advance, not the ink boundary.
                    step=b[0]['origin'][0]-a[-1]['origin'][0]
                    expected=last.get('size',11)*advances.get(last.get('font',''),1.)
                    space=explicit or step>expected+min(item.get('size',11),last.get('size',11))*.15
                else:space=explicit or gap>=min(item.get('size',11),last.get('size',11))*.18
                if space and value[0] not in ',.;:!?)]}、。％%' and parts[-1][-1:] not in '([{':parts.append(' ')
            parts.append(value);last=item
        if previous is not None and row['rect'][1]-previous['rect'][3]>max(3,float(row['items'][0].get('size',11))*1.2):lines.append('')
        lines.append(''.join(parts));previous=row
    text='\n'.join(lines)
    if len(text)>1000000:raise ValueError('합칠 글자가 너무 많습니다. 문단별로 선택하세요.')
    first=rows[0]['items'][0]
    left=min(i['rect'][0] for i in texts);top=min(i['rect'][1] for i in texts)
    right=max(i['rect'][2] for i in texts);bottom=max(i['rect'][3] for i in texts)
    operation={'kind':'text','text':text,'font':safe_font_family(first.get('family',first.get('font',''))),
               'size':first.get('size',11),'bold':bool(first.get('bold')),'color':first.get('color','#111111'),
               'align':first.get('align','left'),'rotate':0,'strict_size':True,'text_frame':True,'object_id':uuid.uuid4().hex}
    origin=first.get('origin') or first.get('native_origin')
    if origin:
        left=min(left,origin[0]);top=max(0,origin[1]-editor_text_layout(operation,max(1,right-left))['baseline'])
    available=page_size[0]-left
    if available<2:raise ValueError('글상자를 놓을 페이지 공간이 부족합니다.')
    width=min(available,max(right-left,editor_text_layout(operation)['width']+2,8))
    height=max(bottom-top,editor_text_layout(operation,width)['height']+1)
    if height>page_size[1]-top:
        width=available;height=max(bottom-top,editor_text_layout(operation,width)['height']+1)
    if height>page_size[1]:raise ValueError('합친 글상자가 페이지에 들어가지 않습니다. 문단별로 선택하세요.')
    top=min(top,page_size[1]-height)
    operation['rect']=[left,top,left+width,top+height]
    return operation


def validate_text_snapshot(item,clean):
    if 'native_pdf' not in item:return clean
    data=base64.b64decode(item['native_pdf'],validate=True)
    if not data.startswith(b'%PDF-') or len(data)>64*1024*1024:raise ValueError('복사한 글상자 원본이 올바르지 않습니다.')
    clean['native_pdf']=item['native_pdf']
    origin=item.get('native_origin')
    if origin is not None:
        if len(origin)!=2 or not all(isinstance(v,(int,float)) and not isinstance(v,bool) and math.isfinite(v) and 0<=v<=20000 for v in origin):
            raise ValueError('복사한 글자의 기준선이 올바르지 않습니다.')
        clean['native_origin']=origin
    family=item.get('family')
    if isinstance(family,str) and len(family)<=256:clean['family']=family
    return clean


def validate_object_bundle(data):
    import base64
    if data.get('version')!=1 or not isinstance(data.get('items'),list) or not 1<=len(data['items'])<=5000:raise ValueError('개체 묶음 정보가 올바르지 않습니다.')
    result=[]
    for item in data['items']:
        kind=item.get('kind');r=item.get('rect',[])
        if len(r)!=4 or any(not isinstance(v,(int,float)) or not math.isfinite(v) or not 0<=v<=20000 for v in r) or r[2]<r[0] or r[3]<r[1]:raise ValueError('개체 좌표가 올바르지 않습니다.')
        clean={'kind':kind,'rect':r}
        if kind=='vector':clean.update(shape=item['shape'],strokes=validate_vector_strokes(item['strokes'],20000,20000))
        elif kind=='text':
            text=item.get('text');size=item.get('size',11);font=item.get('font','sans-serif')
            if not isinstance(text,str) or not text.strip() or len(text)>1000000 or not isinstance(size,(int,float)) or not 4<=size<=144 or not isinstance(font,str) or len(font)>256:raise ValueError('글상자 정보가 올바르지 않습니다.')
            clean.update(text=text,size=size,font=font,bold=bool(item.get('bold')),color=item.get('color','#111111'),rotate=item.get('rotate',0),align=item.get('align','left'))
            if not re.fullmatch('#[0-9a-fA-F]{6}',clean['color']) or clean['rotate'] not in (0,90,180,270) or clean['align'] not in ('left','center','right'):raise ValueError('글자 서식이 올바르지 않습니다.')
            validate_text_snapshot(item,clean)
        elif kind=='image':
            png=base64.b64decode(item['png'],validate=True)
            if len(png)>64*1024*1024 or not png.startswith(b'\x89PNG\r\n\x1a\n') or QImage.fromData(png,'PNG').isNull():raise ValueError('그림 정보가 올바르지 않습니다.')
            clean['png']=item['png']
        elif kind=='cover':
            color=item.get('color','#ffffff')
            if not re.fullmatch('#[0-9a-fA-F]{6}',color):raise ValueError('덮기 색상이 올바르지 않습니다.')
            clean['color']=color
        else:raise ValueError('지원하지 않는 묶음 개체입니다.')
        result.append(clean)
    return {'kind':'bundle','items':result}



def clipboard_edit_payloads(session):
    """클립보드 그림을 즉시 스냅샷으로 보관. PDF 페이지 클립보드는 별도 유지."""
    clipboard=QApplication.clipboard();mime=clipboard.mimeData()
    if mime is None or mime.hasFormat(CLIPBOARD_MIME):return []
    if mime.hasFormat(OBJECT_BUNDLE_CLIPBOARD_MIME):
        return [validate_object_bundle(json.loads(bytes(mime.data(OBJECT_BUNDLE_CLIPBOARD_MIME))))]
    if mime.hasFormat(VECTOR_OBJECT_CLIPBOARD_MIME):
        try:
            data=json.loads(bytes(mime.data(VECTOR_OBJECT_CLIPBOARD_MIME)))
            if data.get('version')!=1 or data.get('kind')!='vector' or data.get('shape') not in ('line','table','frame'):raise ValueError()
            strokes=validate_vector_strokes(data['strokes'],20000,20000)
            return [{'kind':'vector','shape':data['shape'],'strokes':strokes,'rect':vector_bounds(strokes)}]
        except (KeyError,ValueError,TypeError,AttributeError):return []
    if mime.hasFormat(TEXT_OBJECT_CLIPBOARD_MIME):
        try:
            data=json.loads(bytes(mime.data(TEXT_OBJECT_CLIPBOARD_MIME)))
            if data.get('version')!=1 or data.get('kind')!='text':raise ValueError()
            text=data['text'];size=data['size'];rect=data['rect'];color=QColor(data['color'])
            if not isinstance(text,str) or not text.strip() or len(text)>1_000_000:raise ValueError()
            if isinstance(size,bool) or not isinstance(size,(int,float)) or not math.isfinite(size) or not 4<=size<=144:raise ValueError()
            if len(rect)!=4 or not all(isinstance(x,(int,float)) and not isinstance(x,bool) and math.isfinite(x) and 0<=x<=20000 for x in rect) or rect[2]<=rect[0] or rect[3]<=rect[1]:raise ValueError()
            if not isinstance(data['font'],str) or len(data['font'])>256 or not color.isValid():raise ValueError()
            if type(data['bold']) is not bool or data.get('rotate',0) not in (0,90,180,270) or data.get('align','left') not in ('left','center','right'):raise ValueError()
            clean={key:data[key] for key in ('kind','text','font','size','bold','color','rect','rotate','align')}
            return [validate_text_snapshot(data,clean)]
        except (KeyError,ValueError,TypeError,AttributeError):
            # A foreign or old payload can still be pasted as ordinary text.
            pass
    pictures=[]
    if mime.hasImage():
        picture=clipboard.image()
        if not picture.isNull():pictures.append(picture.copy())
    if not pictures and mime.hasUrls():
        for url in mime.urls():
            if not url.isLocalFile() or url.toLocalFile().lower().endswith('.pdf'):continue
            reader=QImageReader(url.toLocalFile());reader.setAutoTransform(True)
            if reader.canRead():
                picture=reader.read()
                if not picture.isNull():pictures.append(picture)
    if pictures:
        folder=TEMP_ROOT/session/'paste';folder.mkdir(parents=True,exist_ok=True)
        result=[]
        for picture in pictures:
            path=folder/(uuid.uuid4().hex+'.png')
            if not picture.save(str(path),'PNG'):raise ValueError('클립보드 그림을 읽지 못했습니다.')
            payload={'kind':'image','filename':str(path),'width':picture.width(),'height':picture.height()}
            if mime.hasFormat(IMAGE_CLIPBOARD_MIME):
                try:
                    size=json.loads(bytes(mime.data(IMAGE_CLIPBOARD_MIME)))
                    if isinstance(size,dict) and size.get('version')==2:
                        rect=size.get('rect',[])
                        if (len(rect)==4 and all(isinstance(v,(int,float)) and not isinstance(v,bool) and math.isfinite(v) and 0<=v<=20000 for v in rect)
                                and rect[2]>rect[0] and rect[3]>rect[1]):
                            payload['rect']=rect
                            size=[rect[2]-rect[0],rect[3]-rect[1]]
                    if len(size)==2 and all(isinstance(v,(int,float)) and math.isfinite(v) and 0<v<=20000 for v in size):
                        payload['pdf_size']=size
                except (ValueError,TypeError):pass
            result.append(payload)
        return result
    if not mime.hasUrls() and mime.hasText() and mime.text().strip():
        return [{'kind':'text','text':mime.text()}]
    return []


class ColorStrip(QWidget):
    colorChanged=Signal(str)
    COLORS=['#111111','#ffffff','#777777','#e53935','#ef8c23','#f4cf35','#259b54','#2385dc','#7144bf']
    def __init__(self,color='#111111',parent=None):
        super().__init__(parent);self.color=QColor(color);self.buttons=[]
        row=QHBoxLayout(self);row.setContentsMargins(0,0,0,0);row.setSpacing(4)
        for value in self.COLORS:
            button=QToolButton();button.setFixedSize(22,22);button.setToolTip(value)
            button.clicked.connect(lambda checked=False,c=value:self.set_color(c))
            row.addWidget(button);self.buttons.append((button,value))
        more=QToolButton();more.setText('…');more.setFixedSize(24,22);more.setToolTip('다른 색상')
        more.clicked.connect(self.choose_color);row.addWidget(more);row.addStretch();self.update_colors()

    def update_colors(self):
        for button,value in self.buttons:
            border='3px solid #ff5971' if value==self.color.name() else '1px solid #969ba6'
            button.setStyleSheet(f'background:{value};border:{border};border-radius:4px;')

    def set_color(self,value):
        self.color=QColor(value);self.update_colors();self.colorChanged.emit(self.color.name())

    def choose_color(self):
        color=QColorDialog.getColor(self.color,self,'글자 색상')
        if color.isValid():self.set_color(color.name())


class PageCountLabel(QLabel):
    """Small, persistent, click-through count overlay for either viewer."""
    def __init__(self,parent):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setStyleSheet('background:rgba(22,27,39,135);color:rgba(255,255,255,215);'
            'border:1px solid rgba(210,220,237,28);border-radius:7px;padding:3px 9px;font-size:11px;')
        self.hide()

    def set_count(self,total,index=None,unit='장'):
        self.setText((f'{index+1:,} / {total:,}'+(' 항목' if unit=='항목' else '')) if index is not None else f'{total:,}{unit}')
        self.setVisible(total>0);self.place()

    def place(self):
        viewport=self.parentWidget();self.adjustSize()
        self.move(max(4,(viewport.width()-self.width())//2),max(4,viewport.height()-self.height()-9))
        self.raise_()


class NavigationNotice(QLabel):
    """Brief, single-line boundary feedback without taking focus or clicks."""
    def __init__(self,parent):
        super().__init__(parent);self.message=''
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setTextFormat(Qt.TextFormat.PlainText)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setStyleSheet('background:rgba(22,27,39,185);color:#eef2f8;'
            'border:0;border-radius:6px;padding:4px 10px;font-size:11px;')
        self.timer=QTimer(self);self.timer.setSingleShot(True)
        self.timer.setInterval(1800);self.timer.timeout.connect(self.hide)
        self.hide()

    def show_message(self,text):
        self.message=str(text).replace('\n',' ')
        self.place();self.show();self.raise_();self.timer.start()

    def place(self):
        viewport=self.parentWidget();width=max(40,viewport.width()-32)
        self.setText(self.fontMetrics().elidedText(self.message,Qt.TextElideMode.ElideRight,max(20,width-20)))
        self.adjustSize()
        self.move(max(4,(viewport.width()-self.width())//2),max(4,viewport.height()-self.height()-38))


class EndOfContainerOverlay(QWidget):
    """첫/마지막 쪽의 명시적 파일 이동. 주변 압축파일을 미리 읽지 않는다."""
    def __init__(self,editor):
        super().__init__(editor.view.viewport());self.editor=editor;self.origin=None;self.container=False
        self.setObjectName('container_end');self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground)
        self.setStyleSheet('QWidget#container_end{background:rgba(24,29,40,175);'
            'border:1px solid rgba(220,229,245,48);border-radius:10px;}'
            'QLabel{background:transparent;border:0;color:rgba(245,248,255,225);font-size:12px;}'
            'QLabel#end_keys{color:rgba(232,238,252,175);font-size:11px;}'
            'QLabel#end_name{color:rgba(240,244,253,215);font-size:11px;}'
            'QLabel:disabled{color:rgba(205,215,234,115);}'
            'QPushButton{background:rgba(245,247,255,20);border:1px solid rgba(220,228,244,42);border-radius:5px;}'
            'QPushButton:hover{background:rgba(183,49,78,175);border-color:rgba(255,141,160,205);}'
            'QPushButton:pressed{background:rgba(135,33,56,210);}'
            'QPushButton:disabled{background:rgba(245,247,255,8);border-color:rgba(220,228,244,15);}')
        layout=QVBoxLayout(self);layout.setContentsMargins(12,10,12,12);layout.setSpacing(7)
        self.heading=QLabel('마지막 페이지입니다');layout.addWidget(self.heading)
        self.buttons={};self.key_labels={};self.captions={};self.name_labels={}
        for action,title,direction in (('previous_file','‹  이전 항목',-1),('next_file','다음 항목  ›',1)):
            button=QPushButton(self);button.setObjectName('end_'+action);button.setFixedHeight(52)
            button.setFocusPolicy(Qt.FocusPolicy.NoFocus);button.setCursor(Qt.CursorShape.PointingHandCursor)
            box=QVBoxLayout(button);box.setContentsMargins(10,5,10,5);box.setSpacing(2)
            row=QHBoxLayout();row.setSpacing(8);box.addLayout(row)
            caption=QLabel(title);keys=QLabel();keys.setObjectName('end_keys');keys.setAlignment(Qt.AlignmentFlag.AlignRight|Qt.AlignmentFlag.AlignVCenter)
            keys.setSizePolicy(QSizePolicy.Policy.Ignored,QSizePolicy.Policy.Preferred)
            name=QLabel();name.setObjectName('end_name');name.setSizePolicy(QSizePolicy.Policy.Ignored,QSizePolicy.Policy.Preferred)
            for label in (caption,keys,name):label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
            row.addWidget(caption);row.addWidget(keys,1);box.addWidget(name);layout.addWidget(button)
            button.clicked.connect(lambda _checked=False,direction=direction:self.editor.owner.navigate_sibling(direction))
            self.buttons[action]=button;self.key_labels[action]=keys;self.captions[action]=caption;self.name_labels[action]=name
        self.hide()

    def sync(self):
        if self.editor.dual_secondary:self.hide();return
        editor=self.editor;owner=editor.owner
        origin,containers,_library=owner.navigation_context()
        # Ordinary photo review (including a folder of photos) uses arrows and
        # a brief boundary notice. The book/archive controls remain available.
        if is_image_source(editor.page.path) and Path(origin or '').suffix.lower() not in ARCHIVE_EXTENSIONS:
            self.hide();return
        if origin!=self.origin:
            self.origin=origin
            self.container=bool(origin) and (Path(origin).suffix.lower() in ARCHIVE_EXTENSIONS or Path(origin).is_dir())
        index=editor.navigation_index()
        at_start=index==0 and editor.first_page_hint_uid==editor.page.uid
        visible=(not editor.closed and editor.mode=='pan' and containers and self.container and bool(owner.pages) and
                 (at_start or index==len(editor.navigation_pages())-1) and not owner.clear_pending and
                 not owner.book_focus and
                 not (owner.pending_import or owner.imports or owner.import_cancelling))
        self.setVisible(visible)
        if not visible:return
        self.heading.setText('첫 페이지입니다' if at_start else '마지막 페이지입니다')
        owner.request_neighbor_names()
        for action,button in self.buttons.items():
            keys=owner.keys.describe(action);title='이전' if action=='previous_file' else '다음'
            path=owner.neighbor_paths.get('previous' if action=='previous_file' else 'next','')
            name=(Path(path).name if path else ('확인 실패' if owner.neighbor_error else '없음')) if owner.neighbor_ready else '확인 중…'
            button.setToolTip((path or owner.neighbor_error or name)+f'\n{title} 항목 · {keys}')
            button.setAccessibleName(f'{title} 항목 ({name}) · {keys}')
            self.name_labels[action].setProperty('full_name',f'({name})')
            button.setEnabled(bool(path) and owner.neighbor_ready and not owner.neighbor_error and
                              owner.navigation_request is None and not editor.busy)
        self.place()

    def place(self):
        if self.isHidden():return
        viewport=self.parentWidget();arrow=self.editor.nav_next.geometry()
        right=arrow.left()-10
        self.setFixedWidth(max(140,min(360,right-8)));self.adjustSize()
        y=arrow.center().y()-self.height()//2-24
        self.move(max(4,right-self.width()),max(8,min(y,viewport.height()-self.height()-8)))
        for action,label in self.key_labels.items():
            text=self.editor.owner.keys.describe(action)
            available=max(16,self.width()-64-self.captions[action].sizeHint().width())
            label.setText(label.fontMetrics().elidedText(text,Qt.TextElideMode.ElideMiddle,available))
            name=self.name_labels[action];full=name.property('full_name') or ''
            name.setText(name.fontMetrics().elidedText(full,Qt.TextElideMode.ElideMiddle,max(20,self.width()-46)))
        self.raise_()


class PageNavButton(QWidget):
    """Vertical displacement controls repeat speed, not an absolute page position."""
    DEAD_ZONE=7

    def __init__(self,editor,direction):
        super().__init__(editor.view.viewport());self.editor=editor;self.direction=direction
        self.setFixedSize(32,72);self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setAccessibleName(('이전' if direction<0 else '다음')+' 페이지')
        self.setToolTip(('이전' if direction<0 else '다음')+' 페이지\n'
            '누른 채 위/아래: 한 장씩 연속 이동 · 약 2cm를 넘기면 가속\n'
            '그대로 유지: 계속 이동 · 시작 위치로 당기기: 정지 · 우클릭/Esc: 취소')
        self.pressed=False;self.dragged=False;self.start_y=0;self.start_index=0;self.target_index=0
        self.start_uid=None;self.hovered=False;self.displacement=0.0;self.slow_distance=76.0
        self.fraction=0.0;self.last_tick=0.0;self.filter_active=False
        self.repeat_timer=QTimer(self);self.repeat_timer.setInterval(25)
        self.repeat_timer.setTimerType(Qt.TimerType.PreciseTimer);self.repeat_timer.timeout.connect(self.repeat_step)

    def drag_threshold(self):
        # QScreen physical DPI is already in device-independent dots (Qt 6).
        # Bad/missing monitor metadata falls back to the configured logical DPI.
        screen=self.screen();dpi=screen.physicalDotsPerInchY() if screen is not None else 96.0
        if not math.isfinite(dpi) or not 40<=dpi<=400:
            dpi=screen.logicalDotsPerInchY() if screen is not None else 96.0
        return max(self.DEAD_ZONE*3,dpi*2/2.54)

    def repeat_rate(self):
        distance=abs(self.displacement)
        if distance<self.DEAD_ZONE:return 0.0
        if distance<=self.slow_distance:
            return 1.5+1.5*(distance-self.DEAD_ZONE)/max(1,self.slow_distance-self.DEAD_ZONE)
        tension=(distance-self.slow_distance)/self.slow_distance
        return min(120.0,3.0+18.0*tension**1.5)

    def fast_drag(self):
        return self.pressed and self.dragged and abs(self.displacement)>self.slow_distance

    def border_color(self):
        if self.fast_drag():
            tension=min(1.0,(abs(self.displacement)/self.slow_distance-1)/1.5)
            return QColor(255,round(185-135*tension),round(65+28*tension),
                          round(215+40*math.sin(time.monotonic()*10)))
        if self.pressed:return QColor('#ff8e9e')
        return QColor(208,221,242,205 if self.hovered or self.hasFocus() else 125)

    def paintEvent(self,event):
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing)
        color=self.border_color();fast=self.fast_drag()
        p.setPen(QPen(color,2 if fast else 1))
        p.setBrush(QColor(25,32,46,175 if self.pressed else (145 if self.hovered else 95)))
        p.drawRoundedRect(QRectF(self.rect()).adjusted(1.5,1.5,-1.5,-1.5),6,6)
        at_end=(self.editor.navigation_index()+self.direction not in range(len(self.editor.navigation_pages())) and
                not self.editor.owner.can_browse_photo_files())
        p.setPen(QPen(color if self.pressed else QColor(244,247,255,115 if at_end else 230),
                      2,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap,Qt.PenJoinStyle.RoundJoin))
        x,y=self.width()/2,self.height()/2
        path=QPainterPath(QPointF(x-self.direction*3,y-6));path.lineTo(x+self.direction*3,y);path.lineTo(x-self.direction*3,y+6)
        p.drawPath(path)
        if self.pressed and self.dragged:
            tension=max(-1.0,min(1.0,self.displacement/(self.slow_distance*3)))
            p.setPen(QPen(color,2,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(6,y),QPointF(6,y+tension*(y-9)))

    def enterEvent(self,event):
        self.hovered=True;self.update();super().enterEvent(event)

    def leaveEvent(self,event):
        self.hovered=False;self.update();super().leaveEvent(event)

    def mousePressEvent(self,event):
        if event.button()==Qt.MouseButton.RightButton and self.pressed:
            self.cancel();event.accept();return
        if event.button()==Qt.MouseButton.LeftButton and self.editor.navigation_pages() and not self.editor.closed:
            self.pressed=True;self.dragged=False;self.start_y=event.globalPosition().y()
            self.start_index=self.editor.nav_display_index if self.editor.nav_target_uid is not None or self.editor.owner.book_target_index is not None else self.editor.navigation_index()
            self.start_index=max(0,min(len(self.editor.navigation_pages())-1,self.start_index))
            self.start_uid=self.editor.navigation_pages()[self.start_index].uid;self.target_index=self.start_index
            self.slow_distance=self.drag_threshold();self.displacement=0.0;self.fraction=0.0
            self.editor.nav_side=self.direction;self.setFocus(Qt.FocusReason.MouseFocusReason)
            QApplication.instance().installEventFilter(self);self.filter_active=True
            self.update();event.accept()

    def mouseDoubleClickEvent(self,event):
        self.mousePressEvent(event)

    def mouseMoveEvent(self,event):
        if not self.pressed:return
        dy=event.globalPosition().y()-self.start_y
        if not self.dragged and abs(dy)<self.DEAD_ZONE:event.accept();return
        first=not self.dragged;reversed_direction=self.displacement*dy<0
        self.dragged=True;self.displacement=dy;self.editor.nav_scrubbing=True
        if first or reversed_direction or abs(dy)<self.DEAD_ZONE:self.fraction=0.0
        if first:
            QToolTip.hideText();self.last_tick=time.monotonic();self.repeat_timer.start()
        if (first or reversed_direction) and abs(dy)>=self.DEAD_ZONE:
            self.advance(1 if dy>0 else -1)
        self.update();self.editor.view.viewport().update();event.accept()

    def advance(self,steps):
        if not self.editor.navigation_pages():return
        target=self.target_index+steps;index=max(0,min(len(self.editor.navigation_pages())-1,target))
        if index==self.target_index:
            self.fraction=0.0
            if target<0:self.editor.request_navigation(target,scrub=True)
            return
        self.target_index=index;self.editor.request_navigation(target,scrub=True)

    def repeat_step(self):
        if not self.pressed or self.editor.closed:self.stop_drag();return
        modal=QApplication.activeModalWidget()
        if modal is not None and modal is not self.editor:self.cancel();return
        now=time.monotonic();elapsed=max(0.0,min(0.1,now-self.last_tick));self.last_tick=now
        self.fraction+=elapsed*self.repeat_rate();steps=int(self.fraction)
        if steps:
            self.fraction-=steps;self.advance(steps if self.displacement>0 else -steps)
        self.update()

    def stop_drag(self):
        self.repeat_timer.stop();self.pressed=False;self.editor.nav_scrubbing=False
        self.displacement=0.0;self.fraction=0.0
        if self.filter_active:
            QApplication.instance().removeEventFilter(self);self.filter_active=False
        self.update();self.editor.view.viewport().update()

    def mouseReleaseEvent(self,event):
        if event.button()!=Qt.MouseButton.LeftButton or not self.pressed:return
        target=self.target_index if self.dragged else self.start_index+self.direction
        self.stop_drag()
        self.editor.request_navigation(target,scrub=self.dragged);self.editor.nav_timer.stop();self.editor.perform_navigation()
        self.editor.refine.start();event.accept()

    def cancel(self):
        if not self.pressed:return
        index=next((i for i,page in enumerate(self.editor.navigation_pages()) if page.uid==self.start_uid),self.start_index)
        self.stop_drag();self.editor.view.suppress_context_until=time.monotonic()+0.5
        self.editor.nav_timer.stop();self.editor.nav_target_uid=None
        self.editor.first_page_hint_uid=None
        self.editor.request_navigation(index,scrub=True);self.editor.perform_navigation();self.editor.update_navigation()

    def eventFilter(self,obj,event):
        if self.pressed:
            if event.type()==QEvent.Type.KeyPress and event.key()==Qt.Key.Key_Escape:
                self.cancel();return True
            if event.type()==QEvent.Type.MouseButtonPress and event.button()==Qt.MouseButton.RightButton:
                self.cancel();return True
            if event.type()==QEvent.Type.WindowDeactivate and obj is self.window():self.cancel()
        return False

    def hideEvent(self,event):
        if self.pressed:self.stop_drag()
        super().hideEvent(event)

    def keyPressEvent(self,event):
        if self.editor.owner.handle_file_key(event):return
        if event.key() in (Qt.Key.Key_Return,Qt.Key.Key_Enter):
            self.editor.request_navigation(self.editor.navigation_index()+self.direction);event.accept();return
        super().keyPressEvent(event)


class ObjectLayerButton(QToolButton):
    stepRequested=Signal(str)
    def __init__(self,role,parent=None):
        super().__init__(parent);self.role=role;self.setFixedSize(32,30)
        if role=='ratio':self.setCheckable(True);self.setChecked(True)
        self.setToolTip({'ratio':'비율 유지 / 자유 조절','front':'맨 앞으로','back':'맨 뒤로',
                        'step':'위: 한 단계 앞으로 · 아래: 한 단계 뒤로'}[role])

    def paintEvent(self,event):
        super().paintEvent(event)
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(QPen(QColor('#f0f3fa' if self.isEnabled() else '#7f8797'),1.5))
        p.setBrush(Qt.BrushStyle.NoBrush)
        if self.role=='ratio':
            p.drawRect(QRectF(9,8,14,14) if self.isChecked() else QRectF(5,10,22,10))
        elif self.role=='step':
            p.drawPolyline([QPointF(11,9),QPointF(16,4),QPointF(21,9)])
            p.drawPolyline([QPointF(11,21),QPointF(16,26),QPointF(21,21)])
        else:
            font=p.font();font.setBold(True);font.setPixelSize(13);p.setFont(font)
            p.drawText(QRectF(5,7,15,18),Qt.AlignmentFlag.AlignCenter,'Z')
            if self.role=='front':
                p.drawLine(QPointF(6,4),QPointF(26,4));p.drawLine(QPointF(24,18),QPointF(24,8))
                p.drawPolyline([QPointF(20,12),QPointF(24,8),QPointF(28,12)])
            else:
                p.drawLine(QPointF(6,26),QPointF(26,26));p.drawLine(QPointF(24,12),QPointF(24,22))
                p.drawPolyline([QPointF(20,18),QPointF(24,22),QPointF(28,18)])

    def mouseReleaseEvent(self,event):
        if self.role=='step' and event.button()==Qt.MouseButton.LeftButton:
            if self.rect().contains(event.position().toPoint()):self.stepRequested.emit('up' if event.position().y()<self.height()/2 else 'down')
            self.setDown(False);event.accept();return
        super().mouseReleaseEvent(event)


def nearest_text_hit(elements,point,tolerance):
    candidates=[]
    for element in elements:
        if element.get('object_id'):continue
        x0,y0,x1,y1=element['rect']
        distance=math.hypot(max(x0-point[0],0,point[0]-x1),max(y0-point[1],0,point[1]-y1))
        if distance<=tolerance:
            candidates.append((distance,(x1-x0)*(y1-y0),math.dist(point,[(x0+x1)/2,(y0+y1)/2]),element))
    return min(candidates,key=lambda item:item[:3])[3] if candidates else None


class SafeFontCombo(QComboBox):
    """Names use the UI font, so opening the list never renders bitmap fonts."""
    currentFontChanged=Signal(QFont)
    def __init__(self,parent=None):
        super().__init__(parent);self.document_fonts=();self.setMaxVisibleItems(20)
        self.view().setMinimumWidth(260)
        self.set_document_fonts(())
        self.currentIndexChanged.connect(lambda _index:self.currentFontChanged.emit(self.currentFont()))
    def currentFont(self):return QFont(safe_font_family(self.currentData() or self.currentText()))
    def setCurrentFont(self,font):
        index=self.findData(safe_font_family(font.family()))
        if index>=0:self.setCurrentIndex(index)
    def set_document_fonts(self,names):
        self.document_fonts=tuple(dict.fromkeys(name for name in names if name))
        families=prioritized_font_families(self.document_fonts)
        if tuple(self.itemData(i) for i in range(self.count()))==families:return
        selected=self.currentData() or safe_font_family()
        blocked=self.blockSignals(True)
        try:
            self.clear()
            for family in families:
                label='맑은 고딕 (Malgun Gothic)' if family=='Malgun Gothic' else family
                self.addItem(label,family)
            index=self.findData(selected);self.setCurrentIndex(index if index>=0 else 0)
        finally:self.blockSignals(blocked)


def photo_navigation_package_selftest():
    """Check the actual navigation worker and the non-blocking photo notice."""
    import subprocess
    from types import SimpleNamespace
    from PIL import Image
    from PySide6.QtCore import QEventLoop
    with tempfile.TemporaryDirectory(prefix='viewer_photo_navigation_') as folder:
        root=Path(folder);photos=root/'photos';photos.mkdir()
        for name in ('1.JPG','2.png','10.JPEG'):Image.new('RGB',(24,18),'navy').save(photos/name)
        for path in (photos/'3.zip',photos/'4.cbz',photos/'5.pdf',photos/'6.txt',root/'photos.zip'):
            path.write_bytes(b'not an image; navigation must not import this file')
        (photos/'7').mkdir()
        expected=[{'previous':'','next':str(photos/'2.png')},
                  {'previous':str(photos/'1.JPG'),'next':str(photos/'10.JPEG')},
                  {'previous':str(photos/'2.png'),'next':''}]
        requests=[]
        for i,name in enumerate(('1.JPG','2.png','10.JPEG')):
            if neighboring_inputs(str(photos/name),True)!=expected[i]:raise ValueError('사진 파일 전용 탐색 실패')
            requests.append({'id':i,'op':'neighbors','path':str(photos/name),'payload':{'include_containers':True}})
        requests.append({'id':3,'op':'sibling','path':str(photos/'10.JPEG'),
                         'payload':{'include_containers':True,'direction':1}})
        executable,args=worker_launch('--pdf-worker')
        done=subprocess.run([executable,*args],input=''.join(json.dumps(r)+'\n' for r in requests).encode(),
            stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90,
            creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        rows=[json.loads(line) for line in done.stdout.splitlines() if line.startswith(b'{')]
        if done.returncode or len(rows)!=4 or not all(r.get('ok') for r in rows):
            raise ValueError('사진 탐색 작업 프로세스 검사 실패: '+str(rows))
        if [r['neighbors'] for r in rows[:3]]!=expected or rows[-1]['path']!='':
            raise ValueError('작업 프로세스가 사진 외 항목을 선택했습니다.')
        host=QWidget();host.resize(640,360);notice=NavigationNotice(host)
        editor=SimpleNamespace(view=SimpleNamespace(viewport=lambda:host),dual_secondary=False,
            page=SimpleNamespace(path=image_source_path(photos/'2.png')),
            owner=SimpleNamespace(navigation_context=lambda:(str(photos),True,None)))
        overlay=EndOfContainerOverlay(editor)
        try:
            host.show();overlay.sync()
            if not overlay.isHidden():raise ValueError('사진 위에 폴더 전환 창이 표시됩니다.')
            notice.show_message('더 이상 읽을 파일이 없습니다.')
            if notice.isHidden() or not notice.testAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents):
                raise ValueError('하단 안내의 비차단 표시 실패')
            if notice.height()>40 or notice.y()<host.height()-90:
                raise ValueError('하단 안내가 사진 중앙을 가립니다.')
            loop=QEventLoop();QTimer.singleShot(2100,loop.quit);loop.exec()
            if not notice.isHidden():raise ValueError('하단 안내가 자동으로 사라지지 않습니다.')
        finally:
            host.close();host.deleteLater();QApplication.sendPostedEvents(None,QEvent.Type.DeferredDelete)
    return {'photo_only_natural_order':True,'real_worker_excludes_archives_and_documents':True,
            'last_photo_has_no_next_import':True,'photo_transition_panel_hidden':True,
            'bottom_notice_click_through_and_auto_hide':True}


def short_text_edit_package_selftest():
    """Generated digits with misleading StemV must retain their real font style."""
    from types import SimpleNamespace
    import reportlab
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.pdfgen import canvas
    from pypdf import PdfReader,PdfWriter
    from pypdf.generic import NameObject,NumberObject
    from PySide6.QtGui import QKeyEvent
    import subprocess
    with tempfile.TemporaryDirectory(prefix='viewer_short_text_') as folder:
        work=Path(folder);fontdir=Path(reportlab.__file__).parent/'fonts'
        pdfmetrics.registerFont(TTFont('ViewerCheckRegular',str(fontdir/'Vera.ttf')))
        pdfmetrics.registerFont(TTFont('ViewerCheckBold',str(fontdir/'VeraBd.ttf')))
        source=work/'digits.pdf';c=canvas.Canvas(str(source),pagesize=(400,300))
        c.setFont('ViewerCheckRegular',8);c.drawString(60,220,'7');c.drawString(100,220,'12')
        c.setFont('ViewerCheckBold',8);c.drawString(140,220,'34');c.save()
        writer=PdfWriter(clone_from=PdfReader(str(source)))
        for obj in writer.pages[0]['/Resources']['/Font'].values():
            font=obj.get_object();descriptor=font.get('/FontDescriptor')
            if descriptor:descriptor.get_object()[NameObject('/StemV')]=NumberObject(20 if 'Bold' in str(font.get('/BaseFont')) else 140)
        source=work/'misleading-weight.pdf'
        with source.open('wb') as output:writer.write(output)
        info=inspect_edit_page(str(source),0);styles={span['text']:span['bold'] for span in info['spans']}
        if styles.get('7') is not False or styles.get('12') is not False or styles.get('34') is not True:
            raise ValueError('원본 보통/굵은 글꼴의 굵기 상태를 유지하지 못했습니다: '+str(styles))
        executable,args=worker_launch('--pdf-worker')
        request={'id':44,'op':'editinfo','path':str(source),'page':0,'payload':{'images':False}}
        done=subprocess.run([executable,*args],input=(json.dumps(request)+'\n').encode(),stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE,timeout=90,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        rows=[json.loads(line) for line in done.stdout.splitlines() if line.startswith(b'{')]
        if done.returncode or not rows or not rows[-1].get('ok'):raise ValueError('숫자 글꼴 작업 프로세스 검사 실패: '+str(rows[-1:]))
        remote={span['text']:span['bold'] for span in rows[-1]['info']['spans']}
        if remote!=styles:raise ValueError('작업 프로세스의 원본 굵기 정보가 다릅니다.')
    digits=[{'text':'7','rect':[10,10,14,18]},{'text':'12','rect':[22,10,32,18]}]
    if nearest_text_hit(digits,[16,14],6) is not digits[0] or nearest_text_hit(digits,[21,14],6) is not digits[1]:
        raise ValueError('작은 숫자 주변 선택 검사 실패')
    if nearest_text_hit(digits,[60,60],6) is not None:raise ValueError('멀리 떨어진 숫자를 선택했습니다.')
    host=QWidget();inline=QTextEdit(host);field=QuickTextInput(host);events=[];applied=[]
    fake=SimpleNamespace(inline_text=inline,quick_text_edit=field,selected_text={'text':'7'},
                         ready=lambda:True,format_commit=None)
    inline.setPlainText('7');PreviewDialog.sync_quick_text(fake)
    field.textEdited.connect(lambda value:PreviewDialog.quick_text_changed(fake,value))
    inline.textChanged.connect(lambda:PreviewDialog.sync_quick_text(fake))
    inline.textChanged.connect(lambda:events.append(inline.toPlainText()))
    field.applyRequested.connect(lambda:applied.append(field.text()))
    try:
        field.selectAll()
        QApplication.sendEvent(field,QKeyEvent(QEvent.Type.KeyPress,Qt.Key.Key_9,Qt.KeyboardModifier.NoModifier,'9'))
        if field.text()!='9' or inline.toPlainText()!='9' or events!=['9']:
            raise ValueError('큰 숫자 입력칸과 문서 편집 내용의 동기화 실패')
        QApplication.sendEvent(field,QKeyEvent(QEvent.Type.KeyPress,Qt.Key.Key_Left,Qt.KeyboardModifier.NoModifier))
        QApplication.sendEvent(field,QKeyEvent(QEvent.Type.KeyPress,Qt.Key.Key_Right,Qt.KeyboardModifier.ShiftModifier))
        if field.selectedText()!='9':raise ValueError('숫자 입력칸의 키보드 선택 실패')
        QApplication.sendEvent(field,QKeyEvent(QEvent.Type.KeyPress,Qt.Key.Key_Return,Qt.KeyboardModifier.NoModifier))
        if applied!=['9']:raise ValueError('숫자 입력칸 Enter 적용 검사 실패')
    finally:
        host.deleteLater();QApplication.sendPostedEvents(None,QEvent.Type.DeferredDelete)
    return {'short_digit_hit_padding':True,'large_input_and_inline_text_synced':True,'keyboard_select_and_enter_apply':True,
            'regular_font_not_auto_bold':True,'real_bold_face_preserved':True,'worker_font_style_matches':True}


def type3_edit_package_selftest():
    """Round-trip generated Type3 PDFs without replacing untouched font programs."""
    from collections import Counter
    import hashlib
    from PIL import Image,ImageChops,ImageDraw
    from pypdf import PdfReader,PdfWriter
    from pypdf.generic import (DictionaryObject as D,NameObject as N,NumberObject as I,
                               FloatObject as F,ArrayObject as A,DecodedStreamObject as S)
    import viewer_pdf_engine as engine
    import viewer_pdf_edit as editing

    def sample(path,matrix,indirect=True,coloured=False):
        writer=PdfWriter();page=writer.add_blank_page(width=400,height=300)
        def stream(data):
            obj=S();obj.set_data(data);return writer._add_object(obj)
        metrics=[(32,250),(65,651),(66,713),(67,577),(68,809)]
        widths=[0]*37;procs=D()
        for code,width in metrics:
            widths[code-32]=width
            head=f'{width} 0 '+('d0' if coloured else '0 0 520 700 d1')+'\n'
            colour='0.1 0.35 0.7 rg\n' if coloured else ''
            body='' if code==32 else f'{colour}40 20 {280+(code-65)*55} 640 re f\n80 280 100 80 re f\n'
            procs[N('/g'+str(code))]=stream((head+body).encode('ascii'))
        encoding=D({N('/Type'):N('/Encoding'),N('/Differences'):A([
            I(32),N('/g32'),I(65),N('/g65'),N('/g66'),N('/g67'),N('/g68')])})
        cmap=(b'/CIDInit /ProcSet findresource begin\n12 dict begin\nbegincmap\n'
              b'/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def\n'
              b'/CMapName /Type3Unicode def\n/CMapType 2 def\n'
              b'1 begincodespacerange\n<00> <FF>\nendcodespacerange\n'
              b'5 beginbfchar\n<20> <0020>\n<41> <AC00>\n<42> <B098>\n'
              b'<43> <B2E4>\n<44> <B77C>\nendbfchar\nendcmap\n'
              b'CMapName currentdict /CMap defineresource pop\nend\nend\n')
        values=A([I(v) for v in widths])
        font=D({N('/Type'):N('/Font'),N('/Subtype'):N('/Type3'),N('/Name'):N('/F3'),
                N('/FontBBox'):A([I(0),I(0),I(850),I(700)]),
                N('/FontMatrix'):A([F(v) for v in matrix]),N('/CharProcs'):procs,
                N('/Encoding'):encoding,N('/FirstChar'):I(32),N('/LastChar'):I(68),
                N('/Widths'):writer._add_object(values) if indirect else values,
                N('/Resources'):D(),N('/ToUnicode'):stream(cmap)})
        normal=D({N('/Type'):N('/Font'),N('/Subtype'):N('/Type1'),
                  N('/BaseFont'):N('/Helvetica'),N('/Encoding'):N('/WinAnsiEncoding')})
        page[N('/Resources')]=D({N('/Font'):D({N('/F3'):writer._add_object(font),N('/F1'):writer._add_object(normal)})})
        page[N('/Contents')]=stream(
            b'q .2 .2 .2 RG .5 w 20 20 360 250 re S Q\n'
            b'BT /F1 14 Tf 1 0 0 1 40 240 Tm (NORMAL SAMPLE) Tj ET\n'
            b'BT /F3 22 Tf 0.4 Tc 1.1 Tw 85 Tz 44 TL 1 0 0 1 40 180 Tm '
            b'[<41> -137 <42> 83 <43> <20> <44>] TJ <4142> Tj T* <4344> Tj ET\n'
            b'BT /F1 12 Tf 1 0 0 1 40 65 Tm (AFTER TYPE3) Tj ET\n')
        with path.open('wb') as output:writer.write(output)
        return path.read_bytes()

    def chars(data):
        with engine.open(stream=data,filetype='pdf') as doc:
            return [{'text':g['c'],'rect':list(g['bbox']),'origin':list(g['origin'])}
                    for g in doc[0]._characters() if g.get('c','').strip()]

    def pixels(data):
        with engine.open(stream=data,filetype='pdf') as doc:
            pix=doc[0].get_pixmap(matrix=engine.Matrix(2,2),alpha=False)
            return Image.frombytes('RGB',(pix.width,pix.height),pix.samples)

    def survivors(before,after,selected,movement=None):
        remaining=list(after)
        for old in before:
            if old is selected and movement is None:continue
            dx,dy=movement if old is selected else (0.,0.)
            point=(old['origin'][0]+dx,old['origin'][1]+dy)
            bounds=[v+(dx if i%2==0 else dy) for i,v in enumerate(old['rect'])]
            matches=[i for i,new in enumerate(remaining) if new['text']==old['text']
                     and math.dist(point,new['origin'])<.003
                     and max(abs(a-b) for a,b in zip(bounds,new['rect']))<.003]
            if len(matches)!=1:raise ValueError('Type3 편집 후 선택 밖 글자의 위치·모양이 달라졌습니다.')
            remaining.pop(matches[0])
        return remaining

    def outside_pixels(before,after,areas):
        difference=ImageChops.difference(pixels(before),pixels(after));draw=ImageDraw.Draw(difference)
        for box in areas:
            draw.rectangle((math.floor(box[0]*2)-3,math.floor(box[1]*2)-3,
                            math.ceil(box[2]*2)+3,math.ceil(box[3]*2)+3),fill=(0,0,0))
        if difference.getbbox() is not None:
            raise ValueError('Type3 편집 영역 밖의 그림·글자 픽셀이 달라졌습니다.')

    def original_font(before,after):
        fonts=[]
        for data in (before,after):
            font=PdfReader(io.BytesIO(data)).pages[0]['/Resources']['/Font']['/F3']
            if font['/Subtype']!='/Type3':raise ValueError('원본 Type3 글꼴이 교체되었습니다.')
            fonts.append({str(name):obj.get_object().get_data() for name,obj in font['/CharProcs'].items()})
        if fonts[0]!=fonts[1]:raise ValueError('선택 밖 글자의 원본 Type3 프로그램이 바뀌었습니다.')

    cases=[([.001,0,0,.001,0,0],True,False),([.002,0,0,.002,0,0],False,True),
           ([.00125,0,0,.00125,0,0],True,False),
           ([.00125,.0002,.0001,.0015,.02,-.01],True,True)]
    checks=0
    with tempfile.TemporaryDirectory(prefix='viewer_type3_check_') as folder:
        work=Path(folder)
        for index,(matrix,indirect,coloured) in enumerate(cases):
            path=work/f'type3-{index}.pdf';data=sample(path,matrix,indirect,coloured)
            before=chars(data);selected=next(g for g in before if g['text']=='나')
            for operation in ('move','delete'):
                with engine.open(path) as doc:
                    if operation=='move':
                        editing.move_text_objects(doc[0],selected['rect'],12.,5.,selected['text'],[selected])
                    else:
                        editing._edit_text_stream(doc[0],[engine.Rect(selected['rect'])],
                                                  expected_text=selected['text'],source_glyphs=[selected])
                    output=work/f'{index}-{operation}.pdf';doc.save(output)
                after=output.read_bytes();movement=(12.,5.) if operation=='move' else None
                if survivors(before,chars(after),selected,movement):raise ValueError('Type3 편집 후 예상하지 않은 글자가 생겼습니다.')
                areas=[selected['rect']]
                if movement:areas.append([v+(12. if i%2==0 else 5.) for i,v in enumerate(selected['rect'])])
                outside_pixels(data,after,areas);original_font(data,after);checks+=1
            if path.read_bytes()!=data:raise ValueError('편집 중 원본 PDF 파일이 바뀌었습니다.')

        path=work/'type3-0.pdf';data=path.read_bytes();before=chars(data)
        normal=next(g for g in before if g['text']=='N')
        with engine.open(path) as doc:
            editing.move_text_objects(doc[0],normal['rect'],7.,3.,normal['text'],[normal])
            after=doc.tobytes()
        if survivors(before,chars(after),normal,(7.,3.)):raise ValueError('일반 글자와 Type3 혼합 편집 실패')
        original_font(data,after);checks+=1
        selected=next(g for g in before if g['text']=='나')
        info=inspect_edit_page(str(path),0)
        glyph=next(g for span in info['spans'] for g in span['source_glyphs']
                   if g['text']=='나' and math.dist(g['origin'],selected['origin'])<.003)
        from PySide6.QtGui import QFontDatabase
        korean_fonts=[f for f in safe_font_families() if QFontDatabase.WritingSystem.Korean in QFontDatabase.writingSystems(f)]
        replacements=('EDIT','수정') if korean_fonts else ('EDIT',)
        for index,text in enumerate(replacements):
            target=[240.,210.,350.,235.]
            output=work/f'replaced-{index}.pdf'
            apply_page_edit(str(path),0,{'kind':'format','rect':glyph['rect'],
                'old_text':glyph['text'],'text':text,'source_glyphs':[glyph],'target':target,
                'font':safe_font_family('맑은 고딕') if text.isascii() or not korean_fonts else korean_fonts[0],'size':12.,'bold':False,'color':'#224466','rotate':0,'align':'left'},str(output))
            after=output.read_bytes()
            added=survivors(before,chars(after),selected)
            if Counter(g['text'] for g in added)!=Counter(text):raise ValueError('Type3 글자 교체 결과가 다릅니다: '+repr(text)+' / '+repr(Counter(g['text'] for g in added)))
            outside_pixels(data,after,[selected['rect'],target]);original_font(data,after);checks+=1
        import subprocess
        output=work/'worker-replaced.pdf'
        operation={'kind':'format','rect':glyph['rect'],'old_text':glyph['text'],'text':'EDIT',
                   'source_glyphs':[glyph],'target':[240.,210.,350.,235.],
                   'font':safe_font_family(),'size':12.,'bold':False,'color':'#224466','rotate':0,'align':'left'}
        executable,args=worker_launch('--pdf-worker')
        request={'id':43,'op':'edit','path':str(path),'page':0,
                 'payload':{'operation':operation,'output':str(output)}}
        done=subprocess.run([executable,*args],input=(json.dumps(request)+'\n').encode('utf-8'),
                            stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90,
                            creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        rows=[json.loads(line) for line in done.stdout.splitlines() if line.startswith(b'{')]
        if done.returncode or not rows or not rows[-1].get('ok') or not output.is_file():
            raise ValueError('Type3 실제 편집 작업 프로세스 실패: '+str(rows[-1:] or done.stderr.decode('utf-8','replace')[-1000:]))
        after=output.read_bytes();added=survivors(before,chars(after),selected)
        if Counter(g['text'] for g in added)!=Counter('EDIT'):raise ValueError('Type3 편집 작업 프로세스 교체 결과 불일치')
        outside_pixels(data,after,[selected['rect'],operation['target']]);original_font(data,after);checks+=1
        with engine.open(path) as doc:
            original=doc[0]._pdfpage.get_contents().get_data()
            try:
                editing.move_text_objects(doc[0],selected['rect'],12.,5.,'다른 글자',[selected])
            except ValueError:pass
            else:raise ValueError('바뀐 글자 선택을 거부하지 않았습니다.')
            if doc[0]._pdfpage.get_contents().get_data()!=original:raise ValueError('실패한 편집이 문서를 바꿨습니다.')
        if hashlib.sha256(path.read_bytes()).digest()!=hashlib.sha256(data).digest():raise ValueError('원본 파일 보존 실패')
        checks+=1
    return {'generated_type3_cases':len(cases),'move_delete_replace_and_guard_checks':checks,
            'korean_unicode_and_mixed_fonts':True,'korean_replacement_checked':bool(korean_fonts),'saved_roundtrip':True,
            'outside_glyph_positions_and_pixels_preserved':True,'original_type3_programs_preserved':True,
            'source_pdf_unchanged':True,'actual_edit_worker_roundtrip':True}


def editing_ui_package_selftest():
    """Exercise the edit toolbar and font choices using temporary preferences only."""
    from types import SimpleNamespace
    families=('Arial','Batang','Malgun Gothic','Noto Sans KR')
    if installed_font_family('ABCDEF+MalgunGothicBold',families)!='Malgun Gothic':
        raise ValueError('PDF 부분 글꼴 이름과 맑은 고딕 연결 실패')
    if prioritized_font_families(('ABCDEF+Batang','없는 글꼴'),families)[:2]!=('Batang','Malgun Gothic'):
        raise ValueError('문서 사용 글꼴 우선 정렬 실패')
    combo=SafeFontCombo();bars=[];host=QWidget();host.resize(640,100)
    try:
        available=safe_font_families()
        if not available:raise ValueError('사용할 수 있는 설치 글꼴이 없습니다.')
        chosen=available[-1];combo.setCurrentFont(QFont(chosen));before=combo.currentFont().family();signals=[]
        combo.currentFontChanged.connect(lambda _font:signals.append(True))
        combo.set_document_fonts((chosen,))
        if combo.itemData(0)!=installed_font_family(chosen) or combo.currentFont().family()!=before or signals:
            raise ValueError('글꼴 목록 정렬이 선택 글꼴을 바꾸거나 서식 변경 신호를 보냈습니다.')
        with tempfile.TemporaryDirectory(prefix='viewer_edit_ui_') as folder:
            settings=QSettings(str(Path(folder)/'settings.ini'),QSettings.Format.IniFormat)
            keys=SimpleNamespace(bindings={name:[] for name in ('clear','save','print','translate','hangul','options')},describe=lambda _name:'')
            owner=SimpleNamespace(settings=settings,keys=keys,preview_dialog=None)
            host.owner=owner;host.page=SimpleNamespace(is_text_document=False,is_document_card=False)
            host.mode='pan';host.set_mode=lambda mode:setattr(host,'mode',mode)
            host.toggle_document_edit=lambda:PreviewDialog.toggle_document_edit(host)
            noop=lambda:None
            bar=CornerActions(host,host,noop,noop,noop,noop,noop,print_document=noop);bars.append(bar)
            if not bar.translate_button.isHidden() or not bar.hangul_button.isHidden():
                raise ValueError('한글·번역 버튼이 기본으로 숨겨지지 않았습니다.')
            width=bar.width()
            if bar.edit_button.icon().isNull() or not bar.edit_button.isEnabled():
                raise ValueError('문서·연필 편집 버튼을 사용할 수 없습니다.')
            bar.edit_button.click()
            if host.mode!='edit' or not bar.edit_button.isChecked():raise ValueError('편집 버튼 진입 상태 불일치')
            bar.edit_button.click()
            if host.mode!='pan' or bar.edit_button.isChecked():raise ValueError('편집 버튼 해제 상태 불일치')
            Window.set_toolbar_button_visible(owner,'translate',True)
            if bar.translate_button.isHidden() or not bar.hangul_button.isHidden() or bar.width()<=width:
                raise ValueError('번역 버튼 표시 설정 또는 도구 모음 너비 갱신 실패')
            restored=CornerActions(host,host,noop,noop,noop,noop,noop,print_document=noop);bars.append(restored)
            if restored.translate_button.isHidden() or not restored.hangul_button.isHidden():
                raise ValueError('새 도구 모음에서 버튼 표시 설정을 복원하지 못했습니다.')
            Window.set_toolbar_button_visible(owner,'hangul',True)
            Window.set_toolbar_button_visible(owner,'translate',False)
            if any(not b.translate_button.isHidden() or b.hangul_button.isHidden() for b in bars):
                raise ValueError('열려 있는 도구 모음의 독립 표시 설정 동기화 실패')
            settings.sync()
        return {'document_fonts_first':True,'malgun_alias_and_pdf_subset':True,
                'font_selection_preserved_without_edit_signal':True,'edit_button_toggle':True,
                'conversion_buttons_default_hidden':True,'preferences_restored_and_synced':True}
    finally:
        combo.deleteLater();host.deleteLater()
        QApplication.sendPostedEvents(None,QEvent.Type.DeferredDelete)


class PageNumberDesignDialog(QDialog):
    def __init__(self,parent,options):
        super().__init__(parent);self.options=dict(options)
        self.setWindowTitle('쪽번호 디자인');self.setMinimumWidth(370)
        layout=QVBoxLayout(self);form=QFormLayout();layout.addLayout(form)
        self.font_box=SafeFontCombo();self.font_box.setCurrentFont(QFont(options['font']))
        self.size=QDoubleSpinBox();self.size.setRange(4,144);self.size.setDecimals(2)
        self.size.setSuffix(' pt');self.size.setValue(options['size'])
        self.bold=QCheckBox('굵게');self.bold.setChecked(options['bold'])
        self.prefix=QLineEdit(options['prefix']);self.suffix=QLineEdit(options['suffix'])
        for edit in (self.prefix,self.suffix):edit.setMaxLength(40)
        self.prefix.setPlaceholderText('예: ( 또는 - ');self.suffix.setPlaceholderText('예: ) 또는 -')
        self.start=QSpinBox();self.start.setRange(0,999999);self.start.setValue(options['start'])
        self.digits=QComboBox();self.digits.addItems(['1','01','001','0001','00001','000001'])
        self.digits.setCurrentIndex(options['digits']-1)
        self.color=QColor(options['color']);self.color_button=QPushButton('글자 색상')
        self.color_button.clicked.connect(self.pick_color)
        for label,widget in [('글자체',self.font_box),('크기',self.size),('',self.bold),
                ('숫자 · 시작 번호',self.start),('숫자 · 자릿수',self.digits),
                ('왼쪽 디자인',self.prefix),('오른쪽 디자인',self.suffix),('',self.color_button)]:
            form.addRow(label,widget)
        self.sample=QLabel();self.sample.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.sample.setMinimumHeight(80);self.sample.setWordWrap(True);layout.addWidget(self.sample)
        buttons=QDialogButtonBox(QDialogButtonBox.StandardButton.Ok|QDialogButtonBox.StandardButton.Cancel)
        buttons.button(QDialogButtonBox.StandardButton.Ok).setText('적용')
        buttons.button(QDialogButtonBox.StandardButton.Cancel).setText('취소')
        buttons.accepted.connect(self.accept);buttons.rejected.connect(self.reject);layout.addWidget(buttons)
        for signal in (self.font_box.currentFontChanged,self.size.valueChanged,self.bold.toggled,
                self.start.valueChanged,self.digits.currentIndexChanged,self.prefix.textChanged,self.suffix.textChanged):
            signal.connect(self.update_sample)
        self.update_sample()

    def values(self):
        return page_number_options({**self.options,'font':self.font_box.currentFont().family(),
            'size':self.size.value(),'bold':self.bold.isChecked(),'start':self.start.value(),
            'digits':self.digits.currentIndex()+1,'prefix':self.prefix.text(),'suffix':self.suffix.text(),
            'color':self.color.name()})

    def update_sample(self,*_args):
        values=self.values();font=QFont(values['font']);font.setPointSizeF(values['size']);font.setBold(values['bold'])
        self.sample.setFont(font);self.sample.setText(values['prefix']+str(values['start']).zfill(values['digits'])+values['suffix'])
        self.sample.setStyleSheet('background:white;color:'+values['color']+';border:1px solid #8793a5;padding:8px;')

    def pick_color(self):
        color=QColorDialog.getColor(self.color,self,'쪽번호 색상')
        if color.isValid():self.color=color;self.update_sample()


class PageNumberSession(QObject):
    def __init__(self,owner,editor,targets,options):
        super().__init__(editor);self.owner=owner;self.editor=editor;self.targets=list(targets)
        self.options=page_number_options(options);self.active=True;self.busy=False;self.dragging=False
        self.record=None;self.documents=[];self.measure_key=();self.preview_error=''
        self.top=QWidget(editor);self.right=QWidget(editor)
        style=('QWidget{background:#253044;color:#e5edf7;font-size:11px;} '
            'QDoubleSpinBox{background:#182130;color:#e5edf7;border:1px solid #65758e;padding:1px 2px;} '
            'QPushButton,QToolButton{background:#36435a;color:#fff;border:1px solid #65758e;border-radius:3px;padding:3px;} '
            'QPushButton:hover,QToolButton:hover{background:#704357;} '
            'QSlider::groove:horizontal{height:3px;background:#48566d;border-radius:1px;margin:0 4px;} '
            'QSlider::handle:horizontal{width:10px;margin:-4px 0;background:#a9bdd2;border:1px solid #d3dfeb;border-radius:3px;} '
            'QSlider::sub-page:horizontal{background:#52a7d7;} '
            'QSlider::groove:vertical{width:3px;background:#48566d;border-radius:1px;margin:4px 0;} '
            'QSlider::handle:vertical{height:10px;margin:0 -4px;background:#a9bdd2;border:1px solid #d3dfeb;border-radius:3px;} '
            'QSlider::sub-page:vertical{background:#52a7d7;}')
        self.top.setStyleSheet(style);self.right.setStyleSheet(style)
        self.right.setFixedWidth(80)
        top_layout=QVBoxLayout(self.top);top_layout.setContentsMargins(4,3,4,3);top_layout.setSpacing(2)
        row=QHBoxLayout();top_layout.addLayout(row);row.setSpacing(3)
        row.addWidget(QLabel('가로 X',self.top));self.x=QDoubleSpinBox(self.top);row.addWidget(self.x)
        self.center_button=QToolButton(self.top);self.center_button.setText('50%');self.center_button.setFixedSize(38,22)
        self.center_button.setToolTip('가로 위치를 50% 가운데로 맞춤 · 세로 위치는 유지')
        self.center_button.clicked.connect(lambda:self.set_coordinate('x',50.))
        row.addWidget(self.center_button)
        self.x_slider=QSlider(Qt.Orientation.Horizontal,self.top)
        self.x_slider.setRange(0,10000);self.x_slider.setSingleStep(10);self.x_slider.setPageStep(100)
        self.x_slider.setFixedHeight(20);self.x_slider.setMinimumWidth(0)
        self.x_slider.setSizePolicy(QSizePolicy.Policy.Ignored,QSizePolicy.Policy.Fixed)
        row.addWidget(QLabel('0'));row.addWidget(self.x_slider,1);row.addWidget(QLabel('100'))
        row=QHBoxLayout();top_layout.addLayout(row);row.setSpacing(4)
        self.caption=QLabel(f'선택한 {len(targets)}쪽 · 선택 순서대로',self.top)
        self.caption.setWordWrap(True);self.caption.setMinimumWidth(0);row.addWidget(self.caption,1)
        self.design=QPushButton('쪽번호 디자인',self.top);self.design.clicked.connect(self.design_clicked)
        self.apply_button=QPushButton('삽입',self.top);self.apply_button.clicked.connect(self.apply)
        self.cancel_button=QToolButton(self.top);self.cancel_button.setText('취소');self.cancel_button.clicked.connect(self.cancel)
        for widget in (self.design,self.apply_button,self.cancel_button):row.addWidget(widget)
        right_layout=QVBoxLayout(self.right);right_layout.setContentsMargins(4,4,4,4);right_layout.setSpacing(3)
        right_layout.addWidget(QLabel('세로 Y',self.right),0,Qt.AlignmentFlag.AlignHCenter)
        self.y=QDoubleSpinBox(self.right);right_layout.addWidget(self.y)
        right_layout.addWidget(QLabel('0 · 위',self.right),0,Qt.AlignmentFlag.AlignHCenter)
        self.y_slider=QSlider(Qt.Orientation.Vertical,self.right);self.y_slider.setInvertedAppearance(True)
        self.y_slider.setRange(0,10000);self.y_slider.setSingleStep(10);self.y_slider.setPageStep(100)
        self.y_slider.setFixedWidth(20);self.y_slider.setMinimumHeight(0)
        self.y_slider.setSizePolicy(QSizePolicy.Policy.Fixed,QSizePolicy.Policy.Ignored)
        right_layout.addWidget(self.y_slider,1,Qt.AlignmentFlag.AlignHCenter)
        right_layout.addWidget(QLabel('100 · 아래',self.right),0,Qt.AlignmentFlag.AlignHCenter)
        for name,spin,slider in [('x',self.x,self.x_slider),('y',self.y,self.y_slider)]:
            spin.setRange(0,100);spin.setDecimals(2);spin.setSingleStep(.1);spin.setSuffix(' %');spin.setFixedSize(72,22)
            spin.setToolTip('번호 중심 위치 · 50은 가운데 · 가장자리에서는 글자가 페이지 안에 놓입니다.')
            spin.setValue(self.options[name]);slider.setValue(round(self.options[name]*100))
            spin.valueChanged.connect(lambda value,n=name:self.set_coordinate(n,value))
            slider.valueChanged.connect(lambda value,n=name:self.set_coordinate(n,value/100))
        editor.main_layout.insertWidget(editor.main_layout.indexOf(editor.view_container),self.top)
        editor.view_row.addWidget(self.right)
        editor.nav_previous.setEnabled(False);editor.nav_next.setEnabled(False)
        editor.view.viewport().setCursor(Qt.CursorShape.SizeAllCursor)
        QApplication.instance().installEventFilter(self)
        self.top.show();self.right.show();self.refresh();owner.update_preview_zoom(editor)

    def set_coordinate(self,name,value):
        if not self.active or self.busy:return
        self.options[name]=round(max(0.,min(100.,float(value))),2)
        spin,slider=(self.x,self.x_slider) if name=='x' else (self.y,self.y_slider)
        for widget,number in ((spin,self.options[name]),(slider,round(self.options[name]*100))):
            previous=widget.blockSignals(True);widget.setValue(number);widget.blockSignals(previous)
        self.refresh()

    def refresh(self):
        from PySide6.QtGui import QTextDocument
        if not self.active:return
        info=self.editor.info
        key=(json.dumps(self.options,sort_keys=True),info['width'],info['height']) if info else None
        if key==self.measure_key:return
        self.measure_key=key;self.record=None;self.documents=[];self.preview_error=''
        if info:
            try:
                record=page_number_record(self.options,0,info['width'],info['height'])
                self.paint_device=QImage(1,1,QImage.Format.Format_RGB32)
                self.paint_device.setDotsPerMeterX(round(720/.0254));self.paint_device.setDotsPerMeterY(round(720/.0254))
                for part in page_number_layout(record)['parts']:
                    content,css=editor_text_content({**record,'text':part['text']})
                    document=QTextDocument();document.documentLayout().setPaintDevice(self.paint_device)
                    document.setDocumentMargin(0);document.setDefaultStyleSheet(css);document.setHtml(content)
                    document.setTextWidth((part['width']+1)*10)
                    self.documents.append((part,document))
                self.record=record
            except ValueError as error:self.preview_error=str(error)
        self.apply_button.setEnabled(self.record is not None and not self.busy)
        self.caption.setText(self.preview_error or f'선택한 {len(self.targets)}쪽 · 선택 순서대로')
        self.editor.view.viewport().update()
        self.owner.canvas.viewport().update()

    def paint(self,painter):
        self.refresh()
        if not self.record:return
        view=self.editor.view;box=view.scene_box(self.record['rect']);frame=view.page_rect;center=box.center()
        painter.save();pen=QPen(QColor('#d54468'),1,Qt.PenStyle.DashLine);pen.setCosmetic(True)
        painter.setPen(pen);painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawLine(QPointF(frame.left(),center.y()),QPointF(frame.right(),center.y()))
        painter.drawLine(QPointF(center.x(),frame.top()),QPointF(center.x(),frame.bottom()))
        painter.drawRect(box);painter.translate(box.topLeft())
        scale=frame.width()/self.editor.info['width']/10;painter.scale(scale,scale)
        for part,document in self.documents:
            painter.save();painter.translate(part['x']*10,part['y']*10)
            document.drawContents(painter,QRectF(0,0,(part['width']+1)*10,(part['height']+.5)*10));painter.restore()
        painter.restore()

    def place(self,position):
        view=self.editor.view
        if view.item is None or not self.editor.info:return False
        point=view.mapToScene(position)
        x=max(0.,min(100.,(point.x()-view.page_rect.left())/view.page_rect.width()*100))
        y=max(0.,min(100.,(point.y()-view.page_rect.top())/view.page_rect.height()*100))
        self.set_coordinate('x',x);self.set_coordinate('y',y);return True

    def eventFilter(self,obj,event):
        if not self.active:return False
        if (event.type()==QEvent.Type.KeyPress and event.key()==Qt.Key.Key_Escape and
                isinstance(obj,QWidget) and (obj is self.owner or self.owner.isAncestorOf(obj)) and
                QApplication.activeModalWidget() is None):
            if not self.busy:self.cancel()
            event.accept();return True
        if obj is not self.editor.view.viewport():return False
        if event.type() in (QEvent.Type.ContextMenu,QEvent.Type.MouseButtonDblClick):event.accept();return True
        if event.type()==QEvent.Type.MouseButtonPress and event.button()==Qt.MouseButton.LeftButton:
            if not self.busy:
                self.editor.view.setFocus();self.dragging=self.place(event.position().toPoint())
            event.accept();return True
        if event.type()==QEvent.Type.MouseMove and self.dragging:
            if not self.busy:self.place(event.position().toPoint())
            event.accept();return True
        if event.type()==QEvent.Type.MouseButtonRelease and self.dragging:
            if not self.busy:self.place(event.position().toPoint())
            self.dragging=False;event.accept();return True
        return False

    def design_clicked(self):
        if self.busy:return
        dialog=PageNumberDesignDialog(self.editor,self.options)
        if dialog.exec()==QDialog.DialogCode.Accepted:
            self.options=dialog.values();self.refresh()
        dialog.deleteLater()

    def apply(self):
        if not self.active or self.busy or self.record is None:return
        self.owner.start_page_batch('page_numbers',self.targets,options=dict(self.options))

    def set_busy(self,busy):
        self.busy=bool(busy);self.dragging=False
        self.top.setEnabled(not busy);self.right.setEnabled(not busy)
        self.caption.setText('쪽번호를 삽입하는 중…' if busy else self.preview_error or f'선택한 {len(self.targets)}쪽 · 선택 순서대로')

    def cancel(self):
        if not self.busy:self.close()

    def close(self):
        if not self.active:return
        self.active=False;self.dragging=False;QApplication.instance().removeEventFilter(self)
        if self.owner.page_number_session is self:self.owner.page_number_session=None
        self.owner.settings.setValue('page_numbers/options',json.dumps(self.options,ensure_ascii=False))
        self.editor.main_layout.removeWidget(self.top);self.editor.view_row.removeWidget(self.right)
        self.top.hide();self.right.hide();self.top.deleteLater();self.right.deleteLater()
        self.editor.nav_previous.setEnabled(True);self.editor.nav_next.setEnabled(True)
        self.editor.set_mode('pan');self.editor.view.viewport().update()
        self.owner.update_preview_zoom(self.editor);self.owner.update_action_states()
        self.owner.canvas.viewport().update();self.deleteLater()


class TextEditDialog(QDialog):
    def __init__(self, parent, sample=None, title='글자 넣기'):
        super().__init__(parent)
        sample = sample or {}
        self.setWindowTitle(title); self.resize(460, 360)
        layout = QVBoxLayout(self)
        self.text = QPlainTextEdit(sample.get('text', ''))
        self.text.setPlaceholderText('내용 입력'); layout.addWidget(self.text)
        form = QFormLayout(); layout.addLayout(form)
        self.size = QDoubleSpinBox(); self.size.setRange(4, 144)
        self.size.setDecimals(1); self.size.setValue(sample.get('size', 11)); self.size.setSuffix(' pt')
        self.font = SafeFontCombo()
        self.font.setCurrentFont(QFont(sample.get('font','sans-serif')))
        self.align = QComboBox()
        for label, value in [('왼쪽', 'left'), ('가운데', 'center'), ('오른쪽', 'right')]:
            self.align.addItem(label, value)
        self.bold = QCheckBox('굵게'); self.bold.setChecked(sample.get('bold', False))
        self.color = QColor(sample.get('color', '#111111'))
        self.palette=ColorStrip(self.color.name());self.palette.colorChanged.connect(self.set_color)
        form.addRow('크기', self.size); form.addRow('글꼴', self.font)
        form.addRow('정렬', self.align); form.addRow('색상', self.palette)
        form.addRow(self.bold)
        hint = QLabel('글자 크기는 유지하고, 상자 폭에 맞춰 줄바꿈합니다.\n추가한 뒤 테두리와 손잡이로 위치·크기를 조절할 수 있습니다.')
        hint.setStyleSheet('color:#888;font-size:11px'); layout.addWidget(hint)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept); buttons.rejected.connect(self.reject); layout.addWidget(buttons)
        self.font.currentFontChanged.connect(self.update_preview)
        self.size.valueChanged.connect(self.update_preview);self.bold.toggled.connect(self.update_preview)
        self.update_preview()
        self.text.setFocus()

    def update_preview(self,*unused):
        font=self.font.currentFont();font.setPointSizeF(self.size.value());font.setBold(self.bold.isChecked())
        self.text.setFont(font);self.text.setStyleSheet('QPlainTextEdit{color:'+self.color.name()+';}')

    def set_color(self,color):
        self.color=QColor(color);self.update_preview()

    def operation(self):
        return {'text': self.text.toPlainText(), 'size': self.size.value(), 'font': self.font.currentFont().family(),
                'align': self.align.currentData(), 'color': self.color.name(), 'bold': self.bold.isChecked(),
                'white': False}


class TableEditDialog(QDialog):
    def __init__(self, parent):
        super().__init__(parent)
        self.setWindowTitle('표 넣기'); self.resize(600, 420)
        layout = QVBoxLayout(self); row = QHBoxLayout(); layout.addLayout(row)
        self.rows = QSpinBox(); self.rows.setRange(1, 30); self.rows.setValue(3)
        self.cols = QSpinBox(); self.cols.setRange(1, 15); self.cols.setValue(3)
        self.size = QDoubleSpinBox(); self.size.setRange(4, 72); self.size.setValue(11)
        for label, widget in [('행', self.rows), ('열', self.cols), ('글자 pt', self.size)]:
            row.addWidget(QLabel(label)); row.addWidget(widget)
        self.table = QTableWidget(3, 3)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        layout.addWidget(self.table)
        self.rows.valueChanged.connect(self.table.setRowCount)
        self.cols.valueChanged.connect(self.table.setColumnCount)
        self.white = QCheckBox('기존 영역을 흰색으로 덮기'); self.white.setChecked(True)
        layout.addWidget(self.white)
        hint = QLabel('셀을 더블클릭해 입력 · Tab으로 다음 셀 · 빈 셀도 생성됩니다.')
        hint.setStyleSheet('color:#888'); layout.addWidget(hint)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept); buttons.rejected.connect(self.reject); layout.addWidget(buttons)

    def operation(self):
        self.table.clearFocus()  # 마지막 셀의 편집 내용을 먼저 반영
        values = [[self.table.item(r, c).text() if self.table.item(r, c) else ''
                   for c in range(self.cols.value())] for r in range(self.rows.value())]
        return {'values': values, 'size': self.size.value(), 'white': self.white.isChecked()}


class ImageGeometryDialog(QDialog):
    def __init__(self, parent, rect, keep_ratio=True):
        super().__init__(parent)
        self.setWindowTitle('그림 위치 / 크기')
        self.replacement_path=None
        self.ratio = (rect[2]-rect[0]) / max(0.01,rect[3]-rect[1])
        form = QFormLayout(self)
        self.fields = []
        for label,value in zip(('X','Y','너비','높이'),(rect[0],rect[1],rect[2]-rect[0],rect[3]-rect[1])):
            spin = QDoubleSpinBox(); spin.setDecimals(2); spin.setSuffix(' mm')
            spin.setRange(0 if len(self.fields)<2 else 0.71,10000); spin.setSingleStep(0.1)
            spin.setValue(value/PT_PER_MM); spin.setKeyboardTracking(False)
            form.addRow(label,spin); self.fields.append(spin)
        self.lock = QCheckBox('가로·세로 비율 유지'); self.lock.setChecked(keep_ratio)
        form.addRow(self.lock)
        self.fields[2].valueChanged.connect(lambda value:self.keep_ratio(2,value))
        self.fields[3].valueChanged.connect(lambda value:self.keep_ratio(3,value))
        self.replace_button=QPushButton('그림 교체…');self.replace_button.clicked.connect(self.pick_replacement);form.addRow(self.replace_button)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok|QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept); buttons.rejected.connect(self.reject); form.addRow(buttons)

    def pick_replacement(self):
        filename,_=QFileDialog.getOpenFileName(self,'그림 교체','','그림 (*.png *.jpg *.jpeg *.bmp *.tif *.tiff)')
        if filename:self.replacement_path=filename;self.replace_button.setText(Path(filename).name)

    def keep_ratio(self, field, value):
        if self.lock.isChecked():
            other = self.fields[3 if field == 2 else 2]
            other.blockSignals(True); other.setValue(value/self.ratio if field == 2 else value*self.ratio); other.blockSignals(False)

    def rectangle(self):
        x,y,w,h = [spin.value()*PT_PER_MM for spin in self.fields]
        return [x,y,x+w,y+h]


class ThumbnailToggle(QToolButton):
    """좁은 버튼에서도 글꼴에 따른 말줄임 없이 두 꺾쇠/더하기를 그린다."""
    def __init__(self,owner,parent):
        super().__init__(parent);self.owner=owner

    def paintEvent(self,event):
        super().paintEvent(event)
        painter=QPainter(self);painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        color='#fff' if self.underMouse() or self.isDown() else ('#c7cfdf' if self.owner.dark else '#4b5668')
        pen=QPen(QColor(color),1.25);pen.setCapStyle(Qt.PenCapStyle.RoundCap);pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        painter.setPen(pen)
        cx=self.width()/2;cy=self.height()/2
        if ((self.owner.dual_mode and not self.owner.thumbnail_host.picker_open) or self.owner.thumbnails_collapsed):
            painter.drawLine(QPointF(cx-4,cy),QPointF(cx+4,cy))
            painter.drawLine(QPointF(cx,cy-4),QPointF(cx,cy+4))
        else:
            for offset in (-2,2.5):
                path=QPainterPath(QPointF(cx+offset+2,cy-3.5))
                path.lineTo(cx+offset-1.5,cy);path.lineTo(cx+offset+2,cy+3.5)
                painter.drawPath(path)


class ThumbnailRail(QWidget):
    """내용·스크롤바 바깥의 18px 테두리. 접힌 상태에서도 같은 자리에 남는다."""
    def __init__(self,owner,parent):
        super().__init__(parent);self.owner=owner
        self.setFixedWidth(18)
        layout=QVBoxLayout(self);layout.setContentsMargins(1,0,0,0);layout.setSpacing(0)
        self.button=ThumbnailToggle(owner,self);self.button.setFixedSize(17,48)
        self.button.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.button.setCursor(Qt.CursorShape.PointingHandCursor)
        self.button.clicked.connect(owner.toggle_thumbnail_panel)
        layout.addStretch();layout.addWidget(self.button);layout.addStretch()
        self.sync()

    def sync(self):
        self.setVisible(not self.owner.book_focus)
        collapsed=(not self.owner.thumbnail_host.picker_open) if self.owner.dual_mode else self.owner.thumbnails_collapsed
        tip='썸네일 펼치기' if collapsed else '썸네일 접기'
        if self.owner.dual_mode:tip='오른쪽 비교 파일·쪽 선택' if collapsed else '오른쪽 비교 화면으로 돌아가기'
        self.button.setToolTip(tip);self.button.setAccessibleName(tip)
        dark=self.owner.dark
        background='#252b38' if dark else '#e4e8ee'
        border='#454e60' if dark else '#b6bfcc'
        self.button.setStyleSheet(
            f'QToolButton{{background:{background};border:1px solid {border};'
            'border-right:0;border-radius:3px;padding:0;}'
            'QToolButton:hover{color:#fff;background:#653647;border-color:#f06a80;}'
            'QToolButton:pressed{background:#8b3048;border-color:#ff8295;}')
        self.update()

    def paintEvent(self,event):
        painter=QPainter(self)
        painter.fillRect(self.rect(),QColor('#1d222d' if self.owner.dark else '#edf0f5'))
        painter.setPen(QColor('#363d4f' if self.owner.dark else '#cbd1db'))
        painter.drawLine(0,0,0,self.height())


class DifferencePulseOverlay(QWidget):
    """Transparent viewport overlay; native coordinates remain untouched."""
    def __init__(self, editor):
        super().__init__(editor.view.viewport());self.editor=editor
        self.boxes=[];self.active=-1;self.hold=False;self.started=time.monotonic()
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.timer=QTimer(self);self.timer.setInterval(40);self.timer.timeout.connect(self.update)
        self.hide()

    def set_candidates(self, candidates, side, hold=False, active=-1):
        self.boxes=[item.get(side) for item in candidates];self.hold=hold;self.active=active
        self.started=time.monotonic();self.setGeometry(self.parentWidget().rect())
        self.setVisible(bool(self.boxes))
        if self.boxes:self.timer.start();self.raise_();self.update()
        else:self.timer.stop()

    def paintEvent(self,event):
        view=self.editor.view
        if self.editor.closed or view.item is None or not self.boxes:return
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing)
        wave=(math.sin((time.monotonic()-self.started)*2*math.pi/1.35)+1)/2
        color=QColor('#ffc15c' if self.hold else '#ff526e')
        rect=view.page_rect
        for index,box in enumerate(self.boxes):
            if not box or box[2]<=box[0] or box[3]<=box[1]:continue
            mapped=view.page_box(box)
            tl=view.mapFromScene(mapped.topLeft())
            br=view.mapFromScene(mapped.bottomRight())
            area=QRectF(QPointF(tl),QPointF(br)).normalized()
            # Circular ring encloses the complete detected box, including its corners.
            radius=max(10.,math.hypot(area.width(),area.height())/2+3)+wave*5
            center=area.center();ring=QRectF(center.x()-radius,center.y()-radius,2*radius,2*radius)
            if not ring.intersects(QRectF(self.rect())):continue
            selected=index==self.active
            halo=QColor(color);halo.setAlpha(30 if selected else 12)
            p.setBrush(halo);p.setPen(QPen(color,2.6 if selected else 1.6));p.drawEllipse(ring)
            if selected or len(self.boxes)<=35:
                tag=QRectF(center.x()-10,center.y()-radius-13,24,15)
                p.setPen(Qt.PenStyle.NoPen);p.setBrush(QColor(25,29,39,215));p.drawRoundedRect(tag,3,3)
                p.setPen(color);p.drawText(tag,Qt.AlignmentFlag.AlignCenter,str(index+1))
        p.end()


class DualCompareController(QObject):
    """Independent document navigation, linked viewport and cancellable analysis."""
    def __init__(self, owner):
        super().__init__(owner);self.owner=owner;self.sync_on=True;self.enabled=False
        self.mode='auto';self.auto_align=True;self.offset=0;self.syncing=False
        self.proc=None;self.serial=0;self.buffer=b'';self.job_key=None
        self.result=None;self.active=-1;self.cache=OrderedDict();self.status=''
        self.debounce=QTimer(self);self.debounce.setSingleShot(True);self.debounce.setInterval(380)
        self.debounce.timeout.connect(self.run)
        self.deadline=QTimer(self);self.deadline.setSingleShot(True);self.deadline.setInterval(COMPARE_TIMEOUT_MS)
        self.deadline.timeout.connect(self.timed_out)
        self.view_timer=QTimer(self);self.view_timer.setSingleShot(True);self.view_timer.setInterval(0)
        self.view_timer.timeout.connect(self.flush_view);self.view_source=None
        self.registration_applied=False
        self.notice_timer=QTimer(self);self.notice_timer.setSingleShot(True);self.notice_timer.setInterval(10000)
        self.notice_timer.timeout.connect(self.dismiss_notice)

    def pair(self):
        a,b=self.owner.preview_dialog,self.owner.dual_preview
        return (a,b) if self.owner.dual_mode and not self.owner.book_mode and a is not None and b is not None and not a.closed and not b.closed else None

    @staticmethod
    def group_key(page):
        return page.comparison_group or os.path.normcase(os.path.abspath(page.input_path or page.label_path))

    def navigation_pages(self, editor):
        if self.owner.book_mode and self.owner.dual_mode and not self.owner.book_mode:return self.owner.book_pages()
        if not self.owner.dual_mode or not self.sync_on:return list(self.owner.pages)
        # Linked panes keep their own document as the page sequence. With sync
        # off, both panes can independently browse the entire loaded list.
        page=self.owner.by_id.get(getattr(editor,'nav_target_uid',None),editor.page)
        key=self.group_key(page)
        return [p for p in self.owner.pages if self.group_key(p)==key]

    def linked(self):
        pair=self.pair()
        return bool(pair and self.sync_on and not self.owner.dual_import_batch)

    def attach(self, editor):
        editor.view.zoomChanged.connect(lambda:self.queue_view(editor))
        editor.view.horizontalScrollBar().valueChanged.connect(lambda _value:self.queue_view(editor))
        editor.view.verticalScrollBar().valueChanged.connect(lambda _value:self.queue_view(editor))

    def rebase(self):
        pair=self.pair()
        if pair:
            self.offset=pair[1].navigation_index()-pair[0].navigation_index()
            self.queue_view(pair[0])

    def set_sync(self, checked):
        self.sync_on=bool(checked)
        pair=self.pair()
        if pair:
            for editor in pair:
                editor.nav_timer.stop();editor.nav_target_uid=None
                editor.nav_previous.stop_drag();editor.nav_next.stop_drag()
                editor.update_navigation()
        self.rebase();self.update_bars()

    def clamp_navigation(self, editor, index):
        pages=self.navigation_pages(editor)
        if not pages:return None
        low,high=0,len(pages)-1
        if self.linked():
            a,b=self.pair();na=len(self.navigation_pages(a));nb=len(self.navigation_pages(b))
            if editor is a:low=max(low,-self.offset);high=min(high,nb-1-self.offset)
            else:low=max(low,self.offset);high=min(high,na-1+self.offset)
        if high<low:return None
        return max(low,min(high,int(index)))

    def page_changed(self, editor, previous_uid):
        if self.owner.book_mode:
            if not self.owner.book_syncing:self.owner.show_book_spread(editor.page,secondary=editor.dual_secondary)
            self.update_bars();return
        self.invalidate()
        pair=self.pair()
        previous=self.owner.by_id.get(previous_uid)
        source_changed=previous is not None and self.group_key(previous)!=self.group_key(editor.page)
        if source_changed:
            # Replacing one source must preserve the other pane's current page.
            self.rebase()
        elif (pair and self.linked() and not self.syncing and previous_uid!=editor.page.uid):
            other=pair[1] if editor is pair[0] else pair[0]
            target=editor.navigation_index()+(self.offset if editor is pair[0] else -self.offset)
            self.syncing=True
            try:
                other.request_navigation(target,select=not other.dual_secondary);other.perform_navigation()
            finally:self.syncing=False
        self.update_bars()

    def queue_view(self, editor):
        if self.syncing or editor.closed or not self.linked():return
        if editor is self.owner.dual_render_target:editor=self.owner.preview_dialog
        if editor is not None and not editor.closed:self.view_source=editor;self.view_timer.start()

    def flush_view(self):
        source=self.view_source;self.view_source=None;pair=self.pair()
        if source is None or source.closed or not self.linked() or source not in pair:return
        target=pair[1] if source is pair[0] else pair[0]
        sv,tv=source.view,target.view
        if sv.item is None or tv.item is None:return
        self.syncing=True
        try:
            if sv.auto_fit:self.fit_pair()
            else:
                tv.auto_fit=False;tv.fit_timer.stop()
                desired=sv.transform().m11()
                tv.scale(desired/max(.001,tv.transform().m11()),desired/max(.001,tv.transform().m11()))
                center=sv.mapToScene(sv.viewport().rect().center())
                if not self.registration_applied:
                    x=(center.x()-sv.page_rect.left())/sv.page_rect.width()
                    y=(center.y()-sv.page_rect.top())/sv.page_rect.height()
                    center=QPointF(tv.page_rect.left()+x*tv.page_rect.width(),tv.page_rect.top()+y*tv.page_rect.height())
                tv.centerOn(center);tv.zoomChanged.emit()
            self.owner.compare_divider.wheel.motion()
        finally:self.syncing=False

    def fit_pair(self):
        pair=self.pair()
        if not self.linked() or not pair or any(p.view.item is None for p in pair):return False
        previous=self.syncing;self.syncing=True
        try:
            scale=min(min((p.view.viewport().width()-4)/max(1,p.view.sceneRect().width()),
                          (p.view.viewport().height()-4)/max(1,p.view.sceneRect().height())) for p in pair)
            scale=max(.001,scale)
            for editor in pair:
                view=editor.view;view.auto_fit=True;view.fit_timer.stop()
                view.setTransform(QTransform.fromScale(scale,scale));view.fit_scale=scale
                view.centerOn(view.sceneRect().center());view.zoomChanged.emit()
            return True
        finally:self.syncing=previous

    def reset_registration(self):
        self.registration_applied=False;previous=self.syncing;self.syncing=True
        try:
            for editor in (self.owner.preview_dialog,self.owner.dual_preview):
                if editor is not None and not editor.closed:editor.view.set_registration()
        finally:self.syncing=previous

    def refresh_registration(self):
        pair=self.pair();result=self.result
        if not pair or not result or not self.auto_align or not result.get('alignment'):return False
        try:
            if self.job_key!=self.current_key():return False
            quality=result['alignment'];matrix=quality['matrix']
            supported=(quality.get('exact') or (quality.get('edge',0)>=.65 and quality.get('stable',0)>=.65
                                               and quality.get('edge_pixels',0)>=100))
            if not supported or quality.get('overlap',0)<.45:return False
            if any(p.view.item is None for p in pair):return False
            if not all(math.isfinite(float(n)) for row in matrix for n in row):return False
            av,bv=pair[0].view,pair[1].view;ar,br=av.page_rect,bv.page_rect
            aw,ah=result['a_size'];bw,bh=result['b_size']
            sx,sy=ar.width()/aw,ar.height()/ah;bx,by=bw/br.width(),bh/br.height()
            transform=QTransform(matrix[0][0]*bx*sx,matrix[1][0]*bx*sy,
                matrix[0][1]*by*sx,matrix[1][1]*by*sy,matrix[0][2]*sx,matrix[1][2]*sy)
            frame=ar.united(transform.mapRect(br))
            previous=self.syncing;self.syncing=True
            try:
                av.set_registration(frame=frame);bv.set_registration(transform,frame)
                self.registration_applied=True
                if av.auto_fit and bv.auto_fit:
                    if not self.fit_pair():av.fit_page();bv.fit_page()
                for editor in pair:editor.difference_overlay.update()
            finally:self.syncing=previous
            return True
        except (OSError,ValueError,KeyError,TypeError,ZeroDivisionError):return False

    def toggle(self, checked):
        self.enabled=bool(checked)
        pair=self.pair()
        if pair:
            for editor in pair:
                if self.enabled or self.auto_align:
                    editor.stop_gif();editor.requested_side=0;editor.request_image()
                else:editor.start_gif()
        self.invalidate();self.update_bars()

    def set_mode(self, index):
        self.mode=('auto','document','image')[max(0,min(2,int(index)))];self.invalidate()

    def set_alignment(self, checked):
        self.auto_align=bool(checked)
        pair=self.pair()
        if pair:
            for editor in pair:
                if self.auto_align:editor.stop_gif()
                elif not self.enabled:editor.start_gif()
        self.invalidate();self.update_bars()

    def stop_job(self):
        self.serial+=1;self.deadline.stop();self.buffer=b''
        proc=self.proc;self.proc=None
        if proc is not None:
            # Every callback captures its process and generation. A late finish cannot affect a newer job.
            if proc.state()!=QProcess.ProcessState.NotRunning:
                proc.finished.connect(proc.deleteLater);proc.kill()
            else:proc.deleteLater()

    def clear_marks(self):
        self.result=None;self.active=-1;self.job_key=None;self.reset_registration()
        for editor in (self.owner.preview_dialog,self.owner.dual_preview):
            if editor is not None and not editor.closed:editor.difference_overlay.set_candidates([], 'a')

    def invalidate(self):
        self.debounce.stop();self.stop_job();self.clear_marks()
        if (self.enabled or self.auto_align) and self.pair():
            self.set_status('분석 대기 · 페이지 이동이 멈추면 자동 비교' if self.enabled else '자동 정렬 대기');self.debounce.start()
        else:self.set_status('')

    def current_key(self):
        pair=self.pair()
        if not pair:return None
        key=[]
        for editor in pair:
            page=editor.page
            real=image_source_info(page.path)['file'] if is_image_source(page.path) else page.path
            stat=Path(real).stat()
            key.append((page.uid,page.path,page.number,stat.st_size,stat.st_mtime_ns))
        return (tuple(key),self.mode,self.auto_align)

    def run(self, force=False):
        pair=self.pair()
        if not (self.enabled or self.auto_align) or not pair:return
        if self.owner.dual_import_batch:
            self.debounce.start();return
        if any(not p.preview_ready or p.busy or p.has_pending_move() or p.nav_target_uid is not None or p.nav_scrubbing
               or p.nav_previous.pressed or p.nav_next.pressed for p in pair):
            self.debounce.start();return
        if any(p.page.is_document_card for p in pair):
            self.apply({'status':'hold','reasons':['PDF/텍스트 대표 카드는 첫 쪽만 표시합니다. 전체 문서를 열어 대응 쪽을 선택하세요.'],
                        'candidates':[],'total':0,'notes':[]},None);return
        try:key=self.current_key()
        except (OSError,ValueError) as exc:
            self.apply({'status':'hold','reasons':['원본 상태 확인 실패: '+str(exc)],'candidates':[],'total':0,'notes':[]},None);return
        if not force and key in self.cache:
            self.cache.move_to_end(key);self.apply(self.cache[key],key);return
        self.stop_job();self.clear_marks();generation=self.serial;self.job_key=key
        proc=QProcess(self);self.proc=proc
        proc.readyReadStandardOutput.connect(lambda:self.read_output(proc,generation,key))
        proc.readyReadStandardError.connect(lambda:proc.readAllStandardError())
        proc.finished.connect(lambda *_args:self.finished(proc,generation,key))
        proc.errorOccurred.connect(lambda _error:self.failed(proc,generation,key))
        executable,args=worker_launch('--compare-worker')
        job={'a':{'path':pair[0].page.path,'number':pair[0].page.number},
             'b':{'path':pair[1].page.path,'number':pair[1].page.number},
             'mode':self.mode,'auto_align':self.auto_align}
        proc.started.connect(lambda:(proc.write((json.dumps(job,ensure_ascii=True)+'\n').encode('ascii')),
                                     proc.closeWriteChannel()))
        env=QProcessEnvironment.systemEnvironment();env.insert('QT_QPA_PLATFORM','offscreen')
        proc.setProcessEnvironment(env);proc.start(executable,args)
        self.set_status('분석 중 · 원본 쪽 읽기');self.deadline.start()

    def read_output(self, proc, generation, key):
        if self.proc is not proc or generation!=self.serial:return
        self.buffer+=bytes(proc.readAllStandardOutput())
        while b'\n' in self.buffer:
            line,self.buffer=self.buffer.split(b'\n',1)
            try:data=json.loads(line)
            except (ValueError,UnicodeError):continue
            if 'progress' in data:self.set_status('분석 중 · '+str(data['progress']))
            elif 'result' in data:
                self.deadline.stop()
                try:current=self.current_key()
                except (OSError,ValueError):current=None
                if key!=current:
                    self.invalidate();return
                result=data['result']
                if result.get('alignment'):
                    self.cache[key]=result;self.cache.move_to_end(key)
                    while len(self.cache)>6:self.cache.popitem(last=False)
                self.apply(result,key)

    def finished(self, proc, generation, key):
        if self.proc is not proc or generation!=self.serial:return
        self.read_output(proc,generation,key)
        if self.proc is not proc:return
        self.deadline.stop();self.proc=None;proc.deleteLater()
        if self.result is None:
            self.apply({'status':'hold','reasons':['비교 프로세스가 결과 없이 종료되었습니다. 모듈·원본을 확인하세요.'],
                        'candidates':[],'total':0,'notes':[]},key)

    def failed(self, proc, generation, key):
        if self.proc is not proc or generation!=self.serial:return
        if proc.state()!=QProcess.ProcessState.NotRunning:return
        self.stop_job();self.apply({'status':'hold','reasons':['비교 프로세스를 시작하지 못했습니다.'],
                                  'candidates':[],'total':0,'notes':[]},key)

    def timed_out(self):
        key=self.job_key;self.stop_job()
        self.apply({'status':'hold','reasons':['45초 안에 분석이 끝나지 않아 중단했습니다. 현재 쪽은 판정하지 않았습니다.'],
                    'candidates':[],'total':0,'notes':[]},key)

    def apply(self, result, key):
        self.result=result;self.job_key=key;self.active=-1
        pair=self.pair()
        if not pair:return
        candidates=result.get('candidates',[]) if self.enabled else [];hold=result.get('status')=='hold'
        aligned=self.refresh_registration()
        for editor,side in zip(pair,('a','b')):
            editor.difference_overlay.set_candidates(candidates,side,hold)
        if hold:text='분석 보류 · '+('정렬 위치 적용 / ' if aligned else '')+' / '.join(result.get('reasons',[])[:2])
        elif not self.enabled:text='자동 정렬 완료 · 화면 위치 적용' if aligned else '자동 정렬 보류 · 공통 특징을 확인하세요.'
        elif candidates:text=f'차이 후보 {result.get("total",len(candidates))}곳 · 현재 두 쪽'
        else:text='차이 후보 없음 · 현재 두 쪽 / 검사 해상도 기준'
        self.set_status(text)
        details=[text,*result.get('reasons',[]),*result.get('notes',[]),result.get('scope','')]
        if result.get('alignment'):
            alignment=result['alignment'];details.append('정렬: '+alignment['method'])
            details.append(f'정렬에 쓴 대응점 {alignment["inliers"]}/{alignment["matches"]} · 겹침 {alignment["overlap"]:.1%}')
        for editor in pair:editor.compare_status.setToolTip('\n'.join(filter(None,details)))
        self.update_bars();self.queue_view(pair[0])

    def set_status(self, text):
        previous=self.status;pair=self.pair()
        if not pair:text=''
        self.status=text
        notice=getattr(self.owner,'comparison_notice',None)
        if notice is not None:
            notice.setText(text);notice.setProperty('warning','보류' in text)
            if not text:self.dismiss_notice()
            elif text!=previous:
                notice.show();self.notice_timer.start()
            footer=getattr(self.owner,'reading_footer',None)
            if footer is not None:footer.sync()
        if pair:
            for editor in pair:
                editor.compare_status.setText(text)
                editor.compare_status.setStyleSheet('background:#252b38;color:'+
                    ('#ffc15c' if text.startswith('분석 보류') else '#d6dfea')+';padding:2px 8px;')

    def dismiss_notice(self):
        self.notice_timer.stop()
        notice=getattr(self.owner,'comparison_notice',None)
        if notice is not None:notice.hide()
        footer=getattr(self.owner,'reading_footer',None)
        if footer is not None:footer.sync()

    def update_bars(self):
        pair=self.pair()
        if not pair:self.set_status('')
        for editor in (self.owner.preview_dialog,self.owner.dual_preview):
            if editor is None or editor.closed:continue
            editor.dual_bar.setVisible(bool(pair or self.owner.book_mode) and not editor.embedded);editor.compare_status.hide()
            pages=self.navigation_pages(editor);index=editor.navigation_index()
            caption=('오른쪽' if editor.dual_secondary else '왼쪽')+' · '+Path(editor.page.input_path or editor.page.label_path).name
            editor.dual_caption.setText(caption)
            editor.dual_caption.setToolTip(caption+f' · {index+1}/{len(pages)}')
            if self.owner.book_mode:
                editor.dual_caption.setText(('빈 쪽' if editor.book_blank else f'{index+1}쪽')+' · '+Path(editor.page.input_path or editor.page.label_path).name)
            if editor.dual_secondary:
                for button,value in ((editor.sync_button,self.sync_on),(editor.compare_button,self.enabled),
                                     (editor.align_button,self.auto_align)):
                    button.blockSignals(True);button.setChecked(value);button.blockSignals(False)
                hint='동시 페이지·확대·스크롤 켜짐 (현재 쪽 간격 유지)' if self.linked() else '두 화면의 현재 쪽 간격을 유지하며 페이지·확대·스크롤을 함께 이동'
                editor.sync_button.setToolTip(hint)
                count=len(self.result.get('candidates',[])) if self.enabled and self.result else 0
                editor.diff_count.setText(f'{self.active+1 if self.active>=0 else 0}/{count}')
                editor.diff_count.setToolTip('현재 차이 후보 / 전체 차이 후보 · 현재 두 쪽')
                editor.diff_previous.setEnabled(count>0);editor.diff_next.setEnabled(count>0)
        divider=getattr(self.owner,'compare_divider',None)
        if divider is not None:divider.wheel.set_active(self.linked() and not self.owner.dual_anim_closing)
        footer=getattr(self.owner,'reading_footer',None)
        if footer is not None:footer.sync()

    def focus_candidate(self, step):
        pair=self.pair();result=self.result
        if not self.enabled or not pair or not result or not result.get('candidates'):return
        candidates=result['candidates']
        self.active=((0 if step>0 else len(candidates)-1) if self.active<0
                     else (self.active+step)%len(candidates))
        self.syncing=True
        try:
            for editor,side in zip(pair,('a','b')):
                box=candidates[self.active].get(side);view=editor.view
                editor.difference_overlay.set_candidates(candidates,side,result['status']=='hold',self.active)
                if view.item is None or not box:continue
                if view.auto_fit:view.zoom_steps(3)
                view.centerOn(view.page_box(box).center())
        finally:self.syncing=False
        self.update_bars();self.queue_view(pair[0])

    def accept_thumbnail(self, editor, uid, lower=False):
        page=self.owner.by_id.get(uid)
        if page is None:return False
        if lower and not editor.dual_secondary:
            if not self.owner.dual_mode:self.owner.open_dual_mode()
            editor=self.owner.dual_preview
        if editor is None:return False
        if editor.dual_secondary:return self.owner.show_comparison_page(editor,page)
        return editor.navigate_to_page(page,select=True)

    def close_dual(self):
        self.enabled=False;self.debounce.stop();self.view_timer.stop();self.view_source=None
        self.stop_job();self.clear_marks();self.set_status('')
        for editor in (self.owner.preview_dialog,self.owner.dual_preview):
            if editor is not None and not editor.closed:
                editor.update_navigation()
        self.update_bars()

class SyncWheelIndicator(QWidget):
    """A lightweight vector mouse; the roller moves while the panes are linked."""
    def __init__(self,parent):
        super().__init__(parent);self.active=False;self.started=time.monotonic();self.last_motion=0.
        self.setFixedHeight(68);self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAccessibleName('동시 이동 마우스 휠 표시')
        self.timer=QTimer(self);self.timer.setInterval(50);self.timer.timeout.connect(self.update)

    def set_active(self,active):
        self.active=bool(active);self.setVisible(self.active)
        if self.active and self.isVisible():self.timer.start()
        else:self.timer.stop()
        self.update()

    def motion(self):
        self.last_motion=time.monotonic();self.update()

    def showEvent(self,event):
        super().showEvent(event)
        if self.active:self.timer.start()

    def hideEvent(self,event):
        self.timer.stop();super().hideEvent(event)

    def paintEvent(self,event):
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now=time.monotonic();phase=((now-self.started)*1.25)%1
        moving=now-self.last_motion<.7;cx=self.width()/2
        color=QColor('#ff829b' if moving else '#b9d7fa')
        p.setPen(QPen(color,1.8));p.setBrush(QColor('#263347'))
        p.drawRoundedRect(QRectF(cx-14,5,28,42),13,13)
        p.drawLine(QPointF(cx,5),QPointF(cx,17))
        p.setBrush(QColor('#111823'));p.drawRoundedRect(QRectF(cx-3,11,6,14),3,3)
        p.setPen(QPen(color,2.4,Qt.PenStyle.SolidLine,Qt.PenCapStyle.RoundCap))
        p.drawLine(QPointF(cx,13+8*phase),QPointF(cx,15+8*phase))
        for direction in (-1,1):
            x=cx+direction*23;y=24+math.sin(phase*math.tau)*2
            p.drawLine(QPointF(x,y-7),QPointF(x,y+7))
            p.drawLine(QPointF(x-3,y+4),QPointF(x,y+7));p.drawLine(QPointF(x+3,y+4),QPointF(x,y+7))
        p.setPen(color);p.drawText(QRectF(0,49,self.width(),17),Qt.AlignmentFlag.AlignCenter,'연결됨')
        p.end()


class CompareDivider(QSplitterHandle):
    """The normal splitter expands into a compact comparison control rail."""
    def __init__(self,orientation,parent):
        super().__init__(orientation,parent);self.editor=None
        self.panel=QWidget(self);self.panel.hide()
        self.column=QVBoxLayout(self.panel);self.column.setContentsMargins(5,8,5,8);self.column.setSpacing(6)
        self.column.addStretch(1)
        self.wheel=SyncWheelIndicator(self.panel);self.column.addWidget(self.wheel)
        self.setAccessibleName('좌우 비교 구분선 및 조절 버튼')
        self.panel.setStyleSheet('QWidget{background:#252c3b;color:#d6e2f4;} '
            'QToolButton{padding:5px 2px;border:1px solid #536079;border-radius:6px;background:#2d374b;}'
            'QToolButton:hover{border-color:#ff8097;background:#473345;}'
            'QToolButton:checked{background:#673246;border-color:#ff8097;}'
            'QComboBox{padding:3px 0;border:1px solid #536079;border-radius:4px;}'
            'QLabel{background:transparent;}')

    def attach(self,editor):
        self.detach();self.editor=editor
        for button,label in ((editor.sync_button,'동시 이동'),(editor.align_button,'자동 정렬'),
                             (editor.compare_button,'차이 비교')):
            button.setText(label);button.setMinimumHeight(33);button.setFixedWidth(74)
            self.column.addWidget(button)
        editor.compare_mode.setFixedWidth(74);editor.compare_mode.setItemText(1,'문서')
        self.column.addWidget(editor.compare_mode,0,Qt.AlignmentFlag.AlignHCenter)
        editor.compare_refresh.setFixedWidth(74);editor.compare_refresh.setText('다시 분석')
        self.column.addWidget(editor.compare_refresh)
        self.column.addWidget(editor.diff_count,0,Qt.AlignmentFlag.AlignHCenter)
        row=QWidget(self.panel);arrows=QHBoxLayout(row);arrows.setContentsMargins(0,0,0,0);arrows.setSpacing(4)
        for button in (editor.diff_previous,editor.diff_next):button.setFixedSize(35,28);arrows.addWidget(button)
        self.arrow_row=row;self.column.addWidget(row)
        self.column.addStretch(1)
        self.wheel.set_active(editor.owner.comparison.linked());self.resize_panel()

    def detach(self):
        self.wheel.set_active(False)
        # Keep controls alive until their PreviewDialog shuts down.
        editor=self.editor
        if editor is not None:
            for widget in (editor.sync_button,editor.align_button,editor.compare_button,editor.compare_mode,
                           editor.compare_refresh,editor.diff_count,editor.diff_previous,editor.diff_next):
                self.column.removeWidget(widget);widget.hide();widget.setParent(editor.dual_bar)
        while self.column.count()>2:
            item=self.column.takeAt(2)
            if item.widget() is not None:item.widget().deleteLater()
        self.editor=None;self.panel.hide()

    def set_progress(self,progress):
        visible=progress>=.68 and self.editor is not None and not self.editor.owner.book_mode
        self.panel.setVisible(visible)
        if visible:
            for widget in (self.editor.sync_button,self.editor.align_button,self.editor.compare_button,
                           self.editor.compare_mode,self.editor.compare_refresh,self.editor.diff_count,
                           self.editor.diff_previous,self.editor.diff_next):widget.show()
        self.resize_panel()

    def resize_panel(self):
        self.panel.setGeometry(0,0,self.width(),self.height())

    def resizeEvent(self,event):
        super().resizeEvent(event);self.resize_panel()

    def paintEvent(self,event):
        p=QPainter(self);p.fillRect(self.rect(),QColor('#252c3b'))
        p.setPen(QColor('#536079'));p.drawLine(0,0,0,self.height());p.drawLine(self.width()-1,0,self.width()-1,self.height())
        if self.panel.isHidden() and not (self.editor and self.editor.owner.book_mode):
            p.setPen(QColor('#ec728b'));p.drawLine(self.width()//2,self.height()//2-18,self.width()//2,self.height()//2+18)
        p.end()


class HoverHelpBlocker(QObject):
    """Remove mouse-hover help without changing action/status messages."""
    def eventFilter(self,watched,event):
        if event.type()==QEvent.Type.ToolTip:
            event.accept();return True
        return False


class BookFocusRestoreButton(QToolButton):
    """Keep a transparent hover target over the page without reserving a row."""
