class HangulExportDialog(QDialog):
    """Keeps conversion in a child process; closing the panel only hides it."""
    def __init__(self, owner, job):
        super().__init__(owner);self.owner=owner;self.busy=True;self.conversion_result=None;self.error=''
        self.buffer=b'';self.errors=b'';self.ended=False
        self.setWindowTitle('한글 통합 변환 · 검사');self.resize(820,520)
        layout=QVBoxLayout(self);self.label=QLabel('한글 변환 준비 중');layout.addWidget(self.label)
        self.bar=QProgressBar();self.bar.setRange(0,len(job['pages']));layout.addWidget(self.bar)
        self.tabs=QTabWidget();layout.addWidget(self.tabs)
        self.checks=QTableWidget(0,7);self.checks.setHorizontalHeaderLabels(['원본 쪽','문단','문자·순서','본문 서식','보존 양식','높이 추정','확인 사항'])
        self.checks.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.ResizeToContents);self.checks.horizontalHeader().setStretchLastSection(True)
        self.checks.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers);self.tabs.addTab(self.checks,'쪽별 검사')
        self.log=QPlainTextEdit();self.log.setReadOnly(True);self.tabs.addTab(self.log,'진행 기록');self.tabs.setCurrentIndex(1)
        mode='통합 · 편집 가능한 문단 + 원본 양식'
        self.log.setPlainText(f'{len(job["pages"])}쪽 · {mode}\n저장 예정: {job["output"]}')
        row=QHBoxLayout();layout.addLayout(row)
        self.review_button=QPushButton('검토뷰 열기');self.review_button.setEnabled(False)
        self.review_button.clicked.connect(self.open_review);row.addWidget(self.review_button)
        self.open_button=QPushButton('한글 파일 열기');self.open_button.setEnabled(False)
        self.open_button.clicked.connect(self.open_result);row.addWidget(self.open_button)
        self.report_button=QPushButton('검사표 열기');self.report_button.setEnabled(False);self.report_button.clicked.connect(self.open_report);row.addWidget(self.report_button)
        close=QPushButton('닫기');close.clicked.connect(self.hide);row.addWidget(close)
        work=TEMP_ROOT/owner.session/'hangul'/uuid.uuid4().hex;work.mkdir(parents=True,exist_ok=True)
        # Keep the selected order and edits at conversion time, independently of later UI changes.
        try:self.review_input=export_pages([PageRef(path,number) for path,number in job['pages']],
                                           work,'변환당시원본',False)[0]
        except Exception:
            shutil.rmtree(work,ignore_errors=True);raise
        self.destroyed.connect(lambda *_args:shutil.rmtree(work,ignore_errors=True))
        self.job_path=work/'job.json';self.job_path.write_text(json.dumps(job,ensure_ascii=False),encoding='utf-8')
        self.process=QProcess(self);self.process.setProcessChannelMode(QProcess.ProcessChannelMode.SeparateChannels)
        self.process.readyReadStandardOutput.connect(self.read_output)
        self.process.readyReadStandardError.connect(self.read_errors)
        self.process.finished.connect(self.on_process_finished)
        self.process.errorOccurred.connect(self.process_error)
        executable,args=worker_launch('--hangul-worker');args=[*args,str(self.job_path)]
        self.process.start(executable,args)

    def read_output(self):
        self.buffer+=bytes(self.process.readAllStandardOutput())
        while b'\n' in self.buffer:
            line,self.buffer=self.buffer.split(b'\n',1)
            try:data=json.loads(line)
            except (ValueError,UnicodeDecodeError):continue
            if 'result' in data:self.conversion_result=data['result']
            elif 'error' in data:self.error=data['error']
            else:
                self.label.setText(data.get('message','변환 중'))
                self.bar.setValue(data.get('progress',0))

    def read_errors(self):
        self.errors=(self.errors+bytes(self.process.readAllStandardError()))[-6000:]

    def process_error(self, error):
        if error==QProcess.ProcessError.FailedToStart:
            self.error=self.process.errorString();self.on_process_finished(-1)

    def on_process_finished(self, code, status=None):
        if self.ended:return
        self.ended=True;self.read_output();self.read_errors();self.busy=False
        if self.conversion_result and code==0 and status!=QProcess.ExitStatus.CrashExit and not self.error:
            self.bar.setValue(self.bar.maximum());self.label.setText('한글 파일 저장 완료')
            self.log.appendPlainText('\n저장 완료: '+self.conversion_result['output'])
            r=self.conversion_result
            self.log.appendPlainText(f'머리말 포함 문단 {r["paragraphs"]:,}개 · 본문 표 {r["tables"]}개 · 부분 그림 {r["figures"]}개')
            self.log.appendPlainText(f'이어 붙인 줄 {r["joined_lines"]:,}개 · 낱말 연결 {r["word_joins"]}개 · 앞뒤 쪽 문단 연결 {r["cross_page_joins"]}개')
            n=r['normalization']
            self.log.appendPlainText('원본 서식 추정: 원본 글꼴/크기/색/줄바꿈 · 줄 위치에서 고정 간격 복원' if r.get('source_format') else
                f'전체 서식 통일: 본문 {n["body_size"]}pt · 장평 {n["body_ratio"]}% · 자간 {n["letter_spacing"]}% · 줄 간격 {n["line_spacing"]}%')
            self.log.appendPlainText(f'본문 글상자 0개 · 머리말 표 {r["header_tables"]}개 · 제목 틀 {r["title_tables"]}개 · 쪽 테두리 {r["page_borders"]}개')
            if r.get('spacing_adjustment'):self.log.appendPlainText(r['spacing_adjustment'])
            from PySide6.QtWidgets import QTableWidgetItem
            self.checks.setRowCount(len(r['page_checks']))
            for i,p in enumerate(r['page_checks']):
                values=[f'{p["index"]} ({p["source_page"]}쪽)',str(p['paragraphs']),'통과' if p['content_ok'] else '실패',
                    '통과' if p['style_ok'] else '실패',f'머리말 {p["headers"]} / 제목 {p["title_frames"]} / 테두리 {p["page_borders"]}',
                    f'{p["estimated_height_pt"]:.0f} / {p["available_height_pt"]:.0f} pt',' · '.join(p['warnings']) or '실제 화면 확인 전']
                for j,value in enumerate(values):
                    item=QTableWidgetItem(value);item.setToolTip(p['source'])
                    if p['warnings']:item.setBackground(QColor('#6b4b23'));item.setForeground(QColor('#ffffff'))
                    self.checks.setItem(i,j,item)
            self.tabs.setCurrentIndex(0)
            review=sum(bool(p['warnings']) for p in r['page_checks'])
            self.label.setText(f'저장 완료 · 문자/순서 {len(r["page_checks"])}/{r["pages"]} · 서식 통과 · 별도 검토 {review}쪽')
            self.report_button.setEnabled(bool(r.get('report')))
            for warning in r['warnings']:self.log.appendPlainText(warning)
            self.log.appendPlainText('한컴오피스에서 열어 글꼴과 배치를 확인하세요.')
            self.open_button.setEnabled(True)
            self.review_button.setEnabled(True)
            QTimer.singleShot(0,self.open_review)
        else:
            self.label.setText('한글 변환 실패')
            self.log.appendPlainText('\n'+(self.error or self.errors.decode('utf-8',errors='replace') or f'변환 프로세스 종료: {code}'))
            try:self.review_input.unlink(missing_ok=True)
            except OSError:pass
        try:self.job_path.unlink(missing_ok=True);self.job_path.parent.rmdir()
        except OSError:pass

    def open_report(self):
        if self.conversion_result and self.conversion_result.get('report'):
            QDesktopServices.openUrl(QUrl.fromLocalFile(self.conversion_result['report']))

    def open_result(self):
        if self.conversion_result:QDesktopServices.openUrl(QUrl.fromLocalFile(self.conversion_result['output']))

    def open_review(self):
        if self.busy or not self.review_button.isEnabled() or not self.conversion_result:return
        if self.owner.open_conversion_review(self.conversion_result['output'],self.review_input,'한글 변환'):
            self.hide()


class ImageExportDialog(QDialog):
    """Keep the final filename absent until a complete PDF is ready to publish."""
    def __init__(self,parent,target,pages=(),inputs=()):
        super().__init__(parent);self.setWindowTitle('JPG to PDF');self.resize(470,160)
        self.target=Path(target);self.stage=self.target.parent/('.pdfmagnet-'+uuid.uuid4().hex+'.tmp.pdf')
        self.result_path=None;self.error='';self.buffer=b'';self.ready=False;self.busy=False;self.cancelled=False;self.ended=False;self.owns_stage=False
        layout=QVBoxLayout(self);self.label=QLabel('변환 준비 중');layout.addWidget(self.label)
        self.bar=QProgressBar();self.bar.setRange(0,0);layout.addWidget(self.bar)
        self.cancel_button=QPushButton('취소');self.cancel_button.clicked.connect(self.reject);layout.addWidget(self.cancel_button)
        self.proc=QProcess(self);self.proc.readyReadStandardOutput.connect(self.read_output)
        self.proc.readyReadStandardError.connect(lambda:self.proc.readAllStandardError())
        self.proc.finished.connect(self.on_process_finished);self.proc.errorOccurred.connect(self.failed)
        self.job={'stage':str(self.stage),'pages':[(p.path,p.number) for p in pages],'inputs':list(inputs)}
        self.proc.started.connect(lambda:self.proc.write((json.dumps(self.job,ensure_ascii=True)+'\n').encode('ascii')))
        QTimer.singleShot(0,self.start)

    def start(self):
        if self.cancelled:return
        try:
            if self.target.exists():raise FileExistsError('같은 이름의 파일이 있습니다. 다른 이름으로 저장하세요.')
            with self.stage.open('xb'):pass
            self.owns_stage=True
            self.busy=True;program,args=worker_launch('--image-export-worker');self.proc.start(program,args)
        except Exception as exc:self.error=str(exc);self.on_process_finished()

    def read_output(self):
        self.buffer+=bytes(self.proc.readAllStandardOutput())
        while b'\n' in self.buffer:
            line,self.buffer=self.buffer.split(b'\n',1)
            try:data=json.loads(line)
            except ValueError:continue
            if 'catalog' in data:
                catalog=data['catalog'];self.label.setText(f'목록 확인 · {catalog.get("done",catalog.get("found",0)):,}개')
            elif 'total' in data:
                done,total=data['done'],max(1,data['total']);self.bar.setRange(0,total);self.bar.setValue(done)
                self.label.setText(f'{int(done*100/total)}% · {done:,}/{total:,}쪽'+(' · PDF 기록 중' if data['phase']=='write' else ' 변환'))
            if data.get('ready'):self.ready=True
            if data.get('error'):self.error=data['error']

    def failed(self,_error):
        if self.proc.state()==QProcess.ProcessState.NotRunning:
            if not self.cancelled:self.error=self.error or 'PDF 변환 프로세스를 실행하지 못했습니다.'
            self.on_process_finished()

    def on_process_finished(self,code=0,_status=None):
        if self.ended:return
        self.ended=True
        if self.proc.isOpen():self.read_output()
        self.busy=False
        try:
            if self.ready and not self.cancelled and code==0 and not self.error:
                if sys.platform=='win32':os.rename(self.stage,self.target)
                else:os.link(self.stage,self.target)
                self.result_path=str(self.target)
            elif not self.cancelled and not self.error:self.error='변환 프로세스가 중단되었습니다.'
        except Exception as exc:self.error=str(exc)
        finally:
            try:
                if self.owns_stage:self.stage.unlink(missing_ok=True)
            except OSError:pass
        if self.result_path:self.accept()
        else:super().reject()

    def reject(self):
        self.cancelled=True
        if self.busy:
            self.cancel_button.setEnabled(False);self.label.setText('변환 중단 중…')
            if self.proc.state()==QProcess.ProcessState.NotRunning:self.on_process_finished(self.proc.exitCode())
            else:self.proc.kill()
        else:super().reject()

    def closeEvent(self,event):
        if self.busy:self.reject();event.ignore()
        else:super().closeEvent(event)


class ImportProgress(QWidget):
    """썸네일 안의 한 줄 안내. 크게 보기나 썸네일 분할 크기는 바꾸지 않는다."""
    cancelled=Signal()
    SETTING_KEY='import/status_seconds'
    DEFAULT_SECONDS=0.5

    @staticmethod
    def normalize_seconds(value):
        try:seconds=float(value)
        except (TypeError,ValueError,OverflowError):seconds=ImportProgress.DEFAULT_SECONDS
        if not math.isfinite(seconds):seconds=ImportProgress.DEFAULT_SECONDS
        return round(max(0.1,min(2.0,seconds)),1)

    def __init__(self,parent,canvas,display_seconds=DEFAULT_SECONDS):
        # canvas는 첫 목록을 읽는 동안 비활성이다. 취소 버튼은 계속 쓸 수 있도록
        # 활성 content를 부모로 두되, 표시 좌표는 반드시 썸네일 viewport 안으로 제한한다.
        super().__init__(parent)
        self.canvas=canvas;self.display_seconds=self.normalize_seconds(display_seconds)
        self.setObjectName('import_progress')
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground,True)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.title=QLabel(self);self.detail=QLabel(self)
        self.title.setObjectName('import_progress_name')
        for label in (self.title,self.detail):
            label.setTextFormat(Qt.TextFormat.PlainText)
            label.setWordWrap(False)
            label.setAlignment(Qt.AlignmentFlag.AlignLeft|Qt.AlignmentFlag.AlignVCenter)
        self.cancel=QPushButton('취소',self)
        self.cancel.setCursor(Qt.CursorShape.PointingHandCursor)
        self.cancel.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.cancel.setToolTip('읽기 취소 · 이미 표시한 쪽은 유지')
        self.cancel.setAccessibleName('파일 읽기 취소')
        self.cancel.clicked.connect(self.cancelled)
        self.bar=QProgressBar(self);self.bar.setTextVisible(False)
        self.hide_timer=QTimer(self);self.hide_timer.setSingleShot(True)
        self.hide_timer.setTimerType(Qt.TimerType.PreciseTimer)
        self.hide_timer.timeout.connect(self.dismiss)
        self.label='';self.data={};self._path='';self._detail_text='';self._full_detail=''
        self._active=False;self._finished_at=None;self._dark=None
        self.sync_style();self.hide()

    def sync_style(self):
        dark=self.canvas.owner.dark
        if self._dark==dark:return
        self._dark=dark
        background,border,foreground,muted,track=(
            ('rgba(31,36,48,235)','#414858','#e6eaf1','#a9b1c0','#3c3541') if dark else
            ('rgba(245,247,251,245)','#cbd2dc','#273244','#657083','#e4dce2'))
        self.setStyleSheet(
            f'QWidget#import_progress{{background:{background};border:1px solid {border};border-radius:5px;}}'
            f'QLabel{{color:{foreground};background:transparent;border:0;font-size:11px;}}'
            f'QLabel#import_progress_name{{color:{muted};}}'
            'QPushButton{color:#fff;background:#8f2942;border:0;border-radius:3px;padding:0;font-size:11px;}'
            'QPushButton:hover{background:#bd3553;} QPushButton:disabled{color:#b3a8ae;background:#50333f;}'
            f'QProgressBar{{background:{track};border:0;border-radius:1px;}}'
            'QProgressBar::chunk{background:#f14665;border-radius:1px;}')

    def place(self):
        if not self._active or self.canvas.isHidden() or self.canvas.owner.thumbnails_collapsed:
            self.hide();return
        self.sync_style()
        viewport=self.canvas.viewport();parent=self.parentWidget()
        width=min(320,viewport.width()-16)
        vector_mode=self.data.get('phase')=='vector' and self._finished_at is None
        self.detail.setWordWrap(vector_mode)
        if vector_mode:
            # Keep the requested message readable inside the thumbnail strip, even on a narrow pane.
            row_height=max(20,self.detail.fontMetrics().height()+2)
            self.detail.setText(self._detail_text)
            detail_width=max(1,width-54)
            detail_height=max(row_height,self.detail.heightForWidth(detail_width))
            height=detail_height+row_height+13
            if width<80 or viewport.height()<height+16:self.hide();return
            origin=viewport.mapTo(parent,QPoint(0,0));bottom=viewport.height()-8
            counter=self.canvas.page_count
            if not counter.isHidden():bottom=min(bottom,counter.y()-6)
            self.setGeometry(origin.x()+(viewport.width()-width)//2,origin.y()+max(8,bottom-height),width,height)
            self.detail.setGeometry(8,4,detail_width,detail_height)
            self.cancel.setGeometry(width-40,4,32,row_height)
            self.title.setGeometry(8,4+detail_height,width-16,row_height)
            stage=f'{self.data.get("stage","")} · {self.data.get("seconds",0)}초 · {self.label}'
            self.title.setText(self.title.fontMetrics().elidedText(stage,Qt.TextElideMode.ElideMiddle,width-16))
            self.bar.setGeometry(8,height-5,width-16,2);self.show();self.raise_();return
        row_height=max(20,self.detail.fontMetrics().height()+2);height=row_height+11
        if width<80 or viewport.height()<height+16:
            self.hide();return
        origin=viewport.mapTo(parent,QPoint(0,0))
        bottom=viewport.height()-8
        counter=self.canvas.page_count
        if not counter.isHidden():bottom=min(bottom,counter.y()-6)
        y=max(8,bottom-height)
        self.setGeometry(origin.x()+(viewport.width()-width)//2,origin.y()+y,width,height)
        # 파일명보다 상태/쪽수에 먼저 공간을 주고, 긴 이름만 가운데를 줄인다.
        right=width-8
        if not self.cancel.isHidden():
            self.cancel.setGeometry(right-32,4,32,row_height);right-=38
        available=max(0,right-8)
        detail_width=min(self.detail.fontMetrics().horizontalAdvance(self._detail_text)+2,
                         max(0,available-min(48,available//3)-6))
        name_width=max(0,available-detail_width-6)
        self.title.setGeometry(8,4,name_width,row_height)
        self.detail.setGeometry(8+name_width+6,4,detail_width,row_height)
        self.title.setText(self.title.fontMetrics().elidedText(self.label,Qt.TextElideMode.ElideMiddle,name_width))
        self.detail.setText(self.detail.fontMetrics().elidedText(self._detail_text,Qt.TextElideMode.ElideRight,detail_width))
        self.bar.setGeometry(8,height-5,width-16,2)
        self.show();self.raise_()

    def set_detail(self,text,full_detail=None):
        self._detail_text=text;self._full_detail=full_detail if full_detail is not None else text
        self.setToolTip(self._path+'\n'+self._full_detail)
        self.setAccessibleName(self.label+' · '+self._full_detail)
        self.place()

    def add_note(self,text):
        self.set_detail(self._detail_text+' · '+text,self._full_detail+' · '+text)

    def set_display_seconds(self,value):
        self.display_seconds=self.normalize_seconds(value)
        if self._active and self._finished_at is not None:self.schedule_hide()

    def schedule_hide(self):
        # 설정을 바꿔도 기존 완료 시각부터 계산한다. 새 입력은 begin에서 이 타이머를 취소한다.
        remaining=self.display_seconds-(time.monotonic()-self._finished_at)
        if remaining<=0:self.dismiss()
        else:self.hide_timer.start(max(1,math.ceil(remaining*1000)))

    def dismiss(self):
        self.hide_timer.stop();self._active=False;self._finished_at=None
        self.hide();QToolTip.hideText()

    def begin(self,path,index,total):
        self.hide_timer.stop();self._finished_at=None;self._active=True
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents,False)
        self.cancel.show();self.cancel.setEnabled(True)
        self.bar.setRange(0,1000);self.bar.setValue(0)
        self.label=Path(path).name.replace('\n',' ').replace('\r',' ')+(f' · {index}/{total}' if total>1 else '')
        self._path=str(path);QToolTip.hideText()
        self.update_progress({'phase':'scan','found':0},0)

    def update_progress(self,data,pages,unit='쪽'):
        if not self._active or self._finished_at is not None:return
        self.data=dict(data)
        if data.get('name'):self._path=str(data['name'])
        if data.get('phase')=='vector':
            self.bar.setRange(0,0)
            detail=data.get('message',VECTOR_READING_MESSAGE)
            full=detail+f'\n{data.get("stage","")} · {data.get("seconds",0)}초 · 취소 가능'
        elif data.get('phase')=='text':
            self.bar.setRange(0,0)
            count=max(0,int(data.get('pages',0)));rows=max(0,int(data.get('rows',0)))
            detail=f'텍스트 페이지 구성 · {count:,}쪽'
            full=detail+f' · 표시 줄 {rows:,}개 · 취소 가능'
        elif data.get('phase')=='scan':
            found=max(0,int(data.get('found',0)))
            self.bar.setRange(0,0)
            detail='목록 확인 중'+(f' · {found:,}개' if found else '')
            full=f'목록 확인 중 · {found:,}개 발견'
        else:
            total=max(0,int(data.get('total',0)));done=max(0,int(data.get('done',0)))
            percent=min(100,max(0,100*(done+data.get('fraction',0))/total)) if total else 0
            self.bar.setRange(0,1000);self.bar.setValue(int(percent*10))
            action='목록' if data.get('phase')=='catalog' else '처리'
            detail=f'{int(percent)}% · {pages:,}{unit}'
            full=f'{int(percent)}% · {action} {done:,}/{total:,}파일 · {pages:,}{unit}'
            if data.get('frames',0)>1:full+=f' · TIFF {data["frame"]}/{data["frames"]}쪽'
        if data.get('errors'):
            detail+=f' · 오류 {data["errors"]}';full+=f' · 오류 {data["errors"]}'
        self.set_detail(detail,full)

    def stopping(self):
        self.hide_timer.stop();self._finished_at=None
        self.cancel.setEnabled(False);self.set_detail('중단 중…','읽기 중단 중 · 임시파일 확인')

    def finish(self,pages,cancelled=False,errors=0,unit='쪽'):
        if not self._active or self._finished_at is not None:return
        self.cancel.hide();self.bar.setRange(0,1000)
        if not cancelled and not errors:self.bar.setValue(1000)
        elif self.bar.value()<0:self.bar.setValue(0)
        if cancelled:
            detail=f'취소 · {pages:,}{unit}';full=f'읽기 취소 · {pages:,}{unit} 유지'
        elif errors:
            detail=f'오류 {errors:,} · {pages:,}{unit}'
            full=f'목록 확인 종료 · {pages:,}{unit} · 오류 {errors:,}개'
        else:
            detail=f'100% · 완료 · {pages:,}{unit}';full=f'100% · 목록 확인 완료 · {pages:,}{unit}'
        # 완료 안내가 떠 있는 동안에도 아래 썸네일 선택/드래그를 가로채지 않는다.
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents,True)
        self._finished_at=time.monotonic();self.set_detail(detail,full);self.schedule_hide()

class ReadingLocations(QObject):
    """Persist source-page positions; never treat temporary edit PDFs as originals."""
    def __init__(self,owner):
        super().__init__(owner);self.owner=owner;self.pending=None;self.applying=False;self.marker=None
        try:
            data=json.loads(owner.settings.value('reading/locations_v1','{}'))
            self.saved={k:v for k,v in data.items() if isinstance(v,dict) and isinstance(v.get('time',0),(int,float))} if isinstance(data,dict) else {}
        except (ValueError,TypeError):self.saved={}
        self.timer=QTimer(self);self.timer.setSingleShot(True);self.timer.setInterval(800)
        self.timer.timeout.connect(self.save_current)

    @staticmethod
    def source(page):
        if page.is_document_card or page.is_text_document or is_image_source(page.path):return None
        path=page.label_path
        if Path(path).suffix.lower()!='.pdf':return None
        try:
            canonical=os.path.normcase(os.path.realpath(path));stamp=Path(canonical).stat()
            if TEMP_ROOT.resolve() in Path(canonical).resolve().parents:return None
            return canonical,[stamp.st_size,stamp.st_mtime_ns]
        except OSError:return None

    def capture(self,editor=None):
        editor=editor or self.owner.preview_dialog
        if editor is None or editor.closed or not editor.preview_ready or editor.view.item is None:return None
        view=editor.view;rect=view.page_rect;center=view.mapToScene(view.viewport().rect().center())
        return {'uid':editor.page.uid,'path':editor.page.path,'number':editor.page.number,
                'source_number':editor.page.label_number,'zoom':view.transform().m11()/max(.001,view.fit_scale),
                'auto_fit':view.auto_fit,'center':[center.x()/max(1.,rect.width()),center.y()/max(1.,rect.height())]}

    def schedule(self,*args):
        if not self.applying and not self.owner.closing:self.timer.start()

    def save_current(self,editor=None):
        if self.applying or self.pending:return
        editor=editor or self.owner.preview_dialog
        if editor is None or editor.dual_secondary:return
        state=self.capture(editor);source=self.source(editor.page)
        if not state or not source:return
        path,stamp=source;state.update(source=path,stamp=stamp,time=time.time())
        self.saved[path]=state
        self.saved=dict(sorted(self.saved.items(),key=lambda pair:pair[1].get('time',0),reverse=True)[:100])
        self.owner.settings.setValue('reading/locations_v1',json.dumps(self.saved,ensure_ascii=False))

    def choose_initial(self,pages):
        if not pages:return None
        source=self.source(pages[0])
        if not source:return None
        value=self.saved.get(source[0])
        if not isinstance(value,dict) or value.get('stamp')!=source[1]:return None
        page=next((p for p in pages if p.label_number==value.get('source_number')),None)
        if page is None:return None
        try:
            zoom=float(value['zoom']);center=[float(v) for v in value['center']]
            if len(center)!=2 or not all(math.isfinite(v) for v in [zoom,*center]):return None
        except (TypeError,ValueError,KeyError):return None
        self.pending={**value,'uid':page.uid,'path':page.path,'number':page.number}
        return page

    def attach(self,editor):
        editor.view.zoomChanged.connect(self.schedule)
        editor.view.verticalScrollBar().valueChanged.connect(self.schedule)
        editor.view.horizontalScrollBar().valueChanged.connect(self.schedule)
        editor.search_overlay=SearchMatchOverlay(editor,self)

    def image_ready(self,editor):
        if hasattr(editor,'search_overlay'):editor.search_overlay.update()
        state=self.pending
        if state and editor is self.owner.preview_dialog and state['uid']==editor.page.uid:
            QTimer.singleShot(0,lambda:self.apply_pending(editor,state))

    def apply_pending(self,editor,state):
        if self.pending is not state or editor.closed or editor.page.uid!=state['uid'] or not editor.preview_ready:return
        self.pending=None;self.applying=True
        try:
            view=editor.view;view.fit_timer.stop()
            if state.get('rects'):
                rect=view.page_box(state['rects'][0]);view.centerOn(rect.center())
                self.marker={'uid':editor.page.uid,'state_key':editor.page.state_key,'rects':state['rects']}
            else:
                view.fitInView(view.sceneRect(),Qt.AspectRatioMode.KeepAspectRatio)
                view.fit_scale=view.transform().m11();view.auto_fit=bool(state.get('auto_fit',False))
                if not view.auto_fit:
                    zoom=max(.25,min(12.,float(state.get('zoom',1.))));view.scale(zoom,zoom)
                    center=state.get('center',[.5,.5]);view.centerOn(center[0]*view.page_rect.width(),center[1]*view.page_rect.height())
                self.marker=None
            editor.changed_zoom()
            if hasattr(editor,'search_overlay'):editor.search_overlay.update()
        finally:self.applying=False
        self.schedule()

    def jump(self,state):
        page=self.owner.by_id.get(state.get('uid'))
        if page is None:return False
        editor=self.owner.preview_dialog
        if editor is None or editor.closed:return False
        self.save_current(editor);self.pending=dict(state)
        if not editor.navigate_to_page(page):self.pending=None;return False
        if editor.page.uid==page.uid and editor.preview_ready:self.image_ready(editor)
        return True


class SearchMatchOverlay(QWidget):
    def __init__(self,editor,locations):
        super().__init__(editor.view.viewport());self.editor=editor;self.locations=locations
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        self.setGeometry(self.parentWidget().rect());self.parentWidget().installEventFilter(self)
        editor.view.zoomChanged.connect(self.update)
        editor.view.verticalScrollBar().valueChanged.connect(self.update)
        editor.view.horizontalScrollBar().valueChanged.connect(self.update);self.show()
    def eventFilter(self,obj,event):
        if event.type()==QEvent.Type.Resize:self.setGeometry(obj.rect())
        return False
    def paintEvent(self,event):
        marker=self.locations.marker;editor=self.editor
        if not marker or marker['uid']!=editor.page.uid or marker['state_key']!=editor.page.state_key:return
        painter=QPainter(self);painter.setPen(QPen(QColor('#f2b544'),1.2));painter.setBrush(QColor(255,207,65,80))
        for box in marker['rects']:
            rect=editor.view.page_box(box);painter.drawPolygon(editor.view.mapFromScene(rect))
        painter.end()


class SearchCardDelegate(QStyledItemDelegate):
    def document(self,index,width):
        doc=QTextDocument();doc.setDefaultFont(QFont('Sans Serif',10));doc.setDocumentMargin(0)
        doc.setHtml(index.data(Qt.ItemDataRole.UserRole+1) or '')
        doc.setTextWidth(max(100,width-24));return doc
    def sizeHint(self,option,index):
        width=self.parent().viewport().width()-12;doc=self.document(index,width)
        return QSize(width,int(doc.size().height())+24)
    def paint(self,painter,option,index):
        painter.save();rect=option.rect.adjusted(3,3,-3,-3)
        selected=bool(option.state & QStyle.StateFlag.State_Selected)
        painter.setPen(QPen(QColor('#d59645' if selected else '#42516a'),1))
        painter.setBrush(QColor('#35465f' if selected else '#263245'));painter.drawRoundedRect(rect,6,6)
        painter.translate(option.rect.left()+12,option.rect.top()+12)
        doc=self.document(index,option.rect.width());doc.drawContents(painter);painter.restore()


class PdfSearchPanel(QWidget):
    LIMIT=500
    def __init__(self,owner):
        super().__init__(owner.thumbnail_host);self.owner=owner;self.generation=0;self.pending=False
        self.targets=[];self.cursor=0;self.query='';self.origin=None;self.results=[];self.errors=[];self.truncated=False
        self.scope=None;self.active_page=None;self.source_states=();self.dirty=False
        self.setObjectName('pdfSearchPanel');self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground);self.setMinimumHeight(230)
        self.setStyleSheet('QWidget#pdfSearchPanel{background:#1d2635;border-top:1px solid #53647d;} QLineEdit{background:#111b29;color:#edf2fa;border:1px solid #647997;border-radius:4px;padding:6px;} QToolButton{background:#304058;color:#edf2fa;border:1px solid #526781;border-radius:4px;padding:5px;} QToolButton:disabled{color:#8390a2;} QLabel{color:#c1cddd;} QListWidget{background:#1d2635;border:0;outline:0;}')
        layout=QVBoxLayout(self);layout.setContentsMargins(8,7,8,7);layout.setSpacing(5)
        row=QHBoxLayout();self.input=QLineEdit();self.input.setObjectName('pdf_search_input')
        self.input.setPlaceholderText('PDF 검색 · Enter');self.input.setMaxLength(300);row.addWidget(self.input,1)
        self.find_button=QToolButton();self.find_button.setText('검색');self.find_button.clicked.connect(self.start);row.addWidget(self.find_button)
        self.close_button=QToolButton();self.close_button.setText('×');self.close_button.setToolTip('검색 닫기 · Esc');self.close_button.clicked.connect(self.close_panel);row.addWidget(self.close_button);layout.addLayout(row)
        row=QHBoxLayout();self.status=QLabel('검색어를 입력하세요.');self.status.setWordWrap(True);row.addWidget(self.status,1)
        self.back=QToolButton();self.back.setText('검색 전 위치');self.back.setEnabled(False);self.back.clicked.connect(self.return_origin);row.addWidget(self.back);layout.addLayout(row)
        self.list=QListWidget();self.list.setObjectName('pdf_search_results');self.list.setSpacing(3)
        self.list.setItemDelegate(SearchCardDelegate(self.list));self.list.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.list.itemClicked.connect(self.activate);self.list.itemActivated.connect(self.activate);layout.addWidget(self.list,1)
        self.input.returnPressed.connect(self.start)
        self.escape=QShortcut(QKeySequence('Esc'),self);self.escape.setContext(Qt.ShortcutContext.WidgetWithChildrenShortcut);self.escape.activated.connect(self.close_panel)
        self.backend=PdfBackend(self,lazy=True);self.backend.searchResult.connect(self.received)
        self.timer=QTimer(self);self.timer.setSingleShot(True);self.timer.timeout.connect(self.next_page)
        self.hide()

    def show_panel(self):
        if self.owner.book_focus:self.owner.set_book_focus(False)
        if self.owner.thumbnails_collapsed:self.owner.toggle_thumbnail_panel()
        self.setMaximumHeight(max(240,int(self.owner.height()*.55)))
        if not self.isVisible():
            self.origin=None;self.back.setEnabled(False);self.results=[];self.list.clear()
            self.status.setText('검색어를 입력하고 Enter를 누르세요.')
        self.show();self.input.setFocus();self.input.selectAll()

    def cancel(self):
        self.generation+=1;self.timer.stop();self.backend.jobs=[];self.pending=False;self.active_page=None

    def close_panel(self):
        self.cancel();self.hide();self.owner.locations.marker=None
        editor=self.owner.preview_dialog
        if editor is not None:
            if hasattr(editor,'search_overlay'):editor.search_overlay.update()
            editor.view.setFocus()

    def document_pages(self):
        editor=self.owner.preview_dialog
        if editor is None or editor.closed:return []
        page=editor.page
        if page.is_document_card or page.is_text_document or is_image_source(page.path):return []
        self.scope=(page.label_path,getattr(page,'comparison_group',''))
        return [p for p in self.owner.pages if not p.is_document_card and not p.is_text_document and not is_image_source(p.path)
                and (p.label_path,getattr(p,'comparison_group',''))==self.scope]

    def start(self):
        query=self.input.text().strip();self.cancel();self.list.clear();self.results=[];self.errors=[];self.truncated=False
        if not query:self.status.setText('검색어를 입력하세요.');return
        if self.owner.pending_import or self.owner.imports:self.status.setText('파일을 모두 연 뒤 검색하세요.');return
        self.targets=list(self.document_pages());self.cursor=0;self.query=query
        if not self.targets:self.status.setText('PDF 문서를 연 뒤 검색하세요.');return
        if self.origin is None or self.origin.get('scope')!=self.scope:
            self.origin=self.owner.locations.capture()
            if self.origin:self.origin['scope']=self.scope
        self.back.setEnabled(self.origin is not None)
        self.source_states=tuple((p.uid,p.state_key) for p in self.targets)
        self.owner.locations.marker=None
        editor=self.owner.preview_dialog
        if editor is not None and hasattr(editor,'search_overlay'):editor.search_overlay.update()
        self.next_page()

    def next_page(self):
        if not self.isVisible() or self.owner.closing or self.pending:return
        if self.cursor>=len(self.targets) or len(self.results)>=self.LIMIT:
            self.truncated|=self.cursor<len(self.targets)
            self.status.setText(f'{len(self.results)}개 결과 · {self.cursor}/{len(self.targets)}쪽 검색'+(' · 일부 결과 생략' if self.truncated else '')+(' · '+str(len(self.errors))+'쪽 검색 실패' if self.errors else '')+(' · 스캔 문서는 문자 정보가 필요합니다.' if not self.results and not self.errors else ''))
            self.status.setToolTip('\n'.join(self.errors));return
        # Visible-page requests take priority over the next search page.
        editors=[e for e in (self.owner.preview_dialog,self.owner.dual_preview) if e is not None and not e.closed]
        if any(not e.preview_ready or e.nav_target_uid is not None or
               (e.backend.active and e.backend.active['op']=='preview') for e in editors):self.timer.start(100);return
        page=self.targets[self.cursor];current=self.owner.by_id.get(page.uid)
        if current is None or current.state_key!=page.state_key:self.start();return
        self.active_page=page;self.pending=True
        self.status.setText(f'{len(self.results)}개 결과 · {self.cursor+1}/{len(self.targets)}쪽 검색 중')
        self.backend.request('search',page.path,page.number,token=self.generation,priority=True,
            payload={'query':self.query,'limit':min(100,self.LIMIT-len(self.results))})

    def received(self,token,data,error):
        if token!=self.generation or not self.pending:return
        self.pending=False;page=self.active_page;self.active_page=None
        if page is None:return
        current=self.owner.by_id.get(page.uid)
        if current is None or current.state_key!=page.state_key:self.start();return
        if error:self.errors.append(f'{self.cursor+1}쪽: {error}')
        else:
            self.truncated|=bool(data.get('truncated'))
            for hit in data.get('hits',[]):
                record={**hit,'uid':page.uid,'path':page.path,'number':page.number,'state_key':page.state_key,'page_label':self.cursor+1}
                self.results.append(record);item=QListWidgetItem();item.setData(Qt.ItemDataRole.UserRole,record)
                esc=lambda value:html.escape(value).replace('\n','<br>')
                card=(f'<div style="color:#a9c5eb;font-size:11px;">{self.cursor+1}쪽 · 결과 {len(self.results)}</div>'
                      '<div style="color:#dce5f2;line-height:125%;margin-top:5px;">'+esc(hit['before'])+
                      '<span style="background-color:#f5ce66;color:#151e2b;font-weight:bold;">'+esc(hit['match'])+'</span>'+esc(hit['after'])+'</div>')
                item.setData(Qt.ItemDataRole.UserRole+1,card);item.setToolTip(hit['before']+hit['match']+hit['after']);self.list.addItem(item)
        self.cursor+=1;self.timer.start(30)

    def activate(self,item):
        value=item.data(Qt.ItemDataRole.UserRole);page=self.owner.by_id.get(value['uid'])
        if page is None or page.state_key!=tuple(value['state_key']):self.status.setText('페이지가 변경됐습니다. 다시 검색하세요.');return
        self.owner.locations.jump(value)

    def return_origin(self):
        if self.origin and not self.owner.locations.jump(self.origin):self.status.setText('검색을 시작한 페이지가 닫혔습니다.')

    def changed(self):
        if not self.isVisible() or not self.query:return
        states=tuple((p.uid,p.state_key) for p in self.owner.pages if (p.label_path,getattr(p,'comparison_group',''))==self.scope)
        if states!=self.source_states:
            self.cancel();self.results=[];self.list.clear();self.source_states=states
            self.status.setText('문서가 변경됐습니다. Enter로 다시 검색하세요.')

    def resizeEvent(self,event):
        super().resizeEvent(event);self.list.scheduleDelayedItemsLayout()

    def shutdown(self):
        self.cancel();self.backend.stop()



