class PrintCommitNumber(QLineEdit):
    valueChanged = Signal(float)
    draftChanged = Signal()

    def __init__(self, value=0., minimum=0., maximum=100., integer=False, parent=None):
        super().__init__(parent)
        self.minimum=minimum; self.maximum=maximum; self.integer=integer
        self._value=int(value) if integer else float(value); self._setting=False; self._pending=False
        self.setAlignment(Qt.AlignmentFlag.AlignRight)
        self.setMinimumWidth(65); self.setToolTip('숫자 입력 → Enter 확정 · Esc 되돌리기 · 휠로 값이 바뀌지 않습니다.')
        self.setValue(value); self.textChanged.connect(self.draft_changed)

    def value(self):return self._value
    def has_pending(self):return self._pending

    def setValue(self, value):
        value=int(value) if self.integer else round(float(value),2)
        if not self.minimum<=value<=self.maximum:raise ValueError('수치 범위를 확인하세요.')
        changed=value!=self._value; self._value=value; self._setting=True
        self.setText(str(value) if self.integer else f'{value:.2f}'.rstrip('0').rstrip('.'))
        self._setting=False; self._pending=False; self.setStyleSheet('')
        if changed:self.valueChanged.emit(float(value))

    def draft_changed(self, *_):
        if self._setting:return
        self._pending=True
        self.setStyleSheet('QLineEdit{border:2px solid #f34f6e;background:#3b2734;color:#ffffff;}')
        self.draftChanged.emit()

    def commit(self):
        text=self.text().strip()
        try:
            if not re.fullmatch(r'[+-]?\d+(?:\.\d{0,2})?',text):raise ValueError()
            value=float(text)
            if not math.isfinite(value) or not self.minimum<=value<=self.maximum:raise ValueError()
            if self.integer and not value.is_integer():raise ValueError()
        except ValueError:
            self.setToolTip(f'{self.minimum:g}~{self.maximum:g} 범위의 '+('정수' if self.integer else '숫자(소수 2자리까지)')+'를 입력하고 Enter를 누르세요.')
            self.draftChanged.emit();return False
        old=self._value;self.setValue(value)
        if old==self._value:self.valueChanged.emit(float(self._value))
        self.draftChanged.emit();return True

    def keyPressEvent(self,event):
        if event.key() in (Qt.Key.Key_Return,Qt.Key.Key_Enter):self.commit();event.accept();return
        if event.key()==Qt.Key.Key_Escape:
            self.setValue(self._value);self.valueChanged.emit(float(self._value));self.draftChanged.emit();event.accept();return
        super().keyPressEvent(event)

    def wheelEvent(self,event):event.ignore()


