class PrintNupTile(QToolButton):
    def __init__(self, count, parent=None):
        super().__init__(parent);self.count=count;self.orientation='portrait';self.setCheckable(True)
        self.setFixedSize(84,91);self.setIconSize(QSize(72,62));self.setText(f'{count}쪽')
        self.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextUnderIcon)
        self.setToolTip(f'한 면에 {count}쪽 · 다시 누르면 선택 해제')
        self.toggled.connect(self.refresh_icon);self.refresh_icon()

    def refresh_icon(self,*_):
        pix=QPixmap(72,62);pix.fill(Qt.GlobalColor.transparent);p=QPainter(pix);p.setRenderHint(QPainter.RenderHint.Antialiasing)
        landscape=self.orientation=='landscape';rect=QRectF(6,12,60,42) if landscape else QRectF(17,3,38,54)
        p.setPen(QPen(QColor('#ef7892' if self.isChecked() else '#9babc3'),1));p.setBrush(QColor('#f4f5f9'));p.drawRoundedRect(rect,2,2)
        columns,rows=print_grid_shape(self.count,self.orientation);area=rect.adjusted(4,4,-4,-4)
        w=area.width()/columns;h=area.height()/rows
        for row in range(rows):
            for col in range(columns):
                box=QRectF(area.x()+col*w+1,area.y()+row*h+1,w-2,h-2)
                p.setPen(QPen(QColor('#be425e' if self.isChecked() else '#5c7093'),.7))
                p.setBrush(QColor('#f9dce4' if self.isChecked() else '#dfe6f0'));p.drawRect(box)
                if self.count<=6:
                    font=p.font();font.setPixelSize(8);p.setFont(font);p.drawText(box,Qt.AlignmentFlag.AlignCenter,str(row*columns+col+1))
        if self.isChecked():
            p.setPen(QPen(QColor('#ff6686'),2.5));p.drawLine(QPointF(56,5),QPointF(60,9));p.drawLine(QPointF(60,9),QPointF(67,1))
        p.end();self.setIcon(QIcon(pix))


class PrintNupPicker(QWidget):
    valueChanged=Signal(int)
    def __init__(self,parent=None):
        super().__init__(parent);self._value=1;self.tiles={}
        layout=QVBoxLayout(self);layout.setContentsMargins(0,0,0,0);layout.setSpacing(6)
        row=QHBoxLayout();self.single=QToolButton();self.single.setText('1쪽 인쇄');self.single.setCheckable(True)
        self.multiple=QToolButton();self.multiple.setText('여러 쪽 인쇄');self.multiple.setCheckable(True)
        row.addWidget(self.single,1);row.addWidget(self.multiple,1);layout.addLayout(row)
        self.panel=QWidget();grid=QGridLayout(self.panel);grid.setContentsMargins(0,0,0,0);grid.setSpacing(5)
        for i,count in enumerate(PRINT_NUP[1:]):
            button=PrintNupTile(count);self.tiles[count]=button;grid.addWidget(button,i//3,i%3)
            button.clicked.connect(lambda _checked=False,n=count:self.choose(n))
        layout.addWidget(self.panel);self.panel.hide();self.single.setChecked(True)
        self.single.clicked.connect(lambda:self.setValue(1))
        self.multiple.clicked.connect(self.toggle_panel)

    def currentData(self):return self._value
    def setValue(self,value,keep_open=False):
        if value not in PRINT_NUP:raise ValueError('모아찍기 배치가 올바르지 않습니다.')
        changed=value!=self._value;self._value=value
        for n,button in self.tiles.items():button.setChecked(n==value)
        self.single.setChecked(value==1);self.multiple.setChecked(value>1 or keep_open)
        self.panel.setVisible(value>1 or keep_open)
        if changed:self.valueChanged.emit(value)
    def choose(self,count):self.setValue(1 if self._value==count else count,keep_open=True)
    def toggle_panel(self,checked):
        if checked:self.panel.show()
        else:self.setValue(1)
    def set_orientation(self,orientation):
        for button in self.tiles.values():button.orientation=orientation;button.refresh_icon()


