        right = QVBoxLayout(); body.addLayout(right,1); self.preview = PrintPreviewCanvas(); right.addWidget(self.preview,1)
        nav = QHBoxLayout(); self.previous = QPushButton('‹'); self.next = QPushButton('›'); self.previous.setFixedWidth(38); self.next.setFixedWidth(38)
        self.face_label = QLabel(''); self.face_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.previous.clicked.connect(lambda:self.change_face(-1)); self.next.clicked.connect(lambda:self.change_face(1))
        nav.addStretch(); nav.addWidget(self.previous); nav.addWidget(self.face_label); nav.addWidget(self.next); nav.addStretch(); right.addLayout(nav)
        self.status = QLabel(''); self.status.setWordWrap(True); self.status.setMinimumHeight(30); root.addWidget(self.status)
