# Conversion implementations for the permissive/LGPL engine build.
# This file is appended to the viewer after its original definitions.
# Qt rich text is deliberately used without QtWebEngine or a web browser.

_VIEWER_QT_CONVERSION_APP = None
_VIEWER_PDF_DPI = 96


def _viewer_conversion_app():
    """Document workers need a GUI font engine; no windows are opened."""
    global _VIEWER_QT_CONVERSION_APP
    from PySide6.QtGui import QGuiApplication
    app = QGuiApplication.instance()
    if app is None:
        if sys.platform != 'win32' and not os.environ.get('DISPLAY'):
            os.environ.setdefault('QT_QPA_PLATFORM', 'offscreen')
        _VIEWER_QT_CONVERSION_APP = QGuiApplication(['TheViewerDocumentWorker'])
        app = _VIEWER_QT_CONVERSION_APP
    return app


def _viewer_conversion_font(text='', size=10):
    """Use installed fonts only. Microsoft fonts are never redistributed."""
    from PySide6.QtGui import QFont, QFontDatabase, QRawFont
    _viewer_conversion_app()
    families = set(safe_font_families())
    preferred = ('Malgun Gothic', '맑은 고딕', 'Noto Sans CJK KR', 'Noto Sans KR',
                 'NanumGothic', 'Apple SD Gothic Neo', 'Arial', 'DejaVu Sans')
    needs_hangul = any('\uac00' <= char <= '\ud7a3' for char in text)
    choices = [family for family in preferred if family in families]
    choices.extend(sorted(families - set(choices)))
    for family in choices:
        font = QFont(family)
        font.setPointSizeF(float(size))
        # Avoid optional OpenType substitutions whose alternate glyphs can be
        # missing from Qt PDF's ToUnicode map. Mandatory script shaping remains
        # controlled by Qt's text engine.
        font.setStyleStrategy(QFont.PreferNoShaping)
        if not needs_hangul or QRawFont.fromFont(font).supportsCharacter(ord('한')):
            return font
    if needs_hangul:
        raise ValueError('한글 글꼴을 찾지 못했습니다. 맑은 고딕 또는 Noto Sans CJK KR 등 한글 글꼴을 설치한 뒤 다시 열어 주세요.')
    font = QFont()
    font.setPointSizeF(float(size))
    font.setStyleStrategy(QFont.PreferNoShaping)
    return font


def _viewer_pdf_layout(writer, width, height):
    from PySide6.QtCore import QMarginsF, QSizeF
    from PySide6.QtGui import QPageLayout, QPageSize
    size = QPageSize(QSizeF(float(width), float(height)), QPageSize.Point,
                     'The Viewer document', QPageSize.ExactMatch)
    layout = QPageLayout(size, QPageLayout.Portrait, QMarginsF(0, 0, 0, 0),
                         QPageLayout.Point)
    if not writer.setPageLayout(layout):
        raise ValueError('PDF 용지 크기를 적용하지 못했습니다.')


def render_plain_text(source, directory, options=None, encoding='auto', emit=lambda _d: None):
    """Paginate selectable Unicode text with Qt; never execute source text."""
    from PySide6.QtCore import QPointF
    from PySide6.QtGui import QColor, QFont, QFontMetricsF, QPainter, QPdfWriter
    state = read_plain_text(source, encoding)
    settings = text_render_options(options)
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / ('text_' + uuid.uuid4().hex + '.pdf')
    font = _viewer_conversion_font(state.text, settings['font_size'])
    writer = QPdfWriter(str(target))
    writer.setResolution(_VIEWER_PDF_DPI)
    writer.setTitle(Path(source).name)
    writer.setCreator(APP_NAME + ' ' + APP_VERSION)
    _viewer_pdf_layout(writer, 595.28, 841.89)
    metrics = QFontMetricsF(font, writer)
    scale = _VIEWER_PDF_DPI / 72
    point = settings['font_size']
    row_height = max(point * settings['line_spacing'], metrics.height() / scale + 1)
    rows_per_page = max(1, int((841.89 - 110) / row_height))
    class WidthFont:
        def text_length(self, value, fontsize=None):
            return metrics.horizontalAdvance(value) / scale
    page_offsets, rows = [], []
    page_count = total_rows = 0
    last = time.monotonic()
    painter = QPainter()
    try:
        if not painter.begin(writer):
            raise PlainTextError('텍스트 PDF 출력 장치를 시작하지 못했습니다.')
        def flush():
            nonlocal rows, page_count
            if not rows:
                return
            if page_count >= TEXT_MAX_PAGES:
                raise PlainTextError('텍스트 10,000쪽 한도를 초과했습니다.')
            if page_count and not writer.newPage():
                raise PlainTextError('텍스트 PDF의 다음 쪽을 만들지 못했습니다.')
            page_count += 1
            page_offsets.append(rows[0][1])
            painter.setFont(font)
            painter.setPen(QColor('#14171c'))
            baseline = 54 * scale + metrics.ascent()
            for index, (line, _) in enumerate(rows):
                if line:
                    painter.drawText(QPointF(52 * scale, baseline + index * row_height * scale), line)
            small = QFont(font)
            small.setPointSizeF(8)
            painter.setFont(small)
            painter.setPen(QColor('#737373'))
            painter.drawText(QPointF(52 * scale, 823 * scale), f'TEXT / {page_count}')
            rows = []
        for row in text_visual_rows(state.text, WidthFont(), settings):
            rows.append(row)
            total_rows += 1
            if len(rows) >= rows_per_page:
                flush()
            if time.monotonic() - last > .12:
                emit({'phase': 'text', 'name': str(source), 'pages': page_count, 'rows': total_rows})
                last = time.monotonic()
        flush()
        if not page_count:
            raise PlainTextError('텍스트 페이지를 구성하지 못했습니다.')
    except BaseException:
        if painter.isActive():
            painter.end()
        del writer
        target.unlink(missing_ok=True)
        raise
    else:
        painter.end()
        del writer
    if hashlib.sha256(Path(source).read_bytes()).hexdigest() != state.sha256:
        target.unlink(missing_ok=True)
        raise PlainTextError('읽는 동안 원본 텍스트가 변경됐습니다. 다시 열어주세요.')
    return {'path': str(target), 'count': page_count,
            'source_path': str(Path(source).resolve()), 'text': True,
            'text_info': {'encoding': state.codec, 'sha256': state.sha256,
                          'page_offsets': page_offsets, 'options': settings,
                          'note': state.note, 'mixed_newlines': state.mixed}}


_LegacyNativeHangulPDF = NativeHangulPDF


class NativeHangulPDF(_LegacyNativeHangulPDF):
    """Offline approximate HWP/HWPX reader using Qt rich text and PDF output.

    Reuses the existing XML parser and its explicit approximation reports.
    Text, tables and bitmap images remain supported; exact Hancom layout is
    not promised. HTML resources are served solely from the document ZIP.
    """
    def __init__(self, source, emit):
        import zipfile
        from lxml import etree
        from hwpx import HwpxDocument
        self.emit = emit
        self.notes, self.assets, self.floats = [], {}, []
        self._qt_resources = {}
        self.page_number = 1
        emit('한글 문단·표·그림 분석')
        if Path(source).stat().st_size > 256 * 1024 * 1024:
            raise ValueError('간편 한글 읽기는 256 MB 이하의 문서를 지원합니다.')
        document = HwpxDocument.open(source)
        try:
            report = getattr(document, 'conversion_report', None)
            self.hwp_report = str(report)[:4000] if report else ''
            if report:
                self.note('HWP5를 HWPX 구조로 변환했습니다. 전용 개체와 서식을 원본과 비교해 주세요.')
            data = document.to_bytes()
        finally:
            close = getattr(document, 'close', None)
            if close:
                close()
        self.parts = {}
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            infos = archive.infolist()
            if len(infos) > 20000 or sum(info.file_size for info in infos) > 512 * 1024 * 1024:
                raise ValueError('한글 내부 데이터가 간편 읽기 제한을 초과했습니다.')
            for info in infos:
                if not info.is_dir():
                    self.parts[info.filename] = archive.read(info)
        def parse(raw):
            return etree.fromstring(raw, etree.XMLParser(resolve_entities=False, no_network=True))
        self.parse = parse
        self.header = parse(self.parts['Contents/header.xml'])
        self.para = {node.get('id'): node for node in self.header.iter(self.HH + 'paraPr')}
        self.char = {node.get('id'): node for node in self.header.iter(self.HH + 'charPr')}
        self.borders = {node.get('id'): node for node in self.header.iter(self.HH + 'borderFill')}
        self.resources = {}
        manifest = parse(self.parts['Contents/content.hpf'])
        for item in manifest.iter():
            if self.local(item) == 'item':
                path = item.get('href', '').replace('\\', '/').lstrip('./')
                if path not in self.parts and 'Contents/' + path in self.parts:
                    path = 'Contents/' + path
                if path in self.parts:
                    self.resources[item.get('id', '')] = path
        names = [name for name in self.parts if re.fullmatch(r'Contents/section\d+\.xml', name)]
        self.sections = [parse(self.parts[name]) for name in sorted(
            names, key=lambda name: int(re.search(r'(\d+)\.xml', name).group(1)))]
        if not self.sections:
            raise ValueError('한글 문서에 본문 구역이 없습니다.')
        self.css = ('body{font-size:10pt;margin:0;padding:0;}'
                    'p{margin:0;}table{border-collapse:collapse;margin-bottom:4pt;}'
                    'td{vertical-align:top;} .object{border:0.5pt solid #888;padding:3pt;}')
        self.note('간편 한글 변환: 설치 글꼴·줄 나눔·쪽 나눔과 겹친 개체 위치는 한글의 출력과 다를 수 있습니다.')

    def picture(self, node):
        from PySide6.QtGui import QImage
        image = node.find('.//' + self.HC + 'img')
        ref = image.get('binaryItemIDRef', '') if image is not None else ''
        part = self.resources.get(ref)
        if not part:
            part = next((name for name in self.parts if name.startswith('BinData/') and
                         Path(name).stem.lower() == ref.lower()), None)
        if not part:
            self.note('찾지 못한 그림 개체가 있습니다.')
            return '<span>[그림 데이터 없음]</span>'
        if part not in self.assets:
            # Qt may have platform metafile handlers. Only bitmap resources are
            # accepted here so unsupported vector/OLE objects never run helpers.
            if Path(part).suffix.lower() in ('.wmf', '.emf', '.svg', '.eps', '.ps'):
                self.note('지원하지 않는 그림 형식(WMF/EMF 등)이 있습니다.')
                return '<span>[지원하지 않는 그림]</span>'
            raw = self.parts[part]
            from PIL import Image
            try:
                with Image.open(io.BytesIO(raw)) as bitmap:
                    if bitmap.width * bitmap.height > 80_000_000:
                        raise ValueError('그림 크기 제한')
                bitmap = QImage.fromData(raw)
                if bitmap.isNull():
                    with Image.open(io.BytesIO(raw)) as fallback:
                        output = io.BytesIO()
                        fallback.convert('RGBA').save(output, format='PNG')
                        bitmap = QImage.fromData(output.getvalue())
                if bitmap.isNull():
                    raise ValueError('그림 형식')
            except Exception:
                self.note('지원하지 않는 그림 형식(WMF/EMF 등)이 있습니다.')
                return '<span>[지원하지 않는 그림]</span>'
            name = 'viewer-resource:asset' + str(len(self.assets))
            self.assets[part] = name
            self._qt_resources[name] = bitmap
        size = node.find(self.HP + 'sz')
        width = self.unit(size.get('width'), 120) if size is not None else 120
        height = self.unit(size.get('height'), 80) if size is not None else 80
        fit = min(1, self.body_width / max(1, width), self.body_height / max(1, height))
        rotation = node.find(self.HP + 'rotationInfo')
        if rotation is not None and self.number(rotation.get('angle')):
            self.note('회전된 한글 그림은 회전 없이 배치했습니다.')
        return (f'<img src="{self.assets[part]}" width="{max(1, width * fit) * 96 / 72:.2f}" '
                f'height="{max(1, height * fit) * 96 / 72:.2f}"/>')

    def _document(self, markup, writer, font, page_width, page_height=None):
        from PySide6.QtCore import QSizeF
        from PySide6.QtGui import QTextDocument
        resources = self._qt_resources
        class PrivateDocument(QTextDocument):
            def loadResource(self, resource_type, url):
                # Never use the base implementation: it can read arbitrary
                # file: URLs. The XML parser emits only our private resources.
                return resources.get(url.toString())
        document = PrivateDocument()
        document.documentLayout().setPaintDevice(writer)
        document.setDefaultFont(font)
        document.setDocumentMargin(0)
        document.setDefaultStyleSheet(self.css)
        if page_height is None:
            document.setTextWidth(page_width)
        else:
            document.setPageSize(QSizeF(page_width, page_height))
        document.setHtml(markup or '<p>&#160;</p>')
        self._format_tables(document, markup)
        return document

    def _format_tables(self, document, markup):
        """Qt HTML ignores CSS table widths/borders: apply native formats."""
        if '<table' not in markup.lower():
            return
        from lxml import html as html_parser
        from PySide6.QtGui import (QBrush, QColor, QTextFrameFormat,
                                  QTextLength, QTextTable)
        scale = _VIEWER_PDF_DPI / 72
        root = html_parser.fragment_fromstring(markup, create_parent='div')
        html_tables = root.findall('.//table')
        qt_tables = []
        def walk(frame):
            for child in frame.childFrames():
                if isinstance(child, QTextTable):
                    qt_tables.append(child)
                walk(child)
        walk(document.rootFrame())
        def style(element):
            return dict((key.strip().lower(), value.strip()) for item in
                        element.get('style', '').split(';') if ':' in item
                        for key, value in [item.split(':', 1)])
        def pixels(value, default=0):
            match = re.match(r'^(-?[\d.]+)\s*(pt|px)?', str(value or ''))
            if not match:
                return default
            return self.number(match.group(1), default) * (scale if match.group(2) == 'pt' else 1)
        if len(html_tables) != len(qt_tables):
            self.note('중첩 표 구조 일부는 Qt에서 단순화되어 원본 표와 다를 수 있습니다.')
        for element, table in zip(html_tables, qt_tables):
            styles = style(element)
            table_format = table.format()
            target_width = pixels(styles.get('width'), self.body_width * scale)
            table_format.setWidth(QTextLength(QTextLength.FixedLength, target_width))
            table_format.setCellSpacing(0)
            table_format.setCellPadding(0)
            table_format.setBorder(0)
            widths = [0.] * table.columns()
            for row_index, row in enumerate(element.findall('./tr')):
                column = 0
                for html_cell in row.findall('./td'):
                    while column < table.columns() and table.cellAt(row_index, column).row() != row_index:
                        column += 1
                    if row_index >= table.rows() or column >= table.columns():
                        break
                    cell = table.cellAt(row_index, column)
                    if not cell.isValid():
                        break
                    cell_styles = style(html_cell)
                    cell_format = cell.format().toTableCellFormat()
                    padding = pixels(cell_styles.get('padding'), 2 * scale)
                    for side in ('Left', 'Right', 'Top', 'Bottom'):
                        getattr(cell_format, 'set' + side + 'Padding')(
                            pixels(cell_styles.get('padding-' + side.lower()), padding))
                        value = cell_styles.get('border-' + side.lower(), '')
                        match = re.match(r'^([\d.]+)\s*(pt|px)?\s+\w+\s+(#[0-9a-fA-F]{6})', value)
                        if match:
                            getattr(cell_format, 'set' + side + 'Border')(pixels(match.group(1) + (match.group(2) or 'px')))
                            getattr(cell_format, 'set' + side + 'BorderStyle')(QTextFrameFormat.BorderStyle_Solid)
                            getattr(cell_format, 'set' + side + 'BorderBrush')(QBrush(QColor(match.group(3))))
                        else:
                            getattr(cell_format, 'set' + side + 'Border')(0)
                    if 'background-color' in cell_styles:
                        cell_format.setBackground(QColor(cell_styles['background-color']))
                    cell.setFormat(cell_format)
                    span = max(1, cell.columnSpan())
                    cell_width = pixels(cell_styles.get('width')) + cell_format.leftPadding() + cell_format.rightPadding()
                    for index in range(column, min(table.columns(), column + span)):
                        widths[index] = max(widths[index], cell_width / span)
                    column += span
            if any(widths):
                fallback = target_width / max(1, len(widths))
                widths = [width or fallback for width in widths]
                ratio = target_width / max(1, sum(widths))
                table_format.setColumnWidthConstraints([
                    QTextLength(QTextLength.FixedLength, width * ratio) for width in widths])
            table.setFormat(table_format)
        # Table edits can leave later blocks outside Qt's previous dirty range.
        # Reflow the entire document so its last paragraphs are never omitted.
        document.markContentsDirty(0, document.characterCount())

    def write(self, target):
        from PySide6.QtCore import QPointF, QRectF
        from PySide6.QtGui import QPainter, QPdfWriter, QAbstractTextDocumentLayout
        _viewer_conversion_app()
        source_text = ''.join(''.join(section.itertext()) for section in self.sections)
        font = _viewer_conversion_font(source_text, 10)
        target = Path(target)
        target.parent.mkdir(parents=True, exist_ok=True)
        writer = QPdfWriter(str(target))
        writer.setResolution(_VIEWER_PDF_DPI)
        writer.setTitle(target.stem)
        writer.setCreator(APP_NAME + ' ' + APP_VERSION)
        painter = QPainter()
        page_count = 0
        scale = _VIEWER_PDF_DPI / 72
        try:
            for section in self.sections:
                self.geometry(section)
                _viewer_pdf_layout(writer, self.width, self.height)
                if not painter.isActive() and not painter.begin(writer):
                    raise ValueError('한글 PDF 출력 장치를 시작하지 못했습니다.')
                groups = [[]]
                for paragraph in section:
                    if self.local(paragraph) != 'p':
                        continue
                    if paragraph.get('pageBreak') == '1' and groups[-1]:
                        groups.append([])
                    groups[-1].append(paragraph)
                decorations = []
                for kind in ('header', 'footer'):
                    element = section.find('.//' + self.HP + kind)
                    if element is not None:
                        markup = ''.join(self.paragraph(node, False) for node in
                                         element.findall('.//' + self.HP + 'subList/' + self.HP + 'p'))
                        decorations.append((kind, markup))
                        self.note('머리말·꼬리말은 구역별로 반복합니다. 홀짝/첫 쪽 예외는 단순화됩니다.')
                for group in groups:
                    self.floats = []
                    markup = ''.join(self.paragraph(node) for node in group)
                    floating = list(self.floats)
                    body = self._document(markup, writer, font, self.body_width * scale,
                                          self.body_height * scale)
                    # Replace body page-number fields from their laid-out block
                    # positions. Headers/footers are replaced per physical page.
                    for _ in range(3):
                        cursor = body.find('__VIEWER_PAGE__')
                        if cursor.isNull():
                            break
                        while not cursor.isNull():
                            position = body.documentLayout().blockBoundingRect(cursor.block()).top()
                            number = page_count + int(max(0, position) / (self.body_height * scale)) + 1
                            cursor.insertText(str(number))
                            cursor = body.find('__VIEWER_PAGE__', cursor)
                    # Native table-format changes invalidate a lazy layout.
                    # Force its complete height before obtaining the page count.
                    body_size = body.documentLayout().documentSize()
                    total = max(1, body.pageCount())
                    if page_count + total > 1000:
                        raise ValueError('간편 한글 변환의 1,000쪽 제한을 초과했습니다.')
                    if body_size.width() > self.body_width * scale + 2:
                        self.note('인쇄 폭을 넘는 표/개체는 잘릴 수 있습니다. 원본 프로그램의 PDF 출력과 비교해 주세요.')
                    for local_page in range(total):
                        if page_count and not writer.newPage():
                            raise ValueError('한글 PDF의 다음 쪽을 만들지 못했습니다.')
                        page_count += 1
                        self.page_number = page_count
                        self.emit(f'한글 → PDF {page_count}쪽 구성')
                        def draw_box(box_markup, rect):
                            x0, y0, x1, y1 = rect
                            width, height = (x1 - x0) * scale, (y1 - y0) * scale
                            if width <= 0 or height <= 0:
                                return
                            fragment = self._document(box_markup.replace('__VIEWER_PAGE__', str(page_count)),
                                                      writer, font, width)
                            actual = fragment.documentLayout().documentSize()
                            fit = min(1, width / max(1, actual.width()), height / max(1, actual.height()))
                            if fit < .999:
                                self.note('내용이 넘친 글상자/머리말을 해당 영역에 맞게 축소했습니다.')
                            painter.save()
                            painter.setClipRect(QRectF(x0 * scale, y0 * scale, width, height))
                            painter.translate(x0 * scale, y0 * scale)
                            painter.scale(fit, fit)
                            fragment.drawContents(painter)
                            painter.restore()
                        if local_page == 0:
                            for box_markup, rect, behind in floating:
                                if behind:
                                    draw_box(box_markup, rect)
                        painter.save()
                        frame = QRectF(self.margin['left'] * scale, self.margin['top'] * scale,
                                       self.body_width * scale, self.body_height * scale)
                        painter.setClipRect(frame)
                        painter.translate(frame.left(), frame.top() - local_page * frame.height())
                        context = QAbstractTextDocumentLayout.PaintContext()
                        context.clip = QRectF(0, local_page * frame.height(), frame.width(), frame.height())
                        body.documentLayout().draw(painter, context)
                        painter.restore()
                        if local_page == 0:
                            for box_markup, rect, behind in floating:
                                if not behind:
                                    draw_box(box_markup, rect)
                        for kind, box_markup in decorations:
                            if kind == 'header':
                                rect = (self.margin['left'], self.margin['header'],
                                        self.width - self.margin['right'],
                                        max(self.margin['header'] + 8, self.margin['top'] - 3))
                            else:
                                y = self.height - self.margin['bottom'] + 3
                                rect = (self.margin['left'], y, self.width - self.margin['right'],
                                        max(y + 9, self.height - self.margin['footer']))
                            if rect[3] <= self.height:
                                draw_box(box_markup, rect)
                            else:
                                self.note('여백이 부족한 머리말/꼬리말이 있습니다.')
        except BaseException:
            if painter.isActive():
                painter.end()
            del writer
            target.unlink(missing_ok=True)
            raise
        else:
            if painter.isActive():
                painter.end()
            del writer
        if not page_count or not target.is_file() or target.stat().st_size < 100:
            target.unlink(missing_ok=True)
            raise ValueError('한글 PDF 결과가 없습니다.')
        return self.notes


def dxf_to_pdf(source, target, emit=lambda _stage: None):
    """ezdxf vector SVG → Qt PDF. No GPL/AGPL conversion executable."""
    import ezdxf
    from ezdxf.addons.drawing import Frontend, RenderContext, layout
    from ezdxf.addons.drawing.config import Configuration, BackgroundPolicy
    from ezdxf.addons.drawing.svg import SVGBackend
    from PySide6.QtCore import QByteArray, QRectF
    from PySide6.QtGui import QPainter, QPdfWriter
    from PySide6.QtSvg import QSvgRenderer
    _viewer_conversion_app()
    emit('CAD 2D 도면 → PDF 저장')
    document = ezdxf.readfile(source)
    papers = [space for space in document.layouts if space.name != 'Model' and any(
        entity.dxftype() != 'VIEWPORT' or entity.dxf.get('id', 1) > 1 for entity in space)]
    pages = papers or [document.modelspace()]
    warnings = []
    if any(block.block.dxf.get('xref_path', '') for block in document.blocks):
        warnings.append('외부참조는 원본과 비교가 필요합니다.')
    warnings.append('DXF 글자는 벡터 윤곽으로 출력되어 PDF에서 문자 검색·본문 편집이 제한됩니다.')
    writer = QPdfWriter(str(target))
    writer.setResolution(_VIEWER_PDF_DPI)
    writer.setTitle(Path(source).stem)
    writer.setCreator(APP_NAME + ' ' + APP_VERSION)
    painter = QPainter()
    try:
        for index, space in enumerate(pages):
            emit(f'CAD 도면 {index + 1}/{len(pages)} → PDF 저장')
            backend = SVGBackend()
            Frontend(RenderContext(document), backend,
                     config=Configuration(background_policy=BackgroundPolicy.WHITE)).draw_layout(space)
            page = (layout.Page.from_dxf_layout(space) if space.name != 'Model'
                    else layout.Page(297, 210, margins=layout.Margins.all(5)))
            svg = backend.get_string(page)
            renderer = QSvgRenderer(QByteArray(svg.encode('utf-8')))
            if not renderer.isValid():
                raise ValueError('DXF 벡터 변환 결과를 읽지 못했습니다.')
            width = max(1, page.width_in_mm) * 72 / 25.4
            height = max(1, page.height_in_mm) * 72 / 25.4
            _viewer_pdf_layout(writer, width, height)
            if index:
                if not writer.newPage():
                    raise ValueError('DXF PDF의 다음 쪽을 만들지 못했습니다.')
            elif not painter.begin(writer):
                raise ValueError('DXF PDF 출력 장치를 시작하지 못했습니다.')
            renderer.render(painter, QRectF(0, 0, width * _VIEWER_PDF_DPI / 72,
                                           height * _VIEWER_PDF_DPI / 72))
    except BaseException:
        if painter.isActive():
            painter.end()
        del writer
        Path(target).unlink(missing_ok=True)
        raise
    else:
        painter.end()
        del writer
    return warnings

def move_pdf_text(page, source_path, number, rect, dx, dy, expected_text, source_glyphs=None):
    """Move only the selected complete glyph run, preserving original codes and spacing."""
    from viewer_pdf_edit import move_text_objects
    move_text_objects(page, rect, dx, dy, expected_text,source_glyphs)

def comparison_render(ref):
    cv2, np = comparison_dependencies()
    path, number = ref['path'], int(ref['number'])
    words = []; styles = []; text_note = ''; reduced = False; render_scale=1.; sample_tolerance=False
    if is_image_source(path):
        Image, ImageOps = pillow_reader()
        with open_image_source(path, number) as (picture, _stream):
            sample_tolerance=picture.format=='JPEG'
            if picture.format=='GIF':text_note='GIF 첫 프레임만 비교했습니다. 이후 프레임은 확인하지 않았습니다.'
            picture.load()
            with ImageOps.exif_transpose(picture) as oriented:
                size = oriented.size
                reduced = max(size) > COMPARE_MAX_SIDE
                oriented.thumbnail((COMPARE_MAX_SIDE,COMPARE_MAX_SIDE),Image.Resampling.LANCZOS)
                with oriented.convert('RGBA') as rgba:
                    with Image.new('RGBA', oriented.size, (255, 255, 255, 255)) as white:
                        white.alpha_composite(rgba)
                        with white.convert('RGB') as rgb:
                            bitmap = np.array(rgb)
        kind = 'image'
    else:
        import viewer_pdf_engine
        with viewer_pdf_engine.open(path) as doc:
            if not doc.is_pdf or doc.needs_pass:
                raise ValueError('암호가 없는 PDF를 선택하세요.')
            page = doc[number]; rect = page.rect
            scale = min(COMPARE_DPI/72, COMPARE_MAX_SIDE/max(rect.width, rect.height))
            render_scale=scale
            reduced = scale < COMPARE_DPI/72-0.001
            pix = page.get_pixmap(matrix=viewer_pdf_engine.Matrix(scale, scale),
                                  colorspace=viewer_pdf_engine.csRGB, alpha=False, annots=True)
            bitmap = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, 3).copy()
            # Native text boxes use unrotated page coordinates; the displayed page may be rotated.
            items = page.get_text('words', sort=True)
            if len(items) > 12000:
                text_note = '문자 항목이 많아 문자 대조를 보류했습니다.'
            elif any('\ufffd' in str(item[4]) for item in items):
                text_note = 'PDF 문자 매핑이 불완전해 문자 대조를 보류했습니다.'
            else:
                for item in items:
                    box = viewer_pdf_engine.Rect(item[:4]) * page.rotation_matrix
                    box = box & rect
                    if box.is_empty or not str(item[4]).strip(): continue
                    words.append({'text': str(item[4]), 'box': [box.x0*scale-pix.x,
                        box.y0*scale-pix.y,box.x1*scale-pix.x,box.y1*scale-pix.y]})
                flags=viewer_pdf_engine.TEXTFLAGS_DICT & ~viewer_pdf_engine.TEXT_PRESERVE_IMAGES
                for block in page.get_text('dict',flags=flags,sort=True)['blocks']:
                    for line in block.get('lines',[]):
                        for span in line.get('spans',[]):
                            if not span.get('text','').strip():continue
                            box=(viewer_pdf_engine.Rect(span['bbox'])*page.rotation_matrix)&rect
                            if box.is_empty:continue
                            styles.append({'text':span['text'],
                                'font':re.sub(r'^[A-Z]{6}\+','',span.get('font','')),
                                'size':float(span.get('size',0))*scale,
                                'color':span.get('color',0),'flags':int(span.get('flags',0)),
                                'box':[box.x0*scale-pix.x,box.y0*scale-pix.y,
                                       box.x1*scale-pix.x,box.y1*scale-pix.y]})
            sample_tolerance=not words and bool(page.get_images())
        kind = 'pdf'
    if min(bitmap.shape[:2]) < 16:
        raise ValueError('비교할 그림/페이지가 너무 작습니다.')
    return {'rgb': bitmap, 'words': words, 'styles':styles,'kind': kind, 'reduced': reduced,
            'text_note': text_note,'render_scale':render_scale,'sample_tolerance':sample_tolerance}


def comparison_rerender_pdf(ref, matrix, render_scale, width, height):
    """Render native vectors at the aligned position instead of resampling glyph pixels."""
    import viewer_pdf_engine
    _cv2,np=comparison_dependencies()
    m=matrix
    transform=viewer_pdf_engine.Matrix(float(m[0,0]*render_scale),float(m[1,0]*render_scale),
        float(m[0,1]*render_scale),float(m[1,1]*render_scale),float(m[0,2]),float(m[1,2]))
    with viewer_pdf_engine.open(ref['path']) as doc:
        pix=doc[int(ref['number'])].get_pixmap(matrix=transform,colorspace=viewer_pdf_engine.csRGB,alpha=False,annots=True)
        data=np.frombuffer(pix.samples,np.uint8).reshape(pix.height,pix.width,3)
        bitmap=np.full((height,width,3),255,np.uint8)
        x0,y0=max(0,pix.x),max(0,pix.y);x1,y1=min(width,pix.x+pix.width),min(height,pix.y+pix.height)
        if x1>x0 and y1>y0:bitmap[y0:y1,x0:x1]=data[y0-pix.y:y1-pix.y,x0-pix.x:x1-pix.x]
        return bitmap


def printing_package_selftest():
    """Offline module/layout check used by pkpk16; never starts a printer job."""
    import ctypes
    import viewer_pdf_engine
    from PySide6.QtPrintSupport import QPrinterInfo
    from PIL import ImageWin
    if ctypes.sizeof(WindowsPrintDevice.devmode_type()) != 220:
        raise ValueError('Windows DEVMODE 구조 크기가 올바르지 않습니다.')
    if sys.platform == 'win32':
        for dll, names in [('winspool.drv', ('OpenPrinterW','DocumentPropertiesW','DeviceCapabilitiesW','SetJobW')),
                           ('gdi32', ('CreateDCW','StartDocW','StartPage','EndPage','EndDoc','AbortDoc','SetAbortProc'))]:
            library = ctypes.WinDLL(dll)
            for name in names:getattr(library,name)
        from PIL import Image
        if not callable(getattr(Image.core,'display',None)):
            raise ValueError('Windows 그림 인쇄 모듈이 누락되었습니다.')
    with tempfile.TemporaryDirectory(prefix='TheViewerPrintCheck_') as directory:
        path=Path(directory);source=path/'input.pdf';target=path/'prepared.pdf';result=path/'output.pdf'
        with viewer_pdf_engine.open() as doc:
            for number in range(5):
                page=doc.new_page();page.insert_text((40,60),f'PRINT CHECK PAGE {number+1}',fontsize=14)
            doc.save(source)
        options=validate_print_options({'paper':'A3','orientation':'landscape','duplex':'long','copies':2,'nup':2})
        entries=[{'path':str(source),'number':i} for i in range(5)]
        build_print_pdf(entries,list(range(5)),options,target)
        publish_print_pdf(target,result,options)
        with viewer_pdf_engine.open(result) as doc:
            if len(doc)!=8 or abs(doc[0].rect.width-420*PT_PER_MM)>.01:
                raise ValueError('인쇄 부수·양면 빈 뒷면·A3 용지 검사에 실패했습니다.')
            if 'PAGE 1' not in doc[0].get_text() or 'PAGE 5' not in doc[2].get_text() or doc[3].get_text().strip():
                raise ValueError('인쇄 쪽 순서 또는 빈 뒷면 검사에 실패했습니다.')
        if list(print_face_order(4,{**options,'collate':False})) != [0,1,0,1,2,3,2,3]:
            raise ValueError('양면 용지별 복사 순서 검사에 실패했습니다.')
        preview=render_print_preview({'entries':entries[:2],'group':[0,1],'options':options})
        if not base64.b64decode(preview['png']).startswith(b'\x89PNG'):
            raise ValueError('인쇄 미리보기 렌더링 검사에 실패했습니다.')
        actual=validate_print_options({'size_mode':'actual','margins':[0.,0.,0.,0.],'offsets':[1.25,-.75]})
        build_print_pdf(entries,[0],actual,target,minimum_margins=(3.,3.,3.,3.))
        with viewer_pdf_engine.open(source) as original, viewer_pdf_engine.open(target) as printed:
            before=original[0].get_text('words')[0];after=printed[0].get_text('words')[0]
            expected_x=(printed[0].rect.width-original[0].rect.width)/2+1.25*PT_PER_MM
            expected_y=(printed[0].rect.height-original[0].rect.height)/2-.75*PT_PER_MM
            if (abs((after[2]-after[0])-(before[2]-before[0]))>.02 or
                abs(after[0]-before[0]-expected_x)>.02 or abs(after[1]-before[1]-expected_y)>.02):
                raise ValueError('100% 크기 또는 mm 위치 이동 검사에 실패했습니다.')
        previous=result.read_bytes()
        try:publish_print_pdf(target,result,actual,overwrite=False)
        except FileExistsError:pass
        else:raise ValueError('일반 PDF 저장의 기존 파일 보호 검사에 실패했습니다.')
        if result.read_bytes()!=previous:raise ValueError('기존 PDF가 변경되었습니다.')
    return {'QtPrintSupport':True,'PIL.ImageWin':True,'A3_landscape_2up':True,
            'copies_duplex_padding':True,'preview':True,'actual_size_and_mm_offset':True,
            'automatic_save_no_overwrite':True,'actual_printer_job':False}


def document_package_selftest():
    import viewer_pdf_engine,ezdxf
    from PIL import Image
    from psd_tools import PSDImage
    from PySide6.QtGui import QMovie
    if b'gif' not in [bytes(v) for v in QMovie.supportedFormats()]:raise ValueError('GIF 재생 플러그인이 없습니다.')
    with tempfile.TemporaryDirectory(prefix='TheViewerDocCheck_') as directory:
        root=Path(directory);psd=root/'sample.psd';pdf=root/'psd.pdf'
        with Image.new('RGB',(120,80),(25,150,90)) as image:PSDImage.frompil(image).save(psd)
        psd_to_pdf(psd,pdf)
        with viewer_pdf_engine.open(pdf) as doc:
            if len(doc)!=1 or not doc[0].get_images():raise ValueError('PSD PDF 검사 실패')
        dxf=root/'drawing.dxf';doc=ezdxf.new('R2010');doc.modelspace().add_line((0,0),(100,100));doc.saveas(dxf)
        dxf_to_pdf(dxf,root/'drawing.pdf')
        with viewer_pdf_engine.open(root/'drawing.pdf') as doc:
            if len(doc)!=1 or not doc[0].get_drawings():raise ValueError('CAD PDF 검사 실패')
        gif=root/'sample.gif'
        with Image.new('RGB',(16,16),'red') as first,Image.new('RGB',(16,16),'blue') as second:
            first.save(gif,save_all=True,append_images=[second],duration=80,loop=0)
        items=[];discover_input_pages(str(gif),items.append)
        if sum(i['count'] for batch in items for i in batch.get('items',[batch]))!=1:raise ValueError('GIF는 한 항목이어야 합니다.')
        from hwpx import HwpxDocument
        hangul=HwpxDocument.new();hangul.add_paragraph('한글 읽기 HWPX NATIVE TEST')
        hangul.save_to_path(root/'sample.hwpx')
        hwp_to_pdf(root/'sample.hwpx',root/'hangul.pdf')
        with viewer_pdf_engine.open(root/'hangul.pdf') as doc:
            text=''.join(page.get_text() for page in doc)
            if 'HWPX NATIVE TEST' not in text or '한글' not in text:
                raise ValueError('HWPX → PDF 글자 변환 검사 실패')
    return {'psd_pdf':True,'dxf_pdf':True,'gif_plugin_and_single_item':True,
            'hwpx_native_text_pdf':True}


def text_package_selftest():
    """Generated local files only: Unicode, newlines, editing, paging and source non-execution."""
    import viewer_pdf_engine
    with tempfile.TemporaryDirectory(prefix='TheViewerTextCheck_') as folder:
        root=Path(folder);source=root/'sample.txt'
        raw=('TEXT READER CHECK\r\n\r\n  한글 들여쓰기\r\n\t탭 유지\r\n'+'긴 글 한 줄 ABC <tag> & 값\r\n'*80+'TEXT LAST PAGE').encode('utf-8')
        source.write_bytes(raw);state=read_plain_text(source)
        if text_encode(state,state.text)!=raw:raise ValueError('텍스트 줄끝 무손실 읽기/저장 실패')
        rendered=render_plain_text(source,root/'out')
        with viewer_pdf_engine.open(rendered['path']) as doc:
            if len(doc)<2 or 'TEXT READER CHECK' not in doc[0].get_text() or 'TEXT LAST PAGE' not in doc[-1].get_text():
                raise ValueError('긴 텍스트 페이지 분할 또는 내용 확인 실패')
            if not doc[0].get_pixmap().samples:raise ValueError('텍스트 첫 페이지 썸네일 렌더링 실패')
        if source.read_bytes()!=raw:raise ValueError('읽기에서 원본 텍스트 변경')
        result=write_plain_text(state,state.text.replace('TEXT READER CHECK','EDITED TEXT CHECK'))
        if not result['backup'] or Path(result['backup']).read_bytes()!=raw or b'\r\n\r\n' not in source.read_bytes():
            raise ValueError('텍스트 저장 백업/빈 줄 유지 실패')
        try:write_plain_text(state,state.text+'stale')
        except PlainTextError:pass
        else:raise ValueError('외부 수정 충돌이 차단되지 않았습니다.')
        legacy=root/'legacy.txt';legacy.write_bytes('한글\r\n두 줄'.encode('cp949'))
        legacy_state=read_plain_text(legacy)
        if text_encode(legacy_state,legacy_state.text)!=legacy.read_bytes():raise ValueError('CP949 왕복 실패')
        py=root/'never_execute.py';sentinel=root/'should_not_exist'
        py.write_text("# coding: utf-8\nfrom pathlib import Path\nPath("+repr(str(sentinel))+").write_text('no')\n",encoding='utf-8')
        render_plain_text(py,root/'py_out')
        if sentinel.exists():raise ValueError('열람한 PY가 실행됐습니다.')
        editor=PlainTextEditor(None,source)
        try:
            if editor.state is None or editor.edit.toPlainText()!=read_plain_text(source).text:
                raise ValueError('실제 텍스트 편집기 읽기 실패')
            original=editor.edit.toPlainText();editor.edit.insertPlainText('UI EDIT ')
            if not editor.changed():raise ValueError('텍스트 편집 상태 표시 실패')
            editor.edit.undo()
            if editor.edit.toPlainText()!=original:raise ValueError('텍스트 편집 되돌리기 실패')
        finally:editor.deleteLater()
    return {'text_pages':rendered['count'],'text_and_thumbnail':True,'native_editor':True,
            'newline_and_cp949_roundtrip':True,'backup_and_conflict_guard':True,'py_not_executed':True}


def vector_package_selftest():
    """Verify the removed converter formats are rejected, including disguised PDF data."""
    import viewer_pdf_engine
    with tempfile.TemporaryDirectory(prefix='TheViewerRemovedFormatCheck_') as directory:
        root=Path(directory)
        with viewer_pdf_engine.open() as doc:
            doc.new_page().insert_text((40,60),'SUPPORTED PDF FORMAT CHECK')
            data=doc.tobytes()
        for name in ('2.ai','3.eps','4.ps','5.dwg'):
            path=root/name
            path.write_bytes(data if path.suffix=='.ai' else b'REMOVED FORMAT TEST')
            if supported_input(path):
                raise ValueError('제외한 파일 형식이 다시 허용되었습니다: '+path.suffix)
        (root/'1.pdf').write_bytes(data);(root/'6.pdf').write_bytes(data)
        if not supported_input(root/'1.pdf'):
            raise ValueError('PDF 직접 열기가 누락되었습니다.')
        items=[];result=discover_input_pages(str(root),items.append)
        paths=[item['path'] for batch in items for item in batch.get('items',[batch]) if 'path' in item]
        removed={'.ai','.eps','.ps','.dwg'}
        if result['errors'] or any(Path(path).suffix.lower() in removed for path in paths):
            raise ValueError('폴더 검색에 제외한 형식이 포함되었습니다.')
        if {Path(path).name for path in paths}!={'1.pdf','6.pdf'}:
            raise ValueError('지원 PDF의 폴더 검색 결과가 올바르지 않습니다.')
        for containers in (False,True):
            neighbors=neighboring_inputs(str(root/'1.pdf'),containers)
            if Path(neighbors['next']).name!='6.pdf':
                raise ValueError('파일 이동에 제외한 형식이 포함되었습니다.')
    return {'removed_ai_eps_ps_dwg_rejected':True,'pdf_still_supported':True,
            'folder_excluded':True,'sibling_navigation_excluded':True}


def bundled_engines_package_selftest():
    """Check excluded engines and run the optional bundled LibreOffice converters offline."""
    import viewer_pdf_engine
    if sys.platform!='win32' or not getattr(sys,'frozen',False):
        return {'deferred':True,'reason':'Windows EXE 빌드 후 동봉 Office 엔진 실제 변환 검사'}
    root=Path(sys._MEIPASS)/'engines'
    if any((root/name).exists() for name in ('ghostscript','libredwg')):
        raise ValueError('제외한 Ghostscript 또는 LibreDWG 엔진이 빌드에 포함되었습니다.')
    office=find_document_engine('office')
    if not (root/'libreoffice').exists():
        return {'not_applicable':True,'reason':'LibreOffice를 동봉하지 않은 빌드',
                'excluded_engines_absent':True}
    if not office or root.resolve() not in Path(office).resolve().parents:
        raise ValueError('동봉 LibreOffice 엔진을 찾지 못했습니다.')
    result={'excluded_engines_absent':True}
    with tempfile.TemporaryDirectory(prefix='TheViewerOfficeEngineCheck_') as folder:
        work=Path(folder)
        for filename,expected in (('word.docx','WORD CONVERSION TEST'),
                                  ('excel.xlsx','EXCEL CONVERSION TEST'),
                                  ('slides.pptx','POWERPOINT CONVERSION TEST')):
            item=work/Path(filename).stem;item.mkdir()
            output=item/'out.pdf'
            office_to_pdf(root/'libreoffice/checks'/filename,output,item,office)
            with viewer_pdf_engine.open(output) as doc:
                if expected not in ''.join(p.get_text() for p in doc):
                    raise ValueError('동봉 Office PDF 내용 검사 실패: '+filename)
                result[filename]=len(doc)
    return result


def publish_print_pdf(source, target, options, *, progress=None, cancelled=lambda: False, overwrite=True,phase=None):
    import viewer_pdf_engine
    target = Path(target)
    part = target.with_name('.'+target.stem+'.'+uuid.uuid4().hex+'.printing.pdf')
    cache=None
    try:
        if not options['color']:
            cache=tempfile.TemporaryDirectory(prefix='TheViewerGrayPrint_')
            rasters=prepare_print_rasters(source,options,cache.name,cancelled,phase)
        with viewer_pdf_engine.open(source) as document, viewer_pdf_engine.open() as output:
            total = len(document)*options['copies']
            for count, number in enumerate(print_face_order(len(document), options), 1):
                if cancelled():
                    raise PrintCancelled()
                if options['color']:
                    output.insert_pdf(document, from_page=number, to_page=number)
                else:
                    source_page = document[number]
                    page = output.new_page(width=source_page.rect.width, height=source_page.rect.height)
                    item=rasters['pages'][number];height=item['height']
                    for band in item['bands']:
                        if cancelled():raise PrintCancelled()
                        top,bottom=band['top'],band['bottom']
                        if phase:phase(f'PDF 흑백 그림 배치 {count:,}/{total:,}면 · {round(bottom/height*100)}%',
                            81+round(((count-1)+top/height)/total*16))
                        clip=[0,source_page.rect.height*top/height,source_page.rect.width,source_page.rect.height*bottom/height]
                        page.insert_image(viewer_pdf_engine.Rect(clip),stream=(Path(cache.name)/band['file']).read_bytes(),keep_proportion=False)
                if progress:
                    progress(count, total)
            if phase:phase('PDF 파일 기록 중',98)
            output.save(part, garbage=3, deflate=True)
        if cancelled():
            raise PrintCancelled()
        if phase:phase('PDF 저장 완료 확인',99)
        commit_output_file(part, target, overwrite=overwrite)
    finally:
        part.unlink(missing_ok=True)
        if cache is not None:cache.cleanup()

